var e=JSON.parse(`[{"id":"srd:spell:acid-arrow","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Acid Arrow","description":"A shimmering green arrow streaks toward a target within range and bursts in a spray of acid. Make a ranged spell attack against the target. On a hit, the target takes 4d4 acid damage immediately and 2d4 acid damage at the end of its next turn. On a miss, the arrow splashes the target with acid for half as much of the initial damage and no damage at the end of its next turn.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, the damage (both initial and later) increases by 1d4 for each slot level above 2nd."},"it":{"name":"Freccia acida","description":"Una freccia verde scintillante sfreccia verso un bersaglio entro gittata ed esplode in uno spruzzo di acido, effettuando un attacco a distanza con incantesimo contro il bersaglio. Se il colpo va a segno, il bersaglio subisce immediatamente 4d4 danni da acido e 2d4 danni da acido alla fine del suo turno successivo. Se il colpo manca, la freccia schizza il bersaglio con l'acido per la metà del danno iniziale e non infligge alcun danno alla fine del suo turno successivo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, i danni (sia iniziali che successivi) aumentano di 1d4 per ogni slot di livello superiore al 2°.","castingTime":"1 azione","range":"27 metri","duration":"Istantanea","material":"foglia di rabarbaro in polvere e stomaco di vipera"}},"data":{"level":2,"school":"srd:rule:school-evocation","classes":["srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"90 feet","components":["V","S","M"],"material":"Powdered rhubarb leaf and an adder's stomach.","ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-acid","atSlotLevel":{"2":"4d4","3":"5d4","4":"6d4","5":"7d4","6":"8d4","7":"9d4","8":"10d4","9":"11d4"}}],"attackType":"ranged"}},{"id":"srd:spell:acid-splash","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Acid Splash","description":"You hurl a bubble of acid. Choose one creature within range, or choose two creatures within range that are within 5 feet of each other. A target must succeed on a dexterity saving throw or take 1d6 acid damage.\\n\\nThis spell's damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6)."},"it":{"name":"Fiotto acido","description":"L'incantatore scaglia una bolla di acido, scegliendo una creatura entro gittata o scegliendone due entro gittata che si trovano a non più di 1,5 metri l'una dall'altra. Un bersaglio deve superare un tiro salvezza su Destrezza, altrimenti subisce 1d6 danni da acido.\\n\\nI danni di questo incantesimo aumentano di 1d6 quando l'incantatore raggiunge il 5° livello (2d6), l'11° livello (3d6) e il 17° livello (4d6).","castingTime":"1 azione","range":"18 metri","duration":"Istantanea"}},"data":{"level":0,"school":"srd:rule:school-conjuration","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-acid","atCharacterLevel":{"1":"1d6","5":"2d6","11":"3d6","17":"4d6"}}],"savingThrow":{"ability":"dex","onSuccess":"none"}}},{"id":"srd:spell:aid","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Aid","description":"Your spell bolsters your allies with toughness and resolve. Choose up to three creatures within range. Each target's hit point maximum and current hit points increase by 5 for the duration.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, a target's hit points increase by an additional 5 for each slot level above 2nd."},"it":{"name":"Aiuto","description":"Questo incantesimo rafforza il vigore e la determinazione degli alleati. L'incantatore sceglie fino a tre creature entro gittata. I punti ferita massimi e i punti ferita attuali di ogni bersaglio aumentano di 5 per la durata dell'incantesimo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, i punti ferita di un bersaglio aumentano di altri 5 punti per ogni slot di livello superiore al 2°.","castingTime":"1 azione","range":"9 metri","duration":"8 ore","material":"una minuscola striscia di tessuto bianco"}},"data":{"level":2,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric","srd:class:paladin"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A tiny strip of white cloth.","ritual":false,"concentration":false,"duration":"8 hours"}},{"id":"srd:spell:alarm","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Alarm","description":"You set an alarm against unwanted intrusion. Choose a door, a window, or an area within range that is no larger than a 20-foot cube. Until the spell ends, an alarm alerts you whenever a Tiny or larger creature touches or enters the warded area. When you cast the spell, you can designate creatures that won't set off the alarm. You also choose whether the alarm is mental or audible.\\n\\nA mental alarm alerts you with a ping in your mind if you are within 1 mile of the warded area. This ping awakens you if you are sleeping.\\n\\nAn audible alarm produces the sound of a hand bell for 10 seconds within 60 feet."},"it":{"name":"Allarme","description":"L'incantatore predispone un allarme contro le visite indesiderate, scegliendo una porta, una finestra o un'area entro gittata che non sia più ampia di un cubo di 6 metri. Finché l'incantesimo non termina, un allarme avverte l'incantatore tutte le volte che una creatura di taglia Minuscola o superiore tocca o entra nell'area protetta. Al momento del lancio dell'incantesimo, l'incantatore designa quali creature non faranno scattare l'allarme. Sceglie inoltre se l'allarme è mentale o udibile.\\n\\nSe l'allarme è mentale, un tintinnio risuona nella mente dell'incantatore se questi si trova entro 1,5 km dall'area protetta. Questo suono lo sveglia se sta dormendo.\\n\\nUn allarme udibile produce il suono di una campanella per 10 secondi entro 18 metri.","castingTime":"1 minuto","range":"9 metri","duration":"8 ore","material":"un campanellino e un pezzo di prezioso filo d'argento"}},"data":{"level":1,"school":"srd:rule:school-abjuration","classes":["srd:class:ranger","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 minute","range":"30 feet","components":["V","S","M"],"material":"A tiny bell and a piece of fine silver wire.","ritual":true,"concentration":false,"duration":"8 hours","area":{"type":"cube","size":20}}},{"id":"srd:spell:alter-self","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Alter Self","description":"You assume a different form. When you cast the spell, choose one of the following options, the effects of which last for the duration of the spell. While the spell lasts, you can end one option as an action to gain the benefits of a different one.\\n\\n***Aquatic Adaptation.*** You adapt your body to an aquatic environment, sprouting gills and growing webbing between your fingers. You can breathe underwater and gain a swimming speed equal to your walking speed.\\n\\n***Change Appearance.*** You transform your appearance. You decide what you look like, including your height, weight, facial features, sound of your voice, hair length, coloration, and distinguishing characteristics, if any. You can make yourself appear as a member of another race, though none of your statistics change. You also can't appear as a creature of a different size than you, and your basic shape stays the same; if you're bipedal, you can't use this spell to become quadrupedal, for instance. At any time for the duration of the spell, you can use your action to change your appearance in this way again.\\n\\n***Natural Weapons.*** You grow claws, fangs, spines, horns, or a different natural weapon of your choice. Your unarmed strikes deal 1d6 bludgeoning, piercing, or slashing damage, as appropriate to the natural weapon you chose, and you are proficient with your unarmed strikes. Finally, the natural weapon is magic and you have a +1 bonus to the attack and damage rolls you make using it."},"it":{"name":"Alterare se stesso","description":"L'incantatore assume una forma differente, scegliendo al momento del lancio dell'incantesimo una delle opzioni seguenti, i cui effetti permangono per la durata dell'incantesimo. Finché l'incantesimo permane, l'incantatore può terminare un'opzione con un'azione per ottenere i benefici di un'opzione diversa.\\n\\n***Adattamento acquatico.*** L'incantatore adatta il proprio corpo a un ambiente acquatico, sviluppando le branchie e una membrana tra le dita. Inoltre, può respirare sott'acqua e ottenere una velocità di nuotare pari alla sua velocità base.\\n\\n***Armi naturali.*** L'incantatore sviluppa artigli, zanne, corna o un'altra arma naturale a sua scelta. I suoi colpi senz'armi infliggono 1d6 danni contundenti, perforanti o taglienti, secondo l'arma naturale scelta e diventa competente nei suoi colpi senz'armi. Infine, l'arma naturale è magica e l'incantatore ottiene un bonus di +1 ai tiri per colpire e ai tiri per i danni effettuati con essa.\\n\\n***Cambiare aspetto.*** L'incantatore altera il suo aspetto, decidendo come apparire e definendo altezza, peso, lineamenti facciali, tono della voce, lunghezza dei capelli, carnagione e tratti distintivi, se lo desidera. L'incantatore può decidere di assomigliare a un membro di un'altra razza, ma le sue statistiche non subiscono modifiche. Inoltre, non può apparire come una creatura di taglia diversa dalla propria e la sua forma base rimane la stessa; per esempio, se è bipede, non può usare un incantesimo per diventare quadrupede. In qualsiasi momento per la durata dell'incantesimo, l'incantatore può usare un'azione per mutare di nuovo aspetto in questo modo.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 1 ora"}},"data":{"level":2,"school":"srd:rule:school-transmutation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:animal-friendship","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Animal Friendship","description":"This spell lets you convince a beast that you mean it no harm. Choose a beast that you can see within range. It must see and hear you. If the beast's Intelligence is 4 or higher, the spell fails. Otherwise, the beast must succeed on a wisdom saving throw or be charmed by you for the spell's duration. If you or one of your companions harms the target, the spells ends."},"it":{"name":"Amicizia con gli animali","description":"Tramite questo incantesimo l'incantatore convince una bestia di essere innocuo. L'incantatore sceglie una bestia entro gittata che è in grado di vedere. La creatura deve essere in grado di vederlo e sentirlo. Tuttavia, se la sua Intelligenza è pari o superiore 4, l'incantesimo fallisce. In caso contrario, la bestia deve superare un tiro salvezza su Saggezza, altrimenti rimarrà affascinata per la durata dell'incantesimo. Se l'incantatore o uno dei suoi compagni infligge danni al bersaglio, l'incantesimo termina.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, può influenzare una bestia aggiuntiva di livello superiore al 1°.","castingTime":"1 azione","range":"9 metri","duration":"24 ore","material":"un boccone di cibo"}},"data":{"level":1,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:druid","srd:class:ranger"],"subclasses":[],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A morsel of food.","ritual":false,"concentration":false,"duration":"24 hours","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:animal-messenger","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Animal Messenger","description":"By means of this spell, you use an animal to deliver a message. Choose a Tiny beast you can see within range, such as a squirrel, a blue jay, or a bat. You specify a location, which you must have visited, and a recipient who matches a general description, such as \\"a man or woman dressed in the uniform of the town guard\\" or \\"a red-haired dwarf wearing a pointed hat.\\" You also speak a message of up to twenty-five words. The target beast travels for the duration of the spell toward the specified location, covering about 50 miles per 24 hours for a flying messenger, or 25 miles for other animals.\\n\\nWhen the messenger arrives, it delivers your message to the creature that you described, replicating the sound of your voice. The messenger speaks only to a creature matching the description you gave. If the messenger doesn't reach its destination before the spell ends, the message is lost, and the beast makes its way back to where you cast this spell.\\n\\n**At Higher Levels.** If you cast this spell using a spell slot of 3nd level or higher, the duration of the spell increases by 48 hours for each slot level above 2nd."},"it":{"name":"Animale messaggero","description":"Tramite questo incantesimo, l'incantatore utilizza un animale per consegnare un messaggio, scegliendo una bestia di taglia Minuscola entro gittata e che è in grado di vedere, come uno scoiattolo, una ghiandaia azzurra o un pipistrello. L'incantatore specifica il luogo di consegna, che deve avere già visitato, e un destinatario che corrisponda a una descrizione generica, come \\"un uomo o una donna che indossa l'uniforme della guardia cittadina\\" o \\"un nano dai capelli rossi che indossa un cappello a punta\\". Inoltre, l'incantatore pronuncia un messaggio composto da un massimo di venticinque parole. La bestia bersaglio viaggia per la durata dell'incantesimo verso il luogo specificato, percorrendo circa 75 km in 24 ore nel caso sia un messaggero volante o 37,5 km nel caso di altri animali.\\n\\nAl suo arrivo, il messaggero consegna il messaggio alla creatura descritta dall'incantatore, replicando il suono della sua voce. Il messaggero parla solamente con una creatura che corrisponda alla descrizione fornita dall'incantatore. Inoltre, se il messaggero non raggiunge la sua destinazione prima della fine dell'incantesimo, il messaggio viene perso e la bestia torna nel luogo dove l'incantatore ha lanciato questo incantesimo.\\n\\n**Ai livelli superiori.** Se l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, la sua durata aumenta di 48 ore per ogni slot di livello superiore al 2°.","castingTime":"1 azione","range":"9 metri","duration":"24 ore","material":"un boccone di cibo"}},"data":{"level":2,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:druid","srd:class:ranger"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A morsel of food.","ritual":true,"concentration":false,"duration":"24 hours"}},{"id":"srd:spell:animal-shapes","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Animal Shapes","description":"Your magic turns others into beasts. Choose any number of willing creatures that you can see within range. You transform each target into the form of a Large or smaller beast with a challenge rating of 4 or lower. On subsequent turns, you can use your action to transform affected creatures into new forms.\\n\\nThe transformation lasts for the duration for each target, or until the target drops to 0 hit points or dies. You can choose a different form for each target. A target's game statistics are replaced by the statistics of the chosen beast, though the target retains its alignment and Intelligence, Wisdom, and Charisma scores. The target assumes the hit points of its new form, and when it reverts to its normal form, it returns to the number of hit points it had before it transformed. If it reverts as a result of dropping to 0 hit points, any excess damage carries over to its normal form. As long as the excess damage doesn't reduce the creature's normal form to 0 hit points, it isn't knocked unconscious. The creature is limited in the actions it can perform by the nature of its new form, and it can't speak or cast spells.\\n\\nThe target's gear melds into the new form. The target can't activate, wield, or otherwise benefit from any of its equipment."},"it":{"name":"Forme animali","description":"La magia dell'incantatore trasforma altre creature in bestie. L'incantatore sceglie un qualsiasi numero di creature consenzienti entro gittata che è in grado di vedere, trasformando ogni bersaglio nella forma di una bestia di taglia Grande o inferiore con un grado di sfida pari o inferiore a 4. Nei turni successivi, l'incantatore può usare la sua azione per trasformare le creature influenzate in altre forme.\\n\\nLa trasformazione permane su ogni bersaglio per la durata dell'incantesimo, oppure finché il bersaglio non scende a 0 punti ferita o muore. L'incantatore può scegliere una forma differente per ogni bersaglio, le cui statistiche di gioco vengono sostituite dalle statistiche della bestia scelta, purtuttavia conservando il proprio allineamento e punteggi di Intelligenza, Saggezza e Carisma. Il bersaglio assume i punti ferita della nuova forma e, quando riassume la sua forma normale, ritorna al numero di punti ferita che aveva prima della trasformazione. Se torna alla sua forma normale per essere sceso a 0 punti ferita, gli eventuali danni in eccesso si trasmettono alla sua forma normale. Fintantoché i danni in eccesso non riducono la forma normale della creatura a 0 punti ferita, questa non cade priva di sensi. La creatura è limitata alle azioni che può effettuare in base alla natura della sua nuova forma e non può parlare o lanciare incantesimi.\\n\\nL'attrezzatura del bersaglio si fonde nella sua nuova forma e la creatura non può attivare, usare, impugnare o beneficiare del proprio equipaggiamento.","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 24 ore"}},"data":{"level":8,"school":"srd:rule:school-transmutation","classes":["srd:class:druid"],"subclasses":[],"castingTime":"1 action","range":"30 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 24 hours"}},{"id":"srd:spell:animate-dead","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Animate Dead","description":"This spell creates an undead servant. Choose a pile of bones or a corpse of a Medium or Small humanoid within range. Your spell imbues the target with a foul mimicry of life, raising it as an undead creature. The target becomes a skeleton if you chose bones or a zombie if you chose a corpse (the GM has the creature's game statistics).\\n\\nOn each of your turns, you can use a bonus action to mentally command any creature you made with this spell if the creature is within 60 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete.\\n\\nThe creature is under your control for 24 hours, after which it stops obeying any command you've given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature again before the current 24-hour period ends. This use of the spell reasserts your control over up to four creatures you have animated with this spell, rather than animating a new one.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, you animate or reassert control over two additional undead creatures for each slot level above 3rd. Each of the creatures must come from a different corpse or pile of bones."},"it":{"name":"Animare morti","description":"Questo incantesimo crea un servo non morto. L'incantatore sceglie una pila di ossa o un cadavere umanoide di taglia Media o Piccola entro gittata, infondendo nel bersaglio tramite l'incantesimo un'empia parvenza di vita, animandolo come creatura non morta. Il bersaglio diventa uno scheletro se l'incantatore ha scelto le ossa o uno zombi se ha scelto il cadavere (il GM possiede le statistiche di gioco della creatura).\\n\\nA ogni suo turno, l'incantatore può usare un'azione bonus per comandare mentalmente qualsiasi creatura creata con questo incantesimo, a patto che si trovi entro 18 metri da lui (se controlla varie creature, l'incantatore può comandarne una o tutte allo stesso momento, impartendo lo stesso comando a ciascuna di loro). L'incantatore decide quale azione effettuerà la creatura e dove si muoverà durante il suo turno successivo, oppure può impartirle un comando generale, come proteggere una stanza o un corridoio particolare. Se non impartisce comandi, la creatura si limita a difendersi dalle creature ostili. Una volta ricevuto un ordine, la creatura continua a seguirlo finché non ha portato a termine il compito.\\n\\nLa creatura rimane sotto il controllo dell'incantatore per 24 ore, passate le quali smette di obbedire a qualsiasi comando ulteriore. Per mantenere il controllo sulla creatura per altre 24 ore, l'incantatore deve lanciare di nuovo questo incantesimo su di essa prima che l'attuale periodo di 24 ore termini. Questo uso dell'incantesimo gli permette di ristabilire il controllo su un massimo di quattro creature da lui animate tramite questo incantesimo, anziché animarne una nuova.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, può animare o ristabilire il controllo su due creature non morte aggiuntive per ogni slot superiore al 3°. Ognuna delle creature deve provenire da un diverso cadavere o mucchio d'ossa.","castingTime":"1 minuto","range":"3 metri","duration":"Istantanea","material":"una goccia di sangue, un pezzo di carne e un pizzico di polvere d'osso"}},"data":{"level":3,"school":"srd:rule:school-necromancy","classes":["srd:class:cleric","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 minute","range":"10 feet","components":["V","S","M"],"material":"A drop of blood, a piece of flesh, and a pinch of bone dust.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:animate-objects","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Animate Objects","description":"Objects come to life at your command. Choose up to ten nonmagical objects within range that are not being worn or carried. Medium targets count as two objects, Large targets count as four objects, Huge targets count as eight objects. You can't animate any object larger than Huge. Each target animates and becomes a creature under your control until the spell ends or until reduced to 0 hit points.\\n\\nAs a bonus action, you can mentally command any creature you made with this spell if the creature is within 500 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete.\\n\\n##### Animated Object Statistics\\n\\n| Size | HP | AC | Attack | Str | Dex |\\n\\n|---|---|---|---|---|---|\\n\\n| Tiny | 20 | 18 | +8 to hit, 1d4 + 4 damage | 4 | 18 |\\n\\n| Small | 25 | 16 | +6 to hit, 1d8 + 2 damage | 6 | 14 |\\n\\n| Medium | 40 | 13 | +5 to hit, 2d6 + 1 damage | 10 | 12 |\\n\\n| Large | 50 | 10 | +6 to hit, 2d10 + 2 damage | 14 | 10 |\\n\\n| Huge | 80 | 10 | +8 to hit, 2d12 + 4 damage | 18 | 6 |\\n\\nAn animated object is a construct with AC, hit points, attacks, Strength, and Dexterity determined by its size. Its Constitution is 10 and its Intelligence and Wisdom are 3, and its Charisma is 1. Its speed is 30 feet; if the object lacks legs or other appendages it can use for locomotion, it instead has a flying speed of 30 feet and can hover. If the object is securely attached to a surface or a larger object, such as a chain bolted to a wall, its speed is 0. It has blindsight with a radius of 30 feet and is blind beyond that distance. When the animated object drops to 0 hit points, it reverts to its original object form, and any remaining damage carries over to its original object form.\\n\\nIf you command an object to attack, it can make a single melee attack against a creature within 5 feet of it. It makes a slam attack with an attack bonus and bludgeoning damage determined by its size. The GM might rule that a specific object inflicts slashing or piercing damage based on its form.\\n\\n**At Higher Levels.** If you cast this spell using a spell slot of 6th level or higher, you can animate two additional objects for each slot level above 5th."},"it":{"name":"Animare oggetti","description":"Gli oggetti prendono vita al comando dell'incantatore, che sceglie un massimo di dieci oggetti non magici entro gittata che non siano indossati o trasportati. I bersagli di taglia Media contano come due oggetti, quelli di taglia Grande come quattro oggetti e quelli di taglia Enorme come otto oggetti. L'incantatore non può animare oggetti di taglia superiore a Enorme. Ogni bersaglio animato diventa una creatura sotto il suo controllo finché l'incantesimo non termina o finché non scende a 0 punti ferita.\\n\\nCome azione bonus, l'incantatore può comandare mentalmente qualsiasi creatura creata con questo incantesimo, a patto che si trovi entro 150 metri da lui (se controlla varie creature, l'incantatore può comandarne una o tutte allo stesso momento, impartendo lo stesso comando a ciascuna di loro). L'incantatore decide quale azione effettuerà la creatura e dove si muoverà durante il suo turno successivo, oppure può impartirle un comando generale, come proteggere una stanza o un corridoio particolare. Se non impartisce comandi, la creatura si limita a difendersi dalle creature ostili. Una volta ricevuto un ordine, la creatura continua a seguirlo finché non ha portato a termine il compito.\\n\\n##### Statistiche degli oggetti animati\\n\\n| Taglia | PF | CA | Attacco | For | Des |\\n\\n|---|---|---|---|---|---|\\n\\n| Minuscola | 20 | 18 | +8 al tiro per colpire, 1d4 + 4 danni | 4 | 18 |\\n\\n| Piccola | 25 | 16 | +6 al tiro per colpire, 1d8 + 2 danni | 6 | 14 |\\n\\n| Media | 40 | 13 | +5 al tiro per colpire, 2d6 + 1 danni | 10 | 12 |\\n\\n| Grande | 50 | 10 | +6 al tiro per colpire, 2d10 + 2 danni | 14 | 10 |\\n\\n| Enorme | 80 | 10 | +8 al tiro per colpire, 2d12 + 4 danni | 18 | 6 |\\n\\nUn oggetto animato è un costrutto con CA, punti ferita, attacchi, Forza e Destrezza determinati dalla sua taglia. La sua Costituzione è pari a 10, la sua Intelligenza e Saggezza sono pari a 3 e il suo Carisma è pari a 1. La sua velocità è di 9 metri; se invece l'oggetto è privo di gambe o altre appendici che possa utilizzare per la locomozione, ha una velocità di volare pari a 9 metri e può fluttuare. Se l'oggetto è agganciato saldamente a una superficie o a un oggetto più grande, come una catena fissata a una parete, la sua velocità è pari a 0. È dotato di vista cieca con un raggio di 9 metri ed è cieco oltre quella distanza. Quando un oggetto animato scende a 0 punti ferita, riassume la sua forma originale, a cui viene trasferito ogni danno rimanente.\\n\\nSe l'incantatore comanda a un oggetto di attaccare, esso può effettuare un singolo attacco in mischia contro una creatura entro 1,5 metri da esso. L'oggetto effettua un attacco Schianto con un bonus di attacco e danni contundenti determinati dalla sua taglia. Il GM potrebbe decidere che un oggetto specifico infligga danni taglienti o perforanti in base alla sua forma.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, può animare due oggetti aggiuntivi per ogni slot superiore al 5°.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":5,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute"}},{"id":"srd:spell:antilife-shell","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Antilife Shell","description":"A shimmering barrier extends out from you in a 10-foot radius and moves with you, remaining centered on you and hedging out creatures other than undead and constructs. The barrier lasts for the duration.\\n\\nThe barrier prevents an affected creature from passing or reaching through. An affected creature can cast spells or make attacks with ranged or reach weapons through the barrier.\\n\\nIf you move so that an affected creature is forced to pass through the barrier, the spell ends."},"it":{"name":"Guscio anti-vita","description":"Una barriera scintillate si proietta dall'incantatore in un raggio di 3 metri, seguendolo nei suoi movimenti e rimanendo centrata su di lui, respingendo tutte le creature diverse da non morti e costrutti. La barriera permane per tutta la durata dell'incantesimo.\\n\\nLa barriera impedisce a una creatura influenzata di attraversarla o protendersi oltre essa. Una creatura influenzata può lanciare incantesimi o effettuare attacchi utilizzando armi a distanza o con portata attraverso la barriera.\\n\\nSe l'incantatore si muove in modo che una creatura influenzata sia costretta ad attraversare la barriera, l'incantesimo termina.","castingTime":"1 azione","range":"Incantatore (raggio di 3 metri)","duration":"Concentrazione, fino a 1 ora"}},"data":{"level":5,"school":"srd:rule:school-abjuration","classes":["srd:class:druid"],"subclasses":[],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 hour","area":{"type":"sphere","size":10}}},{"id":"srd:spell:antimagic-field","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Antimagic Field","description":"A 10-foot-radius invisible sphere of antimagic surrounds you. This area is divorced from the magical energy that suffuses the multiverse. Within the sphere, spells can't be cast, summoned creatures disappear, and even magic items become mundane. Until the spell ends, the sphere moves with you, centered on you.\\n\\nSpells and other magical effects, except those created by an artifact or a deity, are suppressed in the sphere and can't protrude into it. A slot expended to cast a suppressed spell is consumed. While an effect is suppressed, it doesn't function, but the time it spends suppressed counts against its duration.\\n\\n***Targeted Effects.*** Spells and other magical effects, such as magic missile and charm person, that target a creature or an object in the sphere have no effect on that target.\\n\\n***Areas of Magic.*** The area of another spell or magical effect, such as fireball, can't extend into the sphere. If the sphere overlaps an area of magic, the part of the area that is covered by the sphere is suppressed. For example, the flames created by a wall of fire are suppressed within the sphere, creating a gap in the wall if the overlap is large enough.\\n\\n***Spells.*** Any active spell or other magical effect on a creature or an object in the sphere is suppressed while the creature or object is in it.\\n\\n***Magic Items.*** The properties and powers of magic items are suppressed in the sphere. For example, a +1 longsword in the sphere functions as a nonmagical longsword.\\n\\nA magic weapon's properties and powers are suppressed if it is used against a target in the sphere or wielded by an attacker in the sphere. If a magic weapon or a piece of magic ammunition fully leaves the sphere (for example, if you fire a magic arrow or throw a magic spear at a target outside the sphere), the magic of the item ceases to be suppressed as soon as it exits.\\n\\n***Magical Travel.*** Teleportation and planar travel fail to work in the sphere, whether the sphere is the destination or the departure point for such magical travel. A portal to another location, world, or plane of existence, as well as an opening to an extradimensional space such as that created by the rope trick spell, temporarily closes while in the sphere.\\n\\n***Creatures and Objects.*** A creature or object summoned or created by magic temporarily winks out of existence in the sphere. Such a creature instantly reappears once the space the creature occupied is no longer within the sphere.\\n\\n***Dispel Magic.*** Spells and magical effects such as dispel magic have no effect on the sphere. Likewise, the spheres created by different antimagic field spells don't nullify each other."},"it":{"name":"Campo anti-magia","description":"Una sfera invisibile di 3 metri di raggio circonda l'incantatore. Quest'area è isolata dall'energia magica che pervade il multiverso: all'interno della sfera è impossibile lanciare incantesimi, le creature evocate scompaiono e perfino gli oggetti magici diventano comuni. Finché l'incantesimo non termina, la sfera si muove insieme all'incantatore ed è centrata su di lui.\\n\\nAll'interno della sfera, gli incantesimi e gli altri effetti magici, eccetto quelli generati da un manufatto o da una divinità, vengono soppressi e non possono protendersi al suo interno. Uno slot speso per lanciare un incantesimo soppresso viene consumato. Mentre un effetto è soppresso, non funziona, ma il tempo che trascorre in questo stato conta ai fini della sua durata.\\n\\n***Effetti a bersaglio.*** Gli incantesimi o gli altri effetti magici, come dardo incantato e charme su persone, che bersagliano una creatura o un oggetto nella sfera, non hanno alcun effetto su quel bersaglio.\\n\\n***Aree di magia.*** L'area di un altro incantesimo o effetto magico, come palla di fuoco, non si può estendere all'interno della sfera. Se la sfera si sovrappone a un'area di magia, la parte di area coperta dalla sfera viene soppressa; per esempio, le fiamme create da un muro di fuoco vengono soppresse all'interno della sfera, creando un varco nel muro se la sovrapposizione è abbastanza ampia.\\n\\n***Incantesimi.*** Qualsiasi incantesimo o altro effetto magico su una creatura o un oggetto nella sfera viene soppresso finché la creatura o l'oggetto in questione si trova al suo interno.\\n\\n***Oggetti magici.*** All'interno della sfera, le proprietà e i poteri degli oggetti magici vengono soppressi. Per esempio, una spada lunga +1 all'interno della sfera funziona come una spada lunga non magica.\\n\\nLe proprietà e i poteri di un'arma magica vengono soppressi se essa è utilizzata contro un bersaglio che si trova all'interno della sfera o se è impugnata da un attaccante all'interno della sfera. Se un'arma magica o una munizione magica esce interamente dalla sfera (per esempio, se l'incantatore scaglia una freccia magica o una lancia magica contro un bersaglio fuori dalla sfera), la magia dell'oggetto cessa di essere soppressa dal momento stesso in cui esce.\\n\\n***Viaggio magico.*** All'interno della sfera, teletrasporto e viaggio planare non funzionano, che essa costituisca il punto di destinazione o quello di partenza di questi viaggi magici. Un portale per un altro luogo, mondo o piano di esistenza, oltre che un varco verso uno spazio extradimensionale (come quello creato da un incantesimo trucco della corda), si chiude temporaneamente finché si trova all'interno della sfera.\\n\\n***Creature e oggetti.*** Una creatura, oppure un oggetto evocato o creato dalla magia, smette temporaneamente di esistere all'interno della sfera, ma riappare immediatamente una volta che lo spazio che occupava non si trova più all'interno della sfera.\\n\\n***Dissolvi magie.*** Gli incantesimi e gli effetti magici, come dissolvi magie, non hanno alcun effetto sulla sfera. Allo stesso modo, le sfere create da incantesimi campo anti-magia diversi non si annullano a vicenda.","castingTime":"1 azione","range":"Incantatore (sfera di 3 metri di raggio)","duration":"Concentrazione, fino a 1 ora","material":"un pizzico di polvere o di limatura di ferro"}},"data":{"level":8,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A pinch of powdered iron or iron filings.","ritual":false,"concentration":true,"duration":"Up to 1 hour","area":{"type":"sphere","size":10}}},{"id":"srd:spell:antipathy-sympathy","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Antipathy/Sympathy","description":"This spell attracts or repels creatures of your choice. You target something within range, either a Huge or smaller object or creature or an area that is no larger than a 200-foot cube. Then specify a kind of intelligent creature, such as red dragons, goblins, or vampires. You invest the target with an aura that either attracts or repels the specified creatures for the duration. Choose antipathy or sympathy as the aura's effect.\\n\\n***Antipathy.*** The enchantment causes creatures of the kind you designated to feel an intense urge to leave the area and avoid the target. When such a creature can see the target or comes within 60 feet of it, the creature must succeed on a wisdom saving throw or become frightened. The creature remains frightened while it can see the target or is within 60 feet of it. While frightened by the target, the creature must use its movement to move to the nearest safe spot from which it can't see the target. If the creature moves more than 60 feet from the target and can't see it, the creature is no longer frightened, but the creature becomes frightened again if it regains sight of the target or moves within 60 feet of it.\\n\\n***Sympathy.*** The enchantment causes the specified creatures to feel an intense urge to approach the target while within 60 feet of it or able to see it. When such a creature can see the target or comes within 60 feet of it, the creature must succeed on a wisdom saving throw or use its movement on each of its turns to enter the area or move within reach of the target. When the creature has done so, it can't willingly move away from the target.\\n\\nIf the target damages or otherwise harms an affected creature, the affected creature can make a wisdom saving throw to end the effect, as described below.\\n\\n***Ending the Effect.*** If an affected creature ends its turn while not within 60 feet of the target or able to see it, the creature makes a wisdom saving throw. On a successful save, the creature is no longer affected by the target and recognizes the feeling of repugnance or attraction as magical. In addition, a creature affected by the spell is allowed another wisdom saving throw every 24 hours while the spell persists.\\n\\nA creature that successfully saves against this effect is immune to it for 1 minute, after which time it can be affected again."},"it":{"name":"Antipatia/Simpatia","description":"Questo incantesimo attira o repelle le creature. L'incantatore sceglie un bersaglio entro gittata, che può essere un oggetto o una creatura di taglia Enorme o inferiore, oppure un'area non più ampia di un cubo di 60 metri. Dopodiché, specifica un tipo di creatura intelligente, come per esempio draghi rossi, goblin o vampiri. L'incantatore infonde nel bersaglio un'aura che attira oppure respinge le creature specificate per la durata dell'incantesimo, scegliendo antipatia o simpatia come suo effetto.\\n\\n***Antipatia.*** L'ammaliamento suscita nelle creature del tipo scelto dall'incantatore un intenso desiderio di abbandonare l'area ed evitare il bersaglio. Quando una tale creatura è in grado di vedere il bersaglio o si trova entro 18 metri da esso, deve superare un tiro salvezza su Saggezza, altrimenti ne rimane spaventata per tutto il tempo in cui il bersaglio si trova nel suo campo visivo o entro 18 metri da essa. Finché è spaventata dal bersaglio, la creatura deve usare il suo movimento per spostarsi verso il punto sicuro più vicino da cui non può vedere il bersaglio. Se si allontana a più di 18 metri dal bersaglio e non è più in grado di vederlo, la creatura non è più spaventata, ma lo diventa di nuovo se il bersaglio torna nel suo campo visivo o si trova entro 18 metri da essa.\\n\\n***Simpatia.*** L'ammaliamento suscita nelle creature del tipo scelto dall'incantatore un intenso desiderio di avvicinarsi al bersaglio quando si trovano a 18 metri da esso o se sono in grado di vederlo. Quando una tale creatura è in grado di vedere il bersaglio o si trova entro 18 metri da esso, deve superare un tiro salvezza su Saggezza o usare il suo movimento in ogni suo turno per entrare nell'area o muoversi entro la portata del bersaglio. Una volta fatto questo, la creatura non può allontanarsi dal bersaglio di sua spontanea volontà.\\n\\nSe il bersaglio infligge danni o in altro modo danneggia la creatura influenzata, questa può effettuare un tiro salvezza su Saggezza per porre fine all'effetto, come descritto di seguito.\\n\\n***Porre fine all'effetto.*** Se una creatura influenzata termina il suo turno a più di 18 metri dal bersaglio o non è in grado di vederlo, effettua un tiro salvezza su Saggezza. In caso di successo, la creatura non è più influenzata dal bersaglio e riconosce che la sensazione di ripugnanza o attrazione era frutto della magia. Inoltre, una creatura influenzata dall'incantesimo ha diritto a effettuare un ulteriore tiro salvezza su Saggezza ogni 24 ore finché l'incantesimo permane.\\n\\nUna creatura che supera un tiro salvezza contro l'effetto ne è immune per 1 minuto, al termine del quale può esserne influenzata di nuovo.","castingTime":"1 ora","range":"18 metri","duration":"10 giorni","material":"un frammento di allume immerso nell'aceto per l'effetto di antipatia o una goccia di miele per l'effetto di simpatia"}},"data":{"level":8,"school":"srd:rule:school-enchantment","classes":["srd:class:druid","srd:class:wizard"],"subclasses":[],"castingTime":"1 hour","range":"60 feet","components":["V","S","M"],"material":"Either a lump of alum soaked in vinegar for the antipathy effect or a drop of honey for the sympathy effect.","ritual":false,"concentration":false,"duration":"10 days","area":{"type":"cube","size":200}}},{"id":"srd:spell:arcane-eye","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Arcane Eye","description":"You create an invisible, magical eye within range that hovers in the air for the duration.\\n\\nYou mentally receive visual information from the eye, which has normal vision and darkvision out to 30 feet. The eye can look in every direction.\\n\\nAs an action, you can move the eye up to 30 feet in any direction. There is no limit to how far away from you the eye can move, but it can't enter another plane of existence. A solid barrier blocks the eye's movement, but the eye can pass through an opening as small as 1 inch in diameter."},"it":{"name":"Occhio arcano","description":"L'incantatore crea un occhio magico invisibile che fluttua nell'aria per la durata dell'incantesimo entro la sua gittata.\\n\\nL'incantatore riceve informazioni visive dall'occhio, che è dotato di visione normale e scurovisione fino a 9 metri e che può inoltre guardare in ogni direzione.\\n\\nCon un'azione, l'incantatore può muovere l'occhio per un massimo di 9 metri in ogni direzione. Non c'è limite alla distanza di cui l'occhio può allontanarsi dall'incantatore, purché non entri in un altro piano di esistenza. Una barriera solida blocca il movimento dell'occhio, che tuttavia può passare attraverso un'apertura dal diametro minimo di 2,5 centimetri.","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 1 ora","material":"un ciuffo di peli di pipistrello"}},"data":{"level":4,"school":"srd:rule:school-divination","classes":["srd:class:cleric","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A bit of bat fur.","ritual":false,"concentration":true,"duration":"Up to 1 hour","area":{"type":"sphere","size":30}}},{"id":"srd:spell:arcane-hand","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Arcane Hand","description":"You create a Large hand of shimmering, translucent force in an unoccupied space that you can see within range. The hand lasts for the spell's duration, and it moves at your command, mimicking the movements of your own hand.\\n\\nThe hand is an object that has AC 20 and hit points equal to your hit point maximum. If it drops to 0 hit points, the spell ends. It has a Strength of 26 (+8) and a Dexterity of 10 (+0). The hand doesn't fill its space.\\n\\nWhen you cast the spell and as a bonus action on your subsequent turns, you can move the hand up to 60 feet and then cause one of the following effects with it.\\n\\n***Clenched Fist.*** The hand strikes one creature or object within 5 feet of it. Make a melee spell attack for the hand using your game statistics. On a hit, the target takes 4d8 force damage.\\n\\n***Forceful Hand.*** The hand attempts to push a creature within 5 feet of it in a direction you choose. Make a check with the hand's Strength contested by the Strength (Athletics) check of the target. If the target is Medium or smaller, you have advantage on the check. If you succeed, the hand pushes the target up to 5 feet plus a number of feet equal to five times your spellcasting ability modifier. The hand moves with the target to remain within 5 feet of it.\\n\\n***Grasping Hand.*** The hand attempts to grapple a Huge or smaller creature within 5 feet of it. You use the hand's Strength score to resolve the grapple. If the target is Medium or smaller, you have advantage on the check. While the hand is grappling the target, you can use a bonus action to have the hand crush it. When you do so, the target takes bludgeoning damage equal to 2d6 + your spellcasting ability modifier.\\n\\n***Interposing Hand.*** The hand interposes itself between you and a creature you choose until you give the hand a different command. The hand moves to stay between you and the target, providing you with half cover against the target. The target can't move through the hand's space if its Strength score is less than or equal to the hand's Strength score. If its Strength score is higher than the hand's Strength score, the target can move toward you through the hand's space, but that space is difficult terrain for the target.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 6th level or higher, the damage from the clenched fist option increases by 2d8 and the damage from the grasping hand increases by 2d6 for each slot level above 5th."},"it":{"name":"Mano arcana","description":"L'incantatore crea una mano Grande di forza luccicante e traslucida in uno spazio libero entro gittata che è in grado di vedere. La mano permane per la durata dell'incantesimo e si muove al comando dell'incantatore, imitando i movimenti della sua mano.\\n\\nLa mano è un oggetto che possiede CA 20 e una quantità di punti ferita pari ai punti ferita massimi dell'incantatore; quando i punti ferita scendono a 0, l'incantesimo termina. La mano possiede una Forza pari a 26 (+8) e una Destrezza pari a 10 (+0). Inoltre, non riempie il suo spazio.\\n\\nQuando l'incantatore lancia l'incantesimo e come azione bonus nei suoi turni successivi, può muovere la mano per un massimo di 18 metri e poi causare uno dei seguenti effetti.\\n\\n***Mano interposta.*** La mano si interpone tra l'incantatore e una creatura a sua scelta finché non le è impartito un comando diverso. Essa si muove tra l'incantatore e il bersaglio, fornendogli mezza copertura contro quest'ultimo. Il bersaglio non può muoversi nello spazio della mano se il suo punteggio di Forza è pari o inferiore a quello della mano. Se il punteggio di Forza del bersaglio è superiore a quello della mano, esso si può muovere verso l'incantatore attraversando il suo spazio, che tuttavia risulta per lui un terreno difficile.\\n\\n***Mano possente.*** La mano tenta di spingere una creatura che si trova entro 1,5 metri da essa in una direzione a scelta dell'incantatore. Quest'ultimo effettua una prova con la Forza della mano contrapposta alla prova di Forza (Atletica) del bersaglio. Se il bersaglio è di taglia Media o inferiore, l'incantatore dispone di vantaggio alla prova. In caso di successo, la mano spinge il bersaglio fino a una distanza pari a 1,5 metri, più un numero di metri pari a cinque volte il modificatore di caratteristica da incantatore. La mano si muove insieme al bersaglio in modo da rimanere entro 1,5 metri da esso.\\n\\n***Mano stritolatrice.*** La mano tenta di afferrare una creatura di taglia Enorme o inferiore situata entro 1,5 metri da essa: l'incantatore utilizza il punteggio di Forza della mano per risolvere la presa. Se il bersaglio è di taglia Media o inferiore, l'incantatore dispone di vantaggio alla prova. Mentre la mano afferra il bersaglio, l'incantatore può usare un'azione bonus per ordinarle di stritolarlo. In questo caso, il bersaglio subisce 2d6 danni contundenti + il modificatore di caratteristica da incantatore.\\n\\n***Pugno serrato.*** La mano colpisce una creatura o un oggetto situato entro 1,5 metri da essa. Con questo incantesimo l'incantatore effettua un attacco in mischia per la mano usando le proprie statistiche di gioco. Se il colpo va a segno, il bersaglio subisce 4d8 danni da forza.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, i danni provocati dall'opzione pugno serrato aumentano di 2d8 e quelli provocati da mano stritolatrice di 2d6 per ogni slot di livello superiore al 5°.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 1 minuto","material":"un guscio d'uovo e un guanto di pelle di serpente"}},"data":{"level":5,"school":"srd:rule:school-evocation","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","components":["V","S","M"],"material":"An eggshell and a snakeskin glove.","ritual":false,"concentration":true,"duration":"Up to 1 minute"}},{"id":"srd:spell:arcane-lock","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Arcane Lock","description":"You touch a closed door, window, gate, chest, or other entryway, and it becomes locked for the duration. You and the creatures you designate when you cast this spell can open the object normally. You can also set a password that, when spoken within 5 feet of the object, suppresses this spell for 1 minute. Otherwise, it is impassable until it is broken or the spell is dispelled or suppressed. Casting knock on the object suppresses arcane lock for 10 minutes.\\n\\nWhile affected by this spell, the object is more difficult to break or force open; the DC to break it or pick any locks on it increases by 10."},"it":{"name":"Serratura arcana","description":"L'incantatore tocca una porta, una finestra, un portale, un forziere o un altro punto di accesso chiuso, che diventa chiuso a chiave per la durata dell'incantesimo. L'incantatore e le creature da lui designate al momento del lancio dell'incantesimo possono aprire l'oggetto normalmente. L'incantatore può anche stabilire una parola d'ordine che, una volta pronunciata entro 1,5 metri dall'oggetto, sopprime l'incantesimo per 1 minuto. Altrimenti l'oggetto è impenetrabile finché non viene rotto o finché l'incantesimo non viene dissolto o soppresso. Lanciare scassinare sull'oggetto sopprime serratura arcana per 10 minuti.\\n\\nFinché è influenzato da questo incantesimo, l'oggetto è più difficile da rompere o da forzare perché la CD per romperlo o per scassinare le eventuali serrature presenti aumenta di 10.","castingTime":"1 azione","range":"Contatto","duration":"Finché non viene dissolto","material":"polvere d'oro del valore di almeno 25 mo, che l'incantesimo consuma"}},"data":{"level":2,"school":"srd:rule:school-abjuration","classes":["srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"Gold dust worth at least 25gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"Until dispelled"}},{"id":"srd:spell:arcane-sword","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Arcane Sword","description":"You create a sword-shaped plane of force that hovers within range. It lasts for the duration.\\n\\nWhen the sword appears, you make a melee spell attack against a target of your choice within 5 feet of the sword. On a hit, the target takes 3d10 force damage. Until the spell ends, you can use a bonus action on each of your turns to move the sword up to 20 feet to a spot you can see and repeat this attack against the same target or a different one."},"it":{"name":"Spada arcana","description":"L'incantatore crea un piano di forza a forma di spada che fluttua entro gittata e permane per tutta la durata dell'incantesimo.\\n\\nQuando la spada appare, l'incantatore può effettuare un attacco in mischia con questo incantesimo contro un bersaglio a sua scelta che si trova entro 1,5 metri dalla spada. Se il colpo va a segno, il bersaglio subisce 3d10 danni da forza. Finché l'incantesimo non termina, l'incantatore può usare un'azione bonus in ogni suo turno per muovere la spada per un massimo di 6 metri fino a un punto che è in grado di vedere e ripetere questo attacco contro lo stesso bersaglio o contro uno diverso.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 minuto","material":"una spada di platino in miniatura dall'impugnatura e dal pomolo di rame e zinco, del valore di 250 mo"}},"data":{"level":7,"school":"srd:rule:school-evocation","classes":["srd:class:bard","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"A miniature platinum sword with a grip and pommel of copper and zinc, worth 250 gp.","ritual":false,"concentration":true,"duration":"Up to 1 minute","damage":[{"type":"srd:rule:damage-force","atSlotLevel":{"7":"3d10"}}],"attackType":"melee"}},{"id":"srd:spell:arcanists-magic-aura","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Arcanist's Magic Aura","description":"You place an illusion on a creature or an object you touch so that divination spells reveal false information about it. The target can be a willing creature or an object that isn't being carried or worn by another creature.\\n\\nWhen you cast the spell, choose one or both of the following effects. The effect lasts for the duration. If you cast this spell on the same creature or object every day for 30 days, placing the same effect on it each time, the illusion lasts until it is dispelled.\\n\\n***False Aura.*** You change the way the target appears to spells and magical effects, such as detect magic, that detect magical auras. You can make a nonmagical object appear magical, a magical object appear nonmagical, or change the object's magical aura so that it appears to belong to a specific school of magic that you choose. When you use this effect on an object, you can make the false magic apparent to any creature that handles the item.\\n\\n***Mask.*** You change the way the target appears to spells and magical effects that detect creature types, such as a paladin's Divine Sense or the trigger of a symbol spell. You choose a creature type and other spells and magical effects treat the target as if it were a creature of that type or of that alignment."},"it":{"name":"Aura magica dell'arcanista","description":"L'incantatore pone con il suo tocco un'illusione su una creatura o un oggetto in modo che gli incantesimi di divinazione rivelino informazioni false su di esso. Il bersaglio può essere una creatura consenziente o un oggetto che non sia trasportato o indossato da un'altra creatura.\\n\\nQuando questo incantesimo viene lanciato, l'incantatore sceglie uno o entrambi gli effetti seguenti, che permangono per tutta la durata dell'incantesimo. Se l'incantatore lancia questo incantesimo sulla stessa creatura o sullo stesso oggetto ogni giorno per 30 giorni, ponendo ogni volta su di esso lo stesso effetto, l'illusione permane finché non viene dissolta.\\n\\n***Falsa aura.*** L'incantatore modifica il modo in cui il bersaglio appare agli incantesimi e agli effetti magici che individuano le aure magiche, come per esempio individuazione del magico. L'incantatore può fare in modo che un oggetto non magico appaia come magico e viceversa, oppure può cambiare l'aura magica di un oggetto in modo che sembri appartenere a una scuola di magia specifica a sua scelta. Quando usa questo effetto su un oggetto, l'incantatore può rendere la falsa magia apparente a qualsiasi creatura che maneggi l'oggetto.\\n\\n***Maschera.*** L'incantatore modifica il modo in cui il bersaglio appare agli incantesimi e agli effetti magici che individuano i tipi di creature, come per esempio Percezione del divino dei paladini o l'innesco di un incantesimo simbolo. L'incantatore sceglie un tipo di creatura: gli altri incantesimi ed effetti magici considereranno il bersaglio come fosse una creatura di quel tipo o allineamento.","castingTime":"1 azione","range":"Contatto","duration":"24 ore","material":"un piccolo quadrato di seta"}},"data":{"level":2,"school":"srd:rule:school-illusion","classes":["srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A small square of silk.","ritual":false,"concentration":false,"duration":"24 hours"}},{"id":"srd:spell:astral-projection","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Astral Projection","description":"You and up to eight willing creatures within range project your astral bodies into the Astral Plane (the spell fails and the casting is wasted if you are already on that plane). The material body you leave behind is unconscious and in a state of suspended animation; it doesn't need food or air and doesn't age.\\n\\nYour astral body resembles your mortal form in almost every way, replicating your game statistics and possessions. The principal difference is the addition of a silvery cord that extends from between your shoulder blades and trails behind you, fading to invisibility after 1 foot. This cord is your tether to your material body. As long as the tether remains intact, you can find your way home. If the cord is cut--something that can happen only when an effect specifically states that it does--your soul and body are separated, killing you instantly.\\n\\nYour astral form can freely travel through the Astral Plane and can pass through portals there leading to any other plane. If you enter a new plane or return to the plane you were on when casting this spell, your body and possessions are transported along the silver cord, allowing you to re-enter your body as you enter the new plane. Your astral form is a separate incarnation. Any damage or other effects that apply to it have no effect on your physical body, nor do they persist when you return to it.\\n\\nThe spell ends for you and your companions when you use your action to dismiss it. When the spell ends, the affected creature returns to its physical body, and it awakens.\\n\\nThe spell might also end early for you or one of your companions. A successful dispel magic spell used against an astral or physical body ends the spell for that creature. If a creature's original body or its astral form drops to 0 hit points, the spell ends for that creature. If the spell ends and the silver cord is intact, the cord pulls the creature's astral form back to its body, ending its state of suspended animation.\\n\\nIf you are returned to your body prematurely, your companions remain in their astral forms and must find their own way back to their bodies, usually by dropping to 0 hit points."},"it":{"name":"Proiezione astrale","description":"L'incantatore e un massimo di otto creature consenzienti entro gittata proiettano i loro corpi astrali sul Piano Astrale (l'incantesimo fallisce e il lancio è sprecato se l'incantatore si trova già su quel piano). Il corpo materiale abbandonato cade privo di sensi e in uno stato di animazione sospesa; non ha bisogno di cibo o aria e non invecchia.\\n\\nIl corpo astrale assomiglia alla forma mortale dell'incantatore in ogni particolare e replica le sue statistiche di gioco e proprietà. La differenza principale consiste nell'aggiunta di un cordone argentato che si snoda tra le scapole dell'incantatore e fluttua alle sue spalle, diventando invisibile dopo 30 cm. Questo cordone tiene ancorato l'incantatore al suo corpo materiale e, finché rimane intatto, l'incantatore può trovare la strada del ritorno. Se il cordone viene reciso, cosa che può accadere solo quando un effetto lo specifica chiaramente, l'anima e il corpo vengono separati, uccidendo l'incantatore all'istante.\\n\\nLa forma astrale dell'incantatore può viaggiare liberamente per il Piano Astrale e passare attraverso i portali che da lì conducono su altri piani. Se l'incantatore si sposta su un nuovo piano o ritorna al piano in cui si trovava quando ha lanciato l'incantesimo, il suo corpo e le sue proprietà vengono trasportati lungo il cordone argentato, permettendogli di rientrare nel suo corpo nel momento in cui accede al nuovo piano. La forma astrale è un'incarnazione separata: ogni danno o altro effetto che si applichi a essa non ha effetto sul corpo fisico dell'incantatore e non persiste quando vi fa ritorno.\\n\\nL'incantesimo termina per l'incantatore e i suoi compagni quando l'incantatore utilizza la sua azione per interromperlo. Al termine dell'incantesimo, la creatura influenzata ritorna nel suo corpo fisico e si risveglia.\\n\\nÈ anche possibile che l'incantesimo termini prematuramente per l'incantatore e i suoi compagni: un incantesimo dissolvi magie lanciato con successo contro una forma astrale o un corpo fisico termina l'incantesimo per quella creatura. Inoltre, l'incantesimo termina se il corpo originale o la forma astrale di una creatura scende a 0 punti ferita. Se l'incantesimo termina e il cordone argentato è ancora intatto, questo trascina la forma astrale della creatura all'interno del suo corpo, ponendo fine allo stato di animazione sospesa.\\n\\nSe l'incantatore è tornano prematuramente nel suo corpo, i suoi compagni rimangono nelle loro forme astrali e devono trovare da soli il modo di rientrare nei loro corpi, solitamente scendendo a 0 punti ferita.","castingTime":"1 ora","range":"3 metri","duration":"Speciale","material":"per ogni creatura influenzata da questo incantesimo, l'incantatore deve fornire un giacinto del valore di almeno 1.000 mo e un lingotto d'argento finemente decorato del valore di almeno 100 mo, che l'incantesimo consuma"}},"data":{"level":9,"school":"srd:rule:school-necromancy","classes":["srd:class:cleric","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 hour","range":"10 feet","components":["V","S","M"],"material":"For each creature you affect with this spell, you must provide one jacinth worth at least 1,000gp and one ornately carved bar of silver worth at least 100gp, all of which the spell consumes.","ritual":false,"concentration":false,"duration":"Special"}},{"id":"srd:spell:augury","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Augury","description":"By casting gem-inlaid sticks, rolling dragon bones, laying out ornate cards, or employing some other divining tool, you receive an omen from an otherworldly entity about the results of a specific course of action that you plan to take within the next 30 minutes. The GM chooses from the following possible omens:\\n\\n- Weal, for good results\\n\\n- Woe, for bad results\\n\\n- Weal and woe, for both good and bad results\\n\\n- Nothing, for results that aren't especially good or bad\\n\\nThe spell doesn't take into account any possible circumstances that might change the outcome, such as the casting of additional spells or the loss or gain of a companion.\\n\\nIf you cast the spell two or more times before completing your next long rest, there is a cumulative 25 percent chance for each casting after the first that you get a random reading. The GM makes this roll in secret."},"it":{"name":"Presagio","description":"Lanciando bastoncini incastonati di gemme o ossa di drago, rivelando carte illustrate o usando altri strumenti di divinazione, l'incantatore riceve un segno da un'entità ultraterrena riguardo al risultato di un corso d'azione specifico che intende intraprendere entro i prossimi 30 minuti. Il GM sceglie tra i seguenti presagi possibili:\\n\\n- Ventura, se l'azione fornisce risultati positivi\\n\\n- Sventura, se l'azione fornisce risultati negativi\\n\\n- Ventura e sventura, se l'azione fornisce risultati sia positivi che negativi\\n\\n- Nulla, se non ci sono risultati positivi o negativi rilevanti\\n\\nL'incantesimo non prende in considerazione le potenziali circostanze che potrebbero alterare l'esito del presagio, come per esempio il lancio di incantesimi aggiuntivi o la perdita o l'acquisizione di un compagno.\\n\\nSe l'incantatore lancia l'incantesimo due o più volte prima di completare il suo riposo lungo successivo, esiste una probabilità cumulativa del 25% di ottenere un responso casuale per ogni lancio dopo il primo. Il GM effettua questo tiro in segreto.","castingTime":"1 minuto","range":"Incantatore","duration":"Istantanea","material":"bastoncini, ossa o oggetti simili dotati di contrassegni speciali, del valore di almeno 25 mo"}},"data":{"level":2,"school":"srd:rule:school-divination","classes":["srd:class:cleric"],"subclasses":["srd:subclass:lore"],"castingTime":"1 minute","range":"Self","components":["V","S","M"],"material":"Specially marked sticks, bones, or similar tokens worth at least 25gp.","ritual":true,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:awaken","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Awaken","description":"After spending the casting time tracing magical pathways within a precious gemstone, you touch a Huge or smaller beast or plant. The target must have either no Intelligence score or an Intelligence of 3 or less. The target gains an Intelligence of 10. The target also gains the ability to speak one language you know. If the target is a plant, it gains the ability to move its limbs, roots, vines, creepers, and so forth, and it gains senses similar to a human's. Your GM chooses statistics appropriate for the awakened plant, such as the statistics for the awakened shrub or the awakened tree.\\n\\nThe awakened beast or plant is charmed by you for 30 days or until you or your companions do anything harmful to it. When the charmed condition ends, the awakened creature chooses whether to remain friendly to you, based on how you treated it while it was charmed."},"it":{"name":"Risveglio","description":"Dopo aver trascorso il tempo di lancio tracciando percorsi magici su una pietra preziosa, l'incantatore tocca una bestia o un vegetale di taglia Enorme o inferiore. Il bersaglio deve essere privo di un punteggio di Intelligenza o possedere Intelligenza pari o inferiore a 3. Il bersaglio ottiene Intelligenza pari a 10 e la capacità di parlare un linguaggio conosciuto dall'incantatore. Se il bersaglio è un vegetale, ottiene l'abilità di muovere i suoi rami, radici, liane, rampicanti e così via e sviluppa sensi simili a quelli umani. Il GM sceglie le statistiche appropriate per il vegetale risvegliato, come per esempio nel caso di un cespuglio o un albero risvegliato.\\n\\nLa bestia o il vegetale risvegliato rimane affascinato dall'incantatore per 30 giorni o finché quest'ultimo o i suoi compagni non lo danneggiano in qualche modo. Quando la condizione di affascinato termina, la creatura risvegliata sceglie se rimanere amichevole o meno nei confronti dell'incantatore, in base a com'è stata trattata quando affascinata.","castingTime":"8 ore","range":"Contatto","duration":"Istantanea","material":"un'agata del valore di almeno 1.000 mo, che l'incantesimo consuma"}},"data":{"level":5,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:druid"],"subclasses":[],"castingTime":"8 hours","range":"Touch","components":["V","S","M"],"material":"An agate worth at least 1,000 gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:bane","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Bane","description":"Up to three creatures of your choice that you can see within range must make charisma saving throws. Whenever a target that fails this saving throw makes an attack roll or a saving throw before the spell ends, the target must roll a d4 and subtract the number rolled from the attack roll or saving throw.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st."},"it":{"name":"Anatema","description":"L'incantatore sceglie fino a tre creature situate entro gittata e che è in grado di vedere, le quali devono effettuare tiri salvezza su Carisma. Se un bersaglio fallisce questo tiro salvezza, ogni volta che effettua un tiro per colpire o un tiro salvezza prima che l'incantesimo termini, deve tirare un d4 e sottrarre il numero ottenuto al tiro per colpire o al tiro salvezza.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1°.","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 1 minuto","material":"una goccia di sangue"}},"data":{"level":1,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:cleric"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A drop of blood.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"cha","onSuccess":"none"}}},{"id":"srd:spell:banishment","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Banishment","description":"You attempt to send one creature that you can see within range to another plane of existence. The target must succeed on a charisma saving throw or be banished.\\n\\nIf the target is native to the plane of existence you're on, you banish the target to a harmless demiplane. While there, the target is incapacitated. The target remains there until the spell ends, at which point the target reappears in the space it left or in the nearest unoccupied space if that space is occupied.\\n\\nIf the target is native to a different plane of existence than the one you're on, the target is banished with a faint popping noise, returning to its home plane. If the spell ends before 1 minute has passed, the target reappears in the space it left or in the nearest unoccupied space if that space is occupied. Otherwise, the target doesn't return.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 5th level or higher, you can target one additional creature for each slot level above 4th."},"it":{"name":"Esilio","description":"L'incantatore tenta di inviare su un altro piano di esistenza una creatura entro gittata e che è in grado di vedere. Il bersaglio deve superare un tiro salvezza su Carisma altrimenti viene esiliato.\\n\\nSe il bersaglio proviene dal piano di esistenza su cui si trova, l'incantatore lo esilia su un semipiano innocuo. Finché si trova nel semipiano, il bersaglio è incapacitato e rimane in quel luogo fino al termine dell'incantesimo, per poi riapparire nello spazio che ha lasciato o nello spazio libero più vicino se tale spazio è occupato.\\n\\nSe il bersaglio proviene da un piano di esistenza differente di quello su cui si trova, viene esiliato sul suo piano di origine producendo un suono simile a un debole scoppio. Se l'incantesimo termina prima che sia trascorso 1 minuto, il bersaglio riapparire nello spazio che ha lasciato o nello spazio libero più vicino se tale spazio è occupato; altrimenti non fa ritorno.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 5° livello o superiore, può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 4°.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 minuto","material":"un oggetto sgradito al bersaglio"}},"data":{"level":4,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric","srd:class:paladin","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"An item distasteful to the target.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"cha","onSuccess":"none"}}},{"id":"srd:spell:barkskin","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Barkskin","description":"You touch a willing creature. Until the spell ends, the target's skin has a rough, bark-like appearance, and the target's AC can't be less than 16, regardless of what kind of armor it is wearing."},"it":{"name":"Pelle coriacea","description":"L'incantatore tocca una creatura consenziente. Finché l'incantesimo non termina, la pelle del bersaglio assume un aspetto ruvido simile alla corteccia e la sua CA non può essere inferiore a 16, a prescindere dal tipo di armatura indossata.","castingTime":"1 azione","range":"Contatto","duration":"Concentrazione, fino a 1 ora","material":"una manciata di corteccia di quercia"}},"data":{"level":2,"school":"srd:rule:school-transmutation","classes":["srd:class:druid","srd:class:ranger"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A handful of oak bark.","ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:beacon-of-hope","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Beacon of Hope","description":"This spell bestows hope and vitality. Choose any number of creatures within range. For the duration, each target has advantage on wisdom saving throws and death saving throws, and regains the maximum number of hit points possible from any healing."},"it":{"name":"Faro di speranza","description":"Questo incantesimo infonde speranza e vitalità. L'incantatore sceglie un qualsiasi numero di creature entro gittata. Per la durata dell'incantesimo, ogni bersaglio dispone di vantaggio ai tiri salvezza su Saggezza, ai tiri salvezza contro morte e recupera il numero massimo di punti ferita possibile da qualsiasi guarigione.","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":3,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric"],"subclasses":["srd:subclass:lore","srd:subclass:life","srd:subclass:devotion"],"castingTime":"1 action","range":"30 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute"}},{"id":"srd:spell:bestow-curse","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Bestow Curse","description":"You touch a creature, and that creature must succeed on a wisdom saving throw or become cursed for the duration of the spell. When you cast this spell, choose the nature of the curse from the following options:\\n\\n- Choose one ability score. While cursed, the target has disadvantage on ability checks and saving throws made with that ability score.\\n\\n- While cursed, the target has disadvantage on attack rolls against you.\\n\\n- While cursed, the target must make a wisdom saving throw at the start of each of its turns. If it fails, it wastes its action that turn doing nothing.\\n\\n- While the target is cursed, your attacks and spells deal an extra 1d8 necrotic damage to the target.\\n\\nA remove curse spell ends this effect. At the GM's option, you may choose an alternative curse effect, but it should be no more powerful than those described above. The GM has final say on such a curse's effect.\\n\\n**At Higher Levels.** If you cast this spell using a spell slot of 4th level or higher, the duration is concentration, up to 10 minutes. If you use a spell slot of 5th level or higher, the duration is 8 hours. If you use a spell slot of 7th level or higher, the duration is 24 hours. If you use a 9th level spell slot, the spell lasts until it is dispelled. Using a spell slot of 5th level or higher grants a duration that doesn't require concentration."},"it":{"name":"Scagliare maledizione","description":"L'incantatore tocca una creatura, che deve superare un tiro salvezza su Saggezza, altrimenti verrà maledetta per la durata dell'incantesimo. Quando lancia questo incantesimo, l'incantatore sceglie la natura della maledizione tra le seguenti opzioni:\\n\\n- L'incantatore sceglie un punteggio di caratteristica. Mentre è maledetto, il bersaglio subisce svantaggio alle prove di caratteristica e ai tiri salvezza effettuati con quel punteggio di caratteristica.\\n\\n- Mentre è maledetto, il bersaglio ha svantaggio ai tiri per colpire contro l'incantatore.\\n\\n- Mentre è maledetto, il bersaglio deve effettuare un tiro salvezza su Saggezza all'inizio di ogni suo turno. Se lo fallisce, spreca la sua azione in quel turno senza fare nulla.\\n\\n- Mentre è maledetto, gli attacchi e gli incantesimi dell'incantatore infliggono al bersaglio 1d8 danni necrotici extra.\\n\\nUn incantesimo rimuovi maledizione pone fine a questo effetto. A discrezione del GM, l'incantatore può scegliere un effetto alternativo per la maledizione, che tuttavia non dovrebbe risultare più potente di quelli descritti sopra. Il GM ha l'ultima parola su tali effetti della maledizione.\\n\\n**Ai livelli superiori.** Se l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, la durata diventa concentrazione, fino a 10 minuti. Se usa uno slot incantesimo di 5° livello o superiore, la durata diventa 8 ore. Se usa uno slot incantesimo di 7° livello o superiore, la durata è di 24 ore. Se usa uno slot incantesimo di 9° livello, l'incantesimo dura finché non viene dissolto. Usando uno slot incantesimo di 5° livello o superiore, la durata non richiede concentrazione.","castingTime":"1 azione","range":"Contatto","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":3,"school":"srd:rule:school-necromancy","classes":["srd:class:bard","srd:class:cleric","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:black-tentacles","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Black Tentacles","description":"Squirming, ebony tentacles fill a 20-foot square on ground that you can see within range. For the duration, these tentacles turn the ground in the area into difficult terrain.\\n\\nWhen a creature enters the affected area for the first time on a turn or starts its turn there, the creature must succeed on a Dexterity saving throw or take 3d6 bludgeoning damage and be restrained by the tentacles until the spell ends. A creature that starts its turn in the area and is already restrained by the tentacles takes 3d6 bludgeoning damage.\\n\\nA creature restrained by the tentacles can use its action to make a Strength or Dexterity check (its choice) against your spell save DC. On a success, it frees itself."},"it":{"name":"Tentacoli neri","description":"Una massa in movimento di tentacoli color ebano riempie un quadrato con lato di 6 metri situato sul terreno entro gittata e che l'incantatore è in grado di vedere. Per la durata dell'incantesimo, questi tentacoli trasformano quell'area in un terreno difficile.\\n\\nQuando una creatura entra nell'area influenzata per la prima volta in un turno o inizia il suo turno qui, deve superare un tiro salvezza su Destrezza, altrimenti subisce 3d6 danni contundenti ed è trattenuta dai tentacoli fino alla fine dell'incantesimo. Qualsiasi creatura che inizi il proprio turno nell'area e sia già trattenuta dai tentacoli subisce 3d6 danni contundenti.\\n\\nUna creatura trattenuta dai tentacoli può usare la sua azione per effettuare una prova di Forza o Destrezza (a sua scelta) contro la CD del tiro salvezza sull'incantesimo. In caso di successo, si libera.","castingTime":"1 azione","range":"27 metri","duration":"Concentrazione, fino a 1 minuto","material":"un pezzo di tentacolo appartenente a una piovra o una seppia gigante"}},"data":{"level":4,"school":"srd:rule:school-conjuration","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"90 feet","components":["V","S","M"],"material":"A piece of tentacle from a giant octopus or a giant squid","ritual":false,"concentration":true,"duration":"Up to 1 minute","damage":[{"type":"srd:rule:damage-bludgeoning","atSlotLevel":{"4":"3d6"}}],"savingThrow":{"ability":"dex","onSuccess":"none"},"area":{"type":"cube","size":20}}},{"id":"srd:spell:blade-barrier","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Blade Barrier","description":"You create a vertical wall of whirling, razor-sharp blades made of magical energy. The wall appears within range and lasts for the duration. You can make a straight wall up to 100 feet long, 20 feet high, and 5 feet thick, or a ringed wall up to 60 feet in diameter, 20 feet high, and 5 feet thick. The wall provides three-quarters cover to creatures behind it, and its space is difficult terrain.\\n\\nWhen a creature enters the wall's area for the first time on a turn or starts its turn there, the creature must make a dexterity saving throw. On a failed save, the creature takes 6d10 slashing damage. On a successful save, the creature takes half as much damage."},"it":{"name":"Barriera di lame","description":"L'incantatore crea un muro verticale di lame affilate e turbinanti, composte da energia magica. Il muro compare entro gittata e permane per la durata dell'incantesimo. L'incantatore può creare un muro lineare lungo fino a 30 metri, alto 6 metri e spesso 1,5 metri, oppure un muro circolare del diametro massimo di 18 metri, alto 6 metri e spesso 1,5 metri. Il muro garantisce tre quarti di copertura alle creature che vi si trovano dietro e il suo spazio è un terreno difficile.\\n\\nQuando una creatura entra nell'area del muro per la prima volta in un turno o inizia il suo turno qui, deve superare un tiro salvezza su Destrezza. Se fallisce il tiro salvezza, la creatura subisce 6d10 danni taglienti. In caso di successo, subisce invece soltanto la metà di quei danni.","castingTime":"1 azione","range":"27 metri","duration":"Concentrazione, fino a 10 minuti"}},"data":{"level":6,"school":"srd:rule:school-evocation","classes":["srd:class:cleric"],"subclasses":[],"castingTime":"1 action","range":"90 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 10 minutes","damage":[{"type":"srd:rule:damage-slashing","atSlotLevel":{"6":"6d10"}}],"savingThrow":{"ability":"dex","onSuccess":"half"},"area":{"type":"line","size":100}}},{"id":"srd:spell:bless","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Bless","description":"You bless up to three creatures of your choice within range. Whenever a target makes an attack roll or a saving throw before the spell ends, the target can roll a d4 and add the number rolled to the attack roll or saving throw.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st."},"it":{"name":"Benedizione","description":"L'incantatore benedice fino a tre creature a sua scelta entro gittata. Ogni volta che un bersaglio effettua un tiro per colpire o un tiro salvezza prima che l'incantesimo termini, può tirare un d4 e aggiungere il numero ottenuto al tiro per colpire o al tiro salvezza.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1°.","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 1 minuto","material":"uno spruzzo di acqua santa"}},"data":{"level":1,"school":"srd:rule:school-enchantment","classes":["srd:class:cleric","srd:class:paladin"],"subclasses":["srd:subclass:lore","srd:subclass:life"],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A sprinkling of holy water.","ritual":false,"concentration":true,"duration":"Up to 1 minute"}},{"id":"srd:spell:blight","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Blight","description":"Necromantic energy washes over a creature of your choice that you can see within range, draining moisture and vitality from it. The target must make a constitution saving throw. The target takes 8d8 necrotic damage on a failed save, or half as much damage on a successful one. The spell has no effect on undead or constructs.\\n\\nIf you target a plant creature or a magical plant, it makes the saving throw with disadvantage, and the spell deals maximum damage to it.\\n\\nIf you target a nonmagical plant that isn't a creature, such as a tree or shrub, it doesn't make a saving throw; it simply withers and dies.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 5th level of higher, the damage increases by 1d8 for each slot level above 4th."},"it":{"name":"Inaridire","description":"L'energia necromantica si riversa su una creatura a scelta dell'incantatore, situata entro la sua gittata e che è in grado di vedere. Il bersaglio deve effettuare un tiro salvezza su Costituzione. In caso di fallimento, subisce 8d8 danni necrotici, o la metà dei danni in caso di successo. Questo incantesimo non ha effetto sui non morti o sui costrutti.\\n\\nSe l'incantatore bersaglia una creatura vegetale o un vegetale magico, tale bersaglio effettua il tiro salvezza con svantaggio e l'incantesimo infligge il massimo dei danni.\\n\\nSe l'incantatore bersaglia un vegetale non magico che non è una creatura, come un albero o un arbusto, tale bersaglio non effettua un tiro salvezza, ma semplicemente avvizzisce e muore.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 5° livello o superiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 4°.","castingTime":"1 azione","range":"9 metri","duration":"Istantanea"}},"data":{"level":4,"school":"srd:rule:school-necromancy","classes":["srd:class:druid","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:land"],"castingTime":"1 action","range":"30 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-necrotic","atSlotLevel":{"4":"8d8","5":"9d8","6":"10d8","7":"11d8","8":"12d8","9":"13d8"}}],"savingThrow":{"ability":"con","onSuccess":"half"}}},{"id":"srd:spell:blindness-deafness","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Blindness/Deafness","description":"You can blind or deafen a foe. Choose one creature that you can see within range to make a constitution saving throw. If it fails, the target is either blinded or deafened (your choice) for the duration. At the end of each of its turns, the target can make a constitution saving throw. On a success, the spell ends.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd."},"it":{"name":"Cecità/Sordità","description":"L'incantatore può accecare o assordare un nemico, scegliendo una creatura entro gittata e che è in grado di vedere, che deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, il bersaglio è accecato o assordato (a scelta dell'incantatore) per tutta la durata dell'incantesimo. Il bersaglio può effettuare un altro tiro salvezza su Costituzione alla fine di ogni suo turno. In caso di successo, l'incantesimo termina.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, può bersagliare una creatura aggiuntiva per ogni slot superiore al 2°.","castingTime":"1 azione","range":"9 metri","duration":"1 minuto"}},"data":{"level":2,"school":"srd:rule:school-necromancy","classes":["srd:class:bard","srd:class:cleric","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:fiend"],"castingTime":"1 action","range":"30 feet","components":["V"],"ritual":false,"concentration":false,"duration":"1 minute","savingThrow":{"ability":"con","onSuccess":"none"}}},{"id":"srd:spell:blink","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Blink","description":"Roll a d20 at the end of each of your turns for the duration of the spell. On a roll of 11 or higher, you vanish from your current plane of existence and appear in the Ethereal Plane (the spell fails and the casting is wasted if you were already on that plane). At the start of your next turn, and when the spell ends if you are on the Ethereal Plane, you return to an unoccupied space of your choice that you can see within 10 feet of the space you vanished from. If no unoccupied space is available within that range, you appear in the nearest unoccupied space (chosen at random if more than one space is equally near). You can dismiss this spell as an action.\\n\\nWhile on the Ethereal Plane, you can see and hear the plane you originated from, which is cast in shades of gray, and you can't see anything there more than 60 feet away. You can only affect and be affected by other creatures on the Ethereal Plane. Creatures that aren't there can't perceive you or interact with you, unless they have the ability to do so."},"it":{"name":"Intermittenza","description":"L'incantatore tira un d20 alla fine di ogni suo turno per la durata dell'incantesimo. Con un risultato pari o superiore a 11, l'incantatore svanisce dal piano di esistenza in cui si trova per riapparire sul Piano Etereo (l'incantesimo non funziona e il lancio va sprecato se l'incantatore si trova già su quel piano). All'inizio del suo turno successivo, e quando l'incantesimo termina nel caso l'incantatore si trovi già sul Piano Etereo, l'incantatore ritorna in uno spazio libero a sua scelta, che è in grado di vedere e situato entro 3 metri dal punto in cui è svanito. Se nessuno spazio libero è disponibile entro quel raggio, l'incantatore appare nello spazio libero più vicino (scelto casualmente se più spazi liberi si trovano a pari distanza). Con un'azione, l'incantatore può terminare questo incantesimo.\\n\\nMentre si trova sul Piano Etereo, l'incantatore può sentire e vedere il piano da cui proviene, che è proiettato in scala di grigi ed è visibile solo fino a una distanza di 18 metri. L'incantatore può influenzare ed essere influenzato solo dalle creature che si trovano sul Piano Etereo. Quelle che non sono presenti sul piano non possono percepire o interagire con l'incantatore, a meno che non siano dotate di una qualche capacità per farlo.","castingTime":"1 azione","range":"Incantatore","duration":"1 minuto"}},"data":{"level":3,"school":"srd:rule:school-transmutation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":false,"concentration":false,"duration":"1 minute"}},{"id":"srd:spell:blur","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Blur","description":"Your body becomes blurred, shifting and wavering to all who can see you. For the duration, any creature has disadvantage on attack rolls against you. An attacker is immune to this effect if it doesn't rely on sight, as with blindsight, or can see through illusions, as with truesight."},"it":{"name":"Sfocatura","description":"Il corpo dell'incantatore diventa sfocato, instabile e ondeggiante agli occhi di chiunque sia in grado di vederlo. Per la durata dell'incantesimo, tutte le creature subiscono svantaggio ai tiri per colpire contro l'incantatore. Un attaccante è immune a questo effetto se non si affida alla vista naturale, per esempio se è dotato di vista cieca o se è in grado di vedere attraverso le illusioni, come nel caso di vista pura.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":2,"school":"srd:rule:school-illusion","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"Self","components":["V"],"ritual":false,"concentration":true,"duration":"Up to 1 minute"}},{"id":"srd:spell:branding-smite","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Branding Smite","description":"The next time you hit a creature with a weapon attack before this spell ends, the weapon gleams with astral radiance as you strike. The attack deals an extra 2d6 radiant damage to the target, which becomes visible if it's invisible, and the target sheds dim light in a 5-foot radius and can't become invisible until the spell ends.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, the extra damage increases by 1d6 for each slot level above 2nd."},"it":{"name":"Punizione marchiante","description":"La prossima volta che l'incantatore colpisce una creatura con un attacco con arma prima della fine di questo incantesimo, l'arma risplende di un bagliore astrale. L'attacco infligge 2d6 danni radiosi extra al bersaglio, che diventa visibile nel caso fosse invisibile, proietta luce fioca in un raggio di 1,5 metri e non può tornare invisibile fino alla fine dell'incantesimo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, i danni extra aumentano di 1d6 per ogni slot di livello superiore al 2°.","castingTime":"1 azione bonus","range":"Incantatore","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":2,"school":"srd:rule:school-evocation","classes":["srd:class:paladin"],"subclasses":[],"castingTime":"1 bonus action","range":"Self","components":["V"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","damage":[{"type":"srd:rule:damage-radiant","atSlotLevel":{"2":"2d6","3":"3d6","4":"4d6","5":"5d6","6":"6d6","7":"7d6","8":"8d6","9":"9d6"}}]}},{"id":"srd:spell:burning-hands","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Burning Hands","description":"As you hold your hands with thumbs touching and fingers spread, a thin sheet of flames shoots forth from your outstretched fingertips. Each creature in a 15-foot cone must make a dexterity saving throw. A creature takes 3d6 fire damage on a failed save, or half as much damage on a successful one.\\n\\nThe fire ignites any flammable objects in the area that aren't being worn or carried.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st."},"it":{"name":"Mani brucianti","description":"L'incantatore apre le mani, punta i pollici l'uno contro l'altro e dalla punta delle sue dita protese si propaga un sottile velo di fiamme. Ogni creatura entro un cono di 4,5 metri deve effettuare un tiro salvezza su Destrezza. In caso di fallimento, la creatura subisce 3d6 danni da fuoco, o la metà dei danni in caso di successo.\\n\\nIl fuoco incendia ogni oggetto infiammabile nell'area che non sia indossato o trasportato.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d6 per ogni slot di livello superiore al 1°.","castingTime":"1 azione","range":"Incantatore (cono di 4,5 metri)","duration":"Istantanea"}},"data":{"level":1,"school":"srd:rule:school-evocation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:fiend"],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-fire","atSlotLevel":{"1":"3d6","2":"4d6","3":"5d6","4":"6d6","5":"7d6","6":"8d6","7":"9d6","8":"10d6","9":"11d6"}}],"savingThrow":{"ability":"dex","onSuccess":"half"},"area":{"type":"cone","size":15}}},{"id":"srd:spell:call-lightning","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Call Lightning","description":"A storm cloud appears in the shape of a cylinder that is 10 feet tall with a 60-foot radius, centered on a point you can see 100 feet directly above you. The spell fails if you can't see a point in the air where the storm cloud could appear (for example, if you are in a room that can't accommodate the cloud).\\n\\nWhen you cast the spell, choose a point you can see within range. A bolt of lightning flashes down from the cloud to that point. Each creature within 5 feet of that point must make a dexterity saving throw. A creature takes 3d10 lightning damage on a failed save, or half as much damage on a successful one. On each of your turns until the spell ends, you can use your action to call down lightning in this way again, targeting the same point or a different one.\\n\\nIf you are outdoors in stormy conditions when you cast this spell, the spell gives you control over the existing storm instead of creating a new one. Under such conditions, the spell's damage increases by 1d10.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 4th or higher level, the damage increases by 1d10 for each slot level above 3rd."},"it":{"name":"Invocare il fulmine","description":"Una nube di tempesta appare sotto forma cilindrica di altezza pari a 3 metri e raggio pari a 18 metri, centrata su un punto che l'incantatore è in grado di vedere situato a 30 metri esattamente sopra di lui. L'incantesimo non funziona se l'incantatore non può vedere il punto in cui la nube potrebbe comparire (per esempio, se si trova all'interno di una stanza che non è in grado di contenere la nube).\\n\\nQuando lancia questo incantesimo, l'incantatore sceglie un punto che è in grado di vedere entro gittata, dove si abbatte un fulmine originato dalla nube. Ogni creatura situata entro 1,5 metri da quel punto deve effettuare un tiro salvezza su Destrezza, subendo 3d10 danni da fulmine in caso di fallimento, o la metà dei danni in caso di successo. In ogni suoi turno finché l'incantesimo non termina, l'incantatore può usare un'azione per richiamare il fulmine in questo modo, bersagliando lo stesso punto o un punto diverso.\\n\\nSe nel momento in cui lancia l'incantesimo l'incantatore si trova all'esterno durante una tempesta, ottiene il controllo della tempesta esistente invece di crearne una nuova. In queste condizioni, i danni provocati dall'incantesimo aumentano di 1d10.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d10 per ogni slot di livello superiore al 3°.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 10 minuti"}},"data":{"level":3,"school":"srd:rule:school-conjuration","classes":["srd:class:druid"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"120 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 10 minutes","damage":[{"type":"srd:rule:damage-lightning","atSlotLevel":{"3":"3d10","4":"4d10","5":"5d10","6":"6d10","7":"7d10","8":"8d10","9":"9d10"}}],"area":{"type":"sphere","size":5}}},{"id":"srd:spell:calm-emotions","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Calm Emotions","description":"You attempt to suppress strong emotions in a group of people. Each humanoid in a 20-foot-radius sphere centered on a point you choose within range must make a charisma saving throw; a creature can choose to fail this saving throw if it wishes. If a creature fails its saving throw, choose one of the following two effects. You can suppress any effect causing a target to be charmed or frightened. When this spell ends, any suppressed effect resumes, provided that its duration has not expired in the meantime.\\n\\nAlternatively, you can make a target indifferent about creatures of your choice that it is hostile toward. This indifference ends if the target is attacked or harmed by a spell or if it witnesses any of its friends being harmed. When the spell ends, the creature becomes hostile again, unless the GM rules otherwise."},"it":{"name":"Calmare emozioni","description":"L'incantatore tenta di sopprimere le emozioni intense in un gruppo di persone. Ogni umanoide all'interno di una sfera di 6 metri di raggio centrata su un punto scelto dall'incantatore entro gittata deve effettuare un tiro salvezza su Carisma; se lo desidera, una creatura può scegliere di fallire il tiro salvezza. Se una creatura fallisce il tiro salvezza, l'incantatore sceglie uno tra gli effetti seguenti.\\n\\nL'incantatore può sopprimere qualsiasi effetto che rende il bersaglio affascinato o spaventato. Al termine dell'incantesimo, ogni effetto soppresso torna a influenzare il bersaglio, purché nel frattempo la sua durata non sia terminata.\\n\\nIn alternativa, l'incantatore può rendere un bersaglio indifferente verso creature da lui scelte nei cui confronti il bersaglio sarebbe ostile. Questa indifferenza termina se il bersaglio viene attaccato o danneggiato da un incantesimo, oppure se vede uno dei suoi amici subire danni. Al termine dell'incantesimo, la creatura torna a essere ostile, a meno che il GM non decida altrimenti.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":2,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:cleric"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"cha","onSuccess":"none"},"area":{"type":"sphere","size":20}}},{"id":"srd:spell:chain-lightning","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Chain Lightning","description":"You create a bolt of lightning that arcs toward a target of your choice that you can see within range. Three bolts then leap from that target to as many as three other targets, each of which must be within 30 feet of the first target. A target can be a creature or an object and can be targeted by only one of the bolts.\\n\\nA target must make a dexterity saving throw. The target takes 10d8 lightning damage on a failed save, or half as much damage on a successful one.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 7th level or higher, one additional bolt leaps from the first target to another target for each slot level above 6th."},"it":{"name":"Catena di fulmini","description":"L'incantatore crea un fulmine scagliandolo verso un bersaglio di sua scelta entro gittata e che è in grado di vedere. Tre fulmini sfrecciano poi dal bersaglio verso un massimo di altri tre bersagli, ognuno dei quali deve trovarsi entro 9 metri dal primo. I bersagli dell'incantesimo possono essere creature o oggetti, che possono essere bersagliati soltanto da uno dei fulmini.\\n\\nUn bersaglio deve effettuare un tiro salvezza su Destrezza, subendo 10d8 danni da fulmine in caso di fallimento, o la metà dei danni in caso di successo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° livello o superiore, un fulmine aggiuntivo per ogni slot di livello superiore al 6° sfreccia dal primo bersaglio colpendone un altro.","castingTime":"1 azione","range":"45 metri","duration":"Istantanea","material":"un ciuffo di pelliccia; un frammento d'ambra, di vetro o di una verga di cristallo e tre spilli d'argento"}},"data":{"level":6,"school":"srd:rule:school-evocation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"150 feet","components":["V","S","M"],"material":"A bit of fur; a piece of amber, glass, or a crystal rod; and three silver pins.","ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-lightning","atSlotLevel":{"6":"10d8"}}],"savingThrow":{"ability":"dex","onSuccess":"half"}}},{"id":"srd:spell:charm-person","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Charm Person","description":"You attempt to charm a humanoid you can see within range. It must make a wisdom saving throw, and does so with advantage if you or your companions are fighting it. If it fails the saving throw, it is charmed by you until the spell ends or until you or your companions do anything harmful to it. The charmed creature regards you as a friendly acquaintance. When the spell ends, the creature knows it was charmed by you.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st. The creatures must be within 30 feet of each other when you target them."},"it":{"name":"Charme su persone","description":"L'incantatore tenta di affascinare un umanoide entro gittata che è in grado di vedere. L'umanoide deve effettuare un tiro salvezza su Saggezza e dispone di vantaggio se l'incantatore o i suoi compagni stanno combattendo contro di lui. Se lo fallisce, è affascinato dall'incantatore finché l'incantesimo non termina o finché l'incantatore o i suoi compagni non lo danneggiano in qualche modo. La creatura affascinata considera l'incantatore una figura conosciuta e amichevole. Quando l'incantesimo termina, la creatura capirà di essere stata affascinata dall'incantatore.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1°. Quando l'incantatore le bersaglia, le creature devono trovarsi a non più di 9 metri l'una dall'altra.","castingTime":"1 azione","range":"9 metri","duration":"1 ora"}},"data":{"level":1,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:druid","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"30 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"1 hour","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:chill-touch","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Chill Touch","description":"You create a ghostly, skeletal hand in the space of a creature within range. Make a ranged spell attack against the creature to assail it with the chill of the grave. On a hit, the target takes 1d8 necrotic damage, and it can't regain hit points until the start of your next turn. Until then, the hand clings to the target.\\n\\nIf you hit an undead target, it also has disadvantage on attack rolls against you until the end of your next turn.\\n\\nThis spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."},"it":{"name":"Tocco gelido","description":"L'incantatore crea una mano scheletrica e spettrale nello spazio di una creatura entro gittata ed effettua contro di lei un attacco a distanza con incantesimo, investendola con un flusso di gelo sepolcrale. Se il colpo va a segno, il bersaglio subisce 1d8 danni necrotici e non può recuperare punti ferita fino all'inizio del turno successivo dell'incantatore. Fino ad allora, la mano rimane avvinghiata al bersaglio.\\n\\nSe il bersaglio colpito è un non morto, subisce svantaggio ai tiri per colpire contro l'incantatore fino al termine del turno successivo di quest'ultimo.\\n\\nI danni di questo incantesimo aumentano di 1d8 quando l'incantatore raggiunge il 5° livello (2d8), l'11° livello (3d8) e il 17° livello (4d8).","castingTime":"1 azione","range":"36 metri","duration":"1 round"}},"data":{"level":0,"school":"srd:rule:school-necromancy","classes":["srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"120 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"1 round","damage":[{"type":"srd:rule:damage-necrotic","atCharacterLevel":{"1":"1d8","5":"2d8","11":"3d8","17":"4d8"}}],"attackType":"ranged"}},{"id":"srd:spell:circle-of-death","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Circle of Death","description":"A sphere of negative energy ripples out in a 60-foot radius sphere from a point within range. Each creature in that area must make a constitution saving throw. A target takes 8d6 necrotic damage on a failed save, or half as much damage on a successful one.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 7th level or higher, the damage increases by 2d6 for each slot level above 6th."},"it":{"name":"Cerchio di morte","description":"Una sfera d'energia negativa si espande in un raggio di 18 metri da un punto entro gittata. Ogni creatura nell'area deve effettuare un tiro salvezza su Costituzione e subisce 8d6 danni necrotici in caso di fallimento, o la metà dei danni in caso di successo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° livello o superiore, i danni aumentano di 2d6 per ogni slot di livello superiore al 6°.","castingTime":"1 azione","range":"45 metri","duration":"Istantanea","material":"polvere ricavata da una perla nera, del valore di almeno 500 mo"}},"data":{"level":6,"school":"srd:rule:school-necromancy","classes":["srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"150 feet","components":["V","S","M"],"material":"The powder of a crushed black pearl worth at least 500 gp.","ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-necrotic","atSlotLevel":{"6":"8d6","7":"10d6","8":"12d6","9":"14d6"}}],"savingThrow":{"ability":"con","onSuccess":"half"},"area":{"type":"sphere","size":60}}},{"id":"srd:spell:clairvoyance","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Clairvoyance","description":"You create an invisible sensor within range in a location familiar to you (a place you have visited or seen before) or in an obvious location that is unfamiliar to you (such as behind a door, around a corner, or in a grove of trees). The sensor remains in place for the duration, and it can't be attacked or otherwise interacted with.\\n\\nWhen you cast the spell, you choose seeing or hearing. You can use the chosen sense through the sensor as if you were in its space. As your action, you can switch between seeing and hearing.\\n\\nA creature that can see the sensor (such as a creature benefiting from see invisibility or truesight) sees a luminous, intangible orb about the size of your fist."},"it":{"name":"Chiaroveggenza","description":"L'incantatore crea un sensore invisibile entro gittata in un luogo a lui familiare (cioè che ha già visitato o visto), oppure in un luogo comune a lui non familiare (come per esempio dietro una porta, dietro un angolo o in un boschetto). Il sensore rimane in quella posizione per tutta la durata dell'incantesimo e non è possibile attaccarlo o interagire in altri modi con esso.\\n\\nQuando lancia l'incantesimo, l'incantatore sceglie tra vista e udito, potendo utilizzare il senso scelto attraverso il sensore come se si trovasse nel suo spazio. Con un'azione, l'incantatore può passare dalla vista all'udito e viceversa.\\n\\nUna creatura che può vedere il sensore (per esempio una creatura che beneficia di vedere invisibilità o vista pura) scorge una sfera luminosa e intangibile grande quando il pugno dell'incantatore.","castingTime":"10 minuti","range":"1,5 km","duration":"Concentrazione, fino a 10 minuti","material":"un focus del valore di almeno 100 mo, a scelta tra un cornetto acustico incastonato di gemme o un occhio di vetro per la vista"}},"data":{"level":3,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:cleric","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"10 minutes","range":"1 mile","components":["V","S","M"],"material":"A focus worth at least 100gp, either a jeweled horn for hearing or a glass eye for seeing.","ritual":false,"concentration":true,"duration":"Up to 10 minutes"}},{"id":"srd:spell:clone","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Clone","description":"This spell grows an inert duplicate of a living creature as a safeguard against death. This clone forms inside a sealed vessel and grows to full size and maturity after 120 days; you can also choose to have the clone be a younger version of the same creature. It remains inert and endures indefinitely, as long as its vessel remains undisturbed.\\n\\nAt any time after the clone matures, if the original creature dies, its soul transfers to the clone, provided that the soul is free and willing to return. The clone is physically identical to the original and has the same personality, memories, and abilities, but none of the original's equipment. The original creature's physical remains, if they still exist, become inert and can't thereafter be restored to life, since the creature's soul is elsewhere."},"it":{"name":"Clone","description":"Questo incantesimo crea un duplicato inerme di una creatura vivente come protezione contro la morte. Tale clone si sviluppa all'interno di un contenitore sigillato e raggiunge piena taglia e maturità dopo 120 giorni; l'incantatore può anche decidere di creare il clone di una versione più giovane della creatura. Il clone rimane inerte e permane per un tempo indeterminato, fintantoché il suo involucro rimane indisturbato.\\n\\nIn qualsiasi momento dopo che il clone ha raggiunto la maturazione, se la creatura originale muore, la sua anima viene trasferita al clone, purché essa sia libera e disposta a tornare. Il clone è fisicamente identico all'originale e possiede la sua personalità, i suoi ricordi e le sue abilità, ma non il suo equipaggiamento. I resti fisici della creatura originale, se ancora esistono, diventano inerti e non possono più essere riportati in vita, in quanto l'anima della creatura è altrove.","castingTime":"1 ora","range":"Contatto","duration":"Istantanea","material":"un diamante del valore di almeno 1.000 mo, un cubo di carne della creatura da clonare di almeno 2,5 cm per lato, che l'incantesimo consuma, e un contenitore del valore di almeno 2.000 mo che abbia un coperchio sigillabile e sia abbastanza grande da contenere una creatura di taglia Media, come un'urna enorme, una bara, una ciste piena di fango nel terreno o un contenitore di cristallo riempito con acqua salata"}},"data":{"level":8,"school":"srd:rule:school-necromancy","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 hour","range":"Touch","components":["V","S","M"],"material":"A diamond worth at least 1,000 gp and at least 1 cubic inch of flesh of the creature that is to be cloned, which the spell consumes, and a vessel worth at least 2,000 gp that has a sealable lid and is large enough to hold a Medium creature, such as a huge urn, coffin, mud-filled cyst in the ground, or crystal container filled with salt water.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:cloudkill","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Cloudkill","description":"You create a 20-foot-radius sphere of poisonous, yellow-green fog centered on a point you choose within range. The fog spreads around corners. It lasts for the duration or until strong wind disperses the fog, ending the spell. Its area is heavily obscured.\\n\\nWhen a creature enters the spell's area for the first time on a turn or starts its turn there, that creature must make a constitution saving throw. The creature takes 5d8 poison damage on a failed save, or half as much damage on a successful one. Creatures are affected even if they hold their breath or don't need to breathe.\\n\\nThe fog moves 10 feet away from you at the start of each of your turns, rolling along the surface of the ground. The vapors, being heavier than air, sink to the lowest level of the land, even pouring down openings.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d8 for each slot level above 5th."},"it":{"name":"Nube mortale","description":"L'incantatore genera una sfera composta da una velenosa nebbia giallo-verdastra del raggio di 6 metri centrata su un punto a sua scelta situato entro gittata. La nebbia si diffonde oltre gli angoli e permane per tutta la durata dell'incantesimo o finché un vento forte non la disperde, ponendo fine all'incantesimo. La sua area è pesantemente oscurata.\\n\\nQuando una creatura entra nell'area dell'incantesimo per la prima volta in un turno o inizia il suo turno qui, deve superare un tiro salvezza su Costituzione. In caso di fallimento, subisce 5d8 danni da veleno, o la metà dei danni in caso di successo. Le creature sono influenzate dell'incantesimo anche se trattengono il respiro o non hanno bisogno di respirare.\\n\\nLa nebbia si muove serpeggiando lungo il terreno e allontanandosi di 3 metri dall'incantatore all'inizio di ogni suo turno. I vapori sono più pesanti dell'aria e rimangono al livello più basso del terreno, riversandosi anche nelle aperture.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 5°.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 10 minuti"}},"data":{"level":5,"school":"srd:rule:school-conjuration","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:land"],"castingTime":"1 action","range":"120 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 10 minutes","damage":[{"type":"srd:rule:damage-poison","atSlotLevel":{"5":"5d8","6":"6d8","7":"7d8","8":"8d8","9":"9d8"}}],"savingThrow":{"ability":"con","onSuccess":"half"},"area":{"type":"sphere","size":20}}},{"id":"srd:spell:color-spray","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Color Spray","description":"A dazzling array of flashing, colored light springs from your hand. Roll 6d10; the total is how many hit points of creatures this spell can effect. Creatures in a 15-foot cone originating from you are affected in ascending order of their current hit points (ignoring unconscious creatures and creatures that can't see).\\n\\nStarting with the creature that has the lowest current hit points, each creature affected by this spell is blinded until the spell ends. Subtract each creature's hit points from the total before moving on to the creature with the next lowest hit points. A creature's hit points must be equal to or less than the remaining total for that creature to be affected.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, roll an additional 2d10 for each slot level above 1st."},"it":{"name":"Spruzzo colorato","description":"Dalla mano dell'incantatore si sprigiona un lampo abbagliante di luce multicolore. L'incantatore tira un 6d10 e il totale ottenuto è la quantità di punti ferita delle creature che questo incantesimo può influenzare. Le creature all'interno di un cono di 4,5 metri che ha origine dall'incantatore sono influenzate in ordine crescente in base ai loro punti ferita attuali (le creature prive di sensi e vista sono escluse).\\n\\nA partire dalla creatura che al momento possiede meno punti ferita, ogni creatura influenzata da questo incantesimo è accecata fino al termine dell'incantesimo. Si sottraggono i punti ferita di ogni creatura dal totale, per poi iniziare dalla creatura che possiede il numero di punti ferita più basso. Affinché quella creatura possa essere influenzata, il totale dei suoi punti ferita deve essere pari o inferiore al totale rimanente.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, tira 2d10 aggiuntivi per ogni slot di livello superiore al 1°.","castingTime":"1 azione","range":"Incantatore (cono di 4,5 metri)","duration":"1 round","material":"un pizzico di polvere o sabbia di colore rosso, giallo e blu"}},"data":{"level":1,"school":"srd:rule:school-illusion","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A pinch of powder or sand that is colored red, yellow, and blue.","ritual":false,"concentration":false,"duration":"1 round","area":{"type":"cone","size":15}}},{"id":"srd:spell:command","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Command","description":"You speak a one-word command to a creature you can see within range. The target must succeed on a wisdom saving throw or follow the command on its next turn. The spell has no effect if the target is undead, if it doesn't understand your language, or if your command is directly harmful to it.\\n\\nSome typical commands and their effects follow. You might issue a command other than one described here. If you do so, the GM determines how the target behaves. If the target can't follow your command, the spell ends.\\n\\n***Approach.*** The target moves toward you by the shortest and most direct route, ending its turn if it moves within 5 feet of you.\\n\\n***Drop.*** The target drops whatever it is holding and then ends its turn.\\n\\n***Flee.*** The target spends its turn moving away from you by the fastest available means.\\n\\n***Grovel.*** The target falls prone and then ends its turn.\\n\\n***Halt.*** The target doesn't move and takes no actions. A flying creature stays aloft, provided that it is able to do so. If it must move to stay aloft, it flies the minimum distance needed to remain in the air.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you can affect one additional creature for each slot level above 1st. The creatures must be within 30 feet of each other when you target them."},"it":{"name":"Comando","description":"L'incantatore rivolge una parola di comando a una creatura entro gittata che è in grado di vedere. Il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti dovrà obbedire al comando nel suo turno successivo. L'incantesimo non ha effetto se il bersaglio è un non morto, se non comprende il linguaggio dell'incantatore o se il comando si rivela dannoso in modo diretto per il bersaglio.\\n\\nDi seguito sono descritti alcuni comandi tipici e i loro effetti. L'incantatore può impartire un comando diverso da quelli descritti di seguito. In questo caso, è il GM a determinare come si comporta il bersaglio. Se il bersaglio non può eseguire il comando, l'incantesimo termina.\\n\\n***Avvicinati.*** Il bersaglio si muove verso l'incantatore seguendo il percorso più breve e diretto, terminando il suo turno se giunge entro 1,5 metri da lui.\\n\\n***Fermo.*** Il bersaglio non si muove e non effettua azioni. Una creatura volante rimane in aria, se è in grado di farlo. Se deve muoversi per rimanere sospesa, copre in volo la distanza minima richiesta per rimanere in aria.\\n\\n***Fuggi.*** Il bersaglio usa il suo turno per allontanarsi dall'incantatore nel modo più rapido possibile.\\n\\n***Lascia.*** Il bersaglio lascia cadere ciò che stava impugnando, poi termina il suo turno.\\n\\n***Supplica.*** Il bersaglio cade a terra prono e termina il suo turno.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, può influenzare una creatura aggiuntiva per ogni slot di livello superiore al 1°. Quando l'incantatore le bersaglia, le creature devono trovarsi a non più di 9 metri l'una dall'altra.","castingTime":"1 azione","range":"18 metri","duration":"1 round"}},"data":{"level":1,"school":"srd:rule:school-enchantment","classes":["srd:class:cleric","srd:class:paladin"],"subclasses":["srd:subclass:lore","srd:subclass:fiend"],"castingTime":"1 action","range":"60 feet","components":["V"],"ritual":false,"concentration":false,"duration":"1 round","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:commune","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Commune","description":"You contact your deity or a divine proxy and ask up to three questions that can be answered with a yes or no. You must ask your questions before the spell ends. You receive a correct answer for each question.\\n\\nDivine beings aren't necessarily omniscient, so you might receive \\"unclear\\" as an answer if a question pertains to information that lies beyond the deity's knowledge. In a case where a one-word answer could be misleading or contrary to the deity's interests, the GM might offer a short phrase as an answer instead.\\n\\nIf you cast the spell two or more times before finishing your next long rest, there is a cumulative 25 percent chance for each casting after the first that you get no answer. The GM makes this roll in secret."},"it":{"name":"Comunione","description":"L'incantatore entra in contatto con la sua divinità o un emissario divino e, prima della fine dell'incantesimo, pone fino a tre domande a cui è possibile rispondere con sì o no. L'incantatore riceve una risposta corretta per ogni domanda.\\n\\nGli esseri divini non sono necessariamente onniscienti, quindi l'incantatore potrebbe ricevere \\"ignoto\\" come risposta se una domanda riguarda informazioni che vanno oltre le loro conoscenze. Nel caso in cui una risposta di una parola sola possa rivelarsi fuorviante o contraria agli interessi della divinità, il GM può fornire come risposta una breve frase.\\n\\nSe l'incantatore lancia l'incantesimo due o più volte prima di completare il suo riposo lungo successivo, esiste una probabilità cumulativa del 25% di non ottenere risposta per ogni lancio dopo il primo. Il GM effettua questo tiro in segreto.","castingTime":"1 minuto","range":"Incantatore","duration":"1 minuto","material":"incenso e una fiala di acqua santa o sacrilega"}},"data":{"level":5,"school":"srd:rule:school-divination","classes":["srd:class:cleric"],"subclasses":["srd:subclass:devotion"],"castingTime":"1 minute","range":"Self","components":["V","S","M"],"material":"Incense and a vial of holy or unholy water.","ritual":true,"concentration":false,"duration":"1 minute"}},{"id":"srd:spell:commune-with-nature","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Commune With Nature","description":"You briefly become one with nature and gain knowledge of the surrounding territory. In the outdoors, the spell gives you knowledge of the land within 3 miles of you. In caves and other natural underground settings, the radius is limited to 300 feet. The spell doesn't function where nature has been replaced by construction, such as in dungeons and towns.\\n\\nYou instantly gain knowledge of up to three facts of your choice about any of the following subjects as they relate to the area:\\n\\n- terrain and bodies of water\\n\\n- prevalent plants, minerals, animals, or peoples\\n\\n- powerful celestials, fey, fiends, elementals, or undead\\n\\n- influence from other planes of existence\\n\\n- buildings\\n\\nFor example, you could determine the location of powerful undead in the area, the location of major sources of safe drinking water, and the location of any nearby towns."},"it":{"name":"Comunione con la natura","description":"L'incantatore diventa brevemente un tutt'uno con la natura, acquisendo la conoscenza del territorio circostante. All'aperto, l'incantesimo fornisce all'incantatore la conoscenza del territorio entro un raggio di 4,5 km. Nelle caverne e in altri ambienti naturali sotterranei, il raggio è limitato a 90 metri. L'incantesimo non funziona nei luoghi in cui la natura è stata sostituita da costruzioni, come dungeon e cittadine.\\n\\nL'incantatore ottiene immediatamente la conoscenza di un massimo di tre fatti a sua scelta sui seguenti argomenti legati all'area:\\n\\n- terreno e distese d'acqua\\n\\n- vegetali, minerali, animali o popolazioni predominanti\\n\\n- celestiali, folletti, immondi, elementali o non morti potenti\\n\\n- influenza da altri piani di esistenza\\n\\n- edifici\\n\\nPer esempio, l'incantatore potrebbe determinare la posizione di potenti non morti nell'area, delle principali fonti d'acqua potabile e di cittadine vicine.","castingTime":"1 minuto","range":"Incantatore","duration":"Istantanea"}},"data":{"level":5,"school":"srd:rule:school-divination","classes":["srd:class:druid","srd:class:ranger"],"subclasses":["srd:subclass:land"],"castingTime":"1 minute","range":"Self","components":["V","S"],"ritual":true,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:comprehend-languages","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Comprehend Languages","description":"For the duration, you understand the literal meaning of any spoken language that you hear. You also understand any written language that you see, but you must be touching the surface on which the words are written. It takes about 1 minute to read one page of text.\\n\\nThis spell doesn't decode secret messages in a text or a glyph, such as an arcane sigil, that isn't part of a written language."},"it":{"name":"Comprensione dei linguaggi","description":"Per la durata dell'incantesimo, l'incantatore comprende il significato letterale di qualsiasi linguaggio parlato che è in grado di sentire. Comprendi inoltre ogni linguaggio scritto che sei in grado di vedere, ma devi toccare la superficie su cui sono scritte le parole. È necessario circa 1 minuto per leggere una pagina di testo.\\n\\nQuesto incantesimo non decodifica i messaggi segreti di un testo o di un glifo, come un sigillo arcano, che non faccia parte di un linguaggio scritto.","castingTime":"1 azione","range":"Incantatore","duration":"1 ora","material":"un pizzico di fuliggine e di sale"}},"data":{"level":1,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A pinch of soot and salt.","ritual":true,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:compulsion","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Compulsion","description":"Creatures of your choice that you can see within range and that can hear you must make a wisdom saving throw. A target automatically succeeds on this saving throw if it can't be charmed. On a failed save, a target is affected by this spell. Until the spell ends, you can use a bonus action on each of your turns to designate a direction that is horizontal to you. Each affected target must use as much of its movement as possible to move in that direction on its next turn. It can take any action before it moves. After moving in this way, it can make another Wisdom save to try to end the effect.\\n\\nA target isn't compelled to move into an obviously deadly hazard, such as a fire or a pit, but it will provoke opportunity attacks to move in the designated direction."},"it":{"name":"Compulsione","description":"Le creature scelte dall'incantatore situate entro gittata, che sono in grado di sentirlo e che egli è in grado di vedere, devono effettuare un tiro salvezza su Saggezza. Un bersaglio supera automaticamente questo tiro salvezza se non può essere affascinato. Se fallisce, è influenzato dall'incantesimo. Finché l'incantesimo non termina, l'incantatore può usare un'azione bonus in ogni suo turno per scegliere una direzione orizzontale rispetto a lui. Ogni bersaglio influenzato deve usare la maggior parte possibile del suo movimento per muoversi in quella direzione nel suo turno successivo, potendo effettuare prima la sua azione. Dopo essersi mosso in quella direzione, il bersaglio può effettuare un altro tiro salvezza su Saggezza per provare a terminare l'effetto.\\n\\nUn bersaglio non è obbligato a muoversi verso un pericolo mortale, come un incendio o una fossa, ma provocherà attacchi di opportunità nel muoversi verso la direzione designata.","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":4,"school":"srd:rule:school-enchantment","classes":["srd:class:bard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:cone-of-cold","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Cone of Cold","description":"A blast of cold air erupts from your hands. Each creature in a 60-foot cone must make a constitution saving throw. A creature takes 8d8 cold damage on a failed save, or half as much damage on a successful one.\\n\\nA creature killed by this spell becomes a frozen statue until it thaws.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d8 for each slot level above 5th."},"it":{"name":"Cono di freddo","description":"Un getto d'aria gelida si propaga dalle mani dell'incantatore. Ogni creatura entro un cono di 18 metri deve effettuare un tiro salvezza su Costituzione. In caso di fallimento, la creatura subisce 8d8 danni da freddo, o la metà dei danni in caso di successo.\\n\\nUna creatura uccisa da questo incantesimo si tramuta in una statua di ghiaccio finché non si scioglie.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 5°.","castingTime":"1 azione","range":"Incantatore (cono di 18 metri)","duration":"Istantanea","material":"un piccolo cono di cristallo o vetro"}},"data":{"level":5,"school":"srd:rule:school-evocation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:land"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A small crystal or glass cone.","ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-cold","atSlotLevel":{"5":"8d8","6":"9d8","7":"10d8","8":"11d8","9":"12d8"}}],"savingThrow":{"ability":"con","onSuccess":"half"},"area":{"type":"cone","size":60}}},{"id":"srd:spell:confusion","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Confusion","description":"This spell assaults and twists creatures' minds, spawning delusions and provoking uncontrolled action. Each creature in a 10-foot-radius sphere centered on a point you choose within range must succeed on a Wisdom saving throw when you cast this spell or be affected by it.\\n\\nAn affected target can't take reactions and must roll a d10 at the start of each of its turns to determine its behavior for that turn.\\n\\n| d10 | Behavior |\\n\\n|---|---|\\n\\n| 1 | The creature uses all its movement to move in a random direction. To determine the direction, roll a d8 and assign a direction to each die face. The creature doesn't take an action this turn. |\\n\\n| 2-6 | The creature doesn't move or take actions this turn. |\\n\\n| 7-8 | The creature uses its action to make a melee attack against a randomly determined creature within its reach. If there is no creature within its reach, the creature does nothing this turn. |\\n\\n| 9-10 | The creature can act and move normally. |\\n\\nAt the end of each of its turns, an affected target can make a Wisdom saving throw. If it succeeds, this effect ends for that target.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 5th level or higher, the radius of the sphere increases by 5 feet for each slot level above 4th."},"it":{"name":"Confusione","description":"Questo incantesimo assale e sconvolge le menti delle creature, provocando allucinazioni e azioni incontrollate. Ogni creatura all'interno di una sfera del raggio di 3 metri, centrata su un punto a scelta dell'incantatore entro gittata, deve superare un tiro salvezza su Saggezza al lancio dell'incantesimo, altrimenti ne viene influenzata.\\n\\nUn bersaglio influenzato non può effettuare reazioni e deve tirare un d10 all'inizio di ogni suo turno per determinare il suo comportamento.\\n\\n| d10 | Comportamento |\\n\\n|---|---|\\n\\n| 1 | La creatura utilizza tutti i suoi movimenti per spostarsi in una direzione casuale. Per determinare la direzione, l'incantatore tira un d8 assegnando una direzione a ogni faccia del dado. La creatura non effettua un'azione in questo turno. |\\n\\n| 2–6 | La creatura non si muove né effettua un'azione in questo turno. |\\n\\n| 7–8 | La creatura utilizza la sua azione per effettuare un attacco in mischia contro un'altra creatura nella sua portata determinata casualmente. Se non è presente alcuna creatura entro gittata, non fa nulla in questo turno. |\\n\\n| 9–10 | La creatura può agire e muoversi normalmente. |\\n\\nUn bersaglio influenzato può effettuare un tiro salvezza su Saggezza alla fine di ogni suo turno. Se ha successo, questo effetto per lui termina.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 5° livello o superiore, il raggio della sfera aumenta di 1,5 metri per ogni slot di livello superiore al 4°.","castingTime":"1 azione","range":"27 metri","duration":"Concentrazione, fino a 1 minuto","material":"tre gusci di noce"}},"data":{"level":4,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:druid","srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"90 feet","components":["V","S","M"],"material":"Three walnut shells.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"wis","onSuccess":"none"},"area":{"type":"sphere","size":10}}},{"id":"srd:spell:conjure-animals","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Conjure Animals","description":"You summon fey spirits that take the form of beasts and appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears:\\n\\n- One beast of challenge rating 2 or lower\\n\\n- Two beasts of challenge rating 1 or lower\\n\\n- Four beasts of challenge rating 1/2 or lower\\n\\n- Eight beasts of challenge rating 1/4 or lower\\n\\n- Each beast is also considered fey, and it disappears when it drops to 0 hit points or when the spell ends.\\n\\nThe summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which has its own turns. They obey any verbal commands that you issue to them (no action required by you). If you don't issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.\\n\\nThe GM has the creatures' statistics.\\n\\n**At Higher Levels.** When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 5th-level slot, three times as many with a 7th-level."},"it":{"name":"Evoca animali","description":"L'incantatore evoca alcuni spiriti fatati che assumono la forma di bestie e appaiono in spazi liberi che egli è in grado di vedere. Per determinare ciò che appare, l'incantatore sceglie una tra le opzioni seguenti:\\n\\n- Una bestia di grado di sfida pari o inferiore a 2\\n\\n- Due bestie di grado di sfida pari o inferiore a 1\\n\\n- Quattro bestie di grado di sfida pari o inferiore a 1/2\\n\\n- Otto bestie di grado di sfida pari o inferiore a 1/4\\n\\nOgni bestia è anche considerata un folletto e scompare quando scende a 0 punti ferita o quando l'incantesimo termina.\\n\\nLe creature evocate sono amichevoli nei confronti dell'incantatore e dei suoi compagni. Si tira per l'iniziativa delle creature evocate, che svolgono i propri turni come gruppo. Le creature obbediscono ai comandi verbali dell'incantatore (nessuna azione richiesta). Se l'incantatore non impartisce dei comandi, si difendono dalle creature ostili, ma non intraprendono altre azioni.\\n\\nIl GM possiede le statistiche delle creature.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando determinati slot incantesimo di livello superiore, sceglie una delle opzioni di evocazione elencate sopra e appaiono nuove creature: il doppio con uno slot di 5° livello, il triplo con uno slot di 7° livello e il quadruplo con uno slot di 9° livello.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 ora"}},"data":{"level":3,"school":"srd:rule:school-conjuration","classes":["srd:class:druid","srd:class:ranger"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:conjure-celestial","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Conjure Celestial","description":"You summon a celestial of challenge rating 4 or lower, which appears in an unoccupied space that you can see within range. The celestial disappears when it drops to 0 hit points or when the spell ends.\\n\\nThe celestial is friendly to you and your companions for the duration. Roll initiative for the celestial, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you), as long as they don't violate its alignment. If you don't issue any commands to the celestial, it defends itself from hostile creatures but otherwise takes no actions.\\n\\nThe GM has the celestial's statistics.\\n\\n**At Higher Levels.** When you cast this spell using a 9th-level spell slot, you summon a celestial of challenge rating 5 or lower."},"it":{"name":"Evoca celestiale","description":"L'incantatore evoca un celestiale di grado di sfida pari o inferiore a 4, che appare in uno spazio libero entro gittata che è in grado di vedere. Il celestiale scompare quando scende a 0 punti ferita o al termine dell'incantesimo.\\n\\nIl celestiale è amichevole nei confronti dell'incantatore e dei suoi compagni per tutta la durata dell'incantesimo. Si tira per l'iniziativa del celestiale, che svolge i propri turni. Il celestiale obbedisce ai comandi verbali dell'incantatore (nessuna azione richiesta), a patto che non violino il suo allineamento. Se l'incantatore non impartisce comandi al celestiale, quest'ultimo si difende dalle creature ostili, ma non intraprende altre azioni.\\n\\nIl GM possiede le statistiche del celestiale.\\n\\n**Ai livelli superiori.** Quando l'incantatore utilizza questo incantesimo usando uno slot incantesimo di 9° livello, evoca un celestiale con grado di sfida pari o inferiore a 5.","castingTime":"1 minuto","range":"27 metri","duration":"Concentrazione, fino a 1 ora"}},"data":{"level":7,"school":"srd:rule:school-conjuration","classes":["srd:class:cleric"],"subclasses":[],"castingTime":"1 minute","range":"90 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:conjure-elemental","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Conjure Elemental","description":"You call forth an elemental servant. Choose an area of air, earth, fire, or water that fills a 10-foot cube within range. An elemental of challenge rating 5 or lower appropriate to the area you chose appears in an unoccupied space within 10 feet of it. For example, a fire elemental emerges from a bonfire, and an earth elemental rises up from the ground. The elemental disappears when it drops to 0 hit points or when the spell ends.\\n\\nThe elemental is friendly to you and your companions for the duration. Roll initiative for the elemental, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you). If you don't issue any commands to the elemental, it defends itself from hostile creatures but otherwise takes no actions.\\n\\nIf your concentration is broken, the elemental doesn't disappear. Instead, you lose control of the elemental, it becomes hostile toward you and your companions, and it might attack. An uncontrolled elemental can't be dismissed by you, and it disappears 1 hour after you summoned it.\\n\\nThe GM has the elemental's statistics.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 6th level or higher, the challenge rating increases by 1 for each slot level above 5th."},"it":{"name":"Evoca elementale","description":"L'incantatore evoca uno servo elementale, scegliendo un'area di aria, terra, fuoco o acqua delle dimensioni di un cubo di 3 metri entro gittata. Un elementale con grado di sfida pari o inferiore a 5 e compatibile con l'area scelta appare in uno spazio libero entro 3 metri da essa. Per esempio, un elementale del fuoco emerge da un falò e un elementale della terra affiora dal terreno. L'elementale scompare quando scende a 0 punti ferita o al termine dell'incantesimo.\\n\\nL'elementale è amichevole nei confronti dell'incantatore e dei suoi compagni per tutta la durata dell'incantesimo. Si tira per l'iniziativa dell'elementale, che svolge i propri turni. L'elementale obbedisce ai comandi verbali dell'incantatore (nessuna azione richiesta). Se l'incantatore non impartisce comandi, l'elementale si difende dalle creature ostili, ma non intraprende altre azioni.\\n\\nSe la concentrazione viene meno, l'elementale non scompare ma l'incantatore perde il controllo su di lui attirandone l'ostilità su di sé e sui suoi compagni, rischiando che l'elementale li attacchi. L'incantatore non può scacciare un elementale fuori dal suo controllo, che tuttavia scompare 1 ora dopo essere stato evocato.\\n\\nIl GM possiede le statistiche dell'elementale.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, il grado di sfida aumenta di 1 per ogni slot di livello superiore al 5°.","castingTime":"1 minuto","range":"27 metri","duration":"Concentrazione, fino a 1 ora","material":"incenso bruciato per l'aria, argilla morbida per la terra, zolfo e fosforo per il fuoco o acqua e sabbia per l'acqua"}},"data":{"level":5,"school":"srd:rule:school-conjuration","classes":["srd:class:druid","srd:class:wizard"],"subclasses":["srd:subclass:land"],"castingTime":"1 minute","range":"90 feet","components":["V","S","M"],"material":"Burning incense for air, soft clay for earth, sulfur and phosphorus for fire, or water and sand for water.","ritual":false,"concentration":true,"duration":"Up to 1 hour","area":{"type":"cube","size":10}}},{"id":"srd:spell:conjure-fey","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Conjure Fey","description":"You summon a fey creature of challenge rating 6 or lower, or a fey spirit that takes the form of a beast of challenge rating 6 or lower. It appears in an unoccupied space that you can see within range. The fey creature disappears when it drops to 0 hit points or when the spell ends.\\n\\nThe fey creature is friendly to you and your companions for the duration. Roll initiative for the creature, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you), as long as they don't violate its alignment. If you don't issue any commands to the fey creature, it defends itself from hostile creatures but otherwise takes no actions.\\n\\nIf your concentration is broken, the fey creature doesn't disappear. Instead, you lose control of the fey creature, it becomes hostile toward you and your companions, and it might attack. An uncontrolled fey creature can't be dismissed by you, and it disappears 1 hour after you summoned it.\\n\\nThe GM has the fey creature's statistics.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 7th level or higher, the challenge rating increases by 1 for each slot level above 6th."},"it":{"name":"Evoca folletto","description":"L'incantatore evoca un folletto con grado di sfida pari o inferiore a 6, oppure uno spirito fatato che assume la forma di una bestia con grado di sfida pari o inferiore a 6. Il folletto appare in uno spazio libero entro gittata che l'incantatore è in grado di vedere e scompare quando scende a 0 punti ferita o al termine dell'incantesimo.\\n\\nLa creatura fatata è amichevole nei confronti dell'incantatore e dei suoi compagni per tutta la durata dell'incantesimo. Si tira per l'iniziativa della creatura, che svolge i propri turni. Il celestiale obbedisce ai comandi verbali dell'incantatore (nessuna azione richiesta), a patto che non violino il suo allineamento. Se l'incantatore non impartisce comandi, si difende dalle creature ostili, ma non intraprende altre azioni.\\n\\nSe la concentrazione viene meno, il folletto non scompare ma l'incantatore perde il controllo su di lui attirandone l'ostilità su di sé e sui suoi compagni, rischiando che la creatura fatata li attacchi. L'incantatore non può scacciare un folletto fuori dal suo controllo, che tuttavia scompare 1 ora dopo essere stato evocato.\\n\\nIl GM possiede le statistiche della creatura fatata.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° livello o superiore, il grado di sfida aumenta di 1 per ogni slot di livello superiore al 6°.","castingTime":"1 minuto","range":"27 metri","duration":"Concentrazione, fino a 1 ora"}},"data":{"level":6,"school":"srd:rule:school-conjuration","classes":["srd:class:druid","srd:class:warlock"],"subclasses":[],"castingTime":"1 minute","range":"90 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:conjure-minor-elementals","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Conjure Minor Elementals","description":"You summon elementals that appear in unoccupied spaces that you can see within range. You choose one the following options for what appears:\\n\\n- One elemental of challenge rating 2 or lower\\n\\n- Two elementals of challenge rating 1 or lower\\n\\n- Four elementals of challenge rating 1/2 or lower\\n\\n- Eight elementals of challenge rating 1/4 or lower.\\n\\nAn elemental summoned by this spell disappears when it drops to 0 hit points or when the spell ends.\\n\\nThe summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which has its own turns. They obey any verbal commands that you issue to them (no action required by you). If you don't issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.\\n\\nThe GM has the creatures' statistics.\\n\\n**At Higher Levels.** When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 6th-level slot and three times as many with an 8th-level slot."},"it":{"name":"Evoca elementali minori","description":"L'incantatore evoca elementali che appaiono in un spazi liberi entro gittata che è in grado di vedere e per determinare ciò che appare, sceglie una tra le opzioni seguenti:\\n\\n- Un elementale con grado di sfida pari o inferiore a 2\\n\\n- Due elementali con grado di sfida pari o inferiore a 1\\n\\n- Quattro elementali con grado di sfida pari o inferiore a 1/2\\n\\n- Otto elementali con grado di sfida pari o inferiore a 1/4\\n\\nUn elementale evocato da questo incantesimo scompare quando scende a 0 punti ferita o al termine dell'incantesimo.\\n\\nLe creature evocate sono amichevoli nei confronti dell'incantatore e dei suoi compagni. Si tira per l'iniziativa delle creature evocate, che svolgono i propri turni come gruppo. Le creature obbediscono ai comandi verbali dell'incantatore (nessuna azione richiesta). Se l'incantatore non impartisce dei comandi, si difendono dalle creature ostili, ma non intraprendono altre azioni.\\n\\nIl GM possiede le statistiche delle creature.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando determinati slot incantesimo di livello superiore, sceglie una delle opzioni di evocazione elencate sopra e appaiono nuove creature: il doppio con uno slot di 6° livello e il triplo con uno slot di 8° livello.","castingTime":"1 minuto","range":"27 metri","duration":"Concentrazione, fino a 1 ora"}},"data":{"level":4,"school":"srd:rule:school-conjuration","classes":["srd:class:druid","srd:class:wizard"],"subclasses":[],"castingTime":"1 minute","range":"90 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:conjure-woodland-beings","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Conjure Woodland Beings","description":"You summon fey creatures that appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears:\\n\\n- One fey creature of challenge rating 2 or lower\\n\\n- Two fey creatures of challenge rating 1 or lower\\n\\n- Four fey creatures of challenge rating 1/2 or lower\\n\\n- Eight fey creatures of challenge rating 1/4 or lower\\n\\nA summoned creature disappears when it drops to 0 hit points or when the spell ends.\\n\\nThe summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which have their own turns. They obey any verbal commands that you issue to them (no action required by you). If you don't issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.\\n\\nThe GM has the creatures' statistics.\\n\\n**At Higher Levels.** When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 6th-level slot and three times as many with an 8th-level slot."},"it":{"name":"Evoca creature boschive","description":"L'incantatore evoca creature fatate che appaiono in uno spazio libero entro gittata che è in grado di vedere. Per determinare ciò che appare, l'incantatore sceglie una tra le opzioni seguenti:\\n\\n- Una creatura fatata con grado di sfida pari o inferiore a 2\\n\\n- Due creature fatate con grado di sfida pari o inferiore a 1\\n\\n- Quattro creature fatate con grado di sfida pari o inferiore a 1/2\\n\\n- Otto creature fatate con grado di sfida pari o inferiore a 1/4\\n\\nUna creatura evocata scompare quando scende a 0 punti ferita o al termine dell'incantesimo.\\n\\nLe creature evocate sono amichevoli nei confronti dell'incantatore e dei suoi compagni. Si tira per l'iniziativa delle creature evocate, che svolgono i propri turni come gruppo. Le creature obbediscono ai comandi verbali dell'incantatore (nessuna azione richiesta). Se l'incantatore non impartisce dei comandi, si difendono dalle creature ostili, ma non intraprendono altre azioni.\\n\\nIl GM possiede le statistiche delle creature.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando determinati slot incantesimo di livello superiore, sceglie una delle opzioni di evocazione elencate sopra e appaiono nuove creature: il doppio con uno slot di 6° livello e il triplo con uno slot di 8° livello.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 ora","material":"una bacca di agrifoglio per ogni creatura evocata"}},"data":{"level":4,"school":"srd:rule:school-conjuration","classes":["srd:class:druid","srd:class:ranger"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"One holly berry per creature summoned.","ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:contact-other-plane","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Contact Other Plane","description":"You mentally contact a demigod, the spirit of a long-dead sage, or some other mysterious entity from another plane. Contacting this extraplanar intelligence can strain or even break your mind. When you cast this spell, make a DC 15 intelligence saving throw. On a failure, you take 6d6 psychic damage and are insane until you finish a long rest. While insane, you can't take actions, can't understand what other creatures say, can't read, and speak only in gibberish. A greater restoration spell cast on you ends this effect.\\n\\nOn a successful save, you can ask the entity up to five questions. You must ask your questions before the spell ends. The GM answers each question with one word, such as \\"yes,\\" \\"no,\\" \\"maybe,\\" \\"never,\\" \\"irrelevant,\\" or \\"unclear\\" (if the entity doesn't know the answer to the question). If a one-word answer would be misleading, the GM might instead offer a short phrase as an answer."},"it":{"name":"Contattare altri piani","description":"L'incantatore contatta mentalmente un semidio, lo spirito di un sapiente defunto da tempo o qualche altra entità misteriosa appartenente a un altro piano. Contattare questa intelligenza extraplanare può tuttavia affaticare o addirittura sconvolgere la sua mente: quando l'incantatore lancia questo incantesimo, deve effettuare un tiro salvezza su Intelligenza con CD 15. In caso di fallimento, subisce 6d6 danni psichici e impazzisce finché non completa un riposo lungo. Mentre è in questa condizione, non può effettuare azioni, capire i discorsi altrui o leggere e si limita a farfugliare parole senza senso. Un incantesimo ristorare superiore fa svanire questo effetto.\\n\\nIn caso di successo, l'incantatore può porre all'entità un massimo di cinque domande prima del termine dell'incantesimo. Il GM risponde a ogni domanda con una parola, come per esempio \\"sì\\", \\"no\\", \\"forse\\", \\"mai\\", \\"irrilevante\\" o \\"ignoto\\" (se l'entità non conosce la risposta alla domanda). Nel caso in cui una risposta di una parola sola possa rivelarsi fuorviante, il GM può fornire come risposta una breve frase.","castingTime":"1 minuto","range":"Incantatore","duration":"1 minuto"}},"data":{"level":5,"school":"srd:rule:school-divination","classes":["srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 minute","range":"Self","components":["V"],"ritual":true,"concentration":false,"duration":"1 minute","savingThrow":{"ability":"int","onSuccess":"other"}}},{"id":"srd:spell:contagion","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Contagion","description":"Your touch inflicts disease. Make a melee spell attack against a creature within your reach. On a hit, you afflict the creature with a disease of your choice from any of the ones described below.\\n\\nAt the end of each of the target's turns, it must make a constitution saving throw. After failing three of these saving throws, the disease's effects last for the duration, and the creature stops making these saves. After succeeding on three of these saving throws, the creature recovers from the disease, and the spell ends.\\n\\nSince this spell induces a natural disease in its target, any effect that removes a disease or otherwise ameliorates a disease's effects apply to it.\\n\\n***Blinding Sickness.*** Pain grips the creature's mind, and its eyes turn milky white. The creature has disadvantage on wisdom checks and wisdom saving throws and is blinded.\\n\\n***Filth Fever.*** A raging fever sweeps through the creature's body. The creature has disadvantage on strength checks, strength saving throws, and attack rolls that use Strength.\\n\\n***Flesh Rot.*** The creature's flesh decays. The creature has disadvantage on Charisma checks and vulnerability to all damage.\\n\\n***Mindfire.*** The creature's mind becomes feverish. The creature has disadvantage on intelligence checks and intelligence saving throws, and the creature behaves as if under the effects of the confusion spell during combat.\\n\\n***Seizure.*** The creature is overcome with shaking. The creature has disadvantage on dexterity checks, dexterity saving throws, and attack rolls that use Dexterity.\\n\\n***Slimy Doom.*** The creature begins to bleed uncontrollably. The creature has disadvantage on constitution checks and constitution saving throws. In addition, whenever the creature takes damage, it is stunned until the end of its next turn."},"it":{"name":"Contagio","description":"Il tocco dell'incantatore trasmette una malattia. L'incantatore effettua un attacco in mischia con incantesimo contro una creatura entro gittata. Se il colpo va a segno, trasmette alla creatura una malattia a sua scelta tra quelle descritte in seguito.\\n\\nAlla fine di ogni suo turno, il bersaglio deve effettuare un tiro salvezza su Costituzione. Dopo aver fallito tre tiri salvezza, gli effetti della malattia permangono per tutta la durata dell'incantesimo e la creatura non effettua più tiri salvezza. Dopo aver superato tre tiri salvezza, la creatura guarisce dalla malattia e l'incantesimo termina.\\n\\nPoiché questo incantesimo induce una malattia naturale al bersaglio, qualsiasi effetto che rimuove una malattia o ne migliora gli effetti è efficace.\\n\\n***Carne putrefatta.*** La carne della creatura si decompone. La creatura subisce svantaggio alle prove di Carisma e ha vulnerabilità a tutti i danni.\\n\\n***Devastazione vischiosa.*** La creatura inizia a sanguinare in modo incontrollabile. La creatura subisce svantaggio alle prove di Costituzione e ai tiri salvezza su Costituzione. Inoltre, ogni volta che subisce danni, è stordita fino al termine del proprio turno successivo.\\n\\n***Febbre lurida.*** Il corpo della creatura brucia di febbre. La creatura subisce svantaggio alle prove di Forza, ai tiri salvezza su Forza e ai tiri per colpire che utilizzano la Forza.\\n\\n***Fuoco mentale.*** La mente della creatura è febbricitante. La creatura subisce svantaggio alle prove di Intelligenza e ai tiri salvezza su Intelligenza; inoltre, durante il combattimento si comporta come se fosse sotto l'effetto dell'incantesimo confusione.\\n\\n***Infermità accecante.*** La mente della creatura è attanagliata dal dolore e i suoi occhi diventano lattiginosi. La creatura è accecata e subisce svantaggio alle prove di Saggezza e ai tiri salvezza su Saggezza.\\n\\n***Tremori.*** Il corpo della creatura è scosso da tremori. La creatura subisce svantaggio alle prove di Destrezza, ai tiri salvezza su Destrezza e ai tiri per colpire che utilizzano la Destrezza.","castingTime":"1 azione","range":"Contatto","duration":"7 giorni"}},"data":{"level":5,"school":"srd:rule:school-necromancy","classes":["srd:class:cleric","srd:class:druid"],"subclasses":[],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":false,"concentration":false,"duration":"7 days","savingThrow":{"ability":"con","onSuccess":"other"},"attackType":"melee"}},{"id":"srd:spell:contingency","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Contingency","description":"Choose a spell of 5th level or lower that you can cast, that has a casting time of 1 action, and that can target you. You cast that spell--called the contingent spell--as part of casting contingency, expending spell slots for both, but the contingent spell doesn't come into effect. Instead, it takes effect when a certain circumstance occurs. You describe that circumstance when you cast the two spells. For example, a contingency cast with water breathing might stipulate that water breathing comes into effect when you are engulfed in water or a similar liquid.\\n\\nThe contingent spell takes effect immediately after the circumstance is met for the first time, whether or not you want it to. and then contingency ends.\\n\\nThe contingent spell takes effect only on you, even if it can normally target others. You can use only one contingency spell at a time. If you cast this spell again, the effect of another contingency spell on you ends. Also, contingency ends on you if its material component is ever not on your person."},"it":{"name":"Contingenza","description":"L'incantatore sceglie un incantesimo di livello pari o inferiore a 5 che sia in grado di lanciare, che abbia un tempo di lancio di 1 azione e che possa avere come bersaglio l'incantatore stesso. L'incantatore lancia l'incantesimo, chiamato incantesimo contingente, come parte del lancio di contingenza, spendendo gli slot incantesimo per entrambi. L'incantesimo contingente, tuttavia, non ha effetto finché non si verificano determinate circostanze, che l'incantatore descrive nel momento in cui lancia i due incantesimi. Per esempio, un lancio di contingenza con respirare sott'acqua potrebbe stabilire che respirare sott'acqua avrà effetto quando l'incantatore sarà sommerso nell'acqua o in un liquido simile.\\n\\nChe l'incantatore lo desideri o meno, l'incantesimo contingente ha effetto nel momento in cui le circostanze vengono soddisfatte per la prima volta, poi contingenza termina.\\n\\nL'incantesimo contingente ha effetto solamente sull'incantatore, nonostante normalmente possa essere lanciato contro altri. L'incantatore può utilizzare un solo incantesimo contingenza alla volta. Se l'incantatore lancia nuovamente questo incantesimo, l'effetto di un altro incantesimo contingenza su di lui termina. Inoltre, contingenza termina qualora la sua componente materiale non si trovi sulla persona dell'incantatore.","castingTime":"10 minuti","range":"Incantatore","duration":"10 giorni","material":"una statuetta dell'incantatore scolpita in avorio e decorata con gemme del valore di almeno 1.500 mo"}},"data":{"level":6,"school":"srd:rule:school-evocation","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"10 minutes","range":"Self","components":["V","S","M"],"material":"A statuette of yourself carved from ivory and decorated with gems worth at least 1,500 gp.","ritual":false,"concentration":false,"duration":"10 days"}},{"id":"srd:spell:continual-flame","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Continual Flame","description":"A flame, equivalent in brightness to a torch, springs forth from an object that you touch. The effect looks like a regular flame, but it creates no heat and doesn't use oxygen. A continual flame can be covered or hidden but not smothered or quenched."},"it":{"name":"Fiamma perenne","description":"Una fiamma di intensità equivalente a quella di una torcia si sprigiona da un oggetto toccato dall'incantatore. L'effetto è quello di una fiamma comune, ma non crea calore e non utilizza ossigeno. Una fiamma perenne può essere coperta o nascosta, ma non soffocata o estinta.","castingTime":"1 azione","range":"Contatto","duration":"Finché non viene dissolto","material":"polvere di rubino del valore di 50 mo, che l'incantesimo consuma"}},"data":{"level":2,"school":"srd:rule:school-evocation","classes":["srd:class:cleric","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"Ruby dust worth 50 gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"Until dispelled"}},{"id":"srd:spell:control-water","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Control Water","description":"Until the spell ends, you control any freestanding water inside an area you choose that is a cube up to 100 feet on a side. You can choose from any of the following effects when you cast this spell. As an action on your turn, you can repeat the same effect or choose a different one.\\n\\n***Flood.*** You cause the water level of all standing water in the area to rise by as much as 20 feet. If the area includes a shore, the flooding water spills over onto dry land.\\n\\nIf you choose an area in a large body of water, you instead create a 20-foot tall wave that travels from one side of the area to the other and then crashes down. Any Huge or smaller vehicles in the wave's path are carried with it to the other side. Any Huge or smaller vehicles struck by the wave have a 25 percent chance of capsizing.\\n\\nThe water level remains elevated until the spell ends or you choose a different effect. If this effect produced a wave, the wave repeats on the start of your next turn while the flood effect lasts.\\n\\n***Part Water.*** You cause water in the area to move apart and create a trench. The trench extends across the spell's area, and the separated water forms a wall to either side. The trench remains until the spell ends or you choose a different effect. The water then slowly fills in the trench over the course of the next round until the normal water level is restored.\\n\\n***Redirect Flow.*** You cause flowing water in the area to move in a direction you choose, even if the water has to flow over obstacles, up walls, or in other unlikely directions. The water in the area moves as you direct it, but once it moves beyond the spell's area, it resumes its flow based on the terrain conditions. The water continues to move in the direction you chose until the spell ends or you choose a different effect.\\n\\n***Whirlpool.*** This effect requires a body of water at least 50 feet square and 25 feet deep. You cause a whirlpool to form in the center of the area. The whirlpool forms a vortex that is 5 feet wide at the base, up to 50 feet wide at the top, and 25 feet tall. Any creature or object in the water and within 25 feet of the vortex is pulled 10 feet toward it. A creature can swim away from the vortex by making a Strength (Athletics) check against your spell save DC.\\n\\nWhen a creature enters the vortex for the first time on a turn or starts its turn there, it must make a strength saving throw. On a failed save, the creature takes 2d8 bludgeoning damage and is caught in the vortex until the spell ends. On a successful save, the creature takes half damage, and isn't caught in the vortex. A creature caught in the vortex can use its action to try to swim away from the vortex as described above, but has disadvantage on the Strength (Athletics) check to do so.\\n\\nThe first time each turn that an object enters the vortex, the object takes 2d8 bludgeoning damage; this damage occurs each round it remains in the vortex."},"it":{"name":"Controllare acqua","description":"Fino al termine dell'incantesimo, l'incantatore controlla una massa libera d'acqua all'interno di un'area a sua scelta, con un volume massimo pari a un cubo di 30 metri per lato. Quando lancia questo incantesimo, l'incantatore può scegliere uno dei seguenti effetti e, con un'azione durante il suo turno, può ripetere il medesimo effetto o sceglierne uno differente.\\n\\n***Deviare la corrente.*** L'incantatore fa in modo che l'acqua corrente nell'area si muova in una direzione scelta da lui, anche se l'acqua deve risalire ostacoli e pareti o scorrere in altre direzioni inverosimili. L'acqua nell'area si muove secondo le indicazioni dell'incantatore, ma una volta superata l'area dell'incantesimo, riprende il suo corso in base alle condizione del terreno. L'acqua continua a scorrere nella direzione scelta fino al termine dell'incantesimo o finché l'incantatore non sceglie un effetto diverso.\\n\\n***Gorgo.*** Questo effetto richiede uno specchio d'acqua in un'area quadrata di almeno 15 metri e 7,5 metri di profondità. L'incantesimo crea un gorgo al centro dell'area, che forma un vortice alto 7,5 metri e ampio 1,5 metri alla base e fino a 15 metri alla sommità. Qualsiasi creatura o oggetto nell'acqua ed entro 7,5 metri dal vortice viene trascinato per 3 metri verso di esso. Una creatura può allontanarsi nuotando dal vortice superando una prova di Forza (Atletica) contro la CD del tiro salvezza sull'incantesimo.\\n\\nQuando una creatura viene trascinata nel vortice per la prima volta in un turno o inizia il suo turno qui, deve superare un tiro salvezza su Forza. Se lo fallisce, la creatura subisce 2d8 danni contundenti e rimane bloccata nel vortice fino al termine dell'incantesimo. In caso di successo, la creatura subisce invece soltanto la metà di quei danni e non viene trascinata nel vortice. Una creatura trascinata nel vortice può usare un'azione per provare a uscirne come descritto in precedenza, ma subisce svantaggio alla prova di Forza (Atletica).\\n\\nLa prima volta che in ogni turno un oggetto viene trascinato nel vortice, subisce 2d8 danni contundenti; questi danni vengono inferti a ogni round in cui l'oggetto rimane nel vortice.\\n\\n***Inondazione.*** L'incantatore fa in modo che il livello di tutta l'acqua ferma dell'area si alzi di un massimo di 6 metri. Se l'area include una riva, l'inondazione si riversa sulla terraferma.\\n\\nSe l'incantatore sceglie un'area all'interno di un grande specchio d'acqua, genera invece un'onda alta 6 metri che da una parte dell'area si infrange sull'altra. Qualsiasi veicolo di taglia Enorme o inferiore sul percorso dell'onda viene trascinato dall'altra parte dell'area e ha una probabilità del 25% di capovolgersi.\\n\\nIl livello dell'acqua rimane elevato fino al termine dell'incantesimo o finché l'incantatore non sceglie un effetto diverso. Se questo effetto produce un'onda, questa si ripete all'inizio del turno successivo dell'incantatore finché l'effetto di inondazione permane.\\n\\n***Separare le acque.*** L'incantatore fa in modo che l'acqua presente nell'area scelta si separi, creando un canale che si estende per tutta l'area dell'incantesimo; le acque divise formano un muro su entrambi i lati. Il canale permane fino al termine dell'incantesimo o finché l'incantatore non sceglie un effetto diverso. L'acqua poi riempie lentamente il canale nel corso del round successivo, finché il livello normale dell'acqua non viene ripristinato.","castingTime":"1 azione","range":"90 metri","duration":"Concentrazione, fino a 10 minuti","material":"una goccia d'acqua e un pizzico di polvere"}},"data":{"level":4,"school":"srd:rule:school-transmutation","classes":["srd:class:cleric","srd:class:druid","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"300 feet","components":["V","S","M"],"material":"A drop of water and a pinch of dust.","ritual":false,"concentration":true,"duration":"Up to 10 minutes","damage":[{"type":"srd:rule:damage-bludgeoning","atSlotLevel":{"4":"2d8"}}],"savingThrow":{"ability":"str","onSuccess":"half"},"area":{"type":"cube","size":100}}},{"id":"srd:spell:control-weather","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Control Weather","description":"You take control of the weather within 5 miles of you for the duration. You must be outdoors to cast this spell. Moving to a place where you don't have a clear path to the sky ends the spell early.\\n\\nWhen you cast the spell, you change the current weather conditions, which are determined by the GM based on the climate and season. You can change precipitation, temperature, and wind. It takes 1d4 x 10 minutes for the new conditions to take effect. Once they do so, you can change the conditions again. When the spell ends, the weather gradually returns to normal.\\n\\nWhen you change the weather conditions, find a current condition on the following tables and change its stage by one, up or down. When changing the wind, you can change its direction.\\n\\n##### Precipitation\\n\\n| Stage | Condition |\\n\\n|---|---|\\n\\n| 1 | Clear |\\n\\n| 2 | Light clouds |\\n\\n| 3 | Overcast or ground fog |\\n\\n| 4 | Rain, hail, or snow |\\n\\n| 5 | Torrential rain, driving hail, or blizzard |\\n\\n##### Temperature\\n\\n| Stage | Condition |\\n\\n|---|---|\\n\\n| 1 | Unbearable heat |\\n\\n| 2 | Hot |\\n\\n| 3 | Warm |\\n\\n| 4 | Cool |\\n\\n| 5 | Cold |\\n\\n| 6 | Arctic cold |\\n\\n##### Wind\\n\\n| Stage | Condition |\\n\\n|---|---|\\n\\n| 1 | Calm |\\n\\n| 2 | Moderate wind |\\n\\n| 3 | Strong wind |\\n\\n| 4 | Gale |\\n\\n| 5 | Storm |"},"it":{"name":"Controllare tempo atmosferico","description":"L'incantatore assume il controllo del tempo atmosferico entro 7,5 km per la durata dell'incantesimo, che dev'essere lanciato in un luogo all'aperto. Se l'incantatore si sposta in un luogo in cui non dispone di una vista diretta sul cielo, l'incantesimo termina prematuramente.\\n\\nQuando lancia un incantesimo, l'incantatore cambia le condizioni atmosferiche attuali determinate dal GM in base al clima e alla stagione. L'incantatore può modificare le precipitazioni, la temperatura e il vento. Occorrono 1d4 × 10 minuti perché le nuove condizioni abbiano effetto. Quando questo accade, l'incantatore le può cambiare di nuovo. Al termine dell'incantesimo, il tempo atmosferico torna alla normalità.\\n\\nQuando l'incantatore modifica le condizioni atmosferiche, trova la condizione attuale nelle tabelle seguenti e la modifica di un grado, verso l'alto o verso il basso. Quando l'incantatore cambia il vento, può modificarne anche la direzione.\\n\\n##### Precipitazioni\\n\\n| Grado | Condizione |\\n\\n|---|---|\\n\\n| 1 | Sereno |\\n\\n| 2 | Poco nuvoloso |\\n\\n| 3 | Nuvoloso o nebbia |\\n\\n| 4 | Pioggia, grandine o neve |\\n\\n| 5 | Pioggia torrenziale, grandinata violenta o tormenta |\\n\\n##### Temperatura\\n\\n| Grado | Condizione |\\n\\n|---|---|\\n\\n| 1 | Caldo insopportabile |\\n\\n| 2 | Caldo |\\n\\n| 3 | Temperato |\\n\\n| 4 | Fresco |\\n\\n| 5 | Freddo |\\n\\n| 6 | Freddo artico |\\n\\n##### Vento\\n\\n| Grado | Condizione |\\n\\n|---|---|\\n\\n| 1 | Calmo |\\n\\n| 2 | Vento moderato |\\n\\n| 3 | Vento forte |\\n\\n| 4 | Burrasca |\\n\\n| 5 | Tempesta |","castingTime":"10 minuti","range":"Incantatore (raggio di 7,5 km)","duration":"Concentrazione, fino a 8 ore","material":"incenso bruciato e frammenti di terra e legno mescolati nell'acqua"}},"data":{"level":8,"school":"srd:rule:school-transmutation","classes":["srd:class:cleric","srd:class:druid","srd:class:wizard"],"subclasses":["srd:subclass:land"],"castingTime":"10 minutes","range":"Self","components":["V","S","M"],"material":"Burning incense and bits of earth and wood mixed in water.","ritual":false,"concentration":true,"duration":"Up to 8 hours"}},{"id":"srd:spell:counterspell","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Counterspell","description":"You attempt to interrupt a creature in the process of casting a spell. If the creature is casting a spell of 3rd level or lower, its spell fails and has no effect. If it is casting a spell of 4th level or higher, make an ability check using your spellcasting ability. The DC equals 10 + the spell's level. On a success, the creature's spell fails and has no effect.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the interrupted spell has no effect if its level is less than or equal to the level of the spell slot you used."},"it":{"name":"Controincantesimo","description":"L'incantatore tenta di interrompere una creatura nell'atto di lanciare un incantesimo. Se la creatura sta lanciando un incantesimo di 3° livello o inferiore, il suo incantesimo fallisce e non ha effetto. Se l'incantesimo è di 4° livello o superiore, l'incantatore effettua una prova di caratteristica usando la propria caratteristica da incantatore. La CD è pari a 10 + il livello dell'incantesimo. In caso di successo, l'incantesimo fallisce e non sortisce alcun effetto.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, l'incantesimo interrotto non sortisce alcun effetto se il suo livello è pari o inferiore al livello dello slot incantesimo usato dall'incantatore.","castingTime":"1 reazione, che l'incantatore può effettuare quando vede una creatura entro 18 metri da lui lanciare un incantesimo","range":"18 metri","duration":"Istantanea"}},"data":{"level":3,"school":"srd:rule:school-abjuration","classes":["srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 reaction","range":"60 feet","components":["S"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:create-food-and-water","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Create Food and Water","description":"You create 45 pounds of food and 30 gallons of water on the ground or in containers within range, enough to sustain up to fifteen humanoids or five steeds for 24 hours. The food is bland but nourishing, and spoils if uneaten after 24 hours. The water is clean and doesn't go bad."},"it":{"name":"Creare cibo e acqua","description":"L'incantatore crea 20 kg di cibo e 135 litri d'acqua sul terreno o all'interno di un contenitore entro gittata, sufficienti per offrire sostentamento a quindici umanoidi o cinque destrieri per 24 ore. Il cibo è insipido ma nutriente e marcisce se non viene consumato entro 24 ore. L'acqua è pulita e non va a male.","castingTime":"1 azione","range":"9 metri","duration":"Istantanea"}},"data":{"level":3,"school":"srd:rule:school-conjuration","classes":["srd:class:cleric","srd:class:druid","srd:class:paladin"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"30 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:create-undead","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Create Undead","description":"You can cast this spell only at night. Choose up to three corpses of Medium or Small humanoids within range. Each corpse becomes a ghoul under your control. (The GM has game statistics for these creatures.)\\n\\nAs a bonus action on each of your turns, you can mentally command any creature you animated with this spell if the creature is within 120 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete.\\n\\nThe creature is under your control for 24 hours, after which it stops obeying any command you have given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature before the current 24-hour period ends. This use of the spell reasserts your control over up to three creatures you have animated with this spell, rather than animating new ones.\\n\\n**At Higher Levels.** When you cast this spell using a 7th-level spell slot, you can animate or reassert control over four ghouls. When you cast this spell using an 8th-level spell slot, you can animate or reassert control over five ghouls or two ghasts or wights. When you cast this spell using a 9th-level spell slot, you can animate or reassert control over six ghouls, three ghasts or wights, or two mummies."},"it":{"name":"Creare non morti","description":"L'incantatore può lanciare questo incantesimo di notte, scegliendo fino a tre cadaveri umanoidi di taglia Media o Piccola entro gittata. Ogni cadavere diventa un ghoul sotto il controllo dell'incantatore. (Il GM possiede le statistiche di gioco di queste creature.)\\n\\nCome azione bonus a ogni suo turno, l'incantatore può comandare mentalmente qualsiasi creatura animata con questo incantesimo, a patto che si trovi entro 36 metri da lui (se controlla varie creature, l'incantatore può comandarne una o tutte allo stesso momento, impartendo lo stesso comando a ciascuna di loro). L'incantatore decide quale azione effettuerà la creatura e dove si muoverà durante il suo turno successivo, oppure può impartirle un comando generale, come proteggere una stanza o un corridoio particolare. Se non impartisce comandi, la creatura si limita a difendersi dalle creature ostili. Una volta ricevuto un ordine, la creatura continua a seguirlo finché non ha portato a termine il compito.\\n\\nLa creatura rimane sotto il controllo dell'incantatore per 24 ore, passate le quali smette di obbedire a qualsiasi comando ulteriore. Per mantenere il controllo sulla creatura per altre 24 ore, l'incantatore deve lanciare questo incantesimo su di essa prima che l'attuale periodo di 24 ore termini. Questo uso dell'incantesimo gli permette di ristabilire il controllo su un massimo di tre creature da lui animate tramite questo incantesimo, anziché animarne di nuove.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° livello, può animare o ristabilire il controllo su quattro ghoul. Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 8° livello, può animare o ristabilire il controllo su cinque ghoul, oppure su due ghast o wight. Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 9° livello, può animare o ristabilire il controllo su sei ghoul, tre ghast o wight, oppure su due mummie.","castingTime":"1 minuto","range":"3 metri","duration":"Istantanea","material":"un vaso d'argilla colmo di terra raccolta in un cimitero, un vaso d'argilla colmo d'acqua salmastra e una pietra onice nera del valore di 150 mo per ogni cadavere"}},"data":{"level":6,"school":"srd:rule:school-necromancy","classes":["srd:class:cleric","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 minute","range":"10 feet","components":["V","S","M"],"material":"One clay pot filled with grave dirt, one clay pot filled with brackish water, and one 150 gp black onyx stone for each corpse.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:create-or-destroy-water","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Create or Destroy Water","description":"You either create or destroy water.\\n\\n***Create Water.*** You create up to 10 gallons of clean water within range in an open container. Alternatively, the water falls as rain in a 30-foot cube within range.\\n\\n***Destroy Water.*** You destroy up to 10 gallons of water in an open container within range. Alternatively, you destroy fog in a 30-foot cube within range.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you create or destroy 10 additional gallons of water, or the size of the cube increases by 5 feet, for each slot level above 1st."},"it":{"name":"Creare o distruggere acqua","description":"L'incantatore crea o distrugge l'acqua.\\n\\n***Creare acqua.*** L'incantatore crea fino a 45 litri d'acqua pulita in un contenitore aperto entro gittata. In alternativa, l'acqua cade sotto forma di pioggia in un cubo di 9 metri per lato entro gittata, estinguendo le fiamme nell'area.\\n\\n***Distruggere acqua.*** L'incantatore distrugge fino a 45 litri d'acqua in un contenitore aperto entro gittata. In alternativa, distrugge la nebbia presente in un cubo di 9 metri per lato.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, crea o distrugge 45 litri aggiuntivi d'acqua, oppure la grandezza del cubo aumenta di 1,5 metri, per ogni slot di livello superiore al 1°.","castingTime":"1 azione","range":"9 metri","duration":"Istantanea","material":"una goccia d'acqua per creare l'acqua o qualche granello di sabbia per distruggerla"}},"data":{"level":1,"school":"srd:rule:school-transmutation","classes":["srd:class:cleric","srd:class:druid"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A drop of water if creating water, or a few grains of sand if destroying it.","ritual":false,"concentration":false,"duration":"Instantaneous","area":{"type":"cube","size":30}}},{"id":"srd:spell:creation","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Creation","description":"You pull wisps of shadow material from the Shadowfell to create a nonliving object of vegetable matter within range: soft goods, rope, wood, or something similar. You can also use this spell to create mineral objects such as stone, crystal, or metal. The object created must be no larger than a 5-foot cube, and the object must be of a form and material that you have seen before.\\n\\nThe duration depends on the object's material. If the object is composed of multiple materials, use the shortest duration.\\n\\n| Material | Duration |\\n\\n|---|---|\\n\\n| Vegetable matter | 1 day |\\n\\n| Stone or crystal | 12 hours |\\n\\n| Precious metals | 1 hour |\\n\\n| Gems | 10 minutes |\\n\\n| Adamantine or mithral | 1 minute |\\n\\nUsing any material created by this spell as another spell's material component causes that spell to fail.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 6th level or higher, the cube increases by 5 feet for each slot level above 5th."},"it":{"name":"Creazione","description":"L'incantatore attrae a sé dei filamenti di sostanza d'ombra dalla Coltre Oscura per creare un oggetto non vivente di materia vegetale entro gittata: tessuti, corda, legno o materiali simili. Può anche utilizzare questo incantesimo per creare oggetti minerali come pietra, cristallo o metallo. L'oggetto creato non dev'essere più grande di un cubo di 1,5 metri di lato e deve avere una forma ed essere un materiale che l'incantatore ha già visto.\\n\\nLa durata dipende dal materiale dell'oggetto; se l'oggetto è composto da vari materiali, si usa la durata più breve.\\n\\n| Materiale | Durata |\\n\\n|---|---|\\n\\n| Materia vegetale | 1 giorno |\\n\\n| Pietra o cristallo | 12 ore |\\n\\n| Metalli preziosi | 1 ora |\\n\\n| Gemme | 10 minuti |\\n\\n| Adamantio o mithral | 1 minuto |\\n\\nUsare un qualsiasi materiale creato da questo incantesimo come componente materiale di un altro incantesimo ne provoca il fallimento.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, il lato del cubo aumenta di 1,5 metri per ogni slot di livello superiore al 5°.","castingTime":"1 minuto","range":"9 metri","duration":"Speciale","material":"un minuscolo frammento di materia dello stesso tipo dell'oggetto che l'incantatore desidera creare"}},"data":{"level":5,"school":"srd:rule:school-illusion","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 minute","range":"30 feet","components":["V","S","M"],"material":"A tiny piece of matter of the same type of the item you plan to create.","ritual":false,"concentration":false,"duration":"Special","area":{"type":"cube","size":5}}},{"id":"srd:spell:cure-wounds","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Cure Wounds","description":"A creature you touch regains a number of hit points equal to 1d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the healing increases by 1d8 for each slot level above 1st."},"it":{"name":"Cura ferite","description":"Una creatura toccata dall'incantatore recupera un numero di punti ferita pari a 1d8 + il modificatore di caratteristica da incantatore. Questo incantesimo non ha effetto sui non morti o sui costrutti.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, la guarigione aumenta di 1d8 per ogni slot di livello superiore al 1°.","castingTime":"1 azione","range":"Contatto","duration":"Istantanea"}},"data":{"level":1,"school":"srd:rule:school-evocation","classes":["srd:class:bard","srd:class:cleric","srd:class:druid","srd:class:paladin","srd:class:ranger"],"subclasses":["srd:subclass:lore","srd:subclass:life"],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:dancing-lights","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Dancing Lights","description":"You create up to four torch-sized lights within range, making them appear as torches, lanterns, or glowing orbs that hover in the air for the duration. You can also combine the four lights into one glowing vaguely humanoid form of Medium size. Whichever form you choose, each light sheds dim light in a 10-foot radius.\\n\\nAs a bonus action on your turn, you can move the lights up to 60 feet to a new spot within range. A light must be within 20 feet of another light created by this spell, and a light winks out if it exceeds the spell's range."},"it":{"name":"Luci danzanti","description":"L'incantatore crea fino a quattro luci delle dimensioni di una torcia, facendole apparire come lanterne, torce o globi luminosi che fluttuano nell'aria per la durata dell'incantesimo entro la sua gittata. L'incantatore può anche fondere le quattro luci in un'unica forma luminosa vagamente umanoide di taglia Media. Qualunque sia la forma scelta, ogni luce proietta luce fioca entro un raggio di 3 metri.\\n\\nCome azione bonus nel suo turno, l'incantatore può muovere le luci per un massimo di 18 metri fino a un nuovo punto entro gittata. Ogni luce deve trovarsi entro 6 metri da un'altra luce creata da questo incantesimo. Se una delle luci supera la gittata dell'incantesimo, si spegne.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 1 minuto","material":"un frammento di fosforo, di legno wych o una lucciola"}},"data":{"level":0,"school":"srd:rule:school-evocation","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"120 feet","components":["V","S","M"],"material":"A bit of phosphorus or wychwood, or a glowworm.","ritual":false,"concentration":true,"duration":"Up to 1 minute"}},{"id":"srd:spell:darkness","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Darkness","description":"Magical darkness spreads from a point you choose within range to fill a 15-foot-radius sphere for the duration. The darkness spreads around corners. A creature with darkvision can't see through this darkness, and nonmagical light can't illuminate it.\\n\\nIf the point you choose is on an object you are holding or one that isn't being worn or carried, the darkness emanates from the object and moves with it. Completely covering the source of the darkness with an opaque object, such as a bowl or a helm, blocks the darkness.\\n\\nIf any of this spell's area overlaps with an area of light created by a spell of 2nd level or lower, the spell that created the light is dispelled."},"it":{"name":"Oscurità","description":"L'incantatore sceglie un punto situato entro gittata da cui si diffonde un'oscurità magica che riempie una sfera del raggio di 4,5 metri per la durata dell'incantesimo. L'oscurità si diffonde oltre gli angoli. Una creatura dotata di scurovisione non è in grado di vedere attraverso questa oscurità e le luci non magiche non possono illuminarla.\\n\\nSe il punto scelto dall'incantatore si trova su un oggetto che sta impugnando o che non è indossato o trasportato da nessuno, l'oscurità si diffonde dall'oggetto e si muove assieme a esso. Coprire completamente la fonte dell'oscurità con un oggetto opaco, come una scodella o un elmo, blocca l'oscurità.\\n\\nSe una parte dell'area di questo incantesimo si sovrappone a un'area di luce creata da un incantesimo di 2° livello o inferiore, l'incantesimo che ha creato la luce viene dissolto.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 10 minuti","material":"pelo di pipistrello e una goccia di pece o un pezzo di carbone"}},"data":{"level":2,"school":"srd:rule:school-evocation","classes":["srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"60 feet","components":["V","M"],"material":"Bat fur and a drop of pitch or piece of coal.","ritual":false,"concentration":true,"duration":"Up to 10 minutes","area":{"type":"sphere","size":15}}},{"id":"srd:spell:darkvision","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Darkvision","description":"You touch a willing creature to grant it the ability to see in the dark. For the duration, that creature has darkvision out to a range of 60 feet."},"it":{"name":"Scurovisione","description":"L'incantatore tocca una creatura consenziente e le concede l'abilità di vedere nell'oscurità. Per la durata dell'incantesimo, quella creatura ha scurovisione fino a 18 metri.","castingTime":"1 azione","range":"Contatto","duration":"8 ore","material":"un pizzico di carota essiccata o un'agata"}},"data":{"level":2,"school":"srd:rule:school-transmutation","classes":["srd:class:druid","srd:class:ranger","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"Either a pinch of dried carrot or an agate.","ritual":false,"concentration":false,"duration":"8 hours"}},{"id":"srd:spell:daylight","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Daylight","description":"A 60-foot-radius sphere of light spreads out from a point you choose within range. The sphere is bright light and sheds dim light for an additional 60 feet.\\n\\nIf you chose a point on an object you are holding or one that isn't being worn or carried, the light shines from the object and moves with it. Completely covering the affected object with an opaque object, such as a bowl or a helm, blocks the light.\\n\\nIf any of this spell's area overlaps with an area of darkness created by a spell of 3rd level or lower, the spell that created the darkness is dispelled."},"it":{"name":"Luce diurna","description":"Una sfera di luce si espande in un raggio di 18 metri da un punto entro la gittata scelto dall'incantatore. La sfera emette luce intensa e poi luce fioca per ulteriori 18 metri.\\n\\nSe il punto scelto dall'incantatore si trova su un oggetto che lui stesso sta impugnando o che non è indossato o trasportato da nessuno, la luce si diffonde dall'oggetto e si muove assieme a esso. Coprire completamente l'oggetto interessato con un oggetto opaco, come una scodella o un elmo, blocca la luce.\\n\\nSe una parte dell'area di questo incantesimo si sovrappone a un'area d'oscurità creata da un incantesimo di 3° livello o inferiore, l'incantesimo che ha creato l'oscurità viene dissolto.","castingTime":"1 azione","range":"18 metri","duration":"1 ora"}},"data":{"level":3,"school":"srd:rule:school-evocation","classes":["srd:class:cleric","srd:class:druid","srd:class:paladin","srd:class:ranger","srd:class:sorcerer"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"1 hour","area":{"type":"sphere","size":60}}},{"id":"srd:spell:death-ward","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Death Ward","description":"You touch a creature and grant it a measure of protection from death.\\n\\nThe first time the target would drop to 0 hit points as a result of taking damage, the target instead drops to 1 hit point, and the spell ends.\\n\\nIf the spell is still in effect when the target is subjected to an effect that would kill it instantaneously without dealing damage, that effect is instead negated against the target, and the spell ends."},"it":{"name":"Interdizione alla morte","description":"L'incantatore tocca una creatura e le concede una misura di protezione dalla morte.\\n\\nLa prima volta che il bersaglio subisce una quantità di danni tale da farlo scendere a 0 punti ferita, scende invece a 1 punto ferita e l'incantesimo termina.\\n\\nSe l'incantesimo è ancora attivo quando il bersaglio è soggetto a un effetto che ne provocherebbe la morte istantanea senza infliggere danni, quell'effetto viene invece annullato e l'incantesimo termina.","castingTime":"1 azione","range":"Contatto","duration":"8 ore"}},"data":{"level":4,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric","srd:class:paladin"],"subclasses":["srd:subclass:life"],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":false,"concentration":false,"duration":"8 hours"}},{"id":"srd:spell:delayed-blast-fireball","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Delayed Blast Fireball","description":"A beam of yellow light flashes from your pointing finger, then condenses to linger at a chosen point within range as a glowing bead for the duration. When the spell ends, either because your concentration is broken or because you decide to end it, the bead blossoms with a low roar into an explosion of flame that spreads around corners. Each creature in a 20-foot-radius sphere centered on that point must make a dexterity saving throw. A creature takes fire damage equal to the total accumulated damage on a failed save, or half as much damage on a successful one.\\n\\nThe spell's base damage is 12d6. If at the end of your turn the bead has not yet detonated, the damage increases by 1d6.\\n\\nIf the glowing bead is touched before the interval has expired, the creature touching it must make a dexterity saving throw. On a failed save, the spell ends immediately, causing the bead to erupt in flame. On a successful save, the creature can throw the bead up to 40 feet. When it strikes a creature or a solid object, the spell ends, and the bead explodes.\\n\\nThe fire damages objects in the area and ignites flammable objects that aren't being worn or carried.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 8th level or higher, the base damage increases by 1d6 for each slot level above 7th."},"it":{"name":"Palla di fuoco ritardata","description":"Un raggio di luce gialla si sprigiona dal dito indice dell'incantatore per poi condensarsi in un punto a sua scelta entro gittata, formando una sfera scintillante che permane per la durata dell'incantesimo. Quando l'incantesimo termina per decisione dell'incantatore o perché la sua concentrazione viene interrotta, la sfera si disintegra con un cupo boato in un'esplosione di fiamme che si diffondono oltre gli angoli. Ogni creatura situata entro una sfera del raggio di 6 metri centrata su quel punto deve effettuare un tiro salvezza su Destrezza. In caso di fallimento, la creatura subisce una quantità di danni da fuoco pari al totale dei danni accumulati, o la metà dei danni in caso di successo.\\n\\nI danni base dell'incantesimo sono pari a 12d6 e se al termine del turno la sfera non è ancora esplosa, i danni aumentano di 1d6.\\n\\nSe una creatura tocca la sfera scintillante prima dello scadere dell'intervallo, deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, l'incantesimo termina immediatamente, causando l'esplosione della sfera. In caso di successo, la creatura può lanciare la sfera fino a una distanza di 12 metri: quando colpisce una creatura o un oggetto solido, l'incantesimo termina e la sfera esplode.\\n\\nIl fuoco danneggia ogni oggetto presente nell'area e incendia gli oggetti infiammabili non indossati o trasportati.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 8° livello o superiore, i danni di base aumentano di 1d6 per ogni slot di livello superiore al 7°.","castingTime":"1 azione","range":"45 metri","duration":"Concentrazione, fino a 1 minuto","material":"una pallina di guano di pipistrello e zolfo"}},"data":{"level":7,"school":"srd:rule:school-evocation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"150 feet","components":["V","S","M"],"material":"A tiny ball of bat guano and sulfur.","ritual":false,"concentration":true,"duration":"Up to 1 minute","damage":[{"type":"srd:rule:damage-fire","atSlotLevel":{"7":"12d6","8":"13d6","9":"14d6"}}],"savingThrow":{"ability":"dex","onSuccess":"half"},"area":{"type":"sphere","size":20}}},{"id":"srd:spell:demiplane","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Demiplane","description":"You create a shadowy door on a flat solid surface that you can see within range. The door is large enough to allow Medium creatures to pass through unhindered. When opened, the door leads to a demiplane that appears to be an empty room 30 feet in each dimension, made of wood or stone. When the spell ends, the door disappears, and any creatures or objects inside the demiplane remain trapped there, as the door also disappears from the other side.\\n\\nEach time you cast this spell, you can create a new demiplane, or have the shadowy door connect to a demiplane you created with a previous casting of this spell. Additionally, if you know the nature and contents of a demiplane created by a casting of this spell by another creature, you can have the shadowy door connect to its demiplane instead."},"it":{"name":"Semipiano","description":"L'incantatore crea una porta d'ombra su una superficie piatta e solida entro gittata che è in grado di vedere. La porta è ampia a sufficienza per permettere alle creature di taglia Media di attraversarla senza difficoltà e, una volta aperta, conduce a un semipiano che appare come una stanza vuota di legno o pietra ampia 9 metri in ogni dimensione. Al termine dell'incantesimo, la porta scompare e ogni creatura o oggetto all'interno rimane intrappolato nel semipiano, in quanto la porta scompare anche sul lato opposto.\\n\\nOgni volta che lancia questo incantesimo, l'incantatore può creare un nuovo semipiano o collegare la porta d'ombra a un semipiano da lui creato con un lancio precedente di questo incantesimo. Inoltre, se l'incantatore conosce la natura e i contenuti di un semipiano creato da un'altra creatura lanciando questo incantesimo, può fare invece in modo che la porta d'ombra si colleghi a quel semipiano.","castingTime":"1 azione","range":"18 metri","duration":"1 ora"}},"data":{"level":8,"school":"srd:rule:school-conjuration","classes":["srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["S"],"ritual":false,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:detect-evil-and-good","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Detect Evil and Good","description":"For the duration, you know if there is an aberration, celestial, elemental, fey, fiend, or undead within 30 feet of you, as well as where the creature is located. Similarly, you know if there is a place or object within 30 feet of you that has been magically consecrated or desecrated.\\n\\nThe spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt."},"it":{"name":"Individuazione del bene e del male","description":"Per tutta la durata dell'incantesimo, l'incantatore è a conoscenza della presenza e dell'esatta posizione di un'aberrazione, un celestiale, un elementale, un folletto, un immondo o un non morto entro 9 metri da lui. Allo stesso modo, sa se entro 9 metri da lui c'è un luogo o un oggetto consacrato o dissacrato magicamente.\\n\\nL'incantesimo può penetrare la maggior parte delle barriere, ma viene bloccato da 30 cm di pietra, 2,5 cm di metallo comune, una sottile lamina di piombo o 90 cm di legno o terriccio.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 10 minuti"}},"data":{"level":1,"school":"srd:rule:school-divination","classes":["srd:class:cleric","srd:class:paladin"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 10 minutes","area":{"type":"sphere","size":30}}},{"id":"srd:spell:detect-magic","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Detect Magic","description":"For the duration, you sense the presence of magic within 30 feet of you. If you sense magic in this way, you can use your action to see a faint aura around any visible creature or object in the area that bears magic, and you learn its school of magic, if any.\\n\\nThe spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt."},"it":{"name":"Individuazione del magico","description":"Per la durata dell'incantesimo, l'incantesimo percepisce la presenza della magia entro 9 metri. Se percepisce la magia in questo modo, può usare la sua azione per vedere una debole aura attorno a ogni creatura o oggetto visibile nell'area che contenga magia e apprende di che scuola di magia si tratta, se ne esiste una.\\n\\nL'incantesimo può penetrare la maggior parte delle barriere, ma viene bloccato da 30 cm di pietra, 2,5 cm di metallo comune, una sottile lamina di piombo o 90 cm di legno o terriccio.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 10 minuti"}},"data":{"level":1,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:cleric","srd:class:druid","srd:class:paladin","srd:class:ranger","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":true,"concentration":true,"duration":"Up to 10 minutes","area":{"type":"sphere","size":30}}},{"id":"srd:spell:detect-poison-and-disease","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Detect Poison and Disease","description":"For the duration, you can sense the presence and location of poisons, poisonous creatures, and diseases within 30 feet of you. You also identify the kind of poison, poisonous creature, or disease in each case.\\n\\nThe spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt."},"it":{"name":"Individuazione delle malattie e dei veleni","description":"Per la durata dell'incantesimo, l'incantatore può percepire la presenza o l'ubicazione di veleni, creature velenose o malattie entro 9 metri. Inoltre, in ciascun caso può identificare il tipo di pozione, di creatura velenosa o di malattia.\\n\\nL'incantesimo può penetrare la maggior parte delle barriere, ma viene bloccato da 30 cm di pietra, 2,5 cm di metallo comune, una sottile lamina di piombo o 90 cm di legno o terriccio.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 10 minuti","material":"una foglia di tasso"}},"data":{"level":1,"school":"srd:rule:school-divination","classes":["srd:class:cleric","srd:class:druid","srd:class:paladin","srd:class:ranger"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A yew leaf.","ritual":true,"concentration":true,"duration":"Up to 10 minutes","area":{"type":"sphere","size":30}}},{"id":"srd:spell:detect-thoughts","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Detect Thoughts","description":"For the duration, you can read the thoughts of certain creatures. When you cast the spell and as your action on each turn until the spell ends, you can focus your mind on any one creature that you can see within 30 feet of you. If the creature you choose has an Intelligence of 3 or lower or doesn't speak any language, the creature is unaffected.\\n\\nYou initially learn the surface thoughts of the creature - what is most on its mind in that moment. As an action, you can either shift your attention to another creature's thoughts or attempt to probe deeper into the same creature's mind. If you probe deeper, the target must make a Wisdom saving throw. If it fails, you gain insight into its reasoning (if any), its emotional state, and something that looms large in its mind (such as something it worries over, loves, or hates). If it succeeds, the spell ends. Either way, the target knows that you are probing into its mind, and unless you shift your attention to another creature's thoughts, the creature can use its action on its turn to make an Intelligence check contested by your Intelligence check; if it succeeds, the spell ends.\\n\\nQuestions verbally directed at the target creature naturally shape the course of its thoughts, so this spell is particularly effective as part of an interrogation.\\n\\nYou can also use this spell to detect the presence of thinking creatures you can't see. When you cast the spell or as your action during the duration, you can search for thoughts within 30 feet of you. The spell can penetrate barriers, but 2 feet of rock, 2 inches of any metal other than lead, or a thin sheet of lead blocks you. You can't detect a creature with an Intelligence of 3 or lower or one that doesn't speak any language.\\n\\nOnce you detect the presence of a creature in this way, you can read its thoughts for the rest of the duration as described above, even if you can't see it, but it must still be within range."},"it":{"name":"Individuazione dei pensieri","description":"Per la durata dell'incantesimo, l'incantatore può leggere i pensieri di alcune creature. Quando lancia l'incantesimo e come azione in ogni turno finché l'incantesimo non termina, l'incantatore può concentrarsi su una creatura che è in grado di vedere entro 9 metri da lui. Se la creatura scelta ha un'Intelligenza pari o inferiore a 3 o non parla alcun linguaggio, l'incantesimo non avrà effetti su di lei.\\n\\nAll'inizio, l'incantatore apprende i pensieri superficiali della creatura, ciò che sta pensando in quel momento. Con un'azione, l'incantatore può spostare l'attenzione verso i pensieri di un'altra creatura o provare a scavare più in profondità nella mente della creatura su cui era già concentrato. Nell'ultimo caso, il bersaglio deve effettuare un tiro salvezza su Saggezza. Se lo fallisce, l'incantatore riesce ad avere accesso ai suoi ragionamenti (se ne fa), al suo stato emotivo e a ciò che principalmente riempie la sua mente (qualcosa di cui si preoccupa, che ama o odia). In caso di successo, l'incantesimo termina. In ogni caso, il bersaglio è consapevole che l'incantatore ha accesso alla sua mente e, se quest'ultimo non sposta la sua attenzione verso i pensieri di un'altra creatura, può usare la sua azione nel proprio turno per effettuare una prova di Intelligenza contrapposta alla prova di Intelligenza dell'incantatore; in caso di successo, l'incantesimo termina.\\n\\nLe domande rivolte verbalmente alla creatura bersagliata plasmano naturalmente il corso dei suoi pensieri, per questo l'incantesimo è particolarmente efficace nel corso di un interrogatorio.\\n\\nL'incantatore può inoltre utilizzare questo incantesimo per individuare la presenza di creature pensanti che non è in grado di vedere. Quando lancia l'incantesimo o come azione durante la sua durata, l'incantatore può cercare pensieri in un raggio di 9 metri da sé. L'incantesimo può penetrare le barriere, ma viene bloccato da 60 cm di roccia, 5 cm di un metallo diverso dal piombo o da una sottile lamina di piombo. L'incantatore non può rilevare una creatura con un'Intelligenza pari o inferiore a 3, oppure una creatura che non parla alcun linguaggio.\\n\\nUna volta rilevata la presenza di una creatura in questo modo, l'incantatore può leggere i suoi pensieri per il resto della durata dell'incantesimo come descritto in precedenza, anche se non è in grado di vederla; la creatura, tuttavia, deve comunque trovarsi entro gittata.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 1 minuto","material":"una moneta di rame"}},"data":{"level":2,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A copper coin.","ritual":false,"concentration":true,"duration":"Up to 1 minute"}},{"id":"srd:spell:dimension-door","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Dimension Door","description":"You teleport yourself from your current location to any other spot within range. You arrive at exactly the spot desired. It can be a place you can see, one you can visualize, or one you can describe by stating distance and direction, such as \\"200 feet straight downward\\" or \\"upward to the northwest at a 45-degree angle, 300 feet.\\"\\n\\nYou can bring along objects as long as their weight doesn't exceed what you can carry. You can also bring one willing creature of your size or smaller who is carrying gear up to its carrying capacity. The creature must be within 5 feet of you when you cast this spell.\\n\\nIf you would arrive in a place already occupied by an object or a creature, you and any creature traveling with you each take 4d6 force damage, and the spell fails to teleport you."},"it":{"name":"Porta dimensionale","description":"L'incantatore si teletrasporta dalla posizione in cui si trova a un altro punto entro gittata. L'incantatore arriva precisamente nel luogo desiderato, che può essere un punto che è in grado di vedere, che riesce a visualizzare o che è in grado di descrivere dichiarandone la distanza e la direzione, come per esempio \\"60 metri in linea retta verso il basso\\" o \\"verso nord-ovest, a un'angolazione ascendente di 45 gradi per 90 metri\\".\\n\\nL'incantatore può portare con sé degli oggetti il cui peso non superi quello che è in grado di trasportare. Può inoltre portare con sé una creatura consenziente di taglia pari o inferiore alla sua, che trasporti dell'attrezzatura il cui peso non superi la sua capacità di trasporto. Al momento del lancio dell'incantesimo, la creatura non deve trovarsi a più di 1,5 metri dall'incantatore.\\n\\nSe il luogo d'arrivo è già occupato da un oggetto o una creatura, l'incantatore e la creatura che viaggia con lui subiscono 4d6 danni da forza e l'incantesimo di teletrasporto fallisce.","castingTime":"1 azione","range":"150 metri","duration":"Istantanea"}},"data":{"level":4,"school":"srd:rule:school-conjuration","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"500 feet","components":["V"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-force","atSlotLevel":{"4":"4d6"}}]}},{"id":"srd:spell:disguise-self","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Disguise Self","description":"You make yourself--including your clothing, armor, weapons, and other belongings on your person--look different until the spell ends or until you use your action to dismiss it. You can seem 1 foot shorter or taller and can appear thin, fat, or in between. You can't change your body type, so you must adopt a form that has the same basic arrangement of limbs. Otherwise, the extent of the illusion is up to you.\\n\\nThe changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to your outfit, objects pass through the hat, and anyone who touches it would feel nothing or would feel your head and hair. If you use this spell to appear thinner than you are, the hand of someone who reaches out to touch you would bump into you while it was seemingly still in midair.\\n\\nTo discern that you are disguised, a creature can use its action to inspect your appearance and must succeed on an Intelligence (Investigation) check against your spell save DC."},"it":{"name":"Camuffare se stesso","description":"L'incantatore assume un aspetto diverso (che include i suoi abiti, armatura, armi e altri oggetti personali presenti sulla sua persona) per la durata dell'incantesimo o finché non usa la sua azione per terminarlo. Può apparire 30 cm più alto o più basso e apparire magro, grasso o di corporatura normale. Non può cambiare il suo tipo di corpo, quindi deve adottare una forma che usi la stessa disposizione basilare degli arti. Entro questi limiti, la natura dell'illusione dipende da lui.\\n\\nI cambiamenti apportati da questo incantesimo non passano il vaglio di un'ispezione fisica. Per esempio, se l'incantatore usa questo incantesimo per aggiungere un cappello al suo abbigliamento, gli oggetti attraverserebbero il cappello e chiunque toccasse l'incantatore non sentirebbe nulla, o gli toccherebbe la testa e i capelli. Se l'incantatore usa questo incantesimo per apparire più magro rispetto alla realtà, quando qualcuno tenta di toccarlo incontrerebbe il suo corpo mentre la mano è ancora apparentemente a mezz'aria.\\n\\nPer capire che l'incantatore è camuffato, una creatura può usare la sua azione per ispezionarne l'aspetto e deve superare una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo.","castingTime":"1 azione","range":"Incantatore","duration":"1 ora"}},"data":{"level":1,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":false,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:disintegrate","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Disintegrate","description":"A thin green ray springs from your pointing finger to a target that you can see within range. The target can be a creature, an object, or a creation of magical force, such as the wall created by wall of force.\\n\\nA creature targeted by this spell must make a dexterity saving throw. On a failed save, the target takes 10d6 + 40 force damage. If this damage reduces the target to 0 hit points, it is disintegrated.\\n\\nA disintegrated creature and everything it is wearing and carrying, except magic items, are reduced to a pile of fine gray dust. The creature can be restored to life only by means of a true resurrection or a wish spell.\\n\\nThis spell automatically disintegrates a Large or smaller nonmagical object or a creation of magical force. If the target is a Huge or larger object or creation of force, this spell disintegrates a 10-foot-cube portion of it. A magic item is unaffected by this spell.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 7th level or higher, the damage increases by 3d6 for each slot level above 6th."},"it":{"name":"Disintegrazione","description":"Un sottile raggio verde si sprigiona dal dito indice dell'incantatore colpendo un bersaglio che è in grado di vedere entro gittata. Il bersaglio può essere una creatura, un oggetto o una creazione di forza magica, come un muro creato da muro di forza.\\n\\nUna creatura bersagliata da questo incantesimo deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 10d6 + 40 danni da forza. Se questo danno riduce il bersaglio a 0 punti ferita, esso si disintegra.\\n\\nUna creatura disintegrata e tutto ciò che indossa e trasporta, a eccezione degli oggetti magici, si riduce a un cumulo di sottile polvere grigia. Una creatura può essere riportata in vita solo da un incantesimo resurrezione pura o desiderio.\\n\\nQuesto incantesimo disintegra automaticamente un oggetto di taglia Grande o inferiore, oppure una creazione di forza magica. Se il bersaglio è un oggetto di taglia Enorme o superiore, oppure una creazione di forza, questo incantesimo ne disintegra una parte pari a un cubo di 3 metri. Un oggetto magico non è influenzato dall'incantesimo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° livello o superiore, i danni aumentano di 3d6 per ogni slot di livello superiore al 6°.","castingTime":"1 azione","range":"18 metri","duration":"Istantanea","material":"una calamita e un pizzico di polvere"}},"data":{"level":6,"school":"srd:rule:school-transmutation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"A lodestone and a pinch of dust.","ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-force","atSlotLevel":{"6":"10d6 + 40"}}],"savingThrow":{"ability":"dex","onSuccess":"none"},"area":{"type":"cube","size":10}}},{"id":"srd:spell:dispel-evil-and-good","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Dispel Evil and Good","description":"Shimmering energy surrounds and protects you from fey, undead, and creatures originating from beyond the Material Plane. For the duration, celestials, elementals, fey, fiends, and undead have disadvantage on attack rolls against you.\\n\\nYou can end the spell early by using either of the following special functions.\\n\\n***Break Enchantment.*** As your action, you touch a creature you can reach that is charmed, frightened, or possessed by a celestial, an elemental, a fey, a fiend, or an undead. The creature you touch is no longer charmed, frightened, or possessed by such creatures.\\n\\n***Dismissal.*** As your action, make a melee spell attack against a celestial, an elemental, a fey, a fiend, or an undead you can reach. On a hit, you attempt to drive the creature back to its home plane. The creature must succeed on a charisma saving throw or be sent back to its home plane (if it isn't there already). If they aren't on their home plane, undead are sent to the Shadowfell, and fey are sent to the Feywild."},"it":{"name":"Dissolvi il bene e il male","description":"L'incantatore viene circondato da un'energia scintillante che lo protegge da folletti, non morti e creature originarie di un piano diverso dal Piano Materiale. Per tutta la durata dell'incantesimo, celestiali, elementali, folletti, immondi e non morti subiscono svantaggio ai tiri per colpire effettuati contro l'incantatore.\\n\\nL'incantatore può terminare prematuramente l'incantesimo usando una delle funzioni speciali seguenti.\\n\\n***Congedo.*** Con un'azione, l'incantatore effettua un attacco in mischia con questo incantesimo contro un celestiale, un elementale, un folletto, un immondo o un non morto entro gittata. Se il colpo va a segno, l'incantatore tenta di respingere la creatura sul suo piano d'origine. Questa deve superare un tiro salvezza su Carisma, altrimenti viene cacciata sul suo piano d'origine (se non vi si trova già). Se non si trovano già sul loro piano d'origine, i non morti vengono respinti nella Coltre Oscura e i folletti nella Selva Fatata.\\n\\n***Spezzare ammaliamento.*** Con un'azione, l'incantatore tocca una creatura entro gittata affascinata, spaventata o posseduta da un celestiale, un elementale, un folletto, un immondo o un non morto. La creatura toccata non è più affascinata, spaventata o posseduta da quelle creature.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 1 minuto","material":"acqua santa o polvere d'argento e ferro"}},"data":{"level":5,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric","srd:class:paladin"],"subclasses":[],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"Holy water or powdered silver and iron.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"cha","onSuccess":"other"}}},{"id":"srd:spell:dispel-magic","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Dispel Magic","description":"Choose one creature, object, or magical effect within range. Any spell of 3rd level or lower on the target ends. For each spell of 4th level or higher on the target, make an ability check using your spellcasting ability. The DC equals 10 + the spell's level. On a successful check, the spell ends.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, you automatically end the effects of a spell on the target if the spell's level is equal to or less than the level of the spell slot you used."},"it":{"name":"Dissolvi magie","description":"L'incantatore sceglie una creatura, un oggetto o un effetto magico situato entro gittata. Ogni incantesimo di 3° livello o inferiore termina. Per ogni incantesimo di 4° livello o superiore presente sul bersaglio, l'incantatore effettua una prova di caratteristica usando la propria caratteristica da incantatore. La CD è pari a 10 + il livello dell'incantesimo. Se la prova viene superata, l'incantesimo termina.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, termina automaticamente gli effetti di un incantesimo sul bersaglio se il livello di quell'incantesimo è pari o inferiore al livello dello slot incantesimo usato dall'incantatore.","castingTime":"1 azione","range":"36 metri","duration":"Istantanea"}},"data":{"level":3,"school":"srd:rule:school-abjuration","classes":["srd:class:bard","srd:class:cleric","srd:class:druid","srd:class:paladin","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:devotion"],"castingTime":"1 action","range":"120 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:divination","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Divination","description":"Your magic and an offering put you in contact with a god or a god's servants. You ask a single question concerning a specific goal, event, or activity to occur within 7 days. The GM offers a truthful reply. The reply might be a short phrase, a cryptic rhyme, or an omen.\\n\\nThe spell doesn't take into account any possible circumstances that might change the outcome, such as the casting of additional spells or the loss or gain of a companion.\\n\\nIf you cast the spell two or more times before finishing your next long rest, there is a cumulative 25 percent chance for each casting after the first that you get a random reading. The GM makes this roll in secret."},"it":{"name":"Divinazione","description":"La magia e l'offerta mettono in contatto l'incantatore con una divinità o con un servitore della divinità. L'incantatore pone una sola domanda relativa a uno specifico obiettivo, evento o attività che si verificherà entro 7 giorni. Il GM fornisce una risposta onesta, che può essere una breve frase, una rima enigmatica o un presagio.\\n\\nL'incantesimo non prende in considerazione le potenziali circostanze che potrebbero alterare l'esito del presagio, come per esempio il lancio di incantesimi aggiuntivi o la perdita o l'acquisizione di un compagno.\\n\\nSe l'incantatore lancia l'incantesimo due o più volte prima di completare il suo riposo lungo successivo, esiste una probabilità cumulativa del 25% di ottenere un responso casuale per ogni lancio dopo il primo. Il GM effettua questo tiro in segreto.","castingTime":"1 azione","range":"Incantatore","duration":"Istantanea","material":"incenso e un'offerta sacrificale appropriata alla religione dell'incantatore del valore complessivo di almeno 25 mo, che l'incantesimo consuma"}},"data":{"level":4,"school":"srd:rule:school-divination","classes":["srd:class:druid"],"subclasses":["srd:subclass:land"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"Incense and a sacrificial offering appropriate to your religion, together worth at least 25gp, which the spell consumes.","ritual":true,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:divine-favor","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Divine Favor","description":"Your prayer empowers you with divine radiance. Until the spell ends, your weapon attacks deal an extra 1d4 radiant damage on a hit."},"it":{"name":"Favore divino","description":"Intonando una preghiera, l'incantatore è pervaso da radianza divina. Finché l'incantesimo non termina, i suoi attacchi con le armi infliggono 1d4 danni radiosi extra se il colpo va a segno.","castingTime":"1 azione bonus","range":"Incantatore","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":1,"school":"srd:rule:school-evocation","classes":["srd:class:paladin"],"subclasses":["srd:subclass:lore"],"castingTime":"1 bonus action","range":"Self","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","damage":[{"type":"srd:rule:damage-radiant","atSlotLevel":{"1":"1d4"}}]}},{"id":"srd:spell:divine-word","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Divine Word","description":"You utter a divine word, imbued with the power that shaped the world at the dawn of creation. Choose any number of creatures you can see within range. Each creature that can hear you must make a Charisma saving throw. On a failed save, a creature suffers an effect based on its current hit points:\\n\\n- 50 hit points or fewer: deafened for 1 minute\\n\\n- 40 hit points or fewer: deafened and blinded for 10 minutes\\n\\n- 30 hit points or fewer: blinded, deafened, and stunned for 1 hour\\n\\n- 20 hit points or fewer: killed instantly\\n\\nRegardless of its current hit points, a celestial, an elemental, a fey, or a fiend that fails its save is forced back to its plane of origin (if it isn't there already) and can't return to your current plane for 24 hours by any means short of a wish spell."},"it":{"name":"Parola divina","description":"L'incantatore pronuncia una parola divina, pregna del potere che plasmò il mondo all'alba della creazione. L'incantatore sceglie un qualsiasi numero di creature entro gittata che è in grado di vedere: ogni creatura in grado di sentirlo deve effettuare un tiro salvezza su Carisma. Se lo fallisce, una creatura soffre un effetto basato sui suoi punti ferita attuali:\\n\\n- 50 punti ferita o meno: assordata per 1 minuto\\n\\n- 40 punti ferita o meno: assordata e accecata per 10 minuti\\n\\n- 30 punti ferita o meno: assordata, accecata e stordita per 1 ora\\n\\n- 20 punti ferita o meno: uccisa istantaneamente\\n\\nIndipendentemente dai suoi punti ferita, un celestiale, un elementale, un folletto o un immondo che fallisce il suo tiro salvezza viene respinto sul suo piano d'origine (se non vi si trova già) e non può ritornare sul piano attuale dell'incantatore per 24 ore in alcun modo a eccezione che tramite un incantesimo desiderio.","castingTime":"1 azione bonus","range":"9 metri","duration":"Istantanea"}},"data":{"level":7,"school":"srd:rule:school-evocation","classes":["srd:class:cleric"],"subclasses":[],"castingTime":"1 bonus action","range":"30 feet","components":["V"],"ritual":false,"concentration":false,"duration":"Instantaneous","savingThrow":{"ability":"cha","onSuccess":"none"}}},{"id":"srd:spell:dominate-beast","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Dominate Beast","description":"You attempt to beguile a creature that you can see within range. It must succeed on a wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw.\\n\\nWhile the creature is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious (no action required), which it does its best to obey. You can specify a simple and general course of action, such as \\"Attack that creature,\\" \\"Run over there,\\" or \\"Fetch that object.\\" If the creature completes the order and doesn't receive further direction from you, it defends and preserves itself to the best of its ability.\\n\\nYou can use your action to take total and precise control of the target. Until the end of your next turn, the creature takes only the actions you choose, and doesn't do anything that you don't allow it to do. During this time, you can also cause the creature to use a reaction, but this requires you to use your own reaction as well. Each time the target takes damage, it makes a new wisdom saving throw against the spell. If the saving throw succeeds, the spell ends.\\n\\n**At Higher Levels.** When you cast this spell with a 9th level spell slot, the duration is concentration, up to 8 hours."},"it":{"name":"Dominare bestie","description":"L'incantatore tenta di soggiogare una bestia entro gittata che è in grado di vedere e che deve superare un tiro salvezza su Saggezza, altrimenti rimarrà affascinata per la durata dell'incantesimo. Se l'incantatore o le creature a lui amichevoli stanno combattendo questa bestia, essa dispone di vantaggio al tiro salvezza.\\n\\nMentre la bestia è affascinata, l'incantatore ha con essa un legame telepatico finché si trovano sullo stesso piano di esistenza. L'incantatore può utilizzare questo legame telepatico per impartire comandi alla creatura mentre è cosciente (nessuna azione richiesta), la quale fa del suo meglio per obbedire. L'incantatore può specificare una linea d'azione semplice e generale, come \\"attacca quella creatura\\", \\"corri fin laggiù\\" o \\"portami quell'oggetto\\". Se la creatura completa l'ordine e non riceve ulteriori indicazioni da parte dell'incantatore, si difende e si protegge al meglio delle sue abilità.\\n\\nL'incantatore può usare la sua azione per assumere il controllo totale e preciso del bersaglio. Fino al termine del turno successivo dell'incantatore, la creatura compie solamente le azioni decise da lui e non fa nulla che l'incantatore non le consenta di fare. Durante questo periodo, l'incantatore può anche fare in modo che la creatura utilizzi una reazione, ma per riuscirci lui dovrà fare altrettanto.\\n\\nOgni volta che il bersaglio subisce danni, effettua un tiro salvezza su Saggezza contro l'incantesimo: in caso di successo, l'incantesimo termina.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 5° livello, la durata diventa concentrazione, fino a 10 minuti. Quando usa uno slot incantesimo di 6° livello, la durata diventa concentrazione, fino a 1 ora. Quando usa uno slot incantesimo di 7° livello, la durata diventa concentrazione, fino a 8 ore.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":4,"school":"srd:rule:school-enchantment","classes":["srd:class:druid","srd:class:sorcerer"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:dominate-monster","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Dominate Monster","description":"You attempt to beguile a creature that you can see within range. It must succeed on a wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw.\\n\\nWhile the creature is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious (no action required), which it does its best to obey. You can specify a simple and general course of action, such as \\"Attack that creature,\\" \\"Run over there,\\" or \\"Fetch that object.\\" If the creature completes the order and doesn't receive further direction from you, it defends and preserves itself to the best of its ability.\\n\\nYou can use your action to take total and precise control of the target. Until the end of your next turn, the creature takes only the actions you choose, and doesn't do anything that you don't allow it to do. During this time, you can also cause the creature to use a reaction, but this requires you to use your own reaction as well.\\n\\nEach time the target takes damage, it makes a new wisdom saving throw against the spell. If the saving throw succeeds, the spell ends.\\n\\n**At Higher Levels.** When you cast this spell with a 9th-level spell slot, the duration is concentration, up to 8 hours."},"it":{"name":"Dominare mostri","description":"L'incantatore tenta di soggiogare una creatura entro gittata che è in grado di vedere e che deve superare un tiro salvezza su Saggezza, altrimenti rimarrà affascinata per la durata dell'incantesimo. Se l'incantatore o le creature a lui amichevoli stanno combattendo questa bestia, essa dispone di vantaggio al tiro salvezza.\\n\\nMentre la creatura è affascinata, l'incantatore ha con essa un legame telepatico finché si trovano sullo stesso piano di esistenza. L'incantatore può utilizzare questo legame telepatico per impartire comandi alla creatura mentre è cosciente (nessuna azione richiesta), la quale fa del suo meglio per obbedire. L'incantatore può specificare una linea d'azione semplice e generale, come \\"attacca quella creatura\\", \\"corri fin laggiù\\" o \\"portami quell'oggetto\\". Se la creatura completa l'ordine e non riceve ulteriori indicazioni da parte dell'incantatore, si difende e si protegge al meglio delle sue abilità.\\n\\nL'incantatore può usare la sua azione per assumere il controllo totale e preciso del bersaglio. Fino al termine del turno successivo dell'incantatore, la creatura compie solamente le azioni decise da lui e non fa nulla che l'incantatore non le consenta di fare. Durante questo periodo, l'incantatore può anche fare in modo che la creatura utilizzi una reazione, ma per riuscirci lui dovrà fare altrettanto.\\n\\nOgni volta che il bersaglio subisce danni, effettua un tiro salvezza su Saggezza contro l'incantesimo: in caso di successo, l'incantesimo termina.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 9° livello, la durata diventa concentrazione, fino a 8 ore.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 ora"}},"data":{"level":8,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 hour","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:dominate-person","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Dominate Person","description":"You attempt to beguile a humanoid that you can see within range. It must succeed on a wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw.\\n\\nWhile the target is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious (no action required), which it does its best to obey. You can specify a simple and general course of action, such as \\"Attack that creature,\\" \\"Run over there,\\" or \\"Fetch that object.\\" If the creature completes the order and doesn't receive further direction from you, it defends and preserves itself to the best of its ability.\\n\\nYou can use your action to take total and precise control of the target. Until the end of your next turn, the creature takes only the actions you choose, and doesn't do anything that you don't allow it to do. During this time you can also cause the creature to use a reaction, but this requires you to use your own reaction as well.\\n\\nEach time the target takes damage, it makes a new wisdom saving throw against the spell. If the saving throw succeeds, the spell ends.\\n\\n**At Higher Levels.** When you cast this spell using a 6th-level spell slot, the duration is concentration, up to 10 minutes. When you use a 7th-level spell slot, the duration is concentration, up to 1 hour. When you use a spell slot of 8th level or higher, the duration is concentration, up to 8 hours."},"it":{"name":"Dominare persone","description":"L'incantatore tenta di soggiogare un umanoide entro gittata che è in grado di vedere e che deve superare un tiro salvezza su Saggezza, altrimenti rimarrà affascinata per la durata dell'incantesimo. Se l'incantatore o le creature a lui amichevoli stanno combattendo questa bestia, essa dispone di vantaggio al tiro salvezza.\\n\\nMentre il bersaglio è affascinato, l'incantatore ha con lui un legame telepatico finché si trovano sullo stesso piano di esistenza. L'incantatore può utilizzare questo legame telepatico per impartire comandi alla creatura mentre è cosciente (nessuna azione richiesta), la quale fa del suo meglio per obbedire. L'incantatore può specificare una linea d'azione semplice e generale, come \\"attacca quella creatura\\", \\"corri fin laggiù\\" o \\"portami quell'oggetto\\". Se la creatura completa l'ordine e non riceve ulteriori indicazioni da parte dell'incantatore, si difende e si protegge al meglio delle sue abilità.\\n\\nL'incantatore può usare la sua azione per assumere il controllo totale e preciso del bersaglio. Fino al termine del turno successivo dell'incantatore, la creatura compie solamente le azioni decise da lui e non fa nulla che l'incantatore non le consenta di fare. Durante questo periodo, l'incantatore può anche fare in modo che la creatura utilizzi una reazione, ma per riuscirci lui dovrà fare altrettanto.\\n\\nOgni volta che il bersaglio subisce danni, effettua un tiro salvezza su Saggezza contro l'incantesimo: in caso di successo, l'incantesimo termina.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello, la durata diventa concentrazione, fino a 10 minuti. Quando usa uno slot incantesimo di 7° livello, la durata diventa concentrazione, fino a 1 ora. Quando usa uno slot incantesimo di 8° livello, la durata diventa concentrazione, fino a 8 ore.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":5,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"wis","onSuccess":"other"}}},{"id":"srd:spell:dream","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Dream","description":"This spell shapes a creature's dreams. Choose a creature known to you as the target of this spell. The target must be on the same plane of existence as you. Creatures that don't sleep, such as elves, can't be contacted by this spell. You, or a willing creature you touch, enters a trance state, acting as a messenger.\\n\\nWhile in the trance, the messenger is aware of his or her surroundings, but can't take actions or move.\\n\\nIf the target is asleep, the messenger appears in the target's dreams and can converse with the target as long as it remains asleep, through the duration of the spell. The messenger can also shape the environment of the dream, creating landscapes, objects, and other images. The messenger can emerge from the trance at any time, ending the effect of the spell early. The target recalls the dream perfectly upon waking. If the target is awake when you cast the spell, the messenger knows it, and can either end the trance (and the spell) or wait for the target to fall asleep, at which point the messenger appears in the target's dreams.\\n\\nYou can make the messenger appear monstrous and terrifying to the target. If you do, the messenger can deliver a message of no more than ten words and then the target must make a wisdom saving throw. On a failed save, echoes of the phantasmal monstrosity spawn a nightmare that lasts the duration of the target's sleep and prevents the target from gaining any benefit from that rest. In addition, when the target wakes up, it takes 3d6 psychic damage.\\n\\nIf you have a body part, lock of hair, clipping from a nail, or similar portion of the target's body, the target makes its saving throw with disadvantage."},"it":{"name":"Sogno","description":"Questo incantesimo modella i sogni di una creatura. L'incantatore sceglie come bersaglio dell'incantesimo una creatura a lui nota, che deve trovarsi sul suo stesso piano di esistenza. Le creature che non dormono, come gli elfi, non possono essere contattate con questo incantesimo. L'incantatore o una creatura consenziente da lui toccata entra in uno stato di trance, assumendo il ruolo di messaggero. Durante la trance, il messaggero è consapevole di ciò che lo circonda, ma non può intraprendere azioni o muoversi.\\n\\nSe il bersaglio dorme, il messaggero gli appare in sogno e può conversare con lui finché rimane addormentato e l'incantesimo non termina. Il messaggero può anche modellare l'ambiente del sogno, creando paesaggi, oggetti e altre immagini. Il messaggero può uscire dalla trance in ogni momento, terminando prematuramente l'effetto dell'incantesimo. Al suo risveglio, il bersaglio ricorda il sogno perfettamente. Se il bersaglio è sveglio quando l'incantatore lancia l'incantesimo, il messaggero ne è consapevole e può terminare la trance (e l'incantesimo) o aspettare che il bersaglio si addormenti e così apparire nei suoi sogni.\\n\\nL'incantatore può fare in modo che il messaggero appaia mostruoso e terrificante al bersaglio. In questo caso, il messaggero può trasmettere un messaggio di massimo dieci parole e poi il bersaglio deve effettuare un tiro salvezza su Saggezza. Se lo fallisce, echi della mostruosità spettrale generano un incubo che permane per tutta la durata del suo sonno e gli impedisce di ottenere benefici da quel riposo. Inoltre, al suo risveglio, il bersaglio subisce 3d6 danni psichici.\\n\\nSe l'incantatore possiede una parte del corpo, una ciocca di capelli, un frammento di unghia o parti analoghe del corpo del bersaglio, questo subisce svantaggio al tiro salvezza.","castingTime":"1 minuto","range":"Speciale","duration":"8 ore","material":"una manciata di sabbia, una goccia d'inchiostro e un penna strappata a un uccello addormentato"}},"data":{"level":5,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:land"],"castingTime":"1 minute","range":"Special","components":["V","S","M"],"material":"A handful of sand, a dab of ink, and a writing quill plucked from a sleeping bird.","ritual":false,"concentration":false,"duration":"8 hours","damage":[{"type":"srd:rule:damage-psychic","atSlotLevel":{"5":"3d6"}}],"savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:druidcraft","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Druidcraft","description":"Whispering to the spirits of nature, you create one of the following effects within 'range':\\n\\n- You create a tiny, harmless sensory effect that predicts what the weather will be at your location for the next 24 hours. The effect might manifest as a golden orb for clear skies, a cloud for rain, falling snowflakes for snow, and so on. This effect persists for 1 round.\\n\\n- You instantly make a flower bloom, a seed pod open, or a leaf bud bloom.\\n\\n- You create an instantaneous, harmless sensory effect, such as falling leaves, a puff of wind, the sound of a small animal, or the faint order of skunk. The effect must fit in a 5-foot cube.\\n\\n- You instantly light or snuff out a candle, a torch, or a small campfire."},"it":{"name":"Artificio druidico","description":"Sussurrando agli spiriti della natura, l'incantatore crea uno degli effetti seguenti entro gittata:\\n\\n- L'incantatore crea un minuscolo e innocuo effetto sensoriale che predice il tempo atmosferico nel luogo in cui si trova per le successive 24 ore. L'effetto potrebbe manifestarsi come una sfera dorata in caso di cieli tersi, una nuvola in caso di pioggia, fiocchi di neve in caso di nevicate e così via. Questo effetto permane per 1 round.\\n\\n- L'incantatore fa istantaneamente sbocciare un fiore, aprire un baccello o schiudere un germoglio.\\n\\n- L'incantatore crea un effetto sensoriale innocuo e istantaneo, come la caduta di foglie, una folata di vento, il rumore di un piccolo animale o il debole odore di una puzzola. L'effetto deve poter essere contenuto in un cubo di 1,5 metri.\\n\\n- L'incantatore accende o spegne istantaneamente una candela, una torcia o un piccolo fuoco da campo.","castingTime":"1 azione","range":"9 metri","duration":"Istantanea"}},"data":{"level":0,"school":"srd:rule:school-transmutation","classes":["srd:class:druid"],"subclasses":[],"castingTime":"1 action","range":"30 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:earthquake","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Earthquake","description":"You create a seismic disturbance at a point on the ground that you can see within range. For the duration, an intense tremor rips through the ground in a 100-foot-radius circle centered on that point and shakes creatures and structures in contact with the ground in that area.\\n\\nThe ground in the area becomes difficult terrain. Each creature on the ground that is concentrating must make a constitution saving throw. On a failed save, the creature's concentration is broken.\\n\\nWhen you cast this spell and at the end of each turn you spend concentrating on it, each creature on the ground in the area must make a dexterity saving throw. On a failed save, the creature is knocked prone.\\n\\nThis spell can have additional effects depending on the terrain in the area, as determined by the GM.\\n\\nFissures. Fissures open throughout the spell's area at the start of your next turn after you cast the spell. A total of 1d6 such fissures open in locations chosen by the GM. Each is 1d10 x 10 feet deep, 10 feet wide, and extends from one edge of the spell's area to the opposite side. A creature standing on a spot where a fissure opens must succeed on a dexterity saving throw or fall in. A creature that successfully saves moves with the fissure's edge as it opens.\\n\\nA fissure that opens beneath a structure causes it to automatically collapse (see below).\\n\\nStructures. The tremor deals 50 bludgeoning damage to any structure in contact with the ground in the area when you cast the spell and at the start of each of your turns until the spell ends. If a structure drops to 0 hit points, it collapses and potentially damages nearby creatures. A creature within half the distance of a structure's height must make a dexterity saving throw. On a failed save, the creature takes 5d6 bludgeoning damage, is knocked prone, and is buried in the rubble, requiring a DC 20 Strength (Athletics) check as an action to escape. The GM can adjust the DC higher or lower, depending on the nature of the rubble. On a successful save, the creature takes half as much damage and doesn't fall prone or become buried."},"it":{"name":"Terremoto","description":"L'incantatore crea una scossa sismica in un punto del terreno entro gittata che è in grado di vedere. Per la durata dell'incantesimo, una scossa intensa sconquassa il terreno in un raggio di 30 metri centrato su quel punto e scuote creature e strutture a contatto con il terreno di quell'area.\\n\\nIl terreno nell'area diventa terreno difficile: qualsiasi creatura si stia concentrando all'interno dell'area deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, la sua concentrazione viene interrotta.\\n\\nQuando l'incantatore lancia questo incantesimo e alla fine di ogni turno trascorso a concentrarsi su di esso, ogni creatura sul terreno nell'area deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, la creatura viene buttata a terra prona.\\n\\nQuesto incantesimo può avere degli effetti aggiuntivi in base al terreno nell'area, come determinato dal GM.\\n\\nCrepe. Dopo aver lanciato l'incantesimo, per tutta l'area interessata si aprono delle crepe a partire dall'inizio del turno successivo dell'incantatore. Un totale di 1d6 crepe di questo tipo si apre in punti scelti dal GM. Ognuna di esse è profonda 1d10 × 3 metri, ampia 3 metri e si estende da un lato all'altro dell'area dell'incantesimo. Se una creatura si trova nel punto i cui si apre una crepa, deve superare un tiro salvezza su Destrezza o vi cade dentro. Una creatura che supera il tiro salvezza riesce a spostarsi insieme al bordo della crepa mentre si apre.\\n\\nUna crepa che si apre sotto una struttura ne provoca il crollo immediato (vedi di seguito).\\n\\nStrutture. La scossa infligge 50 danni contundenti a una qualsiasi struttura a contatto con il terreno nell'area in cui è stato lanciato l'incantesimo e all'inizio di ogni turno dell'incantatore fino al termine dell'incantesimo. Se la struttura scende a 0 punti ferita, crolla e potenzialmente danneggia le creature vicine. Una creatura situata a una distanza pari alla metà dell'altezza della struttura deve effettuare un tiro salvezza su Destrezza. Se fallisce, subisce 5d6 danni contundenti, viene buttata a terra prona e rimane sepolta sotto le macerie; per liberarsi con un'azione deve effettuare una prova di Forza (Atletica) con CD 20. Il GM può aumentare o ridurre la CD, in base alla natura delle macerie. In caso di successo, subisce la metà dei danni, non viene buttata a terra prona e non viene sepolta sotto le macerie.","castingTime":"1 azione","range":"150 metri","duration":"Concentrazione, fino a 1 minuto","material":"un pizzico di terriccio, un frammento di roccia e un pezzo d'argilla"}},"data":{"level":8,"school":"srd:rule:school-evocation","classes":["srd:class:cleric","srd:class:druid","srd:class:sorcerer"],"subclasses":[],"castingTime":"1 action","range":"500 feet","components":["V","S","M"],"material":"A pinch of dirt, a piece of rock, and a lump of clay.","ritual":false,"concentration":true,"duration":"Up to 1 minute","area":{"type":"sphere","size":100}}},{"id":"srd:spell:eldritch-blast","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Eldritch Blast","description":"A beam of crackling energy streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 force damage. The spell creates more than one beam when you reach higher levels: two beams at 5th level, three beams at 11th level, and four beams at 17th level. You can direct the beams at the same target or at different ones. Make a separate attack roll for each beam."},"it":{"name":"Deflagrazione occulta","description":"Un raggio di energia crepitante viene scagliato contro una creatura entro gittata effettuando un attacco a distanza con incantesimo contro il bersaglio. Se il colpo va a segno, il bersaglio subisce 1d10 danni da forza.\\n\\nL'incantesimo crea più raggi quando l'incantatore raggiunge livelli superiori: due raggi al 5° livello, tre raggi all'11° livello e quattro raggi al 17° livello. L'incantatore può indirizzare i raggi contro lo stesso bersaglio o contro bersagli differenti, effettuando un tiro per colpire separato per ogni raggio.","castingTime":"1 azione","range":"36 metri","duration":"Istantanea"}},"data":{"level":0,"school":"srd:rule:school-evocation","classes":["srd:class:warlock"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"120 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-force","atCharacterLevel":{"1":"1d10","5":"1d10","11":"1d10","17":"1d10"}}],"attackType":"ranged"}},{"id":"srd:spell:enhance-ability","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Enhance Ability","description":"You touch a creature and bestow upon it a magical enhancement. Choose one of the following effects; the target gains that effect until the spell ends.\\n\\n***Bear's Endurance.*** The target has advantage on constitution checks. It also gains 2d6 temporary hit points, which are lost when the spell ends.\\n\\n***Bull's Strength.*** The target has advantage on strength checks, and his or her carrying capacity doubles.\\n\\n***Cat's Grace.*** The target has advantage on dexterity checks. It also doesn't take damage from falling 20 feet or less if it isn't incapacitated.\\n\\n***Eagle's Splendor.*** The target has advantage on Charisma checks.\\n\\n***Fox's Cunning.*** The target has advantage on intelligence checks.\\n\\n***Owl's Wisdom.*** The target has advantage on wisdom checks.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd."},"it":{"name":"Caratteristica potenziata","description":"L'incantatore tocca una creatura e le concede un potenziamento magico, scegliendo uno tra gli effetti seguenti che permane fino al termine dell'incantesimo.\\n\\n***Astuzia della volpe.*** Il bersaglio dispone di vantaggio alle prove di Intelligenza.\\n\\n***Forza del toro.*** Il bersaglio dispone di vantaggio alle prove di Forza e la sua capacità di trasporto raddoppia.\\n\\n***Grazia del gatto.*** Il bersaglio dispone di vantaggio alle prove di Destrezza e non subisce danni se cade da 6 metri o meno, purché non sia incapacitato.\\n\\n***Resistenza dell'orso.*** Il bersaglio dispone di vantaggio alle prove di Costituzione e ottiene inoltre 2d6 punti ferita temporanei, che perde al termine dell'incantesimo.\\n\\n***Saggezza del gufo.*** Il bersaglio dispone di vantaggio alle prove di Saggezza.\\n\\n***Splendore dell'aquila.*** Il bersaglio dispone di vantaggio alle prove di Carisma.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, può bersagliare una creatura aggiuntiva per ogni slot superiore al 2°.","castingTime":"1 azione","range":"Contatto","duration":"Concentrazione, fino a 1 ora.","material":"un ciuffo di pelliccia o una piuma strappata a una bestia"}},"data":{"level":2,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:cleric","srd:class:druid","srd:class:sorcerer"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"Fur or a feather from a beast.","ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:enlarge-reduce","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Enlarge/Reduce","description":"You cause a creature or an object you can see within range to grow larger or smaller for the duration. Choose either a creature or an object that is neither worn nor carried. If the target is unwilling, it can make a Constitution saving throw. On a success, the spell has no effect.\\n\\nIf the target is a creature, everything it is wearing and carrying changes size with it. Any item dropped by an affected creature returns to normal size at once.\\n\\n***Enlarge.*** The target's size doubles in all dimensions, and its weight is multiplied by eight. This growth increases its size by one category-from Medium to Large, for example. If there isn't enough room for the target to double its size, the creature or object attains the maximum possible size in the space available. Until the spell ends, the target also has advantage on Strength checks and Strength saving throws. The target's weapons also grow to match its new size. While these weapons are enlarged, the target's attacks with them deal 1d4 extra damage.\\n\\n***Reduce.*** The target's size is halved in all dimensions, and its weight is reduced to one-eighth of normal. This reduction decreases its size by one category-from Medium to Small, for example. Until the spell ends, the target also has disadvantage on Strength checks and Strength saving throws. The target's weapons also shrink to match its new size. While these weapons are reduced, the target's attacks with them deal 1d4 less damage (this can't reduce the damage below 1)."},"it":{"name":"Ingrandire/Ridurre","description":"Per tutta la durata dell'incantesimo, l'incantatore ingrandisce o riduce la taglia di una creatura o un oggetto entro gittata che è in grado di vedere, scegliendo una creatura o un oggetto che non sia né indossato né trasportato. Il bersaglio può effettuare un tiro salvezza su Costituzione se non è consenziente. Se lo supera, l'incantesimo non sortisce alcun effetto.\\n\\nSe il bersaglio è una creatura, tutto ciò che indossa o trasporta cambia di taglia insieme a lei e, se lascia cadere un oggetto, questo torna immediatamente alla sua taglia normale.\\n\\n***Ingrandire.*** La taglia del bersaglio raddoppia in tutte le dimensioni e il suo peso aumenta di otto volte. Questa crescita aumenta la sua taglia di una categoria (da Media a Grande, per esempio). Se non c'è abbastanza spazio per consentire al bersaglio di raddoppiare la sua taglia, la creatura o l'oggetto in questione cresce fino a raggiungere la taglia maggiore possibile nello spazio disponibile.\\n\\nFino al termine dell'incantesimo, il bersaglio dispone anche di vantaggio alle prove di Forza e ai tiri salvezza su Forza. Inoltre, le sue armi crescono fino ad adattarsi alla sua nuova taglia. Finché queste armi sono ingrandite, gli attacchi effettuati dal bersaglio con esse infliggono 1d4 danni extra.\\n\\n***Ridurre.*** La taglia del bersaglio è dimezzata in tutte le dimensioni e il suo peso si riduce a un ottavo del peso normale. Questa riduzione diminuisce la sua taglia di una categoria (da Media a Piccola, per esempio). Fino al termine dell'incantesimo, il bersaglio subisce anche svantaggio alle prove di Forza e ai tiri salvezza su Forza. Inoltre, le sue armi si riducono fino ad adattarsi alla sua nuova taglia. Finché queste armi sono ridotte, gli attacchi effettuati dal bersaglio con esse infliggono 1d4 danni in meno (i danni non possono scendere a meno di 1).","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 1 minuto","material":"un pizzico di polvere di ferro"}},"data":{"level":2,"school":"srd:rule:school-transmutation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A pinch iron powder.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"con","onSuccess":"none"}}},{"id":"srd:spell:entangle","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Entangle","description":"Grasping weeds and vines sprout from the ground in a 20-foot square starting form a point within range. For the duration, these plants turn the ground in the area into difficult terrain.\\n\\nA creature in the area when you cast the spell must succeed on a strength saving throw or be restrained by the entangling plants until the spell ends. A creature restrained by the plants can use its action to make a Strength check against your spell save DC. On a success, it frees itself.\\n\\nWhen the spell ends, the conjured plants wilt away."},"it":{"name":"Intralciare","description":"Erbacce e rampicanti spuntano dal terreno in un'area di 6 metri per lato che ha origine da un punto situato entro gittata. Per la durata dell'incantesimo, i vegetali trasformano quell'area in un terreno difficile.\\n\\nUna creatura all'interno dell'area quando viene lanciato l'incantesimo deve superare un tiro salvezza su Forza, altrimenti è trattenuta da vegetali intralcianti fino al termine dell'incantesimo. Una creatura così trattenuta può usare la sua azione per effettuare una prova di Forza contro la CD del tiro salvezza sull'incantesimo. In caso di successo, si libera.\\n\\nAl termine dell'incantesimo, i vegetali evocati avvizziscono.","castingTime":"1 azione","range":"27 metri","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":1,"school":"srd:rule:school-conjuration","classes":["srd:class:druid"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"90 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"str","onSuccess":"none"},"area":{"type":"cube","size":20}}},{"id":"srd:spell:enthrall","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Enthrall","description":"You weave a distracting string of words, causing creatures of your choice that you can see within range and that can hear you to make a wisdom saving throw. Any creature that can't be charmed succeeds on this saving throw automatically, and if you or your companions are fighting a creature, it has advantage on the save. On a failed save, the target has disadvantage on Wisdom (Perception) checks made to perceive any creature other than you until the spell ends or until the target can no longer hear you. The spell ends if you are incapacitated or can no longer speak."},"it":{"name":"Estasiare","description":"L'incantatore pronuncia una sequenza di parole disorientante, costringendo le creature da lui scelte entro gittata, che sono in grado di sentirlo e che egli è in grado di vedere, a effettuare un tiro salvezza su Saggezza. Qualsiasi creatura che non può essere affascinata supera automaticamente questo tiro salvezza. Inoltre, se l'incantatore e i suoi compagni stanno combattendo contro una creatura, quella dispone di vantaggio al tiro salvezza. Se lo fallisce, il bersaglio subisce svantaggio alle prove di Saggezza (Percezione) effettuate per percepire una qualsiasi creatura diversa dall'incantatore, finché l'incantesimo non termina o finché il bersaglio non è più in grado di sentirlo. L'incantesimo termina se l'incantatore è incapacitato o non è più in grado di parlare.","castingTime":"1 azione","range":"18 metri","duration":"1 minuto"}},"data":{"level":2,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:warlock"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"1 minute","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:etherealness","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Etherealness","description":"You step into the border regions of the Ethereal Plane, in the area where it overlaps with your current plane. You remain in the Border Ethereal for the duration or until you use your action to dismiss the spell. During this time, you can move in any direction. If you move up or down, every foot of movement costs an extra foot. You can see and hear the plane you originated from, but everything there looks gray, and you can't see anything more than 60 feet away.\\n\\nWhile on the Ethereal Plane, you can only affect and be affected by other creatures on that plane. Creatures that aren't on the Ethereal Plane can't perceive you and can't interact with you, unless a special ability or magic has given them the ability to do so.\\n\\nYou ignore all objects and effects that aren't on the Ethereal Plane, allowing you to move through objects you perceive on the plane you originated from.\\n\\nWhen the spell ends, you immediately return to the plane you originated from in the spot you currently occupy. If you occupy the same spot as a solid object or creature when this happens, you are immediately shunted to the nearest unoccupied space that you can occupy and take force damage equal to twice the number of feet you are moved.\\n\\nThis spell has no effect if you cast it while you are on the Ethereal Plane or a plane that doesn't border it, such as one of the Outer Planes.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 8th level or higher, you can target up to three willing creatures (including you) for each slot level above 7th. The creatures must be within 10 feet of you when you cast the spell."},"it":{"name":"Forma eterea","description":"L'incantatore mette piede nelle regioni di confine del Piano Etereo, nell'area in cui si sovrappone al suo piano attuale. Rimane nel Confine Etereo per la durata dell'incantesimo o finché non utilizza la sua azione per terminarlo. Durante questo periodo, l'incantatore può muoversi in ogni direzione. Muovendosi su o giù, ogni 30 cm di movimento gli costano 30 cm extra. L'incantatore può sentire e vedere il piano da cui proviene, ma tutto gli appare grigio e visibile solo fino a una distanza di 18 metri.\\n\\nMentre l'incantatore si trova sul Piano Etereo, può influenzare ed essere influenzato solo dalle creature che si trovano su quel piano. Le creature che non sono presenti sul Piano Etereo non possono percepire o interagire con l'incantatore, a meno che non siano dotate di magia o di una qualche capacità speciale per farlo.\\n\\nL'incantatore ignora tutti gli oggetti e gli effetti che non si trovano sul Piano Etereo, cosa che gli consente di muoversi attraverso gli oggetti che percepisce sul piano da cui proviene.\\n\\nAl termine dell'incantesimo, l'incantatore ritorna immediatamente sul piano di provenienza, nel punto in cui si trova attualmente. Se quel punto è occupato da un oggetto solido o da una creatura, l'incantatore viene subito sbalzato nello spazio libero più vicino che può occupare e subisce una quantità di danni da forza pari al doppio del numero di metri di cui si è mosso.\\n\\nQuesto incantesimo non ha effetto se l'incantatore lo lancia mentre si trova sul Piano Etereo o su un piano non confinante, come uno dei Piani Esterni.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 8° livello o superiore, può bersagliare fino a tre creature consenzienti (incluso sé stesso) per ogni slot superiore al 7°. Al momento del lancio dell'incantesimo, le creature non devono trovarsi a più di 3 metri dall'incantatore.","castingTime":"1 azione","range":"Incantatore","duration":"Fino a 8 ore"}},"data":{"level":7,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:cleric","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":false,"concentration":false,"duration":"8 hours"}},{"id":"srd:spell:expeditious-retreat","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Expeditious Retreat","description":"This spell allows you to move at an incredible pace. When you cast this spell, and then as a bonus action on each of your turns until the spell ends, you can take the Dash action."},"it":{"name":"Ritirata rapida","description":"Questo incantesimo permette all'incantatore di muoversi a una velocità straordinaria. Quando lancia questo incantesimo e poi come azione bonus a ogni suo turno, può effettuare l'azione Scatto.","castingTime":"1 azione bonus","range":"Incantatore","duration":"Concentrazione, fino a 10 minuti"}},"data":{"level":1,"school":"srd:rule:school-transmutation","classes":["srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 bonus action","range":"Self","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 10 minutes"}},{"id":"srd:spell:eyebite","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Eyebite","description":"For the spell's duration, your eyes become an inky void imbued with dread power. One creature of your choice within 60 feet of you that you can see must succeed on a wisdom saving throw or be affected by one of the following effects of your choice for the duration. On each of your turns until the spell ends, you can use your action to target another creature but can't target a creature again if it has succeeded on a saving throw against this casting of eyebite.\\n\\n***Asleep.*** The target falls unconscious. It wakes up if it takes any damage or if another creature uses its action to shake the sleeper awake.\\n\\n***Panicked.*** The target is frightened of you. On each of its turns, the frightened creature must take the Dash action and move away from you by the safest and shortest available route, unless there is nowhere to move. If the target moves to a place at least 60 feet away from you where it can no longer see you, this effect ends.\\n\\n***Sickened.*** The target has disadvantage on attack rolls and ability checks. At the end of each of its turns, it can make another wisdom saving throw. If it succeeds, the effect ends."},"it":{"name":"Sguardo penetrante","description":"Per tutta la durata dell'incantesimo, gli occhi dell'incantatore diventano neri, vacui e pervasi da un potere sinistro. Una creatura a scelta dell'incantatore entro 18 metri da lui e che è in grado di vedere deve superare un tiro salvezza su Saggezza o essere influenzata da uno dei seguenti effetti a sua scelta per la durata dell'incantesimo. In ogni suo turno finché l'incantesimo non termina, l'incantatore può usare un'azione per bersagliare un'altra creatura, non potendo tuttavia bersagliare di nuovo una creatura che abbia superato un tiro salvezza contro questo lancio di sguardo penetrante.\\n\\n***Addormentato.*** Il bersaglio cade privo di sensi, riprendendosi se subisce danni o se un'altra creatura usa la propria azione per risvegliarlo scuotendolo.\\n\\n***In preda al panico.*** Il bersaglio è spaventato dall'incantatore. In ogni suo turno, la creatura spaventata deve effettuare l'azione Scatto e muoversi per allontanarsi dall'incantatore lungo il percorso più sicuro e rapido possibile, sempre che abbia lo spazio per muoversi. Se il bersaglio si muove in un punto a più di 18 metri dall'incantatore dove non è più in grado di vederlo, l'effetto termina.\\n\\n***Nauseato.*** Il bersaglio subisce svantaggio ai tiri per colpire e alle prove di caratteristica e può effettuare un altro tiro salvezza su Saggezza alla fine di ogni suo turno. In caso di successo, l'effetto termina.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":6,"school":"srd:rule:school-necromancy","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:fabricate","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Fabricate","description":"You convert raw materials into products of the same material. For example, you can fabricate a wooden bridge from a clump of trees, a rope from a patch of hemp, and clothes from flax or wool.\\n\\nChoose raw materials that you can see within range. You can fabricate a Large or smaller object (contained within a 10-foot cube, or eight connected 5-foot cubes), given a sufficient quantity of raw material. If you are working with metal, stone, or another mineral substance, however, the fabricated object can be no larger than Medium (contained within a single 5-foot cube). The quality of objects made by the spell is commensurate with the quality of the raw materials.\\n\\nCreatures or magic items can't be created or transmuted by this spell. You also can't use it to create items that ordinarily require a high degree of craftsmanship, such as jewelry, weapons, glass, or armor, unless you have proficiency with the type of artisan's tools used to craft such objects."},"it":{"name":"Fabbricare","description":"L'incantatore converte materie prime in prodotti dello stesso materiale. Per esempio, può fabbricare un ponte di legno da una catasta di tronchi, una corda da un groviglio di canapa e abiti da lino o lana.\\n\\nL'incantatore sceglie materie prime entro gittata che è in grado di vedere e, qualora ne possegga una quantità sufficiente, può fabbricare un oggetto di taglia Grande o inferiore (contenuto in un cubo di 3 metri o in otto cubi di 1,5 metri collegati tra loro). Tuttavia, se l'incantatore lavora con metallo, pietra o un'altra sostanza minerale, l'oggetto fabbricato potrà essere al massimo di taglia Media (contenuto in un solo cubo di 1,5 metri). La qualità degli oggetti realizzati dall'incantesimo è proporzionale alla qualità delle materie prime.\\n\\nQuesto incantesimo non può creare o trasmutare creature o oggetti magici. Inoltre, l'incantatore non può utilizzarlo per creare oggetti che normalmente richiedono un alto grado di precisione, come gioielli, armi, vetro o armature, a meno che non possegga competenza con il tipo di strumenti da artigiano usati per realizzare tali oggetti.","castingTime":"10 minuti","range":"36 metri","duration":"Istantanea"}},"data":{"level":4,"school":"srd:rule:school-transmutation","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"10 minutes","range":"120 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:faerie-fire","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Faerie Fire","description":"Each object in a 20-foot cube within range is outlined in blue, green, or violet light (your choice). Any creature in the area when the spell is cast is also outlined in light if it fails a dexterity saving throw. For the duration, objects and affected creatures shed dim light in a 10-foot radius.\\n\\nAny attack roll against an affected creature or object has advantage if the attacker can see it, and the affected creature or object can't benefit from being invisible."},"it":{"name":"Luminescenza","description":"Ogni oggetto contenuto in un cubo di 6 metri entro gittata viene evidenziato da un alone di luce blu, verde o viola (a scelta dell'incantatore). Al momento del lancio dell'incantesimo, ogni creatura presente nell'area viene a sua volta evidenziata dall'alone di luce se fallisce un tiro salvezza su Destrezza. Gli oggetti e le creature influenzate proiettano luce fioca entro un raggio di 3 metri per tutta la durata dell'incantesimo.\\n\\nOgni tiro per colpire contro una creatura o un oggetto influenzato dall'incantesimo dispone di vantaggio se l'attaccante è in grado di vederlo e se la creatura o oggetto non trae beneficio dal fatto di essere invisibile.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":1,"school":"srd:rule:school-evocation","classes":["srd:class:druid"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"dex","onSuccess":"none"},"area":{"type":"cube","size":20}}},{"id":"srd:spell:faithful-hound","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Faithful Hound","description":"You conjure a phantom watchdog in an unoccupied space that you can see within range, where it remains for the duration, until you dismiss it as an action, or until you move more than 100 feet away from it.\\n\\nThe hound is invisible to all creatures except you and can't be harmed. When a Small or larger creature comes within 30 feet of it without first speaking the password that you specify when you cast this spell, the hound starts barking loudly. The hound sees invisible creatures and can see into the Ethereal Plane. It ignores illusions.\\n\\nAt the start of each of your turns, the hound attempts to bite one creature within 5 feet of it that is hostile to you. The hound's attack bonus is equal to your spellcasting ability modifier + your proficiency bonus. On a hit, it deals 4d8 piercing damage."},"it":{"name":"Segugio fedele","description":"L'incantatore evoca un cane da guardia fantasma in uno spazio libero entro gittata che è in grado di vedere e che lì rimane per la durata dell'incantesimo, finché l'incantatore non lo congeda con un'azione o si allontana a più di 30 metri da lui.\\n\\nIl segugio è invisibile a tutte le creature tranne all'incantatore e non può essere ferito. Quando una creatura di taglia Piccola o inferiore si avvicina entro 9 metri dal segugio senza prima aver pronunciato la parola d'ordine specificata dall'incantatore al momento del lancio dell'incantesimo, il segugio inizia ad abbaiare sonoramente. Inoltre, il segugio può vedere le creature invisibili e proiettare la sua vista sul Piano Etereo, e ignora le illusioni.\\n\\nAll'inizio di ogni turno dell'incantatore, il segugio tenta di mordere una creatura ostile all'incantatore entro 1,5 metri da lui. Il bonus di attacco del segugio è pari al modificatore di caratteristica da incantatore + il bonus di competenza dell'incantatore. Se il colpo va a segno, infligge 4d8 danni perforanti.","castingTime":"1 azione","range":"9 metri","duration":"8 ore","material":"un fischietto d'argento, un pezzo d'osso e un filo"}},"data":{"level":4,"school":"srd:rule:school-conjuration","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A tiny silver whistle, a piece of bone, and a thread","ritual":false,"concentration":false,"duration":"8 hours","damage":[{"type":"srd:rule:damage-piercing","atSlotLevel":{"4":"4d8"}}],"attackType":"melee"}},{"id":"srd:spell:false-life","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"False Life","description":"Bolstering yourself with a necromantic facsimile of life, you gain 1d4 + 4 temporary hit points for the duration.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you gain 5 additional temporary hit points for each slot level above 1st."},"it":{"name":"Vita falsata","description":"L'incantatore si rafforza con un duplicato necromantico di vita, ottenendo 1d4 + 4 punti ferita temporanei per la durata dell'incantesimo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, può ottenere 5 punti ferita temporanei aggiuntivi per ogni slot di livello superiore al 1°.","castingTime":"1 azione","range":"Incantatore","duration":"1 ora","material":"una piccola quantità di alcol o liquori distillati"}},"data":{"level":1,"school":"srd:rule:school-necromancy","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A small amount of alcohol or distilled spirits.","ritual":false,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:fear","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Fear","description":"You project a phantasmal image of a creature's worst fears. Each creature in a 30-foot cone must succeed on a wisdom saving throw or drop whatever it is holding and become frightened for the duration.\\n\\nWhile frightened by this spell, a creature must take the Dash action and move away from you by the safest available route on each of its turns, unless there is nowhere to move. If the creature ends its turn in a location where it doesn't have line of sight to you, the creature can make a wisdom saving throw. On a successful save, the spell ends for that creature."},"it":{"name":"Paura","description":"L'incantatore proietta la rappresentazione illusoria delle più grandi paure di una creatura. Ogni creatura entro un cono di 9 metri deve superare un tiro salvezza su Saggezza, altrimenti lascia cadere ciò che tiene in mano e diventa spaventata per la durata dell'incantesimo.\\n\\nFinché è spaventata da questo incantesimo, una creatura deve effettuare l'azione Scatto e muoversi a ogni suo turno per allontanarsi dall'incantatore lungo il percorso più sicuro possibile, sempre che abbia lo spazio per muoversi. Se la creatura termina il suo turno in un luogo dove l'incantatore non è in vista, può effettuare un tiro salvezza su Saggezza. Se lo supera, l'incantesimo termina il suo effetto su quella creatura.","castingTime":"1 azione","range":"Incantatore (cono di 9 metri)","duration":"Concentrazione, fino a 1 minuto","material":"una piuma bianca o un cuore di pollo"}},"data":{"level":3,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A white feather or the heart of a hen.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"wis","onSuccess":"none"},"area":{"type":"cone","size":30}}},{"id":"srd:spell:feather-fall","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Feather Fall","description":"Choose up to five falling creatures within range. A falling creature's rate of descent slows to 60 feet per round until the spell ends. If the creature lands before the spell ends, it takes no falling damage and can land on its feet, and the spell ends for that creature."},"it":{"name":"Caduta morbida","description":"L'incantatore sceglie fino a cinque creature in caduta entro gittata. La velocità di discesa di una creatura in caduta rallenta fino a 18 metri per round finché l'incantesimo non termina. Se la creatura atterra prima che l'incantesimo termini, non subisce alcun danno da caduta e può atterrare in piedi, interrompendo l'effetto dell'incantesimo.","castingTime":"1 reazione, che l'incantatore può effettuare quando egli stesso o una creatura entro 18 metri da lui cade","range":"18 metri","duration":"1 minuto","material":"una piccola piuma"}},"data":{"level":1,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 reaction","range":"60 feet","components":["V","M"],"material":"A small feather or a piece of down.","ritual":false,"concentration":false,"duration":"1 minute"}},{"id":"srd:spell:feeblemind","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Feeblemind","description":"You blast the mind of a creature that you can see within range, attempting to shatter its intellect and personality. The target takes 4d6 psychic damage and must make an intelligence saving throw.\\n\\nOn a failed save, the creature's Intelligence and Charisma scores become 1. The creature can't cast spells, activate magic items, understand language, or communicate in any intelligible way. The creature can, however, identify its friends, follow them, and even protect them.\\n\\nAt the end of every 30 days, the creature can repeat its saving throw against this spell. If it succeeds on its saving throw, the spell ends.\\n\\nThe spell can also be ended by greater restoration, heal, or wish."},"it":{"name":"Regressione mentale","description":"L'incantatore assale la mente di una creatura entro gittata che è in grado di vedere, nel tentativo di frantumare il suo intelletto e la sua personalità. Il bersaglio subisce 4d6 danni psichici e deve effettuare un tiro salvezza su Intelligenza.\\n\\nSe lo fallisce, i suoi punteggi di Intelligenza e Carisma si riducono a 1: la creatura non può lanciare incantesimi, attivare oggetti magici, comprendere linguaggi o comunicare in alcun modo intelligibile. Tuttavia, può identificare i propri amici, seguirli e anche proteggerli.\\n\\nAlla fine di ogni 30 giorni, la creatura può ripetere il tiro salvezza contro questo incantesimo. In caso di successo, l'incantesimo termina.\\n\\nAnche gli incantesimi desiderio, guarigione o ristorare superiore possono porre fine a questo incantesimo.","castingTime":"1 azione","range":"45 metri","duration":"Istantanea","material":"una manciata di argilla, cristallo, vetro o sfere di minerali"}},"data":{"level":8,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:druid","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"150 feet","components":["V","S","M"],"material":"A handful of clay, crystal, glass, or mineral spheres.","ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-psychic","atSlotLevel":{"8":"4d6"}}],"savingThrow":{"ability":"int","onSuccess":"other"}}},{"id":"srd:spell:find-familiar","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Find Familiar","description":"You gain the service of a familiar, a spirit that takes an animal form you choose: bat, cat, crab, frog (toad), hawk, lizard, octopus, owl, poisonous snake, fish (quipper), rat, raven, sea horse, spider, or weasel. Appearing in an unoccupied space within range, the familiar has the statistics of the chosen form, though it is a celestial, fey, or fiend (your choice) instead of a beast.\\n\\nYour familiar acts independently of you, but it always obeys your commands. In combat, it rolls its own initiative and acts on its own turn. A familiar can't attack, but it can take other actions as normal.\\n\\nWhen the familiar drops to 0 hit points, it disappears, leaving behind no physical form. It reappears after you cast this spell again.\\n\\nWhile your familiar is within 100 feet of you, you can communicate with it telepathically. Additionally, as an action, you can see through your familiar's eyes and hear what it hears until the start of your next turn, gaining the benefits of any special senses that the familiar has. During this time, you are deaf and blind with regard to your own senses.\\n\\nAs an action, you can temporarily dismiss your familiar. It disappears into a pocket dimension where it awaits your summons. Alternatively, you can dismiss it forever. As an action while it is temporarily dismissed, you can cause it to reappear in any unoccupied space within 30 feet of you.\\n\\nYou can't have more than one familiar at a time. If you cast this spell while you already have a familiar, you instead cause it to adopt a new form. Choose one of the forms from the above list. Your familiar transforms into the chosen creature.\\n\\nFinally, when you cast a spell with a range of touch, your familiar can deliver the spell as if it had cast the spell. Your familiar must be within 100 feet of you, and it must use its reaction to deliver the spell when you cast it. If the spell requires an attack roll, you use your action modifier for the roll."},"it":{"name":"Trova famiglio","description":"L'incantatore ottiene il servizio di un famiglio, uno spirito che assume la forma di un animale a sua scelta: cavalluccio marino, corvo, donnola, falco, gatto, granchio, gufo, lucertola, pesce (quipper), piovra, pipistrello, ragno, rana (rospo), serpente velenoso, topo. Il famiglio appare in uno spazio libero entro gittata, ha le statistiche della forma scelta, anche se si tratta di un celestiale, un folletto o un immondo (a scelta dell'incantatore) invece di una bestia.\\n\\nIl famiglio è indipendente dall'incantatore, ma obbedisce sempre ai suoi comandi. In combattimento, tira per la propria iniziativa e agisce nel proprio turno. Un famiglio non può attaccare, ma può effettuare altre azioni normalmente.\\n\\nQuando un famiglio scende a 0 punti ferita, scompare, non lasciando dietro di sé alcuna forma fisica e riappare quando l'incantatore lancia nuovamente questo incantesimo.\\n\\nFinché il famiglio si trova a 30 metri dall'incantatore, quest'ultimo può comunicare con lui telepaticamente. Inoltre, con un'azione, l'incantatore è in grado di vedere attraverso gli occhi del famiglio e sentire ciò che sente fino all'inizio del turno successivo, ottenendo i benefici di eventuali sensi speciali posseduti dal famiglio. Durante questo periodo, l'incantatore non vede o sente nulla con i propri sensi.\\n\\nCon un'azione, l'incantatore può temporaneamente congedare il suo famiglio, che scompare in una sacca dimensionale dove attende di essere nuovamente evocato. In alternativa, l'incantatore può farlo sparire per sempre. Con un'azione, finché il famiglio è congedato temporaneamente, l'incantatore può farlo ricomparire in un spazio libero entro 9 metri da sé.\\n\\nUn incantatore non può avere più di un famiglio alla volta. Se lancia questo incantesimo mentre è già presente un famiglio, l'incantatore gli impartisce una nuova forma. L'incantatore sceglie una delle forme dalla lista soprastante e il famiglio si trasformerà nella creatura scelta.\\n\\nInfine, quando l'incantatore lancia un incantesimo con gittata a contatto, il suo famiglio può trasmettere l'incantesimo come se fosse stato lui a lanciarlo. Il famiglio deve trovarsi entro 30 metri dall'incantatore e deve usare la sua reazione per trasmettere l'incantesimo lanciato. Se l'incantesimo richiede un tiro per colpire, l'incantatore può utilizzare il suo modificatore di attacco per quel tiro.","castingTime":"1 ora","range":"3 metri","duration":"Istantanea","material":"carbone, incenso ed erbe del valore di 10 mo da bruciare in un braciere d'ottone"}},"data":{"level":1,"school":"srd:rule:school-conjuration","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 hour","range":"10 feet","components":["V","S","M"],"material":"10gp worth of charcoal, incense, and herbs that must be consumed by fire in a brass brazier.","ritual":true,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:find-steed","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Find Steed","description":"You summon a spirit that assumes the form of an unusually intelligent, strong, and loyal steed, creating a long-lasting bond with it. Appearing in an unoccupied space within range, the steed takes on a form that you choose, such as a warhorse, a pony, a camel, an elk, or a mastiff. (Your GM might allow other animals to be summoned as steeds.) The steed has the statistics of the chosen form, though it is a celestial, fey, or fiend (your choice) instead of its normal type. Additionally, if your steed has an Intelligence of 5 or less, its Intelligence becomes 6, and it gains the ability to understand one language of your choice that you speak.\\n\\nYour steed serves you as a mount, both in combat and out, and you have an instinctive bond with it that allows you to fight as a seamless unit. While mounted on your steed, you can make any spell you cast that targets only you also target your steed.\\n\\nWhen the steed drops to 0 hit points, it disappears, leaving behind no physical form. You can also dismiss your steed at any time as an action, causing it to disappear. In either case, casting this spell again summons the same steed, restored to its hit point maximum.\\n\\nWhile your steed is within 1 mile of you, you can communicate with it telepathically.\\n\\nYou can't have more than one steed bonded by this spell at a time. As an action, you can release the steed from its bond at any time, causing it to disappear."},"it":{"name":"Trova cavalcatura","description":"L'incantatore evoca uno spirito che assume la forma di una cavalcatura insolitamente intelligente, forte e leale, stringendovi un legame duraturo. La cavalcatura appare in uno spazio libero entro gittata e assume la forma scelta dall'incantatore: cavallo da guerra, pony, cammello, alce o mastino. (Il GM potrebbe consentire ad altri animali di essere evocati come cavalcature.) La cavalcatura usa le statistiche della forma scelta, anche se si tratta di un celestiale, un folletto o un immondo (a scelta dell'incantatore) anziché di un tipo normale. Inoltre, se la cavalcatura ha un'Intelligenza pari o inferiore a 5, questa diventa 6 e ottiene l'abilità di comprendere un linguaggio a scelta dell'incantatore che quest'ultimo sia in grado di parlare.\\n\\nLa cavalcatura serve l'incantatore sia in combattimento che in altri momenti e, grazie al legame istintivo che li unisce, i due combattono come un'unica entità. Mentre è in sella alla cavalcatura, l'incantatore può fare in modo che ogni incantesimo che bersaglia solo se stesso bersagli anche la sua cavalcatura.\\n\\nQuando una cavalcatura scende a 0 punti ferita, scompare, non lasciando dietro di sé alcuna forma fisica. Inoltre, l'incantatore può in ogni momento congedare la cavalcatura con un'azione, causandone la scomparsa. In ogni caso, lanciare nuovamente questo incantesimo evocherà la medesima cavalcatura, con i suoi punti ferita massimi ripristinati.\\n\\nFinché la cavalcatura si trova a 1,5 km dall'incantatore, quest'ultimo può comunicare con lei telepaticamente.\\n\\nUn incantatore non può legarsi a più di una cavalcatura alla volta tramite questo incantesimo. Con un'azione, l'incantatore può liberare in ogni momento la cavalcatura dal legame che li unisce, causandone la scomparsa.","castingTime":"10 minuti","range":"9 metri","duration":"Istantanea"}},"data":{"level":2,"school":"srd:rule:school-conjuration","classes":["srd:class:paladin"],"subclasses":["srd:subclass:lore"],"castingTime":"10 minutes","range":"30 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:find-traps","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Find Traps","description":"You sense the presence of any trap within range that is within line of sight. A trap, for the purpose of this spell, includes anything that would inflict a sudden or unexpected effect you consider harmful or undesirable, which was specifically intended as such by its creator. Thus, the spell would sense an area affected by the alarm spell, a glyph of warding, or a mechanical pit trap, but it would not reveal a natural weakness in the floor, an unstable ceiling, or a hidden sinkhole.\\n\\nThis spell merely reveals that a trap is present. You don't learn the location of each trap, but you do learn the general nature of the danger posed by a trap you sense."},"it":{"name":"Scopri trappole","description":"L'incantatore percepisce la presenza di qualsiasi trappola piazzata entro gittata e nel suo campo visivo. Ai fini di questo incantesimo, per trappola si intende qualsiasi cosa che infligga un effetto improvviso e inaspettato considerato dannoso o indesiderabile dall'incantatore e specificatamente realizzato a tali fini dal suo creatore. Pertanto, l'incantesimo è in grado di individuare un'area influenzata dall'incantesimo allarme, da un glifo di interdizione o in cui è presente una fossa meccanica nascosta, ma non di rivelare un cedimento naturale del pavimento, un soffitto instabile o una voragine nascosta.\\n\\nQuesto incantesimo rivela semplicemente la presenza di una trappola. L'incantatore non scopre la posizione precisa, ma solo la natura generale del pericolo che pone.","castingTime":"1 azione","range":"36 metri","duration":"Istantanea"}},"data":{"level":2,"school":"srd:rule:school-divination","classes":["srd:class:cleric","srd:class:druid","srd:class:ranger"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"120 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:find-the-path","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Find the Path","description":"This spell allows you to find the shortest, most direct physical route to a specific fixed location that you are familiar with on the same plane of existence. If you name a destination on another plane of existence, a destination that moves (such as a mobile fortress), or a destination that isn't specific (such as \\"a green dragon's lair\\"), the spell fails.\\n\\nFor the duration, as long as you are on the same plane of existence as the destination, you know how far it is and in what direction it lies. While you are traveling there, whenever you are presented with a choice of paths along the way, you automatically determine which path is the shortest and most direct route (but not necessarily the safest route) to the destination."},"it":{"name":"Scopri il percorso","description":"Questo incantesimo permette all'incantatore di scoprire il percorso fisico più breve e diretto verso un determinato luogo fisso a lui noto e che si trova sullo stesso piano di esistenza. Se l'incantatore nomina una destinazione su un altro piano di esistenza, una destinazione in movimento (come una fortezza mobile) o una destinazione poco specifica (come \\"la tana di un drago verde\\"), l'incantesimo non ha effetto.\\n\\nPer tutta la durata dell'incantesimo, finché l'incantatore si trova sullo stesso piano di esistenza della destinazione, sa quanto è lontana e in che direzione si trova. Mentre viaggia per raggiungerla, quando gli si presentano più percorsi tra cui scegliere lungo il cammino, l'incantatore determina automaticamente il percorso più breve e diretto (ma non necessariamente il più sicuro) che lo porterà a destinazione.","castingTime":"1 minuto","range":"Incantatore","duration":"Concentrazione, fino a 1 giorno","material":"una serie di strumenti da divinazione, come ossa, bastoncini d'avorio, carte, denti o incisioni runiche, del valore di 100 mo e un oggetto proveniente dal luogo che si desidera trovare"}},"data":{"level":6,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:cleric","srd:class:druid"],"subclasses":[],"castingTime":"1 minute","range":"Self","components":["V","S","M"],"material":"A set of divinatory tools--such as bones, ivory sticks, cards, teeth, or carved runes--worth 100gp and an object from the location you wish to find.","ritual":false,"concentration":true,"duration":"Up to 24 hours"}},{"id":"srd:spell:finger-of-death","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Finger of Death","description":"You send negative energy coursing through a creature that you can see within range, causing it searing pain. The target must make a constitution saving throw. It takes 7d8 + 30 necrotic damage on a failed save, or half as much damage on a successful one.\\n\\nA humanoid killed by this spell rises at the start of your next turn as a zombie that is permanently under your command, following your verbal orders to the best of its ability."},"it":{"name":"Dito della morte","description":"L'incantatore trasmette un flusso di energia negativa a una creatura entro gittata che è in grado di vedere, causandole dolori lancinanti. Il bersaglio deve effettuare un tiro salvezza su Costituzione e subisce 7d8 + 30 danni necrotici in caso di fallimento, o la metà dei danni in caso di successo.\\n\\nAll'inizio del turno successivo dell'incantatore, un umanoide ucciso da questo incantesimo si rianima come uno zombi, permanentemente al suo comando: obbedirà ai suoi ordini verbali al meglio delle sue capacità.","castingTime":"1 azione","range":"18 metri","duration":"Istantanea"}},"data":{"level":7,"school":"srd:rule:school-necromancy","classes":["srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-necrotic","atSlotLevel":{"7":"7d8 + 30"}}],"savingThrow":{"ability":"con","onSuccess":"half"}}},{"id":"srd:spell:fire-bolt","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Fire Bolt","description":"You hurl a mote of fire at a creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 fire damage. A flammable object hit by this spell ignites if it isn't being worn or carried.\\n\\nThis spell's damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10)."},"it":{"name":"Dardo di fuoco","description":"L'incantatore scaglia una scintilla di fuoco verso una creatura o un oggetto situato entro gittata, effettuando un attacco a distanza con incantesimo contro il bersaglio. Se il colpo va a segno, il bersaglio subisce 1d10 danni da fuoco. Un oggetto infiammabile colpito da questo incantesimo prende fuoco se non indossato o trasportato in quel momento.\\n\\nI danni dell'incantesimo aumentano di 1d10 quando l'incantatore raggiunge il 5° livello (2d10), l'11° livello (3d10) e il 17° livello (4d10).","castingTime":"1 azione","range":"36 metri","duration":"Istantanea"}},"data":{"level":0,"school":"srd:rule:school-evocation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-fire","atCharacterLevel":{"1":"1d10","5":"2d10","11":"3d10","17":"4d10"}}],"attackType":"ranged"}},{"id":"srd:spell:fire-shield","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Fire Shield","description":"Thin and vaporous flame surround your body for the duration of the spell, radiating a bright light bright light in a 10-foot radius and dim light for an additional 10 feet. You can end the spell using an action to make it disappear.\\n\\nThe flames are around you a heat shield or cold, your choice. The heat shield gives you cold damage resistance and the cold resistance to fire damage.\\n\\nIn addition, whenever a creature within 5 feet of you hits you with a melee attack, flames spring from the shield. The attacker then suffers 2d8 points of fire damage or cold, depending on the model."},"it":{"name":"Scudo di fuoco","description":"Per la durata dell'incantesimo, il corpo dell'incantatore è avvolto da fiamme sottili, che proiettano luce intensa in un raggio di 3 metri e luce fioca per ulteriori 3 metri. L'incantatore può usare un'azione per far terminare prematuramente l'incantesimo.\\n\\nLe fiamme conferiscono all'incantatore uno scudo ardente o gelido a sua scelta. Lo scudo ardente gli conferisce resistenza ai danni da freddo, mentre lo scudo gelido resistenza ai danni da fuoco.\\n\\nInoltre, ogni volta che una creatura entro 1,5 metri dall'incantatore lo colpisce con un attacco in mischia, dallo scudo erompono delle fiamme: l'attaccante subisce 2d8 danni da fuoco da uno scudo ardente o 2d8 danni da freddo da uno scudo gelido.","castingTime":"1 azione","range":"Incantatore","duration":"10 minuti","material":"un frammento di fosforo o una lucciola"}},"data":{"level":4,"school":"srd:rule:school-evocation","classes":["srd:class:wizard"],"subclasses":["srd:subclass:fiend"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A little phosphorus or a firefly.","ritual":false,"concentration":false,"duration":"10 minutes","damage":[{"type":"srd:rule:damage-fire","atSlotLevel":{"4":"2d8"}}],"area":{"type":"sphere","size":5}}},{"id":"srd:spell:fire-storm","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Fire Storm","description":"A storm made up of sheets of roaring flame appears in a location you choose within range. The area of the storm consists of up to ten 10-foot cubes, which you can arrange as you wish. Each cube must have at least one face adjacent to the face of another cube. Each creature in the area must make a dexterity saving throw. It takes 7d10 fire damage on a failed save, or half as much damage on a successful one.\\n\\nThe fire damages objects in the area and ignites flammable objects that aren't being worn or carried. If you choose, plant life in the area is unaffected by this spell."},"it":{"name":"Tempesta di fuoco","description":"Una tempesta di ardenti lingue di fuoco appare in un punto entro gittata a scelta dell'incantatore. L'area della tempesta è composta da dieci cubi di 3 metri, che l'incantatore può disporre come desidera. Ognuno di loro deve avere almeno un lato adiacente a quello di un altro cubo. Ogni creatura presente nell'area deve effettuare un tiro salvezza su Destrezza. In caso di fallimento, subisce 7d10 danni da fuoco, o la metà dei danni in caso di successo.\\n\\nIl fuoco danneggia ogni oggetto presente nell'area e incendia gli oggetti infiammabili non indossati o trasportati. L'incantatore può decidere di non influenzare con questo incantesimo le forme di vita vegetali nell'area.","castingTime":"1 azione","range":"45 metri","duration":"Istantanea"}},"data":{"level":7,"school":"srd:rule:school-evocation","classes":["srd:class:cleric","srd:class:druid","srd:class:sorcerer"],"subclasses":[],"castingTime":"1 action","range":"150 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-fire","atSlotLevel":{"7":"7d10"}}],"savingThrow":{"ability":"dex","onSuccess":"half"},"area":{"type":"cube","size":100}}},{"id":"srd:spell:fireball","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Fireball","description":"A bright streak flashes from your pointing finger to a point you choose within range and then blossoms with a low roar into an explosion of flame. Each creature in a 20-foot-radius sphere centered on that point must make a dexterity saving throw. A target takes 8d6 fire damage on a failed save, or half as much damage on a successful one.\\n\\nThe fire spreads around corners. It ignites flammable objects in the area that aren't being worn or carried.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd."},"it":{"name":"Palla di fuoco","description":"Una scia di luce brillante parte dall'indice dell'incantatore e sfreccia fino a un punto a sua scelta entro gittata, provocando un'esplosione di fiamme con un profondo boato. Ogni creatura situata entro una sfera del raggio di 6 metri centrata su quel punto deve effettuare un tiro salvezza su Destrezza. In caso di fallimento, subisce 8d6 danni da fuoco, o la metà dei danni in caso di successo.\\n\\nIl fuoco si diffonde oltre gli angoli e incendia ogni oggetto infiammabile nell'area che non sia indossato o trasportato.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d6 per ogni slot di livello superiore al 3°.","castingTime":"1 azione","range":"45 metri","duration":"Istantanea","material":"una pallina di guano di pipistrello e zolfo"}},"data":{"level":3,"school":"srd:rule:school-evocation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:fiend"],"castingTime":"1 action","range":"150 feet","components":["V","S","M"],"material":"A tiny ball of bat guano and sulfur.","ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-fire","atSlotLevel":{"3":"8d6","4":"9d6","5":"10d6","6":"11d6","7":"12d6","8":"13d6","9":"14d6"}}],"savingThrow":{"ability":"dex","onSuccess":"half"},"area":{"type":"sphere","size":20}}},{"id":"srd:spell:flame-blade","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Flame Blade","description":"You evoke a fiery blade in your free hand. The blade is similar in size and shape to a scimitar, and it lasts for the duration. If you let go of the blade, it disappears, but you can evoke the blade again as a bonus action.\\n\\nYou can use your action to make a melee spell attack with the fiery blade. On a hit, the target takes 3d6 fire damage.\\n\\nThe flaming blade sheds bright light in a 10-foot radius and dim light for an additional 10 feet.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for every two slot levels above 2nd."},"it":{"name":"Lama infuocata","description":"L'incantatore evoca una lama infuocata nella sua mano libera. La lama ha forma e dimensioni simili a una scimitarra e permane per tutta la durata dell'incantesimo. Se l'incantatore la lascia cadere, la lama scompare, ma può essere evocata di nuovo come azione bonus.\\n\\nCon questo incantesimo, l'incantatore può usare la sua azione per effettuare un attacco in mischia con la lama infuocata. Se il colpo va a segno, il bersaglio subisce 3d6 danni da fuoco.\\n\\nLa lama infuocata emana luce intensa in un raggio di 3 metri e luce fioca per ulteriori 3 metri.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d6 per ogni due slot di livello superiore al 2°.","castingTime":"1 azione bonus","range":"Incantatore","duration":"Concentrazione, fino a 10 minuti","material":"foglia di sommacco"}},"data":{"level":2,"school":"srd:rule:school-evocation","classes":["srd:class:druid"],"subclasses":["srd:subclass:lore"],"castingTime":"1 bonus action","range":"Self","components":["V","S","M"],"material":"Leaf of sumac.","ritual":false,"concentration":true,"duration":"Up to 10 minutes","damage":[{"type":"srd:rule:damage-fire","atSlotLevel":{"2":"3d6","4":"4d6","6":"5d6","8":"6d6"}}]}},{"id":"srd:spell:flame-strike","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Flame Strike","description":"A vertical column of divine fire roars down from the heavens in a location you specify. Each creature in a 10-foot-radius, 40-foot-high cylinder centered on a point within range must make a dexterity saving throw. A creature takes 4d6 fire damage and 4d6 radiant damage on a failed save, or half as much damage on a successful one.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 6th level or higher, the fire damage or the radiant damage (your choice) increases by 1d6 for each slot level above 5th."},"it":{"name":"Colpo infuocato","description":"Una colonna verticale di fuoco divino si abbatte dai cieli in un luogo indicato dall'incantatore. Ogni creatura all'interno di un cilindro del raggio di 3 metri e dell'altezza di 12 metri centrato in un punto entro gittata deve effettuare un tiro salvezza su Destrezza. In caso di fallimento, la creatura subisce 4d6 danni da fuoco e 4d6 danni radiosi, o la metà dei danni in caso di successo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, i danni da fuoco o i danni radiosi (a sua scelta) aumentano di 1d6 per ogni slot di livello superiore al 5°.","castingTime":"1 azione","range":"18 metri","duration":"Istantanea","material":"un pizzico di zolfo"}},"data":{"level":5,"school":"srd:rule:school-evocation","classes":["srd:class:cleric"],"subclasses":["srd:subclass:devotion","srd:subclass:fiend"],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"Pinch of sulfur.","ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-fire","atSlotLevel":{"5":"4d6","6":"4d6 OR 5d6","7":"4d6 OR 6d6","8":"4d6 OR 7d6","9":"4d6 OR 8d6"}},{"type":"srd:rule:damage-radiant","atSlotLevel":{"5":"4d6","6":"4d6 OR 5d6","7":"4d6 OR 6d6","8":"4d6 OR 7d6","9":"4d6 OR 8d6"}}],"savingThrow":{"ability":"dex","onSuccess":"half"},"area":{"type":"cylinder","size":40}}},{"id":"srd:spell:flaming-sphere","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Flaming Sphere","description":"A 5-foot-diameter sphere of fire appears in an unoccupied space of your choice within range and lasts for the duration. Any creature that ends its turn within 5 feet of the sphere must make a dexterity saving throw. The creature takes 2d6 fire damage on a failed save, or half as much damage on a successful one.\\n\\nAs a bonus action, you can move the sphere up to 30 feet. If you ram the sphere into a creature, that creature must make the saving throw against the sphere's damage, and the sphere stops moving this turn.\\n\\nWhen you move the sphere, you can direct it over barriers up to 5 feet tall and jump it across pits up to 10 feet wide. The sphere ignites flammable objects not being worn or carried, and it sheds bright light in a 20-foot radius and dim light for an additional 20 feet.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd."},"it":{"name":"Sfera infuocata","description":"Una sfera di fuoco del diametro di 1,5 metri compare in uno spazio libero entro gittata a scelta dell'incantatore, dove permane per la durata dell'incantesimo. Ogni creatura che termina il suo turno entro 1,5 metri dalla sfera deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 2d6 danni da fuoco, mentre se lo supera subisce soltanto la metà di quei danni.\\n\\nCome azione bonus, l'incantatore può muovere la sfera per un massimo di 9 metri. Se una creatura entra in contatto con la sfera, quella creatura deve effettuare il tiro salvezza contro i danni inflitti e la sfera, per quel turno, non può muoversi ulteriormente.\\n\\nQuando l'incantatore muove la sfera, può dirigerla oltre le barriere alte fino a 1,5 metri e farla saltare oltre le fosse larghe fino a 3 metri. La sfera incendia gli oggetti infiammabili che non sono indossati o trasportati, proiettando luce intensa entro un raggio di 6 metri e luce fioca per altri 6 metri.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, i danni aumentano di 1d6 per ogni slot di livello superiore al 2°.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 minuto","material":"un frammento di sego, un pizzico di zolfo e una manciata di polvere di ferro"}},"data":{"level":2,"school":"srd:rule:school-conjuration","classes":["srd:class:druid","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"A bit of tallow, a pinch of brimstone, and a dusting of powdered iron.","ritual":false,"concentration":true,"duration":"Up to 1 minute","damage":[{"type":"srd:rule:damage-fire","atSlotLevel":{"2":"2d6","3":"3d6","4":"4d6","5":"5d6","6":"6d6","7":"7d6","8":"8d6","9":"9d6"}}]}},{"id":"srd:spell:flesh-to-stone","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Flesh to Stone","description":"You attempt to turn one creature that you can see within range into stone. If the target's body is made of flesh, the creature must make a constitution saving throw. On a failed save, it is restrained as its flesh begins to harden. On a successful save, the creature isn't affected.\\n\\nA creature restrained by this spell must make another constitution saving throw at the end of each of its turns. If it successfully saves against this spell three times, the spell ends. If it fails its saves three times, it is turned to stone and subjected to the petrified condition for the duration. The successes and failures don't need to be consecutive; keep track of both until the target collects three of a kind.\\n\\nIf the creature is physically broken while petrified, it suffers from similar deformities if it reverts to its original state.\\n\\nIf you maintain your concentration on this spell for the entire possible duration, the creature is turned to stone until the effect is removed."},"it":{"name":"Carne in pietra","description":"L'incantatore tenta di tramutare in pietra una creatura entro gittata che è in grado di vedere. La creatura deve effettuare un tiro salvezza su Costituzione se il suo corpo è di carne. Se lo fallisce, il bersaglio è trattenuto e la sua carne inizia a indurirsi, mentre se lo supera, la creatura non subisce alcun effetto.\\n\\nUna creatura trattenuta da questo incantesimo deve effettuare un altro tiro salvezza su Costituzione al termine di ogni suo turno. L'incantesimo termina se il bersaglio supera per tre volte il tiro salvezza contro questo incantesimo, mentre se lo fallisce per tre volte, viene tramutato in pietra ed è soggetto alla condizione pietrificato per la durata dell'incantesimo. Non è necessario che i tiri superati o falliti siano consecutivi: si tiene semplicemente il conto di entrambi finché il bersaglio non ne accumula tre di un certo tipo.\\n\\nSe la creatura subisce una rottura fisica mentre è pietrificata, soffrirà di una deformità analoga una volta tornata al suo stato originale.\\n\\nSe l'incantatore mantiene la concentrazione su questo incantesimo per l'intera durata possibile, la creatura viene tramutata in pietra finché l'effetto non viene rimosso.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 minuto","material":"un pizzico di calce, acqua e terra"}},"data":{"level":6,"school":"srd:rule:school-transmutation","classes":["srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"A pinch of lime, water, and earth.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"con","onSuccess":"none"}}},{"id":"srd:spell:floating-disk","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Floating Disk","description":"This spell creates a circular, horizontal plane of force, 3 feet in diameter and 1 inch thick, that floats 3 feet above the ground in an unoccupied space of your choice that you can see within range. The disk remains for the duration, and can hold up to 500 pounds. If more weight is placed on it, the spell ends, and everything on the disk falls to the ground.\\n\\nThe disk is immobile while you are within 20 feet of it. If you move more than 20 feet away from it, the disk follows you so that it remains within 20 feet of you. If can move across uneven terrain, up or down stairs, slopes and the like, but it can't cross an elevation change of 10 feet or more. For example, the disk can't move across a 10-foot-deep pit, nor could it leave such a pit if it was created at the bottom.\\n\\nIf you move more than 100 feet away from the disk (typically because it can't move around an obstacle to follow you), the spell ends."},"it":{"name":"Disco fluttuante","description":"Questo incantesimo crea un piano circolare e orizzontale di forza del diametro di 90 cm e spessore di 2,5 cm, che fluttua 90 cm sopra il terreno in uno spazio libero a scelta dell'incantatore entro gittata e che è in grado di vedere. Questo disco permane per la durata dell'incantesimo e può sostenere fino a 250 kg. Se si aggiunge ulteriore peso, l'incantesimo termina e tutto ciò che si trovava sul disco precipita a terra.\\n\\nIl disco rimane immobile se l'incantatore si trova entro 6 metri da esso. Se l'incantatore si allontana a più di 6 metri, il disco lo segue per rimanere entro 6 metri da lui. Può muoversi sul terreno dissestato, lungo scalinate, pendii e terreni simili, ma non può superare un dislivello pari o superiore a 3 metri. Per esempio, il disco non può attraversare una fossa profonda 3 metri o uscirne se si trovasse sul fondo.\\n\\nL'incantesimo termina se l'incantatore si allontana di più di 30 metri dal disco (normalmente accade perché il disco non può superare un ostacolo per seguirlo).","castingTime":"1 azione","range":"9 metri","duration":"1 ora","material":"una goccia di mercurio"}},"data":{"level":1,"school":"srd:rule:school-conjuration","classes":["srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A drop of mercury.","ritual":true,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:fly","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Fly","description":"You touch a willing creature. The target gains a flying speed of 60 feet for the duration. When the spell ends, the target falls if it is still aloft, unless it can stop the fall.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd."},"it":{"name":"Volare","description":"L'incantatore tocca una creatura consenziente. Il bersaglio ottiene una velocità di volo di 18 metri per round per la durata dell'incantesimo. Quando l'incantesimo termina, il bersaglio ancora sospeso in aria cade, sempre che non abbia modo di impedire la caduta.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, può bersagliare una creatura aggiuntiva per ogni slot superiore al 3°.","castingTime":"1 azione","range":"Contatto","duration":"Concentrazione, fino a 10 minuti","material":"la piuma dell'ala di un qualsiasi uccello"}},"data":{"level":3,"school":"srd:rule:school-transmutation","classes":["srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A wing feather from any bird.","ritual":false,"concentration":true,"duration":"Up to 10 minutes"}},{"id":"srd:spell:fog-cloud","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Fog Cloud","description":"You create a 20-foot-radius sphere of fog centered on a point within range. The sphere spreads around corners, and its area is heavily obscured. It lasts for the duration or until a wind of moderate or greater speed (at least 10 miles per hour) disperses it.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the radius of the fog increases by 20 feet for each slot level above 1st."},"it":{"name":"Nube di nebbia","description":"L'incantatore genera una sfera di nebbia del raggio di 6 metri centrata su un punto entro gittata. La sfera si estende intorno agli angoli e la sua area è pesantemente oscurata. Permane per la durata dell'incantesimo o finché un vento di velocità moderata o superiore (almeno 15 km orari) non la disperde.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, il raggio della sfera di nebbia aumenta di 6 metri per ogni slot di livello superiore al 1°.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 1 ora"}},"data":{"level":1,"school":"srd:rule:school-conjuration","classes":["srd:class:druid","srd:class:ranger","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"120 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 hour","area":{"type":"sphere","size":20}}},{"id":"srd:spell:forbiddance","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Forbiddance","description":"You create a ward against magical travel that protects up to 40,000 square feet of floor space to a height of 30 feet above the floor. For the duration, creatures can't teleport into the area or use portals, such as those created by the gate spell, to enter the area. The spell proofs the area against planar travel, and therefore prevents creatures from accessing the area by way of the Astral Plane, Ethereal Plane, Feywild, Shadowfell, or the plane shift spell.\\n\\nIn addition, the spell damages types of creatures that you choose when you cast it. Choose one or more of the following: celestials, elementals, fey, fiends, and undead. When a chosen creature enters the spell's area for the first time on a turn or starts its turn there, the creature takes 5d10 radiant or necrotic damage (your choice when you cast this spell).\\n\\nWhen you cast this spell, you can designate a password. A creature that speaks the password as it enters the area takes no damage from the spell.\\n\\nThe spell's area can't overlap with the area of another forbiddance spell. If you cast forbiddance every day for 30 days in the same location, the spell lasts until it is dispelled, and the material components are consumed on the last casting."},"it":{"name":"Proibizione","description":"L'incantatore crea una difesa contro i viaggi magici che protegge un'area quadrata di terreno di 60 metri e un'altezza di massimo 9 metri. Per la durata dell'incantesimo, per entrare in tale area le creature non possono utilizzare teletrasporto o portali, come quelli creati dall'incantesimo portale. L'incantesimo protegge l'area contro i viaggi planari, impedendo perciò alle creature di accedervi tramite il Piano Astrale, il Piano Etereo, la Selva Fatata, la Coltre Oscura e l'incantesimo spostamento planare.\\n\\nInoltre, infligge danni a uno o più tipi di creature indicati dall'incantatore al momento del lancio scelti tra i seguenti: celestiali, elementali, folletti, immondi e non morti. Quando una creatura scelta entra nell'area dell'incantesimo per la prima volta in un turno o inizia il suo turno qui, subisce 5d10 danni necrotici o radiosi (a scelta dell'incantatore al momento del lancio).\\n\\nQuando lancia questo incantesimo, l'incantatore può indicare una parola d'ordine: una creatura che la pronuncia accedendo all'area non subisce danni.\\n\\nL'area di questo incantesimo non può sovrapporsi all'area di un altro incantesimo proibizione. Se l'incantatore lancia proibizione ogni giorno nello stesso luogo per 30 giorni, l'incantesimo permane finché non viene dissolto e i componenti materiali vengono consumati al momento dell'ultimo lancio.","castingTime":"10 minuti","range":"Contatto","duration":"1 giorno","material":"uno spruzzo di acqua santa, incenso raro e polvere di rubino del valore di almeno 1.000 mo"}},"data":{"level":6,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric"],"subclasses":[],"castingTime":"10 minutes","range":"Touch","components":["V","S","M"],"material":"A sprinkling of holy water, rare incense, and powdered ruby worth at least 1,000 gp.","ritual":true,"concentration":false,"duration":"24 hours","area":{"type":"cube","size":40000}}},{"id":"srd:spell:forcecage","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Forcecage","description":"An immobile, invisible, cube-shaped prison composed of magical force springs into existence around an area you choose within range. The prison can be a cage or a solid box, as you choose.\\n\\nA prison in the shape of a cage can be up to 20 feet on a side and is made from 1/2-inch diameter bars spaced 1/2 inch apart.\\n\\nA prison in the shape of a box can be up to 10 feet on a side, creating a solid barrier that prevents any matter from passing through it and blocking any spells cast into or out from the area.\\n\\nWhen you cast the spell, any creature that is completely inside the cage's area is trapped. Creatures only partially within the area, or those too large to fit inside the area, are pushed away from the center of the area until they are completely outside the area.\\n\\nA creature inside the cage can't leave it by nonmagical means. If the creature tries to use teleportation or interplanar travel to leave the cage, it must first make a charisma saving throw. On a success, the creature can use that magic to exit the cage. On a failure, the creature can't exit the cage and wastes the use of the spell or effect. The cage also extends into the Ethereal Plane, blocking ethereal travel.\\n\\nThis spell can't be dispelled by dispel magic."},"it":{"name":"Gabbia di forza","description":"Una prigione cubica di forza magica invisibile e immobile si materializza intorno a un'area entro gittata scelta dall'incantatore. La prigione può essere una gabbia o una struttura solida a sua scelta.\\n\\nUna prigione a forma di gabbia può misurare fino a 6 metri per lato ed essere composta da sbarre di 1,25 cm di diametro disposte a 1,25 cm di distanza.\\n\\nUna prigione a forma di gabbia può misurare fino a 3 metri per lato e crea una barriera compatta che impedisce a ogni tipo di materia di passarle attraverso e blocca qualsiasi incantesimo lanciato verso l'interno o l'esterno dell'area.\\n\\nAl momento del lancio dell'incantesimo, ogni creatura completamente all'interno dell'area della gabbia è intrappolata. Le creature situate solo parzialmente all'interno dell'area o quelle di dimensioni troppo grandi per essere contenute nell'area sono spinte lontano dal centro dell'area finché non ne fuoriescono completamente.\\n\\nUna creatura all'interno della gabbia non può uscirne tramite mezzi non magici. Se la creatura prova a utilizzare il teletrasporto o il viaggio interplanare, deve prima effettuare un tiro salvezza su Carisma. Se lo supera, la creatura può usare quella magia per uscire dalla gabbia, mentre se lo fallisce, non può uscirne e spreca un uso dell'incantesimo o dell'effetto. La gabbia si estende anche sul Piano Etereo, bloccando i viaggi eterei.\\n\\nQuesto incantesimo non può essere dissolto con dissolvi magie.","castingTime":"1 azione","range":"30 metri","duration":"1 ora","material":"polvere di rubino del valore di 1.500 mo"}},"data":{"level":7,"school":"srd:rule:school-evocation","classes":["srd:class:bard","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"100 feet","components":["V","S","M"],"material":"Ruby dust worth 1,500 gp.","ritual":false,"concentration":false,"duration":"1 hour","area":{"type":"cube","size":20}}},{"id":"srd:spell:foresight","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Foresight","description":"You touch a willing creature and bestow a limited ability to see into the immediate future. For the duration, the target can't be surprised and has advantage on attack rolls, ability checks, and saving throws. Additionally, other creatures have disadvantage on attack rolls against the target for the duration.\\n\\nThis spell immediately ends if you cast it again before its duration ends."},"it":{"name":"Previsione","description":"L'incantatore tocca una creatura consenziente e le conferisce una capacità limitata di vedere nell'immediato futuro. Per la durata dell'incantesimo, il bersaglio non può essere sorpreso e dispone di vantaggio ai tiri per colpire, prove di caratteristica e tiri salvezza. Inoltre, le altre creature subiscono svantaggio ai tiri per colpire indirizzati contro il bersaglio.\\n\\nQuesto incantesimo termina immediatamente se l'incantatore lo lancia nuovamente prima che la sua durata termini.","castingTime":"1 minuto","range":"Contatto","duration":"8 ore","material":"una piuma di colibrì"}},"data":{"level":9,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:druid","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 minute","range":"Touch","components":["V","S","M"],"material":"A hummingbird feather.","ritual":false,"concentration":false,"duration":"8 hours"}},{"id":"srd:spell:freedom-of-movement","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Freedom of Movement","description":"You touch a willing creature. For the duration, the target's movement is unaffected by difficult terrain, and spells and other magical effects can neither reduce the target's speed nor cause the target to be paralyzed or restrained.\\n\\nThe target can also spend 5 feet of movement to automatically escape from nonmagical restraints, such as manacles or a creature that has it grappled. Finally, being underwater imposes no penalties on the target's movement or attacks."},"it":{"name":"Libertà di movimento","description":"L'incantatore tocca una creatura consenziente. Per la durata dell'incantesimo, il movimento del bersaglio non è influenzato dal terreno difficile, inoltre incantesimi e altri effetti magici non possono né ridurne la velocità né trattenerlo o provocarne la paralisi.\\n\\nIl bersaglio può inoltre spendere 1,5 metri di movimento per sfuggire automaticamente alle restrizioni non magiche, come manette o la presa di una creatura. Infine, se si trova sott'acqua, il movimento e gli attacchi del bersaglio non subiscono penalità.","castingTime":"1 azione","range":"Contatto","duration":"1 ora","material":"una cinghia di cuoio legata intorno al braccio o un'appendice simile"}},"data":{"level":4,"school":"srd:rule:school-abjuration","classes":["srd:class:bard","srd:class:cleric","srd:class:druid","srd:class:ranger"],"subclasses":["srd:subclass:land","srd:subclass:devotion"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A leather strap, bound around the arm or a similar appendage.","ritual":false,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:freezing-sphere","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Freezing Sphere","description":"A frigid globe of cold energy streaks from your fingertips to a point of your choice within range, where it explodes in a 60-foot-radius sphere. Each creature within the area must make a constitution saving throw. On a failed save, a creature takes 10d6 cold damage. On a successful save, it takes half as much damage.\\n\\nIf the globe strikes a body of water or a liquid that is principally water (not including water-based creatures), it freezes the liquid to a depth of 6 inches over an area 30 feet square. This ice lasts for 1 minute. Creatures that were swimming on the surface of frozen water are trapped in the ice. A trapped creature can use an action to make a Strength check against your spell save DC to break free.\\n\\nYou can refrain from firing the globe after completing the spell, if you wish. A small globe about the size of a sling stone, cool to the touch, appears in your hand. At any time, you or a creature you give the globe to can throw the globe (to a range of 40 feet) or hurl it with a sling (to the sling's normal range). It shatters on impact, with the same effect as the normal casting of the spell. You can also set the globe down without shattering it. After 1 minute, if the globe hasn't already shattered, it explodes.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 7th level or higher, the damage increases by 1d6 for each slot level above 6th."},"it":{"name":"Sfera congelante","description":"Una sfera congelata di energia fredda sfreccia dal dito dell'incantatore verso un punto a sua scelta entro gittata, dove esplode in una sfera di 18 metri di raggio. Ogni creatura nell'area deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 10d6 danni da freddo, mentre se lo supera, subisce solo la metà dei danni.\\n\\nSe la sfera colpisce uno specchio d'acqua o un liquido composto principalmente da acqua (escluse le creature di questo tipo), ghiaccia il liquido fino a una profondità di 15 cm in un'area quadrata di 9 metri. Il ghiaccio dura 1 minuto. Le creature che stavano nuotando sulla superficie dell'acqua ghiacciata rimangono intrappolate nel ghiaccio e possono usare un'azione per effettuare una prova di Forza contro la CD del tiro salvezza sull'incantesimo.\\n\\nUna volta completato l'incantesimo, l'incantatore può decidere di non scagliare la sfera. Una piccola sfera della grandezza di una pietra da fionda, fredda al tocco, appare tra le mani dell'incantatore. In qualsiasi momento, l'incantatore o una creatura a cui l'ha consegnata può lanciare la sfera (entro una gittata di 12 metri) o scagliarla con una fionda (entro la normale gittata della fionda). La sfera si infrange all'impatto, con lo stesso effetto del lancio normale dell'incantesimo. Tuttavia, l'incantatore può anche appoggiare la sfera a terra senza romperla. Dopo 1 minuto, se non è ancora stata infranta, la sfera esplode.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° livello o superiore, i danni aumentano di 1d6 per ogni slot di livello superiore al 6°.","castingTime":"1 azione","range":"90 metri","duration":"Istantanea","material":"un piccola sfera di cristallo"}},"data":{"level":6,"school":"srd:rule:school-evocation","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"300 feet","components":["V","S","M"],"material":"A small crystal sphere.","ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-cold","atSlotLevel":{"6":"10d6"}}],"savingThrow":{"ability":"con","onSuccess":"half"},"area":{"type":"sphere","size":60}}},{"id":"srd:spell:gaseous-form","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Gaseous Form","description":"You transform a willing creature you touch, along with everything it's wearing and carrying, into a misty cloud for the duration. The spell ends if the creature drops to 0 hit points. An incorporeal creature isn't affected.\\n\\nWhile in this form, the target's only method of movement is a flying speed of 10 feet. The target can enter and occupy the space of another creature. The target has resistance to nonmagical damage, and it has advantage on Strength, Dexterity, and constitution saving throws. The target can pass through small holes, narrow openings, and even mere cracks, though it treats liquids as though they were solid surfaces. The target can't fall and remains hovering in the air even when stunned or otherwise incapacitated.\\n\\nWhile in the form of a misty cloud, the target can't talk or manipulate objects, and any objects it was carrying or holding can't be dropped, used, or otherwise interacted with. The target can't attack or cast spells."},"it":{"name":"Forma gassosa","description":"L'incantatore trasforma una creatura consenziente da lui toccata, nonché tutto ciò che indossa o trasporta, in una nube fosca per la durata dell'incantesimo, che termina quando i punti ferita della creatura scendono a 0. Una creatura incorporea non subisce gli effetti dell'incantesimo.\\n\\nMentre si trova in questa forma, una velocità di volare di 3 metri è l'unico metodo di movimento del bersaglio, che può entrare o occupare lo spazio di un'altra creatura. Inoltre, il bersaglio ha resistenza ai danni non magici e dispone di vantaggio ai tiri salvezza su Forza, Destrezza e Costituzione. Può passare attraverso piccoli fori, aperture strette e perfino semplici crepe, benché tratti i liquidi come fossero superfici solide. Il bersaglio non può cadere e continua a fluttuare nell'aria anche quando è stordito o incapacitato in altri modi.\\n\\nMentre è sotto forma di nube, il bersaglio non può parlare o manipolare oggetti e quelli che trasporta o impugna non possono essere lasciati cadere, usati o manipolati in alcun modo. Il bersaglio non può attaccare o lanciare incantesimi.","castingTime":"1 azione","range":"Contatto","duration":"Concentrazione, fino a 1 ora","material":"un frammento di garza e un filo di fumo"}},"data":{"level":3,"school":"srd:rule:school-transmutation","classes":["srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A bit of gauze and a wisp of smoke.","ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:gate","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Gate","description":"You conjure a portal linking an unoccupied space you can see within range to a precise location on a different plane of existence. The portal is a circular opening, which you can make 5 to 20 feet in diameter. You can orient the portal in any direction you choose. The portal lasts for the duration.\\n\\nThe portal has a front and a back on each plane where it appears. Travel through the portal is possible only by moving through its front. Anything that does so is instantly transported to the other plane, appearing in the unoccupied space nearest to the portal.\\n\\nDeities and other planar rulers can prevent portals created by this spell from opening in their presence or anywhere within their domains.\\n\\nWhen you cast this spell, you can speak the name of a specific creature (a pseudonym, title, or nickname doesn't work). If that creature is on a plane other than the one you are on, the portal opens in the named creature's immediate vicinity and draws the creature through it to the nearest unoccupied space on your side of the portal. You gain no special power over the creature, and it is free to act as the GM deems appropriate. It might leave, attack you, or help you."},"it":{"name":"Portale","description":"L'incantatore evoca un portale che collega uno spazio libero che è in grado di vedere a un luogo preciso su un piano di esistenza differente. Il portale è un'apertura circolare, del diametro variabile tra 1,5 e 6 metri a scelta dell'incantatore e può essere orientato in qualsiasi direzione, permanendo per tutta la durata dell'incantesimo.\\n\\nIl portale ha un lato anteriore e un lato posteriore su ogni piano dove appare e i viaggi sono possibili solo attraversandolo dalla parte anteriore. Tutto ciò che lo attraversa è trasportato immediatamente sull'altro piano, apparendo nello spazio libero più vicino al portale.\\n\\nDivinità e altri signori planari possono impedire che i portali creati tramite questo incantesimo si aprano in loro presenza o nei loro domini.\\n\\nQuando lancia questo incantesimo, l'incantatore può pronunciare il nome di una creatura specifica (pseudonimi, titoli o soprannomi non funzionano). Se la creatura nominata si trova su un piano diverso da quello in cui si trova l'incantatore, il portale si apre nelle sue immediate vicinanze attirandola attraverso di esso, fino alla spazio libero più vicino sul lato del portale in cui si trova l'incantatore. L'incantatore non ottiene alcun potere speciale sulla creatura, che è libera di agire come il GM ritiene più appropriato: potrebbe andarsene, attaccarlo o aiutarlo.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 minuto","material":"un diamante del valore di almeno 5.000 mo"}},"data":{"level":9,"school":"srd:rule:school-conjuration","classes":["srd:class:cleric","srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"A diamond worth at least 5,000gp.","ritual":false,"concentration":true,"duration":"Up to 1 minute"}},{"id":"srd:spell:geas","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Geas","description":"You place a magical command on a creature that you can see within range, forcing it to carry out some service or refrain from some action or course of activity as you decide. If the creature can understand you, it must succeed on a wisdom saving throw or become charmed by you for the duration. While the creature is charmed by you, it takes 5d10 psychic damage each time it acts in a manner directly counter to your instructions, but no more than once each day. A creature that can't understand you is unaffected by the spell.\\n\\nYou can issue any command you choose, short of an activity that would result in certain death. Should you issue a suicidal command, the spell ends.\\n\\nYou can end the spell early by using an action to dismiss it. A remove curse, greater restoration, or wish spell also ends it.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 7th or 8th level, the duration is 1 year. When you cast this spell using a spell slot of 9th level, the spell lasts until it is ended by one of the spells mentioned above."},"it":{"name":"Costrizione","description":"L'incantatore impartisce un comando magico a una creatura entro gittata che è in grado di vedere, costringendola a svolgere per lui un servizio di qualche tipo o ad astenersi dal compiere un'azione o un'attività. Se la creatura è in grado di comprendere l'incantatore, deve superare un tiro salvezza su Saggezza, altrimenti rimane affascinata per la durata dell'incantesimo. Mentre la creatura è affascinata dall'incantatore, subisce 5d10 danni psichici ogni volta che agisce in maniera direttamente contraria alle sue istruzioni, ma non più di una volta al giorno. L'incantesimo non ha effetto su una creatura che non è in grado di comprendere l'incantatore.\\n\\nL'incantatore può impartire al bersaglio un comando a sua scelta, a eccezione di un'attività che ne provocherebbe la morte certa: se impartisce un comando suicida, l'incantesimo termina.\\n\\nL'incantatore può usare un'azione per far cessare prematuramente l'incantesimo, che termina inoltre con un incantesimo rimuovi maledizione, ristorare superiore o desiderio.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° o 8° livello, la durata è pari a 1 anno. Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 9° livello, l'incantesimo permane finché uno degli incantesimi menzionati sopra non vi pone fine.","castingTime":"1 minuto","range":"18 metri","duration":"30 giorni"}},"data":{"level":5,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:cleric","srd:class:druid","srd:class:paladin","srd:class:wizard"],"subclasses":[],"castingTime":"1 minute","range":"60 feet","components":["V"],"ritual":false,"concentration":false,"duration":"30 days","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:gentle-repose","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Gentle Repose","description":"You touch a corpse or other remains. For the duration, the target is protected from decay and can't become undead.\\n\\nThe spell also effectively extends the time limit on raising the target from the dead, since days spent under the influence of this spell don't count against the time limit of spells such as raise dead."},"it":{"name":"Riposo inviolato","description":"L'incantatore tocca un cadavere o altri resti: per la durata dell'incantesimo, il bersaglio è protetto dalla decomposizione e non può diventare un non morto.\\n\\nInoltre, l'incantesimo estende il limite di tempo entro cui rianimare il bersaglio dalla morte, in quanto i giorni trascorsi sotto l'influenza di questo incantesimo non contano al fine di determinare il limite di tempo di incantesimi come rianimare morti.","castingTime":"1 azione","range":"Contatto","duration":"10 giorni","material":"un pizzico di sale e due monete di rame da posizionare sugli occhi del cadavere, che deve rimanere in quella posizione per la durata dell'incantesimo"}},"data":{"level":2,"school":"srd:rule:school-necromancy","classes":["srd:class:cleric","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A pinch of salt and one copper piece placed on each of the corpse's eyes, which must remain there for the duration.","ritual":true,"concentration":false,"duration":"10 days"}},{"id":"srd:spell:giant-insect","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Giant Insect","description":"You transform up to ten centipedes, three spiders, five wasps, or one scorpion within range into giant versions of their natural forms for the duration. A centipede becomes a giant centipede, a spider becomes a giant spider, a wasp becomes a giant wasp, and a scorpion becomes a giant scorpion.\\n\\nEach creature obeys your verbal commands, and in combat, they act on your turn each round. The GM has the statistics for these creatures and resolves their actions and movement.\\n\\nA creature remains in its giant size for the duration, until it drops to 0 hit points, or until you use an action to dismiss the effect on it.\\n\\nThe GM might allow you to choose different targets. For example, if you transform a bee, its giant version might have the same statistics as a giant wasp."},"it":{"name":"Insetto gigante","description":"Per la durata dell'incantesimo, l'incantatore trasforma un massimo di dieci millepiedi, tre ragni, cinque vespe o uno scorpione entro gittata in versioni giganti delle loro forme naturali. Un millepiedi diventa un millepiedi gigante, un ragno diventa un ragno gigante, una vespa diventa una vespa gigante e uno scorpione diventa uno scorpione gigante.\\n\\nOgni creatura obbedisce ai comandi verbali dell'incantatore e, durante il combattimento, agisce nel turno dell'incantatore in ogni round. Il GM possiede le statistiche di queste creature e risolve le loro azioni e i loro movimenti.\\n\\nUna creatura rimane nella sua forma gigante per la durata dell'incantesimo, finché scende a 0 punti ferita o finché l'incantatore usa un'azione per terminare l'effetto su di essa.\\n\\nIl GM potrebbe permettere all'incantatore di scegliere bersagli differenti. Per esempio, se trasforma un'ape, le statistiche generali della sua versione gigante potrebbero essere le stesse della vespa gigante.","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 10 minuti"}},"data":{"level":4,"school":"srd:rule:school-transmutation","classes":["srd:class:druid"],"subclasses":[],"castingTime":"1 action","range":"30 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 10 minutes"}},{"id":"srd:spell:glibness","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Glibness","description":"Until the spell ends, when you make a Charisma check, you can replace the number you roll with a 15. Additionally, no matter what you say, magic that would determine if you are telling the truth indicates that you are being truthful."},"it":{"name":"Loquacità","description":"Fino al termine dell'incantesimo, quando l'incantatore effettua una prova di Carisma, può sostituire il risultato del tiro con un 15. Inoltre, a prescindere da ciò che dice, le magie in grado di determinare se un bersaglio stia dicendo o meno la verità indicano che l'incantatore è sincero.","castingTime":"1 azione","range":"Incantatore","duration":"1 ora"}},"data":{"level":8,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:warlock"],"subclasses":[],"castingTime":"1 action","range":"Self","components":["V"],"ritual":false,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:globe-of-invulnerability","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Globe of Invulnerability","description":"An immobile, faintly shimmering barrier springs into existence in a 10-foot radius around you and remains for the duration.\\n\\nAny spell of 5th level or lower cast from outside the barrier can't affect creatures or objects within it, even if the spell is cast using a higher level spell slot. Such a spell can target creatures and objects within the barrier, but the spell has no effect on them. Similarly, the area within the barrier is excluded from the areas affected by such spells.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 7th level or higher, the barrier blocks spells of one level higher for each slot level above 6th."},"it":{"name":"Globo di invulnerabilità","description":"Una barriera immobile e lievemente scintillante si materializza entro un raggio di 3 metri dall'incantatore e permane per la durata dell'incantesimo.\\n\\nQualsiasi incantesimo di 5° livello o inferiore lanciato dall'esterno della barriera non ha alcun effetto sulle creature o gli oggetti all'interno, nemmeno se viene lanciato utilizzando uno slot incantesimo di livello superiore. Questo tipo di incantesimo può essere rivolto contro le creature e gli oggetti all'interno della barriera, senza tuttavia avere effetti su di loro. Allo stesso modo, l'area all'interno della barriera è esclusa dalle aree influenzate da questo tipo di incantesimi.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° livello o superiore, la barriera blocca gli incantesimi di un livello superiore per ogni slot di livello superiore al 6°.","castingTime":"1 azione","range":"Incantatore (raggio di 3 metri)","duration":"Concentrazione, fino a 1 minuto","material":"una perla di vetro o cristallo che si frantuma al termine dell'incantesimo"}},"data":{"level":6,"school":"srd:rule:school-abjuration","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A glass or crystal bead that shatters when the spell ends.","ritual":false,"concentration":true,"duration":"Up to 1 minute","area":{"type":"sphere","size":10}}},{"id":"srd:spell:glyph-of-warding","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Glyph of Warding","description":"When you cast this spell, you inscribe a glyph that harms other creatures, either upon a surface (such as a table or a section of floor or wall) or within an object that can be closed (such as a book, a scroll, or a treasure chest) to conceal the glyph. If you choose a surface, the glyph can cover an area of the surface no larger than 10 feet in diameter. If you choose an object, that object must remain in its place; if the object is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered.\\n\\nThe glyph is nearly invisible and requires a successful Intelligence (Investigation) check against your spell save DC to be found.\\n\\nYou decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, the most typical triggers include touching or standing on the glyph, removing another object covering the glyph, approaching within a certain distance of the glyph, or manipulating the object on which the glyph is inscribed. For glyphs inscribed within an object, the most common triggers include opening that object, approaching within a certain distance of the object, or seeing or reading the glyph. Once a glyph is triggered, this spell ends.\\n\\nYou can further refine the trigger so the spell activates only under certain circumstances or according to physical characteristics (such as height or weight), creature kind (for example, the ward could be set to affect aberrations or drow), or alignment. You can also set conditions for creatures that don't trigger the glyph, such as those who say a certain password.\\n\\nWhen you inscribe the glyph, choose *explosive runes* or a *spell glyph*.\\n\\n***Explosive Runes.*** When triggered, the glyph erupts with magical energy in a 20-foot-radius sphere centered on the glyph. The sphere spreads around corners. Each creature in the area must make a Dexterity saving throw. A creature takes 5d8 acid, cold, fire, lightning, or thunder damage on a failed saving throw (your choice when you create the glyph), or half as much damage on a successful one.\\n\\n***Spell Glyph.*** You can store a prepared spell of 3rd level or lower in the glyph by casting it as part of creating the glyph. The spell must target a single creature or an area. The spell being stored has no immediate effect when cast in this way. When the glyph is triggered, the stored spell is cast. If the spell has a target, it targets the creature that triggered the glyph. If the spell affects an area, the area is centered on that creature. If the spell summons hostile creatures or creates harmful objects or traps, they appear as close as possible to the intruder and attack it. If the spell requires concentration, it lasts until the end of its full duration.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the damage of an explosive runes glyph increases by 1d8 for each slot level above 3rd. If you create a spell glyph, you can store any spell of up to the same level as the slot you use for the glyph of warding."},"it":{"name":"Glifo di interdizione","description":"Quando lancia questo incantesimo, l'incantatore traccia un glifo che danneggia le altre creature su una superficie (come un tavolo o una sezione di pavimento o parete) o, al fine di nasconderlo, all'interno di un oggetto che può essere chiuso (come un libro, una pergamena o un forziere del tesoro). Se sceglie una superficie, il glifo può coprire un'area massima del diametro di 3 metri. Se l'incantatore sceglie un oggetto, questo non deve essere spostato; se ciò avviene, una volta che l'oggetto si allontana per più di 3 metri dal luogo in cui è stato lanciato l'incantesimo, il glifo si infrange e l'incantesimo termina senza essere innescato.\\n\\nIl glifo è pressoché invisibile e per scorgerlo è necessario superare una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo.\\n\\nQuando questo incantesimo viene lanciato, l'incantatore decide cosa innesca il glifo. Nel caso di glifi tracciati su una superficie, gli inneschi più comuni includono: toccare o camminare su di essi, rimuovere un altro oggetto che li copre, avvicinarsi a una certa distanza da loro o manipolare gli oggetti su cui sono tracciati. Nel caso di glifi tracciati all'interno di un oggetto, gli inneschi più comuni includono: aprire l'oggetto, avvicinarsi a una certa distanza da esso, oppure vedere o leggere il glifo.\\n\\nUna volta che un glifo viene innescato, l'incantesimo termina.\\n\\nL'incantatore può definire l'innesco in modo che l'incantesimo si attivi solamente in certe circostanze o in base a certe caratteristiche fisiche (come peso o altezza), al tipo di creature (per esempio, la protezione potrebbe attivarsi solo contro aberrazioni o drow) o all'allineamento. L'incantatore può inoltre impostare condizioni per evitare di innescare il glifo, come pronunciare una specifica parola d'ordine.\\n\\nQuando l'incantatore traccia il glifo, può scegliere tra glifo magico o rune esplosive.\\n\\n***Glifo magico.*** L'incantatore può custodire un incantesimo preparato di 3° livello o inferiore all'interno del glifo lanciandolo come parte del suo processo di creazione. L'incantesimo deve avere come bersaglio una sola creatura o un'area. In questo modo, l'incantesimo custodito non ha effetto immediato, ma viene lanciato quando il glifo si attiva. Se l'incantesimo ha un bersaglio, risulterà essere la creatura che ha attivato il glifo, mentre se influenza un'area, tale area sarà centrata su quella creatura. Se l'incantesimo evoca creature ostili oppure crea oggetti o trappole dannose, ciò che viene evocato o creato appare nel punto più vicino possibile all'intruso e lo attacca. Se l'incantesimo richiede concentrazione, permane per tutta la sua durata.\\n\\n***Rune esplosive.*** Quando attivato, il glifo esplode in una sfera di energia con raggio di 6 metri centrata su di esso che si estende oltre gli angoli. Ogni creatura presente nell'area deve effettuare un tiro salvezza su Destrezza. In caso di fallimento, subisce 5d8 danni da acido, freddo, fulmine, fuoco o tuono (a scelta dell'incantatore al momento della creazione del glifo), o la metà dei danni in caso di successo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, i danni di un glifo rune esplosive aumentano di 1d8 per ogni slot di livello superiore al 3°. Se l'incantatore crea un glifo magico, può custodirvi qualsiasi incantesimo di livello pari o inferiore a quello dello slot usato per il glifo di interdizione.","castingTime":"1 ora","range":"Contatto","duration":"Finché non viene dissolto o innescato","material":"incenso e polvere di diamante del valore di almeno 200 mo, che l'incantesimo consuma"}},"data":{"level":3,"school":"srd:rule:school-abjuration","classes":["srd:class:bard","srd:class:cleric","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 hour","range":"Touch","components":["V","S","M"],"material":"Incense and powdered diamond worth at least 200 gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"Until dispelled"}},{"id":"srd:spell:goodberry","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Goodberry","description":"Up to ten berries appear in your hand and are infused with magic for the duration. A creature can use its action to eat one berry. Eating a berry restores 1 hit point, and the berry provides enough nourishment to sustain a creature for a day.\\n\\nThe berries lose their potency if they have not been consumed within 24 hours of the casting of this spell."},"it":{"name":"Bacche benefiche","description":"Per la durata dell'incantesimo, nella mano dell'incantatore appaiono fino a dieci bacche infuse di magia. Una creatura può usare la sua azione per mangiare una bacca, recuperando così 1 punto ferita e ottenendo nutrimento sufficiente per una giornata intera.\\n\\nLe bacche perdono la loro potenza se non vengono consumate entro 24 ore dal lancio di questo incantesimo.","castingTime":"1 azione","range":"Contatto","duration":"Istantanea","material":"un rametto di vischio"}},"data":{"level":1,"school":"srd:rule:school-transmutation","classes":["srd:class:druid","srd:class:ranger"],"subclasses":[],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A sprig of mistletoe.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:grease","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Grease","description":"Slick grease covers the ground in a 10-foot square centered on a point within range and turns it into difficult terrain for the duration.\\n\\nWhen the grease appears, each creature standing in its area must succeed on a dexterity saving throw or fall prone. A creature that enters the area or ends its turn there must also succeed on a dexterity saving throw or fall prone."},"it":{"name":"Unto","description":"Una patina viscida di unto ricopre un'area di terreno di 3 metri per lato centrata su un punto entro gittata che diventa terreno difficile per la durata dell'incantesimo.\\n\\nQuando l'unto compare, ogni creatura nell'area deve superare un tiro salvezza su Destrezza, altrimenti cade a terra prona. Anche una creatura che entra nell'area o vi termina il proprio turno deve superare un tiro salvezza su Destrezza, altrimenti cade prona.","castingTime":"1 azione","range":"18 metri","duration":"1 minuto","material":"un pezzo di cotenna di maiale o burro"}},"data":{"level":1,"school":"srd:rule:school-conjuration","classes":["srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"A bit of pork rind or butter.","ritual":false,"concentration":false,"duration":"1 minute","savingThrow":{"ability":"dex","onSuccess":"none"},"area":{"type":"cube","size":10}}},{"id":"srd:spell:greater-invisibility","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Greater Invisibility","description":"You or a creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target's person."},"it":{"name":"Invisibilità superiore","description":"L'incantatore o una creatura da lui toccata diventa invisibile fino al termine dell'incantesimo. Ciò accade anche a tutto ciò che il bersaglio indossa o trasporta, sempre che non se ne separi.","castingTime":"1 azione","range":"Contatto","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":4,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:land"],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute"}},{"id":"srd:spell:greater-restoration","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Greater Restoration","description":"You imbue a creature you touch with positive energy to undo a debilitating effect. You can reduce the target's exhaustion level by one, or end one of the following effects on the target:\\n\\n- One effect that charmed or petrified the target\\n\\n- One curse, including the target's attunement to a cursed magic item\\n\\n- Any reduction to one of the target's ability scores\\n\\n- One effect reducing the target's hit point maximum"},"it":{"name":"Ristorare superiore","description":"L'incantatore infonde energia positiva in una creatura toccata per annullare un effetto debilitante. Può ridurre di uno il livello di indebolimento del bersaglio o porre fine a uno dei seguenti effetti su di esso:\\n\\n- Un effetto che ha affascinato o pietrificato il bersaglio\\n\\n- Una maledizione, inclusa la sintonia del bersaglio con un oggetto magico maledetto\\n\\n- Qualsiasi riduzione di un punteggio di caratteristica del bersaglio\\n\\n- Un effetto che riduce i punti ferita massimi del bersaglio","castingTime":"1 azione","range":"Contatto","duration":"Istantanea","material":"polvere di diamante del valore di almeno 100 mo, che l'incantesimo consuma"}},"data":{"level":5,"school":"srd:rule:school-abjuration","classes":["srd:class:bard","srd:class:cleric","srd:class:druid"],"subclasses":[],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"Diamond dust worth at least 100gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:guardian-of-faith","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Guardian of Faith","description":"A Large spectral guardian appears and hovers for the duration in an unoccupied space of your choice that you can see within range. The guardian occupies that space and is indistinct except for a gleaming sword and shield emblazoned with the symbol of your deity.\\n\\nAny creature hostile to you that moves to a space within 10 feet of the guardian for the first time on a turn must succeed on a dexterity saving throw. The creature takes 20 radiant damage on a failed save, or half as much damage on a successful one. The guardian vanishes when it has dealt a total of 60 damage."},"it":{"name":"Guardiano della fede","description":"Per la durata dell'incantesimo, un guardiano spettrale di taglia Grande compare e fluttua in uno spazio libero a scelta dell'incantatore, entro gittata e che è in grado di vedere. Il guardiano occupa quello spazio e appare indefinito, fatta eccezione per una spada e uno scudo scintillanti decorati con il simbolo della divinità dell'incantatore.\\n\\nOgni creatura ostile all'incantatore che si muove in uno spazio entro 3 metri dal guardiano per la prima volta in un turno deve superare un tiro salvezza su Destrezza. In caso di fallimento, subisce 20 danni radiosi, o la metà dei danni in caso di successo. Il guardiano svanisce quando ha inflitto un totale di 60 danni.","castingTime":"1 azione","range":"9 metri","duration":"8 ore"}},"data":{"level":4,"school":"srd:rule:school-conjuration","classes":["srd:class:cleric"],"subclasses":[],"castingTime":"1 action","range":"30 feet","components":["V"],"ritual":false,"concentration":false,"duration":"8 hours","damage":[{"type":"srd:rule:damage-radiant","atSlotLevel":{"4":"20"}}],"savingThrow":{"ability":"dex","onSuccess":"half"},"area":{"type":"cylinder","size":10}}},{"id":"srd:spell:guards-and-wards","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Guards and Wards","description":"You create a ward that protects up to 2,500 square feet of floor space (an area 50 feet square, or one hundred 5-foot squares or twenty-five 10-foot squares). The warded area can be up to 20 feet tall, and shaped as you desire. You can ward several stories of a stronghold by dividing the area among them, as long as you can walk into each contiguous area while you are casting the spell.\\n\\nWhen you cast this spell, you can specify individuals that are unaffected by any or all of the effects that you choose. You can also specify a password that, when spoken aloud, makes the speaker immune to these effects.\\n\\nGuards and wards creates the following effects within the warded area.\\n\\n***Corridors.*** Fog fills all the warded corridors, making them heavily obscured. In addition, at each intersection or branching passage offering a choice of direction, there is a 50 percent chance that a creature other than you will believe it is going in the opposite direction from the one it chooses.\\n\\n***Doors.*** All doors in the warded area are magically locked, as if sealed by an arcane lock spell. In addition, you can cover up to ten doors with an illusion (equivalent to the illusory object function of the minor illusion spell) to make them appear as plain sections of wall.\\n\\n***Stairs.*** Webs fill all stairs in the warded area from top to bottom, as the web spell. These strands regrow in 10 minutes if they are burned or torn away while guards and wards lasts.\\n\\n***Other Spell Effect.*** You can place your choice of one of the following magical effects within the warded area of the stronghold.\\n\\n- Place dancing lights in four corridors. You can designate a simple program that the lights repeat as long as guards and wards lasts.\\n\\n- Place magic mouth in two locations.\\n\\n- Place stinking cloud in two locations. The vapors appear in the places you designate; they return within 10 minutes if dispersed by wind while guards and wards lasts.\\n\\n- Place a constant gust of wind in one corridor or room.\\n\\n- Place a suggestion in one location. You select an area of up to 5 feet square, and any creature that enters or passes through the area receives the suggestion mentally.\\n\\nThe whole warded area radiates magic. A dispel magic cast on a specific effect, if successful, removes only that effect.\\n\\nYou can create a permanently guarded and warded structure by casting this spell there every day for one year."},"it":{"name":"Vigilanza e interdizione","description":"L'incantatore crea una difesa che protegge un'area quadrata di terreno di massimo 750 metri (un'area di 15 metri per lato, cento aree di 1,5 metri per lato o venticinque aree di 3 metri per lato). L'area protetta può essere alta fino a 6 metri e avere la forma desiderata dall'incantatore. È anche possibile proteggere diversi piani di una roccaforte dividendo l'area su di essi, purché l'incantatore possa camminare in ogni area contigua mentre lancia l'incantesimo.\\n\\nAl momento del lancio, l'incantatore può specificare quali individui non subiscono alcuni o tutti gli effetti da lui scelti. Può anche specificare una parola d'ordine che, quando pronunciata a voce alta, rende chi la pronuncia immune a questi effetti.\\n\\nVigilanza e interdizione crea i seguenti effetti nell'area protetta.\\n\\n***Corridoi.*** La nebbia riempie tutti i corridoi protetti, oscurandoli pesantemente. Inoltre, a ogni incrocio o diramazione che richieda di scegliere una direzione, una creatura diversa dall'incantatore ha una probabilità del 50% di credere di andare in una direzione differente da quella che ha scelto.\\n\\n***Porte.*** Tutte le porte nell'area protetta vengono chiuse a chiave magicamente, come sigillate da un incantesimo serratura arcana. Inoltre, l'incantatore può coprire fino a dieci porte con un'illusione (equivalente alla funzione di oggetto illusorio dell'incantesimo illusione minore) per farle apparire come normali sezioni di parete.\\n\\n***Scale.*** Tutte le scale nell'area protetta si riempiono da cima a fondo di ragnatele, come succederebbe lanciando un incantesimo ragnatela. Per la durata dell'incantesimo vigilanza e interdizione, i fili di queste ragnatele si riformano in 10 minuti se vengono bruciate o strappate.\\n\\n***Altri effetti dell'incantesimo.*** L'incantatore può collocare uno dei seguenti effetti magici a sua scelta all'interno dell'area protetta della roccaforte.\\n\\n- Collocare bocca magica in due luoghi.\\n\\n- Collocare una folata di vento costante in un corridoio o in una stanza.\\n\\n- Collocare luci danzanti in quattro corridoi, specificando anche un semplice schema che le luci ripetono per la durata di vigilanza e interdizione.\\n\\n- Collocare nube maleodorante in due luoghi. Il vapore compare nei luoghi scelti e riappare nel giro di 10 minuti se disperso dal vento fintantoché vigilanza e interdizione permane.\\n\\n- Collocare una suggestione in un luogo. L'incantatore seleziona un'area di un massimo di 1,5 metri per lato e qualsiasi creatura che vi entri o la attraversi riceve mentalmente la suggestione.\\n\\nL'intera area protetta emana magia. Un incantesimo dissolvi magie lanciato con successo su un effetto specifico rimuove solamente quello.\\n\\nL'incantatore può creare una struttura permanentemente protetta da vigilanza e interdizione lanciando l'incantesimo sulla struttura ogni giorno per un anno.","castingTime":"10 minuti","range":"Contatto","duration":"24 ore","material":"incenso bruciato, una piccola dose di zolfo e olio, uno spago annodato, una piccola quantità di sangue di umber hulk e una piccola verga d'argento del valore di almeno 10 mo"}},"data":{"level":6,"school":"srd:rule:school-abjuration","classes":["srd:class:bard","srd:class:wizard"],"subclasses":[],"castingTime":"10 minutes","range":"Touch","components":["V","S","M"],"material":"Burning incense, a small measure of brimstone and oil, a knotted string, a small amount of umber hulk blood, and a small silver rod worth at least 10 gp.","ritual":false,"concentration":false,"duration":"24 hours","area":{"type":"cube","size":2500}}},{"id":"srd:spell:guidance","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Guidance","description":"You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one ability check of its choice. It can roll the die before or after making the ability check. The spell then ends."},"it":{"name":"Guida","description":"L'incantatore tocca una creatura consenziente. Prima che l'incantesimo termini, il bersaglio può tirare un d4 e aggiungere il risultato a una prova di caratteristica a sua scelta. Può tirare il dado prima o dopo avere effettuato la prova di caratteristica, dopodiché l'incantesimo termina.","castingTime":"1 azione","range":"Contatto","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":0,"school":"srd:rule:school-divination","classes":["srd:class:cleric","srd:class:druid"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute"}},{"id":"srd:spell:guiding-bolt","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Guiding Bolt","description":"A flash of light streaks toward a creature of your choice within range. Make a ranged spell attack against the target. On a hit, the target takes 4d6 radiant damage, and the next attack roll made against this target before the end of your next turn has advantage, thanks to the mystical dim light glittering on the target until then.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st."},"it":{"name":"Dardo tracciante","description":"Un lampo di luce sfreccia verso una creatura entro gittata scelta dall'incantatore, effettuando un attacco a distanza con incantesimo contro il bersaglio. Se il colpo va a segno, il bersaglio subisce 4d6 danni radiosi e il successivo tiro per colpire effettuato dall'incantatore contro il bersaglio entro la fine del turno successivo dispone di vantaggio, grazie all'alone mistico di luce fioca che lo avvolge fino ad allora.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d6 per ogni slot di livello superiore al 1°.","castingTime":"1 azione","range":"36 metri","duration":"1 round"}},"data":{"level":1,"school":"srd:rule:school-evocation","classes":["srd:class:cleric"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"120 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"1 round","damage":[{"type":"srd:rule:damage-radiant","atSlotLevel":{"1":"4d6","2":"5d6","3":"6d6","4":"7d6","5":"8d6","6":"9d6","7":"10d6","8":"11d6","9":"12d6"}}],"attackType":"ranged"}},{"id":"srd:spell:gust-of-wind","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Gust of Wind","description":"A line of strong wind 60 feet long and 10 feet wide blasts from you in a direction you choose for the spell's duration. Each creature that starts its turn in the line must succeed on a strength saving throw or be pushed 15 feet away from you in a direction following the line.\\n\\nAny creature in the line must spend 2 feet of movement for every 1 foot it moves when moving closer to you.\\n\\nThe gust disperses gas or vapor, and it extinguishes candles, torches, and similar unprotected flames in the area. It causes protected flames, such as those of lanterns, to dance wildly and has a 50 percent chance to extinguish them.\\n\\nAs a bonus action on each of your turns before the spell ends, you can change the direction in which the line blasts from you."},"it":{"name":"Folata di vento","description":"Una linea di vento forte lunga 18 metri e ampia 3 metri viene indirizzata dall'incantatore in una direzione a sua scelta per la durata dell'incantesimo. Ogni creatura che inizia il suo turno nella linea deve superare un tiro salvezza su Forza o viene spinta per 4,5 metri lontano dall'incantatore nella direzione della linea.\\n\\nQualsiasi creatura nella linea deve usare 60 cm di movimento per ogni 30 cm percorsi per avvicinarsi all'incantatore.\\n\\nLa folata può disperdere gas o vapore e spegne candele, torce e simili fiamme non protette nell'area. Le fiamme protette, come quelle delle lanterne, tremolano e hanno il 50% di possibilità di spegnersi.\\n\\nCome azione bonus in ogni suo turno prima del termine dell'incantesimo, l'incantatore può cambiare la direzione della linea da lui originata.","castingTime":"1 azione","range":"Incantatore (linea di 18 metri)","duration":"Concentrazione, fino a 1 minuto","material":"un seme di legume"}},"data":{"level":2,"school":"srd:rule:school-evocation","classes":["srd:class:druid","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A legume seed.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"str","onSuccess":"none"},"area":{"type":"line","size":60}}},{"id":"srd:spell:hallow","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Hallow","description":"You touch a point and infuse an area around it with holy (or unholy) power. The area can have a radius up to 60 feet, and the spell fails if the radius includes an area already under the effect a hallow spell. The affected area is subject to the following effects.\\n\\nFirst, celestials, elementals, fey, fiends, and undead can't enter the area, nor can such creatures charm, frighten, or possess creatures within it. Any creature charmed, frightened, or possessed by such a creature is no longer charmed, frightened, or possessed upon entering the area. You can exclude one or more of those types of creatures from this effect.\\n\\nSecond, you can bind an extra effect to the area. Choose the effect from the following list, or choose an effect offered by the GM. Some of these effects apply to creatures in the area; you can designate whether the effect applies to all creatures, creatures that follow a specific deity or leader, or creatures of a specific sort, such as ores or trolls. When a creature that would be affected enters the spell's area for the first time on a turn or starts its turn there, it can make a charisma saving throw. On a success, the creature ignores the extra effect until it leaves the area.\\n\\n***Courage.*** Affected creatures can't be frightened while in the area.\\n\\n***Darkness.*** Darkness fills the area. Normal light, as well as magical light created by spells of a lower level than the slot you used to cast this spell, can't illuminate the area.\\n\\n***Daylight.*** Bright light fills the area. Magical darkness created by spells of a lower level than the slot you used to cast this spell can't extinguish the light.\\n\\n***Energy Protection.*** Affected creatures in the area have resistance to one damage type of your choice, except for bludgeoning, piercing, or slashing.\\n\\n***Energy Vulnerability.*** Affected creatures in the area have vulnerability to one damage type of your choice, except for bludgeoning, piercing, or slashing.\\n\\n***Everlasting Rest.*** Dead bodies interred in the area can't be turned into undead.\\n\\n***Extradimensional Interference.*** Affected creatures can't move or travel using teleportation or by extradimensional or interplanar means.\\n\\n***Fear.*** Affected creatures are frightened while in the area.\\n\\n***Silence.*** No sound can emanate from within the area, and no sound can reach into it.\\n\\n***Tongues.*** Affected creatures can communicate with any other creature in the area, even if they don't share a common language."},"it":{"name":"Santificare","description":"L'incantatore tocca un punto e infonde un potere sacro (o sacrilego) in un'area del raggio massimo di 18 metri intorno a esso. L'incantesimo tuttavia fallisce se il raggio comprende un'area già sotto l'effetto dell'incantesimo santificare. L'area influenzata è soggetta agli effetti seguenti.\\n\\nPer prima cosa, celestiali, elementali, folletti, immondi e non morti non possono entrare nell'area o affascinare, spaventare o possedere le creature al suo interno. Nel momento in cui entra nell'area, qualsiasi creatura affascinata, spaventata o posseduta da questo tipo di creature non ne è più influenzata. L'incantatore può inoltre escludere uno o più tipi delle creature sopracitate da questo effetto.\\n\\nIn secondo luogo, l'incantatore può vincolare un effetto aggiuntivo all'area, scegliendo dalla lista seguente o utilizzando un effetto offerto dal GM. Alcuni di questi effetti si applicano alle creature all'interno dell'area e l'incantatore può decidere se questo avviene per ognuna di esse, per quelle che seguono una divinità o un capo specifico, oppure per quelle appartenenti a un tipo specifico, come per esempio orchi o troll. Quando una creatura che ne sarebbe influenzata entra nell'area dell'incantesimo per la prima volta in un turno o inizia il suo turno qui, deve superare un tiro salvezza su Carisma. In caso di successo, la creatura ignora l'effetto aggiuntivo finché non lascia l'area.\\n\\n***Coraggio.*** Le creature influenzate non possono essere spaventate mentre si trovano nell'area.\\n\\n***Eterno riposo.*** I cadaveri sepolti nell'area non possono diventare non morti.\\n\\n***Interferenza extradimensionale.*** Le creature influenzate non possono muoversi o viaggiare usando il teletrasporto o mezzi extradimensionali o interplanari.\\n\\n***Linguaggi.*** Le creature influenzate possono comunicare con qualsiasi creatura all'interno dell'area, anche se non condividono il medesimo linguaggio.\\n\\n***Luce diurna.*** L'area è pervasa di luce intensa: l'oscurità magica creata da incantesimi di livello inferiore rispetto allo slot usato in questo caso dall'incantatore non possono oscurare la luce.\\n\\n***Oscurità.*** L'area si riempie di oscurità: la luce normale, nonché quella magica creata da incantesimi di livello inferiore rispetto allo slot usato in questo caso dall'incantatore, non possono illuminare l'area.\\n\\n***Paura.*** Le creature influenzate sono spaventate mentre si trovano nell'area.\\n\\n***Protezione dell'energia.*** Le creature influenzate nell'area ottengono resistenza a un tipo di danno a scelta dell'incantatore, a eccezione dei danni contundenti, perforanti o taglienti.\\n\\n***Silenzio.*** L'area è insonorizzata, nessun suono può fuoriuscire o penetrare al suo interno.\\n\\n***Vulnerabilità all'energia.*** Le creature influenzate nell'area ottengono vulnerabilità a un tipo di danno a scelta dell'incantatore, a eccezione dei danni contundenti, perforanti o taglienti.","castingTime":"24 ore","range":"Contatto","duration":"Finché non viene dissolto","material":"erbe, oli e incenso del valore di almeno 1.000 mo, che l'incantesimo consuma"}},"data":{"level":5,"school":"srd:rule:school-evocation","classes":["srd:class:cleric"],"subclasses":["srd:subclass:fiend"],"castingTime":"24 hours","range":"Touch","components":["V","S","M"],"material":"Herbs, oils, and incense worth at least 1,000 gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"Until dispelled","savingThrow":{"ability":"cha","onSuccess":"none"},"area":{"type":"sphere","size":60}}},{"id":"srd:spell:hallucinatory-terrain","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Hallucinatory Terrain","description":"You make natural terrain in a 150-foot cube in range look, sound, and smell like some other sort of natural terrain. Thus, open fields or a road can be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road. Manufactured structures, equipment, and creatures within the area aren't changed in appearance.\\n\\nThe tactile characteristics of the terrain are unchanged, so creatures entering the area are likely to see through the illusion. If the difference isn't obvious by touch, a creature carefully examining the illusion can attempt an Intelligence (Investigation) check against your spell save DC to disbelieve it. A creature who discerns the illusion for what it is, sees it as a vague image superimposed on the terrain."},"it":{"name":"Terreno illusorio","description":"L'incantatore fa in modo che un terreno naturale in un cubo di 45 metri abbia l'aspetto, i suoni e gli odori di un altro tipo di terreno naturale. Un campo aperto o una strada potrebbe così sembrare una palude, una collina, un crepaccio o qualche altro tipo di terreno difficile e invalicabile. Allo stesso modo, uno stagno potrebbe apparire come un prato erboso, un precipizio come un dolce pendio o un fosso erto di rocce come una strada ampia e accogliente. Tuttavia, le strutture artificiali, l'equipaggiamento e le creature all'interno dell'area non cambiano aspetto.\\n\\nInoltre, le caratteristiche tattili del terreno rimangono invariate, quindi le creature che entrano nell'area hanno buone probabilità di accorgersi dell'illusione. Se la differenza non è ovvia al tatto, una creatura che esamina attentamente l'illusione può tentare una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo per non essere tratta in inganno. Una creatura che riconosce l'illusione per ciò che è la vede come un'immagine nebulosa sovrapposta al terreno.","castingTime":"10 minuti","range":"90 metri","duration":"24 ore","material":"una pietra, un rametto e un frammento di un vegetale florido"}},"data":{"level":4,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:druid","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:land"],"castingTime":"10 minutes","range":"300 feet","components":["V","S","M"],"material":"A stone, a twig, and a bit of green plant.","ritual":false,"concentration":false,"duration":"24 hours","area":{"type":"cube","size":150}}},{"id":"srd:spell:harm","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Harm","description":"You unleash a virulent disease on a creature that you can see within range. The target must make a constitution saving throw. On a failed save, it takes 14d6 necrotic damage, or half as much damage on a successful save. The damage can't reduce the target's hit points below 1. If the target fails the saving throw, its hit point maximum is reduced for 1 hour by an amount equal to the necrotic damage it took. Any effect that removes a disease allows a creature's hit point maximum to return to normal before that time passes."},"it":{"name":"Ferire","description":"L'incantatore scatena una malattia virulenta contro una creatura entro gittata che è in grado di vedere. Il bersaglio deve effettuare un tiro salvezza su Costituzione subendo 14d6 danni necrotici in caso di fallimento, o la metà dei danni in caso di successo. Il danno non può ridurre i punti ferita del bersaglio a meno di 1. Se il bersaglio fallisce il tiro salvezza, i suoi punti ferita massimi vengono ridotti di un ammontare pari ai danni necrotici subiti. Qualsiasi effetto che rimuove le malattie riporta i punti ferita massimi della creatura alla normalità prima che quel periodo termini.","castingTime":"1 azione","range":"18 metri","duration":"Istantanea"}},"data":{"level":6,"school":"srd:rule:school-necromancy","classes":["srd:class:cleric"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-necrotic","atSlotLevel":{"6":"14d6"}}],"savingThrow":{"ability":"con","onSuccess":"half"}}},{"id":"srd:spell:haste","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Haste","description":"Choose a willing creature that you can see within range. Until the spell ends, the target's speed is doubled, it gains a +2 bonus to AC, it has advantage on dexterity saving throws, and it gains an additional action on each of its turns. That action can be used only to take the Attack (one weapon attack only), Dash, Disengage, Hide, or Use an Object action.\\n\\nWhen the spell ends, the target can't move or take actions until after its next turn, as a wave of lethargy sweeps over it."},"it":{"name":"Velocità","description":"L'incantatore sceglie una creatura consenziente entro gittata che è in grado di vedere. Finché l'incantesimo non termina, il bersaglio ottiene un bonus di +2 alla CA, dispone di vantaggio ai tiri salvezza su Destrezza, la sua velocità raddoppia e ottiene un'azione aggiuntiva per ogni turno. L'azione aggiuntiva può essere usata soltanto per effettuare un'azione Attacco (solo attacchi con un'arma), Disimpegno, Nascondersi, Scatto o Usare un oggetto.\\n\\nQuando l'incantesimo termina, il bersaglio non può muoversi o effettuare azioni fino alla fine del turno successivo, essendo sopraffatto da un'ondata di spossatezza.","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 1 minuto","material":"una scaglia di radice di liquirizia"}},"data":{"level":3,"school":"srd:rule:school-transmutation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A shaving of licorice root.","ritual":false,"concentration":true,"duration":"Up to 1 minute"}},{"id":"srd:spell:heal","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Heal","description":"Choose a creature that you can see within range. A surge of positive energy washes through the creature, causing it to regain 70 hit points. This spell also ends blindness, deafness, and any diseases affecting the target. This spell has no effect on constructs or undead.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 7th level or higher, the amount of healing increases by 10 for each slot level above 6th."},"it":{"name":"Guarigione","description":"L'incantatore sceglie una creatura entro gittata che è in grado di vedere. Un flusso di energia positiva investe la creatura, facendole recuperare 70 punti ferita. Questo incantesimo termina qualsiasi forma di cecità, sordità e malattia che influenza il bersaglio e non ha effetto su costrutti o non morti.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° livello o superiore, l'ammontare di guarigione aumenta di 10 per ogni slot di livello superiore al 6°.","castingTime":"1 azione","range":"18 metri","duration":"Istantanea"}},"data":{"level":6,"school":"srd:rule:school-evocation","classes":["srd:class:cleric","srd:class:druid"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:healing-word","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Healing Word","description":"A creature of your choice that you can see within range regains hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on undead or constructs.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the healing increases by 1d4 for each slot level above 1st."},"it":{"name":"Parola guaritrice","description":"Una creatura scelta dall'incantatore entro gittata e che egli sia in grado di vedere recupera un ammontare di punti ferita pari a 1d4 + il modificatore di caratteristica da incantatore. Questo incantesimo non ha effetto sui non morti o sui costrutti.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, la guarigione aumenta di 1d4 per ogni slot di livello superiore al 1°.","castingTime":"1 azione bonus","range":"18 metri","duration":"Istantanea"}},"data":{"level":1,"school":"srd:rule:school-evocation","classes":["srd:class:bard","srd:class:cleric","srd:class:druid"],"subclasses":["srd:subclass:lore"],"castingTime":"1 bonus action","range":"60 feet","components":["V"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:heat-metal","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Heat Metal","description":"Choose a manufactured metal object, such as a metal weapon or a suit of heavy or medium metal armor, that you can see within range. You cause the object to glow red-hot. Any creature in physical contact with the object takes 2d8 fire damage when you cast the spell. Until the spell ends, you can use a bonus action on each of your subsequent turns to cause this damage again.\\n\\nIf a creature is holding or wearing the object and takes the damage from it, the creature must succeed on a constitution saving throw or drop the object if it can. If it doesn't drop the object, it has disadvantage on attack rolls and ability checks until the start of your next turn.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd."},"it":{"name":"Riscaldare il metallo","description":"L'incantatore sceglie un oggetto lavorato in metallo, come un'arma in metallo o un'armatura di metallo media o pesante entro gittata che è in grado di vedere e la rende incandescente. Qualsiasi creatura a contatto fisico con l'oggetto subisce 2d8 danni da fuoco al momento del lancio dell'incantesimo, fino al termine del quale l'incantatore può usare un'azione bonus in ogni suo turno successivo per causare nuovamente questo danno.\\n\\nSe una creatura sta stringendo o indossando l'oggetto e ne subisce i danni, deve superare un tiro salvezza su Costituzione o, se possibile, lasciar cadere l'oggetto. Se ciò non avviene, il bersaglio ha svantaggio ai tiri per colpire e alle prove di caratteristica effettuati prima dell'inizio del turno successivo dell'incantatore.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 2°.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 minuto","material":"un pezzo di ferro e una fiamma"}},"data":{"level":2,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:druid"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"A piece of iron and a flame.","ritual":false,"concentration":true,"duration":"Up to 1 minute","damage":[{"type":"srd:rule:damage-fire","atSlotLevel":{"2":"2d8","3":"3d8","4":"4d8","5":"5d8","6":"6d8","7":"7d8","8":"8d8","9":"9d8"}}],"savingThrow":{"ability":"con","onSuccess":"other"}}},{"id":"srd:spell:hellish-rebuke","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Hellish Rebuke","description":"You point your finger, and the creature that damaged you is momentarily surrounded by hellish flames. The creature must make a dexterity saving throw. It takes 2d10 fire damage on a failed save, or half as much damage on a successful one.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d10 for each slot level above 1st."},"it":{"name":"Intimorire infernale","description":"L'incantatore punta il dito contro la creatura che gli ha inferto danni, la quale viene momentaneamente avvolta da fiamme infernali. La creatura deve effettuare un tiro salvezza su Destrezza e subisce 2d10 danni da fuoco in caso di fallimento, o la metà dei danni in caso di successo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d10 per ogni slot di livello superiore al 1°.","castingTime":"1 reazione, che l'incantatore può effettuare quando subisce danni da una creatura entro 18 metri che è in grado di vedere.","range":"18 metri","duration":"Istantanea"}},"data":{"level":1,"school":"srd:rule:school-evocation","classes":["srd:class:warlock"],"subclasses":[],"castingTime":"1 reaction","range":"60 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-fire","atSlotLevel":{"1":"2d10","2":"3d10","3":"4d10","4":"5d10","5":"6d10","6":"7d10","7":"8d10","8":"9d10","9":"10d10"}}],"savingThrow":{"ability":"dex","onSuccess":"half"}}},{"id":"srd:spell:heroes-feast","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Heroes' Feast","description":"You bring forth a great feast, including magnificent food and drink. The feast takes 1 hour to consume and disappears at the end of that time, and the beneficial effects don't set in until this hour is over. Up to twelve other creatures can partake of the feast.\\n\\nA creature that partakes of the feast gains several benefits. The creature is cured of all diseases and poison, becomes immune to poison and being frightened, and makes all wisdom saving throws with advantage. Its hit point maximum also increases by 2d10, and it gains the same number of hit points. These benefits last for 24 hours."},"it":{"name":"Banchetto degli eroi","description":"L'incantatore evoca un ricco banchetto, completo di sontuose pietanze e bevande. Consumare il banchetto richiede 1 ora, solo al termine della quale il convivio scompare e i suoi effetti benefici vengono applicati. Fino a un massimo di dodici creature possono partecipare al banchetto.\\n\\nUna creatura che partecipa al banchetto ne trae diversi benefici: viene curata da tutti i tipi di malattie e veleni, diventa immune ai veleni e alla condizione spaventato e dispone di vantaggio a tutti i tiri salvezza su Saggezza. Inoltre, i suoi punti ferita massimi aumentano di 2d10 e ottiene lo stesso numero di punti ferita. Questi benefici permangono per 24 ore.","castingTime":"10 minuti","range":"9 metri","duration":"Istantanea","material":"una ciotola tempestata di gemme del valore di almeno 1.000 mo, che l'incantesimo consuma"}},"data":{"level":6,"school":"srd:rule:school-conjuration","classes":["srd:class:cleric","srd:class:druid"],"subclasses":[],"castingTime":"10 minutes","range":"30 feet","components":["V","S","M"],"material":"A gem-encrusted bowl worth at least 1,000gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:heroism","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Heroism","description":"A willing creature you touch is imbued with bravery. Until the spell ends, the creature is immune to being frightened and gains temporary hit points equal to your spellcasting ability modifier at the start of each of its turns. When the spell ends, the target loses any remaining temporary hit points from this spell."},"it":{"name":"Eroismo","description":"Una creatura consenziente toccata dall'incantatore è animata da grande coraggio. Fino al termine dell'incantesimo, la creatura è immune alla condizione spaventato e all'inizio di ogni suo turno ottiene una quantità di punti ferita temporanei pari al modificatore di caratteristica da incantatore. Al termine dell'incantesimo, il bersaglio perde tutti i punti ferita temporanei rimasti dall'incantesimo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1°.","castingTime":"1 azione","range":"Contatto","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":1,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:paladin"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute"}},{"id":"srd:spell:hideous-laughter","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Hideous Laughter","description":"A creature of your choice that you can see within range perceives everything as hilariously funny and falls into fits of laughter if this spell affects it. The target must succeed on a wisdom saving throw or fall prone, becoming incapacitated and unable to stand up for the duration. A creature with an Intelligence score of 4 or less isn't affected.\\n\\nAt the end of each of its turns, and each time it takes damage, the target can make another wisdom saving throw. The target had advantage on the saving throw if it's triggered by damage. On a success, the spell ends."},"it":{"name":"Risata incontenibile","description":"Sotto l'influenza di questo incantesimo, una creatura scelta dall'incantatore, situata entro gittata e che è in grado di vedere, percepisce ogni cosa come esilarante ed è scossa da risate incontrollabili. Il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti cade prono, rimanendo incapacitato e immobilizzato per la durata dell'incantesimo. Una creatura con un punteggio di Intelligenza pari o inferiore a 4 non è influenzata dall'incantesimo.\\n\\nIl bersaglio può effettuare un altro tiro salvezza su Saggezza alla fine di ogni suo turno e ogni volta che subisce danni; in quest'ultimo caso dispone di vantaggio al tiro salvezza. In caso di successo, l'incantesimo termina.","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 1 minuto","material":"una manciata di briciole e una piuma da agitare in aria"}},"data":{"level":1,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"Tiny tarts and a feather that is waved in the air.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:hold-monster","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Hold Monster","description":"Choose a creature you can see and reach. The target must make a saving throw of Wisdom or be paralyzed for the duration of the spell. This spell has no effect against the undead. At the end of each round, the target can make a new saving throw of Wisdom. If successful, the spell ends for the creature.\\n\\n**At Higher Levels.** When you cast this spell using a level 6 or higher location, you can target an additional creature for each level of location beyond the fifth. The creatures must be within 30 feet o f each other when you target them."},"it":{"name":"Blocca mostri","description":"L'incantatore sceglie una creatura entro gittata che è in grado di vedere. Il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti sarà paralizzato per la durata dell'incantesimo. Questo incantesimo non ha effetto sui non morti. Il bersaglio può effettuare un altro tiro salvezza su Saggezza alla fine di ogni suo turno. Se lo supera, si libera dall'effetto dell'incantesimo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, può bersagliare una creatura aggiuntiva per ogni slot superiore al 5°. Quando l'incantatore le bersaglia, le creature devono trovarsi a non più di 9 metri l'una dall'altra.","castingTime":"1 azione","range":"27 metri","duration":"Concentrazione, fino a 1 minuto","material":"un piccola sbarra di ferro"}},"data":{"level":5,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"90 feet","components":["V","S","M"],"material":"A small piece of iron.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:hold-person","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Hold Person","description":"Choose a humanoid that you can see within range. The target must succeed on a wisdom saving throw or be paralyzed for the duration. At the end of each of its turns, the target can make another wisdom saving throw. On a success, the spell ends on the target.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, you can target one additional humanoid for each slot level above 2nd. The humanoids must be within 30 feet of each other when you target them."},"it":{"name":"Blocca persone","description":"L'incantatore sceglie un umanoide entro gittata che è in grado di vedere. Il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti sarà paralizzato per la durata dell'incantesimo. Il bersaglio può effettuare un altro tiro salvezza su Saggezza alla fine di ogni suo turno. Se lo supera, si libera dall'effetto dell'incantesimo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, può bersagliare un umanoide aggiuntivo per ogni slot superiore al 2°. In quel momento, gli umanoidi devono trovarsi a non più di 9 metri l'uno dall'altro.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 minuto","material":"un piccola sbarra di ferro"}},"data":{"level":2,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:cleric","srd:class:druid","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"A small, straight piece of iron.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:holy-aura","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Holy Aura","description":"Divine light washes out from you and coalesces in a soft radiance in a 30-foot radius around you. Creatures of your choice in that radius when you cast this spell shed dim light in a 5-foot radius and have advantage on all saving throws, and other creatures have disadvantage on attack rolls against them until the spell ends. In addition, when a fiend or an undead hits an affected creature with a melee attack, the aura flashes with brilliant light. The attacker must succeed on a constitution saving throw or be blinded until the spell ends."},"it":{"name":"Aura sacra","description":"Dall'incantatore si diffonde una luce divina che si materializza in un tenue bagliore in un raggio di 9 metri intorno a lui. Le creature da lui scelte presenti in quell'area al momento del lancio proiettano luce fioca in un raggio di 1,5 metri e dispongono di vantaggio ai tiri salvezza; le altre creature subiscono svantaggio ai tiri per colpire contro di loro fino al termine dell'incantesimo.\\n\\nInoltre, quando una creatura influenzata dall'incantesimo viene colpita da un immondo o un non morto con un attacco in mischia, l'aura emette bagliore accecante e l'attaccante deve superare un tiro salvezza su Costituzione, altrimenti sarà accecato fino al termine dell'incantesimo.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 1 minuto","material":"un minuscolo reliquiario del valore di almeno 1.000 mo contenente una reliquia sacra, come un brandello della tunica di un santo o un frammento di pergamena di un testo religioso"}},"data":{"level":8,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric"],"subclasses":[],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A tiny reliquary worth at least 1,000gp containing a sacred relic, such as a scrap of cloth from a saint's robe or a piece of parchment from a religious text.","ritual":false,"concentration":true,"duration":"Up to 1 minute","area":{"type":"sphere","size":30}}},{"id":"srd:spell:hunters-mark","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Hunter's Mark","description":"You choose a creature you can see within range and mystically mark it as your quarry. Until the spell ends, you deal an extra 1d6 damage to the target whenever you hit it with a weapon attack, and you have advantage on any Wisdom (Perception) or Wisdom (Survival) check you make to find it. If the target drops to 0 hit points before this spell ends, you can use a bonus action on a subsequent turn of yours to mark a new creature.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd or 4th level, you can maintain your concentration on the spell for up to 8 hours. When you use a spell slot of 5th level or higher, you can maintain your concentration on the spell for up to 24 hours."},"it":{"name":"Marchio del cacciatore","description":"L'incantatore sceglie una creatura entro gittata che è in grado di vedere, marchiandola misticamente come sua preda. Fino al termine dell'incantesimo, l'incantatore infligge 1d6 danni extra al bersaglio ogni volta che lo colpisce con un attacco con arma e inoltre dispone di vantaggio a ogni prova di Saggezza (Sopravvivenza) o Saggezza (Percezione) effettuata per trovarlo. Se il bersaglio scende a 0 punti ferita prima del termine dell'incantesimo, l'incantatore può usare un'azione bonus in un suo turno successivo per marchiare una nuova creatura.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° o 4° livello, può mantenere la concentrazione sull'incantesimo fino a un massimo di 8 ore. Se usa uno slot incantesimo di 5° livello o superiore, la può mantenere fino a un massimo di 24 ore.","castingTime":"1 azione bonus","range":"27 metri","duration":"Concentrazione, fino a 1 ora"}},"data":{"level":1,"school":"srd:rule:school-divination","classes":["srd:class:ranger"],"subclasses":[],"castingTime":"1 bonus action","range":"90 feet","components":["V"],"ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:hypnotic-pattern","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Hypnotic Pattern","description":"You create a twisting pattern of colors that weaves through the air inside a 30-foot cube within range. The pattern appears for a moment and vanishes. Each creature in the area who sees the pattern must make a wisdom saving throw. On a failed save, the creature becomes charmed for the duration. While charmed by this spell, the creature is incapacitated and has a speed of 0.\\n\\nThe spell ends for an affected creature if it takes any damage or if someone else uses an action to shake the creature out of its stupor."},"it":{"name":"Trama ipnotica","description":"L'incantatore crea un intreccio di colori che si snoda nell'aria all'interno di un cubo di 9 metri entro gittata, apparendo per qualche secondo prima di svanire. Ogni creatura presente nell'area che vede l'intreccio deve effettuare un tiro salvezza su Saggezza. Se lo fallisce, rimane affascinata per tutta la durata dell'incantesimo, in quel momento è incapacitata e ha una velocità di movimento pari a 0.\\n\\nL'incantesimo su una creatura influenzata termina se questa subisce danni o se qualcuno usa un'azione per scuoterla, destandola dal suo stato confusionale.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 1 minuto","material":"un bastoncino d'incenso acceso o una fiala di cristallo piena di materiale fosforescente"}},"data":{"level":3,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"120 feet","components":["S","M"],"material":"A glowing stick of incense or a crystal vial filled with phosphorescent material.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:ice-storm","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Ice Storm","description":"A hail of rock-hard ice pounds to the ground in a 20-foot-radius, 40-foot-high cylinder centered on a point within range. Each creature in the cylinder must make a dexterity saving throw. A creature takes 2d8 bludgeoning damage and 4d6 cold damage on a failed save, or half as much damage on a successful one.\\n\\nHailstones turn the storm's area of effect into difficult terrain until the end of your next turn.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 5th level or higher, the bludgeoning damage increases by 1d8 for each slot level above 4th."},"it":{"name":"Tempesta di ghiaccio","description":"Chicchi di grandine duri come la roccia cadono sul terreno all'interno di un cilindro del raggio di 6 metri e dell'altezza di 12 metri centrato in un punto entro gittata. Ogni creatura presente nel cilindro deve effettuare un tiro salvezza su Destrezza, subendo 2d8 danni contundenti e 4d6 danni da freddo in caso di fallimento, o la metà dei danni in caso di successo.\\n\\nLa grandine trasforma l'area di effetto della tempesta in un terreno difficile fino al termine del turno successivo dell'incantatore.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 5° livello o superiore, i danni contundenti aumentano di 1d8 per ogni slot di livello superiore al 4°.","castingTime":"1 azione","range":"90 metri","duration":"Istantanea","material":"un pizzico di polvere e qualche goccia d'acqua"}},"data":{"level":4,"school":"srd:rule:school-evocation","classes":["srd:class:druid","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:land"],"castingTime":"1 action","range":"300 feet","components":["V","S","M"],"material":"A pinch of dust and a few drops of water.","ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-bludgeoning","atSlotLevel":{"4":"2d8","5":"3d8","6":"4d8","7":"5d8","8":"6d8","9":"7d8"}},{"type":"srd:rule:damage-cold","atSlotLevel":{"4":"4d6","5":"4d6","6":"4d6","7":"4d6","8":"4d6","9":"4d6"}}],"savingThrow":{"ability":"dex","onSuccess":"half"},"area":{"type":"cylinder","size":20}}},{"id":"srd:spell:identify","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Identify","description":"You choose one object that you must touch throughout the casting of the spell. If it is a magic item or some other magic-imbued object, you learn its properties and how to use them, whether it requires attunement to use, and how many charges it has, if any. You learn whether any spells are affecting the item and what they are. If the item was created by a spell, you learn which spell created it.\\n\\nIf you instead touch a creature throughout the casting, you learn what spells, if any, are currently affecting it."},"it":{"name":"Identificare","description":"L'incantatore sceglie un oggetto che deve toccare durante il lancio dell'incantesimo. Se si tratta di un oggetto magico o di un altro oggetto infuso di magia, apprende le sue proprietà e come usarlo, se è necessaria la sintonia per usarlo e quante cariche contiene, se ce ne sono. Apprende anche se l'oggetto è influenzato da eventuali incantesimi e di quali si tratta. Se l'oggetto è stato creato da un incantesimo, l'incantatore apprende quale incantesimo l'ha creato.\\n\\nSe invece durante il lancio dell'incantesimo tocca una creatura, apprende quali incantesimi la stanno attualmente influenzando, se ce ne sono.","castingTime":"1 minuto","range":"Contatto","duration":"Istantanea","material":"una perla del valore di almeno 100 mo e una piuma di gufo"}},"data":{"level":1,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 minute","range":"Touch","components":["V","S","M"],"material":"A pearl worth at least 100gp and an owl feather.","ritual":true,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:illusory-script","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Illusory Script","description":"You write on parchment, paper, or some other suitable writing material and imbue it with a potent illusion that lasts for the duration.\\n\\nTo you and any creatures you designate when you cast the spell, the writing appears normal, written in your hand, and conveys whatever meaning you intended when you wrote the text. To all others, the writing appears as if it were written in an unknown or magical script that is unintelligible. Alternatively, you can cause the writing to appear to be an entirely different message, written in a different hand and language, though the language must be one you know.\\n\\nShould the spell be dispelled, the original script and the illusion both disappear.\\n\\nA creature with truesight can read the hidden message."},"it":{"name":"Scritto illusorio","description":"L'incantatore scrive su una pergamena, un foglio o un altro materiale adatto alla scrittura e infonde nello scritto una potente illusione che permane per la durata dell'incantesimo.\\n\\nAll'incantatore e a qualsiasi creatura indicata da lui al momento del lancio, lo scritto appare normale, stilato nella calligrafia dell'incantatore e trasmette il significato inteso nel momento in cui è stato scritto. Agli occhi di tutti gli altri, il messaggio appare scritto in un linguaggio magico o ignoto che risulta per loro incomprensibile. In alternativa, l'incantatore può fare in modo che appaia come un messaggio totalmente diverso, scritto in una calligrafia e un linguaggio differenti, quest'ultimo tuttavia deve essere noto all'incantatore.\\n\\nNel caso in cui l'incantesimo venga dissolto, il messaggio originale e l'illusione scompaiono.\\n\\nUna creatura con vista pura può leggere il messaggio nascosto.","castingTime":"1 minuto","range":"Contatto","duration":"10 giorni","material":"inchiostro a base di piombo del valore di almeno 10 mo, che l'incantesimo consuma"}},"data":{"level":1,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 minute","range":"Touch","components":["S","M"],"material":"A lead-based ink worth at least 10gp, which this spell consumes.","ritual":true,"concentration":false,"duration":"10 days"}},{"id":"srd:spell:imprisonment","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Imprisonment","description":"You create a magical restraint to hold a creature that you can see within range. The target must succeed on a wisdom saving throw or be bound by the spell; if it succeeds, it is immune to this spell if you cast it again. While affected by this spell, the creature doesn't need to breathe, eat, or drink, and it doesn't age. Divination spells can't locate or perceive the target.\\n\\nWhen you cast the spell, you choose one of the following forms of imprisonment.\\n\\n***Burial.*** The target is entombed far beneath the earth in a sphere of magical force that is just large enough to contain the target. Nothing can pass through the sphere, nor can any creature teleport or use planar travel to get into or out of it.\\n\\nThe special component for this version of the spell is a small mithral orb.\\n\\n***Chaining.*** Heavy chains, firmly rooted in the ground, hold the target in place. The target is restrained until the spell ends, and it can't move or be moved by any means until then.\\n\\nThe special component for this version of the spell is a fine chain of precious metal.\\n\\n***Hedged Prison.*** The spell transports the target into a tiny demiplane that is warded against teleportation and planar travel. The demiplane can be a labyrinth, a cage, a tower, or any similar confined structure or area of your choice.\\n\\nThe special component for this version of the spell is a miniature representation of the prison made from jade.\\n\\n***Minimus Containment.*** The target shrinks to a height of 1 inch and is imprisoned inside a gemstone or similar object. Light can pass through the gemstone normally (allowing the target to see out and other creatures to see in), but nothing else can pass through, even by means of teleportation or planar travel. The gemstone can't be cut or broken while the spell remains in effect.\\n\\nThe special component for this version of the spell is a large, transparent gemstone, such as a corundum, diamond, or ruby.\\n\\n***Slumber.*** The target falls asleep and can't be awoken.\\n\\nThe special component for this version of the spell consists of rare soporific herbs.\\n\\n***Ending the Spell.*** During the casting of the spell, in any of its versions, you can specify a condition that will cause the spell to end and release the target. The condition can be as specific or as elaborate as you choose, but the GM must agree that the condition is reasonable and has a likelihood of coming to pass. The conditions can be based on a creature's name, identity, or deity but otherwise must be based on observable actions or qualities and not based on intangibles such as level, class, or hit points.\\n\\nA dispel magic spell can end the spell only if it is cast as a 9th-level spell, targeting either the prison or the special component used to create it.\\n\\nYou can use a particular special component to create only one prison at a time. If you cast the spell again using the same component, the target of the first casting is immediately freed from its binding."},"it":{"name":"Imprigionare","description":"L'incantatore crea una costrizione magica per trattenere una creatura entro gittata che è in grado di vedere. Il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti sarà vincolato dall'incantesimo; in caso di successo, ne diventa immune qualora l'incantatore volesse lanciarlo di nuovo. Finché è influenzata da questo incantesimo, la creatura non ha bisogno di respirare, mangiare o bere e non invecchia. Gli incantesimi di divinazione non possono localizzare o individuare il bersaglio.\\n\\nQuando questo incantesimo viene lanciato, l'incantatore sceglie una delle forme di reclusione seguenti.\\n\\n***Ceppi.*** Il bersaglio è bloccato da una serie di pesanti catene saldamente ancorate al terreno ed è trattenuto fino al termine dell'incantesimo, non potendo muoversi o essere mosso in alcun modo fino a allora.\\n\\n***Prigione protetta.*** L'incantesimo trasporta il bersaglio in un semipiano minuscolo protetto da teletrasporto e viaggi planari. Il semipiano può essere un labirinto, una gabbia, una torre o un'analoga struttura o area delimitata a scelta dell'incantatore.\\n\\nLa componente speciale per questa versione dell'incantesimo è una rappresentazione in miniatura della prigione realizzata in giada.\\n\\n***Prigionia ridotta.*** Il bersaglio viene rimpicciolito a un'altezza di 2,5 centimetri e imprigionato all'interno di una gemma o un oggetto simile. La luce passa normalmente attraverso la gemma (permettendo al bersaglio di guardare all'esterno e alle altre creature di guardare all'interno), ma nient'altro può attraversarla, nemmeno utilizzando il teletrasporto o i viaggi planari. La gemma non può essere tagliata o rotta mentre l'incantesimo è attivo.\\n\\nLa componente speciale per questa versione dell'incantesimo è una grande gemma trasparente, come un corindone, un diamante o un rubino.\\n\\n***Sepoltura.*** Il bersaglio viene sepolto nelle viscere della terra in una sfera di forza magica sufficientemente ampia da contenerlo. Nulla può attraversare la sfera e nessuna creatura può utilizzare il teletrasporto o i viaggi planari per entrarvi o uscirvi.\\n\\nLa componente speciale per questa versione dell'incantesimo è un piccolo globo di mithral.\\n\\nLa componente speciale per questa versione dell'incantesimo è una sottile catena di metallo prezioso.\\n\\n***Sonno.*** Il bersaglio si addormenta e non può essere svegliato. La componente speciale per questa versione dell'incantesimo consiste in rare erbe soporifere.\\n\\n***Porre fine all'incantesimo.*** Durante il lancio dell'incantesimo, in qualsiasi sua versione, l'incantatore può specificare una condizione che vi pone fine, liberando il bersaglio. La condizione può essere specifica e complessa quanto l'incantatore desidera, ma il GM deve considerarla ragionevole e ritenere che abbia una possibilità di verificarsi. Le condizioni possono essere basate sul nome, l'identità o la divinità di una creatura, ma devono fondarsi su azioni o qualità osservabili e non su concetti intangibili come livello, classe o punti ferita.\\n\\nDissolvi magie può porre fine a questo incantesimo solo se viene lanciato come un incantesimo di 9° livello, bersagliando la prigione o la componente speciale usata per crearla.\\n\\nL'incantatore può utilizzare una particolare componente speciale per creare una sola prigione alla volta. Se l'incantatore lancia nuovamente l'incantesimo usando la stessa componente, il bersaglio del primo lancio viene subito liberato dalla sua prigionia.","castingTime":"1 minuto","range":"9 metri","duration":"Finché non viene dissolto","material":"un ritratto su pergamena o una statuetta intagliata con le fattezze del bersaglio e una componente speciale che varia in base alla versione dell'incantesimo scelta, del valore di almeno 500 mo per ogni Dado Vita del bersaglio"}},"data":{"level":9,"school":"srd:rule:school-abjuration","classes":["srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 minute","range":"30 feet","components":["V","S","M"],"material":"A vellum depiction or a carved statuette in the likeness of the target, and a special component that varies according to the version of the spell you choose, worth at least 500gp per Hit Die of the target.","ritual":false,"concentration":false,"duration":"Until dispelled","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:incendiary-cloud","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Incendiary Cloud","description":"A swirling cloud of smoke shot through with white-hot embers appears in a 20-foot-radius sphere centered on a point within range. The cloud spreads around corners and is heavily obscured. It lasts for the duration or until a wind of moderate or greater speed (at least 10 miles per hour) disperses it.\\n\\nWhen the cloud appears, each creature in it must make a dexterity saving throw. A creature takes 10d8 fire damage on a failed save, or half as much damage on a successful one. A creature must also make this saving throw when it enters the spell's area for the first time on a turn or ends its turn there.\\n\\nThe cloud moves 10 feet directly away from you in a direction that you choose at the start of each of your turns."},"it":{"name":"Nube incendiaria","description":"Una nube turbinante di fumo mista a tizzoni ardenti appare in una sfera del raggio di 6 metri centrata su un punto entro gittata. La nube si estende intorno agli angoli, è pesantemente oscurata e permane per la durata dell'incantesimo o finché un vento di velocità moderata o superiore (almeno 15 km orari) non la disperde.\\n\\nQuando appare la nube, ogni creatura al suo interno deve effettuare un tiro salvezza su Destrezza, subendo 10d8 danni da fuoco in caso di fallimento, o la metà dei danni in caso di successo. Inoltre, una creatura deve superare tale tiro salvezza anche quando entra nell'area dell'incantesimo per la prima volta in un turno o termina il suo turno qui.\\n\\nLa nube si allontana di 3 metri dall'incantatore in una direzione scelta da quest'ultimo all'inizio di ogni suo turno.","castingTime":"1 azione","range":"45 metri","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":8,"school":"srd:rule:school-conjuration","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"150 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","damage":[{"type":"srd:rule:damage-fire","atSlotLevel":{"8":"10d8"}}],"savingThrow":{"ability":"dex","onSuccess":"half"},"area":{"type":"sphere","size":20}}},{"id":"srd:spell:inflict-wounds","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Inflict Wounds","description":"Make a melee spell attack against a creature you can reach. On a hit, the target takes 3d10 necrotic damage.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d10 for each slot level above 1st."},"it":{"name":"Infliggi ferite","description":"Con questo incantesimo l'incantatore effettua un attacco in mischia contro una creatura entro la sua portata. Se il colpo va a segno, il bersaglio subisce 3d10 danni necrotici.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d10 per ogni slot di livello superiore al 1°.","castingTime":"1 azione","range":"Contatto","duration":"Istantanea"}},"data":{"level":1,"school":"srd:rule:school-necromancy","classes":["srd:class:cleric"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-necrotic","atSlotLevel":{"1":"3d10","2":"4d10","3":"5d10","4":"6d10","5":"7d10","6":"8d10","7":"9d10","8":"10d10","9":"11d10"}}],"attackType":"melee"}},{"id":"srd:spell:insect-plague","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Insect Plague","description":"Swarming, biting locusts fill a 20-foot-radius sphere centered on a point you choose within range. The sphere spreads around corners. The sphere remains for the duration, and its area is lightly obscured. The sphere's area is difficult terrain.\\n\\nWhen the area appears, each creature in it must make a constitution saving throw. A creature takes 4d10 piercing damage on a failed save, or half as much damage on a successful one. A creature must also make this saving throw when it enters the spell's area for the first time on a turn or ends its turn there.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d10 for each slot level above 5th."},"it":{"name":"Piaga degli insetti","description":"Uno sciame di locuste fameliche riempie una sfera del raggio di 6 metri centrata su un punto a scelta dell'incantatore situato entro gittata che si estende oltre gli angoli, permane per tutta la durata dell'incantesimo e la cui area è leggermente oscurata. La sfera è inoltre terreno difficile.\\n\\nQuando appare l'area, ogni creatura al suo interno deve effettuare un tiro salvezza su Costituzione, subendo 4d10 danni perforanti in caso di fallimento, o la metà dei danni in caso di successo. Inoltre, una creatura deve superare tale tiro salvezza anche quando entra nell'area dell'incantesimo per la prima volta in un turno o termina il suo turno qui.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, i danni aumentano di 1d10 per ogni slot di livello superiore al 5°.","castingTime":"1 azione","range":"90 metri","duration":"Concentrazione, fino a 10 minuti","material":"qualche granello di zucchero, alcuni chicchi di grano e uno sbaffo di grasso"}},"data":{"level":5,"school":"srd:rule:school-conjuration","classes":["srd:class:cleric","srd:class:druid","srd:class:sorcerer"],"subclasses":["srd:subclass:land"],"castingTime":"1 action","range":"300 feet","components":["V","S","M"],"material":"A few grains of sugar, some kernels of grain, and a smear of fat.","ritual":false,"concentration":true,"duration":"Up to 10 minutes","damage":[{"type":"srd:rule:damage-piercing","atSlotLevel":{"5":"4d10","6":"5d10","7":"6d10","8":"7d10","9":"8d10"}}],"savingThrow":{"ability":"con","onSuccess":"half"},"area":{"type":"sphere","size":20}}},{"id":"srd:spell:instant-summons","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Instant Summons","description":"You touch an object weighing 10 pounds or less whose longest dimension is 6 feet or less. The spell leaves an invisible mark on its surface and invisibly inscribes the name of the item on the sapphire you use as the material component. Each time you cast this spell, you must use a different sapphire.\\n\\nAt any time thereafter, you can use your action to speak the item's name and crush the sapphire. The item instantly appears in your hand regardless of physical or planar distances, and the spell ends.\\n\\nIf another creature is holding or carrying the item, crushing the sapphire doesn't transport the item to you, but instead you learn who the creature possessing the object is and roughly where that creature is located at that moment.\\n\\nDispel magic or a similar effect successfully applied to the sapphire ends this spell's effect."},"it":{"name":"Evocazioni istantanee","description":"L'incantatore tocca un oggetto del peso pari o inferiore a 5 kg e la cui dimensione più lunga sia pari o inferiore a 1,8 metri. L'incantesimo imprime un marchio invisibile sulla sua superficie e traccia in modo invisibile il nome dell'oggetto sullo zaffiro usato come componente materiale. Ogni volta che l'incantatore lancia questo incantesimo, deve utilizzare uno zaffiro diverso.\\n\\nDa quel momento in poi, l'incantatore può usare la sua azione per pronunciare il nome dell'oggetto e distruggere lo zaffiro. L'oggetto appare immediatamente nella mano dell'incantatore, a prescindere dalle distanze fisiche o planari e l'incantesimo termina.\\n\\nSe un'altra creatura impugna o trasporta l'oggetto, la distruzione dello zaffiro non comporta l'apparizione dell'oggetto, ma l'incantatore apprende invece chi è la creatura in suo possesso e l'ubicazione approssimativa.\\n\\nDissolvi magie o un effetto analogo applicato con successo sullo zaffiro termina l'effetto di questo incantesimo.","castingTime":"1 minuto","range":"Contatto","duration":"Finché non viene dissolto","material":"uno zaffiro del valore di 1.000 mo"}},"data":{"level":6,"school":"srd:rule:school-conjuration","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 minute","range":"Touch","components":["V","S","M"],"material":"A sapphire worth 1,000 gp.","ritual":true,"concentration":false,"duration":"Until dispelled"}},{"id":"srd:spell:invisibility","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Invisibility","description":"A creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target's person. The spell ends for a target that attacks or casts a spell.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd."},"it":{"name":"Invisibilità","description":"Una creatura toccata dall'incantatore diventa invisibile fino al termine dell'incantesimo. Ciò accade anche a tutto ciò che il bersaglio indossa o trasporta, sempre che non se ne separi. L'incantesimo termina quando il bersaglio attacca o lancia un incantesimo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, può bersagliare una creatura aggiuntiva per ogni slot superiore al 2°.","castingTime":"1 azione","range":"Contatto","duration":"Concentrazione, fino a 1 ora","material":"un ciglio ricoperto da uno strato di resina"}},"data":{"level":2,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"An eyelash encased in gum arabic.","ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:irresistible-dance","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Irresistible Dance","description":"Choose one creature that you can see within range. The target begins a comic dance in place: shuffling, tapping its feet, and capering for the duration. Creatures that can't be charmed are immune to this spell.\\n\\nA dancing creature must use all its movement to dance without leaving its space and has disadvantage on dexterity saving throws and attack rolls. While the target is affected by this spell, other creatures have advantage on attack rolls against it. As an action, a dancing creature makes a wisdom saving throw to regain control of itself. On a successful save, the spell ends."},"it":{"name":"Danza irresistibile","description":"L'incantatore sceglie una creatura entro gittata che è in grado di vedere. Il bersaglio inizia a danzare comicamente sul posto, agitando le braccia, battendo i piedi e facendo capriole per la durata dell'incantesimo. Le creature che non possono essere affascinate sono immuni a questo incantesimo.\\n\\nUna creatura danzante deve usare tutti i suoi movimenti per ballare senza uscire dal suo spazio e subisce svantaggio ai tiri salvezza e ai tiri per colpire su Destrezza. Inoltre, mentre il bersaglio è influenzato dall'incantesimo, le altre creature dispongono di vantaggio ai tiri per colpire indirizzati contro di lui. Con un'azione, una creatura danzante effettua un tiro salvezza su Saggezza per riprendere il controllo di sé. In caso di successo, l'incantesimo termina.","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":6,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","components":["V"],"ritual":false,"concentration":true,"duration":"Up to 1 minute"}},{"id":"srd:spell:jump","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Jump","description":"You touch a creature. The creature's jump distance is tripled until the spell ends."},"it":{"name":"Saltare","description":"L'incantatore tocca una creatura, la cui distanza di salto viene triplicata fino al termine dell'incantesimo.","castingTime":"1 azione","range":"Contatto","duration":"1 minuto","material":"la zampa posteriore di una cavalletta"}},"data":{"level":1,"school":"srd:rule:school-transmutation","classes":["srd:class:druid","srd:class:ranger","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A grasshopper's hind leg.","ritual":false,"concentration":false,"duration":"1 minute"}},{"id":"srd:spell:knock","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Knock","description":"Choose an object that you can see within range. The object can be a door, a box, a chest, a set of manacles, a padlock, or another object that contains a mundane or magical means that prevents access.\\n\\nA target that is held shut by a mundane lock or that is stuck or barred becomes unlocked, unstuck, or unbarred. If the object has multiple locks, only one of them is unlocked.\\n\\nIf you choose a target that is held shut with arcane lock, that spell is suppressed for 10 minutes, during which time the target can be opened and shut normally.\\n\\nWhen you cast the spell, a loud knock, audible from as far away as 300 feet, emanates from the target object."},"it":{"name":"Scassinare","description":"L'incantatore sceglie un oggetto entro gittata che è in grado di vedere. Può trattarsi di una porta, uno scrigno, un forziere, un paio di manette, un lucchetto o un altro oggetto dotato di un mezzo normale o magico per la chiusura.\\n\\nUn bersaglio tenuto chiuso da una normale serratura, incastrato o sbarrato, cessa di essere tale. Se l'oggetto è protetto da più serrature, con questo incantesimo se ne sblocca soltanto una.\\n\\nSe l'incantatore sceglie un bersaglio tenuto chiuso da serratura arcana, quell'incantesimo è soppresso per 10 minuti, nel corso dei quali l'oggetto può essere aperto e chiuso normalmente.\\n\\nQuando l'incantatore lancia l'incantesimo, si percepisce un forte rumore simile al bussare proveniente dall'oggetto bersaglio, udibile fino a una distanza di 90 metri.","castingTime":"1 azione","range":"18 metri","duration":"Istantanea"}},"data":{"level":2,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:legend-lore","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Legend Lore","description":"Name or describe a person, place, or object. The spell brings to your mind a brief summary of the significant lore about the thing you named. The lore might consist of current tales, forgotten stories, or even secret lore that has never been widely known. If the thing you named isn't of legendary importance, you gain no information. The more information you already have about the thing, the more precise and detailed the information you receive is.\\n\\nThe information you learn is accurate but might be couched in figurative language. For example, if you have a mysterious magic axe on hand the spell might yield this information: \\"Woe to the evildoer whose hand touches the axe, for even the haft slices the hand of the evil ones. Only a true Child of Stone, lover and beloved of Moradin, may awaken the true powers of the axe, and only with the sacred word *Rudnogg* on the lips.\\""},"it":{"name":"Conoscenza delle legende","description":"L'incantatore nomina o descrive una persona, un luogo o un oggetto. L'incantesimo trasmette alla sua mente un breve riassunto delle conoscenze più significative relative all'oggetto nominato. Queste conoscenze possono includere storie attuali, racconti dimenticati o perfino conoscenze segrete che non sono note ai più. Se ciò che l'incantatore ha nominato non è di leggendaria importanza, non ottiene alcuna informazione. Più informazioni l'incantatore possiede già, più precise e dettagliate saranno le informazioni che riceverà.\\n\\nLe informazioni apprese dall'incantatore sono accurate ma potrebbero essere espresse in un linguaggio figurativo. Per esempio, se l'incantatore impugna un'ascia magica, l'incantesimo potrebbe fornire le seguenti informazioni: \\"La sventura attende il malfattore la cui mano tocca l'ascia, dacché la sola impugnatura fende il palmo dei malvagi. Soltanto un vero Figlio della Pietra, fedele a Moradin e da lui amato, può risvegliare i veri poteri dell'ascia, purché la parola sacra Rudnogg abbia sulle labbra.\\"","castingTime":"10 minuti","range":"Incantatore","duration":"Istantanea","material":"incenso del valore di almeno 250 mo, che l'incantesimo consuma e quattro lamine di avorio del valore di almeno 50 mo ciascuna"}},"data":{"level":5,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:cleric","srd:class:wizard"],"subclasses":[],"castingTime":"10 minutes","range":"Self","components":["V","S","M"],"material":"Incense worth at least 250 gp, which the spell consumes, and four ivory strips worth at least 50 gp each.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:lesser-restoration","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Lesser Restoration","description":"You touch a creature and can end either one disease or one condition afflicting it. The condition can be blinded, deafened, paralyzed, or poisoned."},"it":{"name":"Ristorare inferiore","description":"L'incantatore tocca una creatura e può porre termine a una malattia o una condizione che lo affligge tra accecato, assordato, avvelenato o paralizzato.","castingTime":"1 azione","range":"Contatto","duration":"Istantanea"}},"data":{"level":2,"school":"srd:rule:school-abjuration","classes":["srd:class:bard","srd:class:cleric","srd:class:druid","srd:class:paladin","srd:class:ranger"],"subclasses":["srd:subclass:lore","srd:subclass:life","srd:subclass:devotion"],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:levitate","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Levitate","description":"One creature or object of your choice that you can see within range rises vertically, up to 20 feet, and remains suspended there for the duration. The spell can levitate a target that weighs up to 500 pounds. An unwilling creature that succeeds on a constitution saving throw is unaffected.\\n\\nThe target can move only by pushing or pulling against a fixed object or surface within reach (such as a wall or a ceiling), which allows it to move as if it were climbing. You can change the target's altitude by up to 20 feet in either direction on your turn. If you are the target, you can move up or down as part of your move. Otherwise, you can use your action to move the target, which must remain within the spell's range.\\n\\nWhen the spell ends, the target floats gently to the ground if it is still aloft."},"it":{"name":"Levitazione","description":"Una creatura o un oggetto a scelta dell'incantatore, situato entro gittata e che è in grado di vedere, si solleva verticalmente fino a 6 metri rimanendo sospeso per la durata dell'incantesimo. L'incantesimo può far levitare un bersaglio che pesa fino a 250 kg. Una creatura non consenziente che supera un tiro salvezza su Costituzione non subisce l'effetto dell'incantesimo.\\n\\nIl bersaglio può muoversi soltanto spingendosi o aggrappandosi a un oggetto fisso o a una superficie entro portata (come per esempio una parete o un soffitto), che gli permetta di muoversi come se ne stesse scalando la superficie. Nel proprio turno, l'incantatore può variare l'altitudine del bersaglio per un massimo di 6 metri in ogni direzione. Se il bersaglio è l'incantatore stesso, può muoversi verso l'alto o verso il basso come parte del suo movimento. Altrimenti può usare la sua azione per muovere il bersaglio, che deve rimanere entro gittata.\\n\\nIl bersaglio, se è ancora sospeso, al termine dell'incantesimo fluttua dolcemente fino a terra.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 10 minuti","material":"un piccolo cappio di cuoio o un sottile cavo dorato piegato a forma di coppa con un lungo manico a un'estremità"}},"data":{"level":2,"school":"srd:rule:school-transmutation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"Either a small leather loop or a piece of golden wire bent into a cup shape with a long shank on one end.","ritual":false,"concentration":true,"duration":"Up to 10 minutes"}},{"id":"srd:spell:light","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Light","description":"You touch one object that is no larger than 10 feet in any dimension. Until the spell ends, the object sheds bright light in a 20-foot radius and dim light for an additional 20 feet. The light can be colored as you like. Completely covering the object with something opaque blocks the light. The spell ends if you cast it again or dismiss it as an action.\\n\\nIf you target an object held or worn by a hostile creature, that creature must succeed on a dexterity saving throw to avoid the spell."},"it":{"name":"Luce","description":"L'incantatore tocca un oggetto del volume di non più di 3 metri. Finché l'incantesimo non termina, l'oggetto proietta luce intensa entro un raggio di 6 metri e luce fioca per altri 6 metri. La luce può essere del colore che desideri. Coprire completamente l'oggetto con qualcosa di opaco blocca la luce. L'incantesimo termina se l'incantatore lo lancia di nuovo o lo interrompe con un'azione.\\n\\nSe l'incantatore bersaglia un oggetto impugnato o posseduto da una creatura ostile, quella creatura deve superare un tiro salvezza su Destrezza per evitare l'incantesimo.","castingTime":"1 azione","range":"Contatto","duration":"1 ora","material":"una lucciola o del muschio fosforescente"}},"data":{"level":0,"school":"srd:rule:school-evocation","classes":["srd:class:bard","srd:class:cleric","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","M"],"material":"A firefly or phosphorescent moss.","ritual":false,"concentration":false,"duration":"1 hour","savingThrow":{"ability":"dex","onSuccess":"none"}}},{"id":"srd:spell:lightning-bolt","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Lightning Bolt","description":"A stroke of lightning forming a line 100 feet long and 5 feet wide blasts out from you in a direction you choose. Each creature in the line must make a dexterity saving throw. A creature takes 8d6 lightning damage on a failed save, or half as much damage on a successful one.\\n\\nThe lightning ignites flammable objects in the area that aren't being worn or carried.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd."},"it":{"name":"Fulmine","description":"Un fulmine parte dall'incantatore in una direzione a sua scelta, formando una linea lunga 30 metri e larga 1,5 metri. Ogni creatura entro la linea deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, la creatura subisce 8d6 danni da fulmine, mentre se lo supera subisce soltanto la metà di quei danni.\\n\\nIl fulmine incendia ogni oggetto infiammabile nell'area che non sia indossato o trasportato.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d6 per ogni slot di livello superiore al 3°.","castingTime":"1 azione","range":"Incantatore (linea di 30 metri)","duration":"Istantanea","material":"un ciuffo di pelo e una verga d'ambra, di cristallo o di vetro"}},"data":{"level":3,"school":"srd:rule:school-evocation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A bit of fur and a rod of amber, crystal, or glass.","ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-lightning","atSlotLevel":{"3":"8d6","4":"9d6","5":"10d6","6":"11d6","7":"12d6","8":"13d6","9":"14d6"}}],"savingThrow":{"ability":"dex","onSuccess":"half"},"area":{"type":"line","size":100}}},{"id":"srd:spell:locate-animals-or-plants","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Locate Animals or Plants","description":"Describe or name a specific kind of beast or plant. Concentrating on the voice of nature in your surroundings, you learn the direction and distance to the closest creature or plant of that kind within 5 miles, if any are present."},"it":{"name":"Localizza animali o vegetali","description":"L'incantatore descrive o nomina un tipo specifico di bestia o vegetale. Concentrandosi sulla voce della natura intorno a lui, apprende la direzione e la distanza fino alla creatura o al vegetale di quel tipo più vicino entro 7,5 km, se ne è presente almeno uno.","castingTime":"1 azione","range":"Incantatore","duration":"Istantanea","material":"un ciuffo di peli di un segugio"}},"data":{"level":2,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:druid","srd:class:ranger"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A bit of fur from a bloodhound.","ritual":true,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:locate-creature","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Locate Creature","description":"Describe or name a creature that is familiar to you. You sense the direction to the creature's location, as long as that creature is within 1,000 feet of you. If the creature is moving, you know the direction of its movement.\\n\\nThe spell can locate a specific creature known to you, or the nearest creature of a specific kind (such as a human or a unicorn), so long as you have seen such a creature up close--within 30 feet--at least once. If the creature you described or named is in a different form, such as being under the effects of a polymorph spell, this spell doesn't locate the creature.\\n\\nThis spell can't locate a creature if running water at least 10 feet wide blocks a direct path between you and the creature."},"it":{"name":"Localizza creatura","description":"L'incantatore descrive o nomina una creatura a lui familiare, percependo la direzione della sua ubicazione, purché si trovi entro 300 metri da lui. Se la creatura è in movimento, l'incantatore apprende verso quale direzione si sta dirigendo.\\n\\nL'incantesimo può localizzare una creatura specifica nota all'incantatore o una creatura di un tipo specifico più vicina (come un umano o un unicorno), purché l'incantatore abbia visto tale creatura da vicino (entro 9 metri) almeno una volta. Se la creatura descritta o nominata ha una forma diversa, per esempio se si trova sono l'effetto di un incantesimo metamorfosi, questo incantesimo non riesce a localizzarla.\\n\\nInoltre, questo incantesimo non può localizzare una creatura se un corso d'acqua largo almeno 3 metri blocca il percorso diretto tra essa e l'incantatore.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 1 ora","material":"un ciuffo di peli di un segugio"}},"data":{"level":4,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:cleric","srd:class:druid","srd:class:paladin","srd:class:ranger","srd:class:wizard"],"subclasses":["srd:subclass:land"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A bit of fur from a bloodhound.","ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:locate-object","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Locate Object","description":"Describe or name an object that is familiar to you. You sense the direction to the object's location, as long as that object is within 1,000 feet of you. If the object is in motion, you know the direction of its movement.\\n\\nThe spell can locate a specific object known to you, as long as you have seen it up close--within 30 feet--at least once. Alternatively, the spell can locate the nearest object of a particular kind, such as a certain kind of apparel, jewelry, furniture, tool, or weapon.\\n\\nThis spell can't locate an object if any thickness of lead, even a thin sheet, blocks a direct path between you and the object."},"it":{"name":"Localizza oggetto","description":"L'incantatore descrive o nomina un oggetto a lui familiare, percependo la direzione della sua ubicazione, purché si trovi entro 300 metri da lui. Se l'oggetto è in movimento, l'incantatore apprende verso quale direzione si sta dirigendo.\\n\\nL'incantesimo può localizzare un oggetto specifico noto all'incantatore, purché l'abbia visto da vicino (entro 9 metri) almeno una volta. In alternativa, può localizzare l'oggetto di un tipo particolare più vicino, come per esempio un certo tipo di veste, gioiello, mobile, strumento o arma.\\n\\nInoltre, questo incantesimo non può localizzare un oggetto se uno strato di piombo di qualsiasi spessore, anche una lamina sottile, blocca il percorso diretto tra esso e l'incantatore.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 10 minuti","material":"un ramoscello biforcuto"}},"data":{"level":2,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:cleric","srd:class:druid","srd:class:paladin","srd:class:ranger","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A forked twig.","ritual":false,"concentration":true,"duration":"Up to 10 minutes"}},{"id":"srd:spell:longstrider","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Longstrider","description":"You touch a creature. The target's speed increases by 10 feet until the spell ends.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each spell slot above 1st."},"it":{"name":"Passo veloce","description":"L'incantatore tocca una creatura, la cui velocità aumenta di 3 metri fino al termine dell'incantesimo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1°.","castingTime":"1 azione","range":"Contatto","duration":"1 ora","material":"un pizzico di terriccio"}},"data":{"level":1,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:druid","srd:class:ranger","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A pinch of dirt.","ritual":false,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:mage-armor","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Mage Armor","description":"You touch a willing creature who isn't wearing armor, and a protective magical force surrounds it until the spell ends. The target's base AC becomes 13 + its Dexterity modifier. The spell ends if the target dons armor or if you dismiss the spell as an action."},"it":{"name":"Armatura magica","description":"L'incantatore tocca una creatura consenziente che non indossi un'armatura, che viene circondata da una forza magica protettiva fino al termine dell'incantesimo. La CA base del bersaglio diventa 13 + il suo modificatore di Destrezza. L'incantesimo termina se il bersaglio indossa un'armatura o se interrompi l'incantesimo con un'azione.","castingTime":"1 azione","range":"Contatto","duration":"8 ore","material":"un pezzo di cuoio trattato"}},"data":{"level":1,"school":"srd:rule:school-abjuration","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A piece of cured leather.","ritual":false,"concentration":false,"duration":"8 hours"}},{"id":"srd:spell:mage-hand","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Mage Hand","description":"A spectral, floating hand appears at a point you choose within range. The hand lasts for the duration or until you dismiss it as an action. The hand vanishes if it is ever more than 30 feet away from you or if you cast this spell again.\\n\\nYou can use your action to control the hand. You can use the hand to manipulate an object, open an unlocked door or container, stow or retrieve an item from an open container, or pour the contents out of a vial. You can move the hand up to 30 feet each time you use it.\\n\\nThe hand can't attack, activate magic items, or carry more than 10 pounds."},"it":{"name":"Mano magica","description":"Una mano spettrale fluttuante compare in un punto a scelta dell'incantatore situato entro gittata. La mano permane per la durata dell'incantesimo o finché non la congedi con un'azione. La mano svanisce se si trova a più di 9 metri dall'incantatore o se quest'ultimo lancia nuovamente l'incantesimo.\\n\\nL'incantatore può utilizzare la sua azione per controllare la mano e usarla per maneggiare un oggetto, aprire una porta o un contenitore che non sia chiuso a chiave, estrarre o riporre un oggetto da un contenitore aperto o versare il contenuto di una fiala. Ogni volta che la usa, può muovere la mano per un massimo di 9 metri.\\n\\nLa mano non può attaccare, attivare oggetti magici o trasportare più di 5 kg.","castingTime":"1 azione","range":"9 metri","duration":"1 minuto"}},"data":{"level":0,"school":"srd:rule:school-conjuration","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"30 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"1 minute"}},{"id":"srd:spell:magic-circle","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Magic Circle","description":"You create a 10-foot radius, 20-foot-tall cylinder of magical energy centered on a point on the ground that you can see within range. Glowing runes appear whenever the cylinder intersects with the floor or other surface.\\n\\nChoose one or more of the following types of creatures: celestials, elementals, fey, fiends, or undead. The circle affects a creature of the chosen type in the following ways:\\n\\n- The creature can't willingly enter the cylinder by nonmagical means. If the creature tries to use teleportation or interplanar travel to do so, it must first succeed on a charisma saving throw.\\n\\n- The creature has disadvantage on attack rolls against targets within the cylinder.\\n\\n- Targets within the cylinder can't be charmed, frightened, or possessed by the creature.\\n\\nWhen you cast this spell, you can elect to cause its magic to operate in the reverse direction, preventing a creature of the specified type from leaving the cylinder and protecting targets outside it.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the duration increases by 1 hour for each slot level above 3rd."},"it":{"name":"Cerchio magico","description":"L'incantatore crea un cilindro di energia magica di 3 metri di raggio e 6 metri di altezza centrato in un punto del terreno entro gittata che è in grado di vedere. Rune luminose appaiono nei punti in cui il cilindro si interseca con il pavimento o altre superfici.\\n\\nL'incantatore sceglie uno o più tra i tipi di creature seguenti: celestiali, elementali, folletti, immondi o non morti. Il cerchio influenza una creatura del tipo scelto nei seguenti modi:\\n\\n- La creatura non può entrare volontariamente nel cilindro tramite mezzi non magici. Se prova a utilizzare il teletrasporto o il viaggio interplanare, deve prima superare un tiro salvezza su Carisma.\\n\\n- La creatura subisce svantaggio ai tiri per colpire contro i bersagli all'interno del cilindro.\\n\\n- I bersagli all'interno del cilindro non possono essere affascinati, spaventati o posseduti dalla creatura.\\n\\nQuando lancia questo incantesimo, l'incantatore può decidere di far funzionare la sua magia nella direzione inversa, impedendo cioè a una creatura di un tipo specifico di uscire dal cilindro e proteggendo i bersagli all'esterno.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, la durata aumenta di 1 ora per ogni slot di livello superiore al 3°.","castingTime":"1 minuto","range":"3 metri","duration":"1 ora","material":"acqua santa o polvere d'argento e di ferro del valore di almeno 100 mo, che l'incantesimo consuma"}},"data":{"level":3,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric","srd:class:paladin","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 minute","range":"10 feet","components":["V","S","M"],"material":"Holy water or powdered silver and iron worth at least 100 gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"1 hour","savingThrow":{"ability":"cha","onSuccess":"other"},"area":{"type":"cylinder","size":10}}},{"id":"srd:spell:magic-jar","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Magic Jar","description":"Your body falls into a catatonic state as your soul leaves it and enters the container you used for the spell's material component. While your soul inhabits the container, you are aware of your surroundings as if you were in the container's space. You can't move or use reactions. The only action you can take is to project your soul up to 100 feet out of the container, either returning to your living body (and ending the spell) or attempting to possess a humanoids body.\\n\\nYou can attempt to possess any humanoid within 100 feet of you that you can see (creatures warded by a protection from evil and good or magic circle spell can't be possessed). The target must make a charisma saving throw. On a failure, your soul moves into the target's body, and the target's soul becomes trapped in the container. On a success, the target resists your efforts to possess it, and you can't attempt to possess it again for 24 hours.\\n\\nOnce you possess a creature's body, you control it. Your game statistics are replaced by the statistics of the creature, though you retain your alignment and your Intelligence, Wisdom, and Charisma scores. You retain the benefit of your own class features. If the target has any class levels, you can't use any of its class features.\\n\\nMeanwhile, the possessed creature's soul can perceive from the container using its own senses, but it can't move or take actions at all.\\n\\nWhile possessing a body, you can use your action to return from the host body to the container if it is within 100 feet of you, returning the host creature's soul to its body. If the host body dies while you're in it, the creature dies, and you must make a charisma saving throw against your own spellcasting DC. On a success, you return to the container if it is within 100 feet of you. Otherwise, you die.\\n\\nIf the container is destroyed or the spell ends, your soul immediately returns to your body. If your body is more than 100 feet away from you or if your body is dead when you attempt to return to it, you die. If another creature's soul is in the container when it is destroyed, the creature's soul returns to its body if the body is alive and within 100 feet. Otherwise, that creature dies.\\n\\nWhen the spell ends, the container is destroyed."},"it":{"name":"Giara magica","description":"Il corpo dell'incantatore cade in uno stato catatonico e la sua anima lo abbandona entrando nel contenitore utilizzato come componente materiale dell'incantesimo. Mentre la sua anima si trova all'interno del contenitore, l'incantatore è consapevole di ciò che accade intorno a lui come se si trovasse nello spazio del contenitore; non può tuttavia muoversi o usare reazioni. L'unica azione che può effettuare è proiettare la propria anima fino a 30 metri fuori dal contenitore, tornando nel suo corpo (e così terminando l'incantesimo) o provando a prendere possesso di un corpo umanoide.\\n\\nL'incantatore può tentare di possedere un qualsiasi umanoide entro 30 metri da lui che è in grado di vedere (tranne le creature protette da un incantesimo protezione dal bene e dal male o cerchio magico). Il bersaglio deve effettuare un tiro salvezza su Carisma. In caso di fallimento, l'anima dell'incantatore migra nel corpo del bersaglio, la cui anima viene intrappolata nel contenitore. In caso di successo, il bersaglio resiste agli sforzi dell'incantatore di possederlo e quest'ultimo non può riprovare per le 24 ore successive.\\n\\nQuando l'incantatore prende possesso del corpo di una creatura, ne ha il pieno controllo. Le sue statistiche di gioco vengono sostituite dalle statistiche della creatura, benché l'incantatore conservi il proprio allineamento, i punteggi di Intelligenza, Saggezza e Carisma e il beneficio dei suoi privilegi di classe. Se il bersaglio ha dei livelli di classe, l'incantatore non può utilizzare i privilegi di classe della creatura.\\n\\nNel frattempo, l'anima della creatura posseduta può percepire ciò che accade intorno al contenitore utilizzando i propri sensi, ma non può muoversi o effettuare azioni.\\n\\nMentre è in possesso di un corpo, l'incantatore può usare la sua azione per tornare nel contenitore se si trova entro 30 metri da lui, riportando l'anima della creatura ospite nel suo corpo. Se il corpo ospite muore mentre l'incantatore si trova al suo interno, anche la creatura muore e l'incantatore deve effettuare un tiro salvezza su Carisma contro la CD del suo stesso incantesimo. In caso di successo, l'incantatore torna nel contenitore, che deve tuttavia trovarsi entro 30 metri da lui; altrimenti muore.\\n\\nSe il contenitore viene distrutto o l'incantesimo termina, l'anima dell'incantatore torna nel suo corpo. Tuttavia, se il corpo si trova a più di 30 metri da lui o se è morto quando l'incantatore tenta di tornarci, anche l'incantatore perirà. Se l'anima di un'altra creatura si trova all'interno del contenitore quando viene distrutto, questa ritorna nel suo corpo, a patto che sia vivo e si trovi entro 30 metri; altrimenti, la creatura muore.\\n\\nAl termine dell'incantesimo, il contenitore viene distrutto.","castingTime":"1 minuto","range":"Incantatore","duration":"Finché non viene dissolto","material":"una gemma, un cristallo, un reliquiario o un altro contenitore ornamentale del valore di almeno 500 mo"}},"data":{"level":6,"school":"srd:rule:school-necromancy","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 minute","range":"Self","components":["V","S","M"],"material":"A gem, crystal, reliquary, or some other ornamental container worth at least 500 gp.","ritual":false,"concentration":false,"duration":"Until dispelled","savingThrow":{"ability":"cha","onSuccess":"other"}}},{"id":"srd:spell:magic-missile","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Magic Missile","description":"You create three glowing darts of magical force. Each dart hits a creature of your choice that you can see within range. A dart deals 1d4 + 1 force damage to its target. The darts all strike simultaneously, and you can direct them to hit one creature or several.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the spell creates one more dart for each slot level above 1st."},"it":{"name":"Dardo incantato","description":"L'incantatore crea tre dardi lucenti di forza magica. Ogni dardo colpisce una creatura a tua scelta, situata entro gittata e che sei in grado di vedere. Un dardo infligge 1d4 + 1 danni da forza al suo bersaglio. Tutti i dardi colpiscono simultaneamente e l'incantatore può dirigerli per colpire una o più creature.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, l'incantesimo crea un dardo aggiuntivo per ogni slot di livello superiore al 1°.","castingTime":"1 azione","range":"36 metri","duration":"Istantanea"}},"data":{"level":1,"school":"srd:rule:school-evocation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"120 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-force","atSlotLevel":{"1":"3d4 + 3","2":"4d4 + 4","3":"5d4 + 5","4":"6d4 + 6","5":"7d4 + 7","6":"8d4 + 8","7":"9d4 + 9","8":"10d4 + 10","9":"11d4 + 11"}}]}},{"id":"srd:spell:magic-mouth","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Magic Mouth","description":"You plant a message to an object in the range of the spell. The message is verbalized when the trigger conditions are met. Choose an object that you see, and that is not worn or carried by another creature. Then say the message, which should not exceed 25 words but listening can take up to 10 minutes. Finally, establish the circumstances that trigger the spell to deliver your message.\\n\\nWhen these conditions are satisfied, a magical mouth appears on the object and it articulates the message imitating your voice, the same tone used during implantation of the message. If the selected object has a mouth or something that approaches such as the mouth of a statue, the magic mouth come alive at this point, giving the illusion that the words come from the mouth of the object.\\n\\nWhen you cast this spell, you may decide that the spell ends when the message is delivered or it can persist and repeat the message whenever circumstances occur.\\n\\nThe triggering circumstance can be as general or as detailed as you like, though it must be based on visual or audible conditions that occur within 30 feet of the object. For example, you could instruct the mouth to speak when any creature moves within 30 feet of the object or when a silver bell rings within 30 feet of it."},"it":{"name":"Bocca magica","description":"L'incantatore imprime un messaggio all'interno di un oggetto entro gittata, che viene pronunciato quando si verifica una condizione di innesco. L'incantatore sceglie un oggetto che è in grado di vedere e che non è indossato o trasportato da un'altra creatura. Quindi pronuncia il messaggio, che non deve essere più lungo di 25 parole, ma può essere enunciato nell'arco di 10 minuti. Infine, determina la circostanza che innesca l'incantesimo e l'emissione del messaggio.\\n\\nQuando quella circostanza si verifica, sull'oggetto appare una bocca magica che recita il messaggio con il tono e il volume di voce dell'incantatore. Se l'oggetto scelto presenta già una bocca o qualcosa di simile (per esempio, la bocca di una statua), la bocca magica appare in modo che le parole sembrino pronunciate dalla bocca dell'oggetto. Quando lancia questo incantesimo, l'incantatore può fare in modo che esso termini una volta consegnato il messaggio o che rimanga attivo ripetendo il messaggio ogniqualvolta si verifica la circostanza di innesco.\\n\\nLa circostanza di innesco può essere sia generale che dettagliata, ma deve essere basata su condizioni visibili o udibili che si verificano entro 9 metri dall'oggetto. Per esempio, l'incantatore potrebbe ordinare alla bocca di parlare quando, entro 9 metri dall'oggetto, una qualsiasi creatura si muove, oppure un campana d'argento suona.","castingTime":"1 minuto","range":"9 metri","duration":"Finché non viene dissolto","material":"un frammento di favo e polvere di giada del valore di almeno 10 mo, che l'incantesimo consuma"}},"data":{"level":2,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 minute","range":"30 feet","components":["V","S","M"],"material":"A honeycomb and jade dust of at least 10 inches, the spell consumes.","ritual":true,"concentration":false,"duration":"Until dispelled"}},{"id":"srd:spell:magic-weapon","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Magic Weapon","description":"You touch a nonmagical weapon. Until the spell ends, that weapon becomes a magic weapon with a +1 bonus to attack rolls and damage rolls.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the bonus increases to +2. When you use a spell slot of 6th level or higher, the bonus increases to +3."},"it":{"name":"Arma magica","description":"L'incantatore tocca un'arma non magica e, finché l'incantesimo non termina, quell'arma diventa un'arma magica con un bonus di +1 ai tiri per colpire e ai tiri per i danni.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, il bonus aumenta a +2. Quando l'incantatore usa uno slot incantesimo di 6° livello o superiore, il bonus aumenta a +3.","castingTime":"1 azione bonus","range":"Contatto","duration":"Concentrazione, fino a 1 ora"}},"data":{"level":2,"school":"srd:rule:school-transmutation","classes":["srd:class:paladin","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 bonus action","range":"Touch","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:magnificent-mansion","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Magnificent Mansion","description":"You conjure an extradimensional dwelling in range that lasts for the duration. You choose where its one entrance is located. The entrance shimmers faintly and is 5 feet wide and 10 feet tall. You and any creature you designate when you cast the spell can enter the extradimensional dwelling as long as the portal remains open. You can open or close the portal if you are within 30 feet of it. While closed, the portal is invisible.\\n\\nBeyond the portal is a magnificent foyer with numerous chambers beyond. The atmosphere is clean, fresh, and warm.\\n\\nYou can create any floor plan you like, but the space can't exceed 50 cubes, each cube being 10 feet on each side. The place is furnished and decorated as you choose. It contains sufficient food to serve a nine course banquet for up to 100 people. A staff of 100 near-transparent servants attends all who enter. You decide the visual appearance of these servants and their attire. They are completely obedient to your orders. Each servant can perform any task a normal human servant could perform, but they can't attack or take any action that would directly harm another creature. Thus the servants can fetch things, clean, mend, fold clothes, light fires, serve food, pour wine, and so on. The servants can go anywhere in the mansion but can't leave it. Furnishings and other objects created by this spell dissipate into smoke if removed from the mansion. When the spell ends, any creatures inside the extradimensional space are expelled into the open spaces nearest to the entrance."},"it":{"name":"Reggia meravigliosa","description":"L'incantatore evoca entro gittata una dimora extradimensionale che permane per la durata dell'incantesimo. Sceglie inoltre l'ubicazione della sua entrata, che risplende di un debole bagliore ed è larga 1,5 metri e alta 3 metri. L'incantatore e una qualsiasi creatura da lui scelta al momento del lancio possono entrare nella dimora extradimensionale fintantoché il portale rimane aperto. L'incantatore può aprire o chiudere il portale se si trova entro 9 metri da esso; quando è chiuso, il portale è invisibile.\\n\\nOltre il portale si trova un atrio sfarzoso su cui si aprono numerose stanze. L'atmosfera è pulita, fresca e accogliente.\\n\\nL'incantatore può definire la planimetria della dimora, ma lo spazio non può superare la grandezza di 50 cubi, ciascuno con lato di 3 metri. Inoltre, la dimora è ammobiliata e decorata come l'incantatore preferisce e contiene cibo a sufficienza per servire un banchetto di nove portate per un massimo di 100 persone. A provvedere a ogni bisogno degli ospiti è presente una schiera di 100 servitori semitrasparenti, il cui aspetto e abbigliamento è deciso dall'incantatore, ai cui ordini sono totalmente ubbidienti. Ogni servitore può eseguire qualsiasi compito allo stesso modo di un servitore umano, ma non può attaccare o effettuare azioni che ferirebbero in modo diretto un'altra creatura. I servitori possono perciò trasportare oggetti, pulire, riparare, piegare abiti, accendere fuochi, servire cibo, versare vino e così via. Possono inoltre spostarsi ovunque nell'edificio, ma non possono uscirne. Arredi e altri oggetti creati da questo incantesimo si dissolvono in fumo quando vengono rimossi dalla dimora. Al termine dell'incantesimo, tutte le creature all'interno dello spazio extradimensionale vengono espulse negli spazi aperti più vicini all'entrata.","castingTime":"1 minuto","range":"90 metri","duration":"24 ore","material":"un portale in miniatura scolpito in avorio, un frammento di marmo lucido, un cucchiaino d'argento, del valore di almeno 5 mo ciascuno"}},"data":{"level":7,"school":"srd:rule:school-conjuration","classes":["srd:class:bard","srd:class:wizard"],"subclasses":[],"castingTime":"1 minute","range":"300 feet","components":["V","S","M"],"material":"A miniature portal carved from ivory, a small piece of polished marble, and a tiny silver spoon, each item worth at least 5 gp.","ritual":false,"concentration":false,"duration":"24 hours","area":{"type":"cube","size":5}}},{"id":"srd:spell:major-image","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Major Image","description":"You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 20-foot cube. The image appears at a spot that you can see within range and lasts for the duration. It seems completely real, including sounds, smells, and temperature appropriate to the thing depicted. You can't create sufficient heat or cold to cause damage, a sound loud enough to deal thunder damage or deafen a creature, or a smell that might sicken a creature (like a troglodyte's stench).\\n\\nAs long as you are within range of the illusion, you can use your action to cause the image to move to any other spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking. Similarly, you can cause the illusion to make different sounds at different times, even making it carry on a conversation, for example.\\n\\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and its other sensory qualities become faint to the creature.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 6th level or higher, the spell lasts until dispelled, without requiring your concentration."},"it":{"name":"Immagine maggiore","description":"L'incantatore crea l'immagine di un oggetto, una creatura o qualche altro fenomeno visibile che non sia più grande di un cubo di 6 metri. L'immagine, apparendo in un punto situato entro gittata che l'incantatore sia in grado di vedere, permane per la durata dell'incantesimo. L'immagine illusoria sembra completamente reale e include suoni, odori e temperatura dell'oggetto che rappresenta. L'incantatore non può creare calore o freddo sufficienti a infliggere danni, un rumore abbastanza forte da infliggere danni da tuono o assordare una creatura, oppure un odore in grado di rendere una creatura inferma (come il fetore di un troglodita).\\n\\nFinché l'incantatore si trova entro la gittata dell'immagine illusoria, può usare la sua azione per fare in modo che essa si muova fino a un qualsiasi altro punto entro gittata. Mentre l'immagine è in movimento, l'incantatore può alterarne l'aspetto in modo che i movimenti risultino naturali. Ad esempio, se l'incantatore crea l'immagine di una creatura e decide di farla muovere, può alterare l'immagine in modo da simulare che stia camminando. Analogamente, può fare in modo che l'illusione generi suoni diversi in momenti diversi, in modo per esempio da farla perfino partecipare a una conversazione.\\n\\nL'illusione può essere rivelata da un'interazione fisica, perché è possibile passarle attraverso. Una creatura che usa la sua azione per esaminare l'immagine può determinare che si tratta di un'illusione superando una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo. Se una creatura riconosce l'illusione per ciò che è, riesce a vedere attraverso l'immagine, di cui si attenuano le altre caratteristiche sensoriali.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, l'incantesimo dura finché non viene dissolto, senza richiedere la concentrazione dell'incantatore.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 10 minuti","material":"un ciuffo di lana"}},"data":{"level":3,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"120 feet","components":["V","S","M"],"material":"A bit of fleece.","ritual":false,"concentration":true,"duration":"Up to 10 minutes"}},{"id":"srd:spell:mass-cure-wounds","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Mass Cure Wounds","description":"A wave of healing energy washes out from a point of your choice within range. Choose up to six creatures in a 30-foot-radius sphere centered on that point. Each target regains hit points equal to 3d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 6th level or higher, the healing increases by 1d8 for each slot level above 5th."},"it":{"name":"Cura ferite di massa","description":"Un'ondata di energia curativa si sprigiona da un punto a scelta dell'incantatore entro gittata. L'incantatore sceglie fino a sei creature in una sfera di 9 metri di raggio centrata su quel punto: ogni bersaglio recupera una quantità di punti ferita pari a 3d8 + il modificatore di caratteristica da incantatore. Questo incantesimo non ha effetto sui non morti o sui costrutti.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, la guarigione aumenta di 1d8 per ogni slot di livello superiore al 5°.","castingTime":"1 azione","range":"18 metri","duration":"Istantanea"}},"data":{"level":5,"school":"srd:rule:school-conjuration","classes":["srd:class:bard","srd:class:cleric","srd:class:druid"],"subclasses":["srd:subclass:life"],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","area":{"type":"sphere","size":30}}},{"id":"srd:spell:mass-heal","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Mass Heal","description":"A flood of healing energy flows from you into injured creatures around you. You restore up to 700 hit points, divided as you choose among any number of creatures that you can see within range. Creatures healed by this spell are also cured of all diseases and any effect making them blinded or deafened. This spell has no effect on undead or constructs."},"it":{"name":"Guarigione di massa","description":"Un'ondata di energia curativa si sprigiona dall'incantatore, investendo le creature ferite intorno a lui. In questo modo, ripristina fino a 700 punti ferita, ripartendoli come desidera tra un qualsiasi numero di creature entro gittata e che è in grado di vedere. Le creature guarite da questo incantesimo vengono inoltre curate da ogni malattia e qualsiasi effetto che le accechi o assordi. Questo incantesimo non ha effetto sui non morti o sui costrutti.","castingTime":"1 azione","range":"18 metri","duration":"Istantanea"}},"data":{"level":9,"school":"srd:rule:school-conjuration","classes":["srd:class:cleric"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:mass-healing-word","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Mass Healing Word","description":"As you call out words of restoration, up to six creatures of your choice that you can see within range regain hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on undead or constructs.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the healing increases by 1d4 for each slot level above 3rd."},"it":{"name":"Parola guaritrice di massa","description":"L'incantatore pronuncia una serie di parole di guarigione e fino a sei creature a sua scelta, entro gittata e che è in grado di vedere, recuperano una quantità di punti ferita pari a 1d4 + il modificatore di caratteristica da incantatore. Questo incantesimo non ha effetto sui non morti o sui costrutti.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, la guarigione aumenta di 1d4 per ogni slot di livello superiore al 3°.","castingTime":"1 azione bonus","range":"18 metri","duration":"Istantanea"}},"data":{"level":3,"school":"srd:rule:school-evocation","classes":["srd:class:cleric"],"subclasses":["srd:subclass:lore"],"castingTime":"1 bonus action","range":"60 feet","components":["V"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:mass-suggestion","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Mass Suggestion","description":"You suggest a course of activity (limited to a sentence or two) and magically influence up to twelve creatures of your choice that you can see within range and that can hear and understand you. Creatures that can't be charmed are immune to this effect. The suggestion must be worded in such a manner as to make the course of action sound reasonable. Asking the creature to stab itself, throw itself onto a spear, immolate itself, or do some other obviously harmful act automatically negates the effect of the spell.\\n\\nEach target must make a wisdom saving throw. On a failed save, it pursues the course of action you described to the best of its ability. The suggested course of action can continue for the entire duration. If the suggested activity can be completed in a shorter time, the spell ends when the subject finishes what it was asked to do.\\n\\nYou can also specify conditions that will trigger a special activity during the duration. For example, you might suggest that a group of soldiers give all their money to the first beggar they meet. If the condition isn't met before the spell ends, the activity isn't performed.\\n\\nIf you or any of your companions damage a creature affected by this spell, the spell ends for that creature.\\n\\n**At Higher Levels.** When you cast this spell using a 7th-level spell slot, the duration is 10 days. When you use an 8th-level spell slot, the duration is 30 days. When you use a 9th-level spell slot, the duration is a year and a day."},"it":{"name":"Suggestione di massa","description":"L'incantatore suggerisce un corso d'azione da intraprendere (limitandosi a una o due frasi) influenzando magicamente fino a dodici creature entro gittata che è in grado di vedere, le quali devono essere in grado di sentire l'incantatore e di comprenderne le parole. Le creature che non possono essere affascinate sono immuni a questo effetto. La suggestione deve essere formulata in modo che il corso d'azione appaia ragionevole: chiedere a una creatura di pugnalarsi, gettarsi su una lancia, immolarsi o compiere altri atti palesemente autolesionistici annulla automaticamente l'effetto dell'incantesimo.\\n\\nOgni bersaglio deve effettuare un tiro salvezza su Saggezza. Se lo fallisce, deve perseguire il corso d'azione descritto dall'incantatore al meglio delle sue capacità. Tale corso d'azione può proseguire per l'intera durata dell'incantesimo. Se l'attività suggerita può essere completata in un periodo di tempo più breve, l'incantesimo termina quando il soggetto conclude ciò che gli è stato chiesto di fare.\\n\\nMentre l'incantesimo è attivo, l'incantatore può anche specificare delle condizioni che inneschino un'attività speciale. Per esempio, potrebbe suggerire che dei soldati cedano tutti i loro soldi al primo mendicante che incontrano. Se la condizione non viene soddisfatta prima che l'incantesimo termini, l'attività non viene eseguita.\\n\\nSe l'incantatore o uno dei suoi compagni infligge danni a una creatura influenzata dall'incantesimo, questo termina per quella creatura.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° livello, la durata è pari a 10 giorni. Quando usa uno slot incantesimo di 8° livello, la durata è pari a 30 giorni. Quando invece usa uno slot incantesimo di 9° livello, la durata è pari a un anno e un giorno.","castingTime":"1 azione","range":"18 metri","duration":"24 ore","material":"una lingua di serpente e un elemento a scelta tra un frammento di alveare e una goccia di olio dolce"}},"data":{"level":6,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","M"],"material":"A snake's tongue and either a bit of honeycomb or a drop of sweet oil.","ritual":false,"concentration":false,"duration":"24 hours","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:maze","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Maze","description":"You banish a creature that you can see within range into a labyrinthine demiplane. The target remains there for the duration or until it escapes the maze.\\n\\nThe target can use its action to attempt to escape. When it does so, it makes a DC 20 Intelligence check. If it succeeds, it escapes, and the spell ends (a minotaur or goristro demon automatically succeeds).\\n\\nWhen the spell ends, the target reappears in the space it left or, if that space is occupied, in the nearest unoccupied space."},"it":{"name":"Labirinto","description":"L'incantatore bandisce una creatura entro gittata che è in grado di vedere in un semipiano labirintico. Il bersaglio rimane laggiù per la durata dell'incantesimo o finché non fugge dal labirinto.\\n\\nIl bersaglio può usare la sua azione per provare a fuggire. Quando questo avviene, effettua una prova di Intelligenza con CD 20. Se la supera, riesce a fuggire e l'incantesimo termina (un minotauro o un demone goristro la superano automaticamente).\\n\\nAl termine dell'incantesimo, il bersaglio riappare nello spazio in cui si trovava prima del lancio o, se è occupato, nello spazio libero più vicino.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 10 minuti"}},"data":{"level":8,"school":"srd:rule:school-conjuration","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 10 minutes"}},{"id":"srd:spell:meld-into-stone","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Meld Into Stone","description":"You step into a stone object or surface large enough to fully contain your body, melding yourself and all the equipment you carry with the stone for the duration. Using your movement, you step into the stone at a point you can touch. Nothing of your presence remains visible or otherwise detectable by nonmagical senses.\\n\\nWhile merged with the stone, you can't see what occurs outside it, and any Wisdom (Perception) checks you make to hear sounds outside it are made with disadvantage. You remain aware of the passage of time and can cast spells on yourself while merged in the stone. You can use your movement to leave the stone where you entered it, which ends the spell. You otherwise can't move.\\n\\nMinor physical damage to the stone doesn't harm you, but its partial destruction or a change in its shape (to the extent that you no longer fit within it) expels you and deals 6d6 bludgeoning damage to you. The stone's complete destruction (or transmutation into a different substance) expels you and deals 50 bludgeoning damage to you. If expelled, you fall prone in an unoccupied space closest to where you first entered."},"it":{"name":"Fondersi nella pietra","description":"L'incantatore entra in un oggetto o in una superficie di pietra sufficientemente grande da contenere il suo corpo, fondendosi con esso insieme a tutto l'equipaggiamento che trasporta per la durata dell'incantesimo. Usando il suo movimento, entra nella pietra in un punto che è in grado di toccare e nulla della sua presenza rimane visibile o individuabile da qualsiasi senso non magico.\\n\\nMentre è fuso nella pietra, l'incantatore non può vedere ciò che accade al di fuori e subisce svantaggio in qualsiasi prova di Saggezza (Percezione) effettuata per udire i suoni all'esterno. Rimane tuttavia cosciente del passare del tempo e può lanciare incantesimi su di sé. L'incantatore può usare il suo movimento per uscire dalla pietra nel punto in cui è entrato, ponendo fine all'incantesimo. Altrimenti, non può muoversi.\\n\\nEventuali danni fisici minori inflitti alla pietra non danneggiano l'incantatore, ma una distruzione parziale o un'alterazione nella forma (al punto da non contenerne più il corpo) provoca l'espulsione dell'incantatore, infliggendogli 6d6 danni contundenti. La completa distruzione della pietra (o la sua trasmutazione in una sostanza differente) provoca l'espulsione dell'incantatore e gli infligge 50 danni contundenti. Se l'incantatore viene espulso, cade prono nello spazio libero più vicino al punto in cui era entrato.","castingTime":"1 azione","range":"Contatto","duration":"8 ore"}},"data":{"level":3,"school":"srd:rule:school-transmutation","classes":["srd:class:cleric"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":true,"concentration":false,"duration":"8 hours"}},{"id":"srd:spell:mending","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Mending","description":"This spell repairs a single break or tear in an object you touch, such as a broken key, a torn cloak, or a leaking wineskin. As long as the break or tear is no longer than 1 foot in any dimension, you mend it, leaving no trace of the former damage.\\n\\nThis spell can physically repair a magic item or construct, but the spell can't restore magic to such an object."},"it":{"name":"Riparare","description":"Questo incantesimo ripara una singola crepa o uno squarcio in un oggetto toccato dall'incantatore, come l'anello spezzato di una catena, due metà di una chiave spezzata, un mantello strappato o un otre forato. Se le dimensioni della crepa o dello squarcio non superano i 30 cm, l'incantatore ripara l'oggetto senza lasciare traccia del danno precedente.\\n\\nQuesto incantesimo può riparare un oggetto magico o un costrutto solo fisicamente, senza ripristinare la magia in esso contenuta.","castingTime":"1 minuto","range":"Contatto","duration":"Istantanea","material":"due calamite"}},"data":{"level":0,"school":"srd:rule:school-transmutation","classes":["srd:class:cleric","srd:class:bard","srd:class:druid","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 minute","range":"Touch","components":["V","S","M"],"material":"Two lodestones.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:message","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Message","description":"You point your finger toward a creature within range and whisper a message. The target (and only the target) hears the message and can reply in a whisper that only you can hear.\\n\\nYou can cast this spell through solid objects if you are familiar with the target and know it is beyond the barrier. Magical silence, 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood blocks the spell. The spell doesn't have to follow a straight line and can travel freely around corners or through openings."},"it":{"name":"Messaggio","description":"L'incantatore punta il dito contro una creatura entro gittata e sussurra un messaggio. Solo il bersaglio sente il messaggio e può sussurrare una risposta che unicamente l'incantatore può sentire.\\n\\nL'incantatore può lanciare questo incantesimo attraverso oggetti solidi se il bersaglio gli è noto e sa che si trova oltre la barriera. Tuttavia, l'incantesimo viene bloccato da silenzio magico, 30 cm di pietra, 2,5 cm di metallo comune, una sottile lamina di piombo o 90 cm di legno. Inoltre, l'incantesimo non deve necessariamente seguire una linea retta e può svilupparsi liberamente oltre gli angoli o attraverso le aperture.","castingTime":"1 azione","range":"36 metri","duration":"1 round","material":"un piccolo pezzo di filo di rame"}},"data":{"level":0,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"120 feet","components":["V","S","M"],"material":"A short piece of copper wire.","ritual":false,"concentration":false,"duration":"1 round"}},{"id":"srd:spell:meteor-swarm","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Meteor Swarm","description":"Blazing orbs of fire plummet to the ground at four different points you can see within range. Each creature in a 40-foot-radius sphere centered on each point you choose must make a dexterity saving throw. The sphere spreads around corners. A creature takes 20d6 fire damage and 20d6 bludgeoning damage on a failed save, or half as much damage on a successful one. A creature in the area of more than one fiery burst is affected only once.\\n\\nThe spell damages objects in the area and ignites flammable objects that aren't being worn or carried."},"it":{"name":"Sciame di meteore","description":"Globi infuocati precipitano sul terreno in quattro punti differenti entro gittata che l'incantatore è in grado di vedere. Ogni creatura situata in una sfera del raggio di 12 metri centrata su ognuno di quei punti deve effettuare un tiro salvezza su Destrezza. La sfera si estende intorno agli angoli. Una creatura subisce 20d6 danni da fuoco e 20d6 danni contundenti in caso di fallimento, o la metà dei danni in caso di successo. Una creatura in un'area con più esplosioni infuocate subisce l'effetto soltanto una volta.\\n\\nL'incantesimo danneggia gli oggetti presenti nell'area e incendia quelli infiammabili non indossati o trasportati.","castingTime":"1 azione","range":"1,5 km","duration":"Istantanea"}},"data":{"level":9,"school":"srd:rule:school-evocation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"1 mile","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-fire","atSlotLevel":{"9":"20d6"}},{"type":"srd:rule:damage-bludgeoning","atSlotLevel":{"9":"20d6"}}],"savingThrow":{"ability":"dex","onSuccess":"half"},"area":{"type":"sphere","size":40}}},{"id":"srd:spell:mind-blank","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Mind Blank","description":"Until the spell ends, one willing creature you touch is immune to psychic damage, any effect that would sense its emotions or read its thoughts, divination spells, and the charmed condition. The spell even foils wish spells and spells or effects of similar power used to affect the target's mind or to gain information about the target."},"it":{"name":"Vuoto mentale","description":"Finché l'incantesimo non termina, una creatura consenziente toccata dall'incantatore è immune ai danni psichici, a qualsiasi effetto che possa percepirne le emozioni o leggerne i pensieri, agli incantesimi di divinazione e alla condizione affascinato. L'incantesimo annulla perfino gli incantesimi desiderio e gli incantesimi o effetti di potenza analoga usati per influenzare la mente del bersaglio o per ottenere informazioni su quest'ultimo.","castingTime":"1 azione","range":"Contatto","duration":"24 ore"}},"data":{"level":8,"school":"srd:rule:school-abjuration","classes":["srd:class:bard","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":false,"concentration":false,"duration":"24 hours"}},{"id":"srd:spell:minor-illusion","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Minor Illusion","description":"You create a sound or an image of an object within range that lasts for the duration. The illusion also ends if you dismiss it as an action or cast this spell again.\\n\\nIf you create a sound, its volume can range from a whisper to a scream. It can be your voice, someone else's voice, a lion's roar, a beating of drums, or any other sound you choose. The sound continues unabated throughout the duration, or you can make discrete sounds at different times before the spell ends.\\n\\nIf you create an image of an object--such as a chair, muddy footprints, or a small chest--it must be no larger than a 5-foot cube. The image can't create sound, light, smell, or any other sensory effect. Physical interaction with the image reveals it to be an illusion, because things can pass through it.\\n\\nIf a creature uses its action to examine the sound or image, the creature can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the illusion becomes faint to the creature."},"it":{"name":"Illusione minore","description":"L'incantatore crea un suono o un'immagine di un oggetto entro gittata che permane per la durata dell'incantesimo. Inoltre, l'illusione termina se l'incantatore la interrompe con un'azione o se lancia questo incantesimo di nuovo.\\n\\nSe l'incantatore crea un suono, la sua intensità può variare da quella di un sussurro a quella di un urlo. Può trattarsi della voce dell'incantatore o di altri, del ruggito di un leone, di un rullo di tamburi o di un qualsiasi altro suono a sua scelta. Il suono può echeggiare ininterrottamente per tutta la durata dell'incantesimo, oppure l'incantatore può emettere dei suoni separati in momenti diversi prima che l'incantesimo termini.\\n\\nSe l'incantatore crea l'immagine di un oggetto (come per esempio una sedia, una serie di impronte nel fango o uno scrigno), quell'oggetto non deve essere più grande di un cubo di 1,5 metri. L'illusione non può emettere suoni, luci, odori o qualsiasi altro effetto sensoriale e può essere rivelata da un'interazione fisica, perché gli oggetti possono attraversarla.\\n\\nSe una creatura usa la sua azione per esaminare il suono o l'immagine, può determinare che si tratta di un'illusione superando una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo. Se una creatura riconosce l'illusione per ciò che è, risulta attenuata per quella creatura.","castingTime":"1 azione","range":"9 metri","duration":"1 minuto","material":"un ciuffo di lana"}},"data":{"level":0,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"30 feet","components":["S","M"],"material":"A bit of fleece.","ritual":false,"concentration":false,"duration":"1 minute"}},{"id":"srd:spell:mirage-arcane","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Mirage Arcane","description":"You make terrain in an area up to 1 mile square look, sound, smell, and even feel like some other sort of terrain. The terrain's general shape remains the same, however. Open fields or a road could be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road.\\n\\nSimilarly, you can alter the appearance of structures, or add them where none are present. The spell doesn't disguise, conceal, or add creatures.\\n\\nThe illusion includes audible, visual, tactile, and olfactory elements, so it can turn clear ground into difficult terrain (or vice versa) or otherwise impede movement through the area. Any piece of the illusory terrain (such as a rock or stick) that is removed from the spell's area disappears immediately.\\n\\nCreatures with truesight can see through the illusion to the terrain's true form; however, all other elements of the illusion remain, so while the creature is aware of the illusion's presence, the creature can still physically interact with the illusion."},"it":{"name":"Miraggio arcano","description":"L'incantatore fa in modo che il terreno in un'area massima di un quadrato con lato di 1,5 km appaia, suoni, odori e perfino risulti al tatto come un altro tipo di terreno, nonostante la sua forma generale rimanga la medesima. Un campo aperto o una strada potrebbe così sembrare una palude, una collina, un crepaccio o qualche altro tipo di terreno difficile e invalicabile. Allo stesso modo, uno stagno potrebbe apparire come un prato erboso, un precipizio come un dolce pendio o un fosso erto di rocce come una strada ampia e accogliente.\\n\\nL'incantatore può similmente modificare l'aspetto di strutture o aggiungerne altre dove non sono presenti. Tuttavia, l'incantesimo non può camuffare, occultare o aggiungere creature.\\n\\nL'illusione include elementi uditivi, visivi, tattili e olfattivi, quindi può trasformare un terreno libero in un terreno difficile (o viceversa), oppure ostacolare in altri modi i movimenti all'interno dell'area. Ogni frammento di terreno illusorio (come una roccia o un bastone) che viene rimosso dall'area dell'incantesimo scompare immediatamente.\\n\\nLe creature con vista pura sono in grado di vedere la vera forma del terreno attraverso l'illusione; tuttavia, permangono tutti gli altri elementi dell'illusione, quindi nonostante la creatura sia consapevole della sua presenza, può continuare a interagire fisicamente con essa.","castingTime":"10 minuti","range":"Vista","duration":"10 giorni"}},"data":{"level":7,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:druid","srd:class:wizard"],"subclasses":[],"castingTime":"10 minutes","range":"Sight","components":["V","S"],"ritual":false,"concentration":false,"duration":"10 days","area":{"type":"cube","size":5280}}},{"id":"srd:spell:mirror-image","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Mirror Image","description":"Three illusory duplicates of yourself appear in your space. Until the spell ends, the duplicates move with you and mimic your actions, shifting position so it's impossible to track which image is real. You can use your action to dismiss the illusory duplicates.\\n\\nEach time a creature targets you with an attack during the spell's duration, roll a d20 to determine whether the attack instead targets one of your duplicates.\\n\\nIf you have three duplicates, you must roll a 6 or higher to change the attack's target to a duplicate. With two duplicates, you must roll an 8 or higher. With one duplicate, you must roll an 11 or higher.\\n\\nA duplicate's AC equals 10 + your Dexterity modifier. If an attack hits a duplicate, the duplicate is destroyed. A duplicate can be destroyed only by an attack that hits it. It ignores all other damage and effects. The spell ends when all three duplicates are destroyed.\\n\\nA creature is unaffected by this spell if it can't see, if it relies on senses other than sight, such as blindsight, or if it can perceive illusions as false, as with truesight."},"it":{"name":"Immagine speculare","description":"Tre duplicati illusori dell'incantatore appaiono nel suo spazio. Fino al termine dell'incantesimo, i duplicati si muovono con l'incantatore e imitano le sue azioni, cambiando posizione in modo che sia impossibile individuare quale sia l'immagine reale. L'incantatore può utilizzare la sua azione per rimuovere i duplicati illusori.\\n\\nNel corso della durata dell'incantesimo, ogni volta che una creatura bersaglia l'incantatore con un attacco, quest'ultimo tira un d20 per determinare se l'attacco bersagli invece uno dei suoi duplicati.\\n\\nSe l'incantatore ha tre duplicati, per spostare il bersaglio dell'attacco su un duplicato deve ottenere al tiro un 6 o più. Con due duplicati, deve ottenere un 8 o più. Con un duplicato, deve ottenere un 11 o più.\\n\\nLa CA di un duplicato è pari a 10 + il modificatore di Destrezza dell'incantatore. Se un attacco colpisce un duplicato, questo viene distrutto. I duplicati possono essere distrutti solo da un attacco che li colpisce, mentre ignorano tutti gli altri tipi di danni ed effetti. L'incantesimo termina quando tutti e i tre duplicati sono distrutti.\\n\\nUna creatura non è influenzata da questo incantesimo se non può vedere, se si affida a sensi diversi dalla vista, come la vista cieca, o se può percepire la falsità delle illusioni, come nel caso sia dotata di vista pura.","castingTime":"1 azione","range":"Incantatore","duration":"1 minuto"}},"data":{"level":2,"school":"srd:rule:school-illusion","classes":["srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":false,"concentration":false,"duration":"1 minute"}},{"id":"srd:spell:mislead","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Mislead","description":"You become invisible at the same time that an illusory double of you appears where you are standing. The double lasts for the duration, but the invisibility ends if you attack or cast a spell.\\n\\nYou can use your action to move your illusory double up to twice your speed and make it gesture, speak, and behave in whatever way you choose.\\n\\nYou can see through its eyes and hear through its ears as if you were located where it is. On each of your turns as a bonus action, you can switch from using its senses to using your own, or back again. While you are using its senses, you are blinded and deafened in regard to your own surroundings."},"it":{"name":"Fuorviare","description":"L'incantatore diventa invisibile nello stesso momento in cui un suo sosia illusorio appare nel punto in cui si trova. Il suo sosia permane per la durata dell'incantesimo, ma l'invisibilità termina quando l'incantatore attacca o lancia un incantesimo.\\n\\nL'incantatore può usare la sua azione per muovere il sosia illusorio fino al doppio della sua velocità e farlo gesticolare, parlare e comportare nel modo che ritiene più opportuno.\\n\\nInoltre, può vedere e sentire attraverso il sosia, come se si trovasse nello stesso punto. In ognuno dei suoi turni come azione bonus, l'incantatore può passare dall'uso dei propri sensi a quelli del sosia e viceversa. Mentre utilizza i sensi del sosia, non può vedere né sentire nulla di ciò che circonda il suo vero corpo.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 1 ora"}},"data":{"level":5,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","components":["S"],"ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:misty-step","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Misty Step","description":"Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space that you can see."},"it":{"name":"Passo velato","description":"L'incantatore è avvolto per un istante da una foschia argentata e si teletrasporta di un massimo di 9 metri fino a uno spazio libero che è in grado di vedere.","castingTime":"1 azione bonus","range":"Incantatore","duration":"Istantanea"}},"data":{"level":2,"school":"srd:rule:school-conjuration","classes":["srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 bonus action","range":"Self","components":["V"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:modify-memory","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Modify Memory","description":"You attempt to reshape another creature's memories. One creature that you can see must make a wisdom saving throw. If you are fighting the creature, it has advantage on the saving throw. On a failed save, the target becomes charmed by you for the duration. The charmed target is incapacitated and unaware of its surroundings, though it can still hear you. If it takes any damage or is targeted by another spell, this spell ends, and none of the target's memories are modified.\\n\\nWhile this charm lasts, you can affect the target's memory of an event that it experienced within the last 24 hours and that lasted no more than 10 minutes. You can permanently eliminate all memory of the event, allow the target to recall the event with perfect clarity and exacting detail, change its memory of the details of the event, or create a memory of some other event.\\n\\nYou must speak to the target to describe how its memories are affected, and it must be able to understand your language for the modified memories to take root. Its mind fills in any gaps in the details of your description. If the spell ends before you have finished describing the modified memories, the creature's memory isn't altered. Otherwise, the modified memories take hold when the spell ends.\\n\\nA modified memory doesn't necessarily affect how a creature behaves, particularly if the memory contradicts the creature's natural inclinations, alignment, or beliefs. An illogical modified memory, such as implanting a memory of how much the creature enjoyed dousing itself in acid, is dismissed, perhaps as a bad dream. The GM might deem a modified memory too nonsensical to affect a creature in a significant manner.\\n\\nA remove curse or greater restoration spell cast on the target restores the creature's true memory.\\n\\n**At Higher Levels.** If you cast this spell using a spell slot of 6th level or higher, you can alter the target's memories of an event that took place up to 7 days ago (6th level), 30 days ago (7th level), 1 year ago (8th level), or any time in the creature's past (9th level)."},"it":{"name":"Modificare memoria","description":"L'incantatore tenta di alterare i ricordi di un'altra creatura che è in grado di vedere, la quale deve effettuare un tiro salvezza su Saggezza. Se l'incantatore sta combattendo contro la creatura, essa dispone di vantaggio al tiro salvezza. Se lo fallisce, il bersaglio rimane affascinato per tutta la durata dell'incantesimo, è inoltre incapacitato e inconsapevole di ciò che accade intorno a lui, ma può ancora udire l'incantatore. Se subisce danni o è bersagliato da un altro incantesimo, questo incantesimo termina e nessun ricordo del bersaglio viene modificato.\\n\\nFinché questo ammaliamento permane, l'incantatore può alterare il ricordo che il bersaglio ha di un evento avvenuto entro le 24 ore precedenti e della durata massima di 10 minuti. Può eliminare permanentemente tutti i ricordi dell'evento, consentire al bersaglio di ricordarlo con estrema chiarezza e in ogni dettaglio, alterare il ricordo di alcuni dettagli dell'evento o creare il ricordo di un evento diverso.\\n\\nPer descrivere in che modo i ricordi vengono alterati, l'incantatore deve parlare con il bersaglio, che deve quindi comprendere il linguaggio usato affinché i ricordi modificati si radichino nella sua mente. Essa poi riempie le eventuali lacune presenti nella descrizione dell'incantatore. Se l'incantesimo termina prima che l'incantatore abbia finito di descrivere i ricordi modificati, la memoria della creatura non subisce alcuna alterazione. In caso contrario, i ricordi modificati si radicano nella sua mente e l'incantesimo termina.\\n\\nUn ricordo modificato non influenza necessariamente il comportamento di una creatura, in particolare se contraddice le sue inclinazioni naturali, il suo allineamento o le sue convinzioni. Un ricordo modificato illogicamente, come per esempio il ricordo di quanto la creatura ami immergersi nell'acido, viene ignorato e considerato probabilmente come un brutto sogno. Il GM potrebbe ritenere che un ricordo modificato sia troppo insensato per influenzare la creatura in modo significativo.\\n\\nUn incantesimo rimuovi maledizione o ristorare superiore lanciato su un bersaglio ripristina i veri ricordi della creatura.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, può modificare i ricordi del bersaglio relativi a un evento risalente fino a 7 giorni prima (6° livello), 30 giorni prima (7° livello), 1 anno prima (8° livello) o a un qualsiasi momento del suo passato (9° livello).","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":5,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:moonbeam","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Moonbeam","description":"A silvery beam of pale light shines down in a 5-foot radius, 40-foot-high cylinder centered on a point within range. Until the spell ends, dim light fills the cylinder.\\n\\nWhen a creature enters the spell's area for the first time on a turn or starts its turn there, it is engulfed in ghostly flames that cause searing pain, and it must make a constitution saving throw. It takes 2d10 radiant damage on a failed save, or half as much damage on a successful one.\\n\\nA shapechanger makes its saving throw with disadvantage. If it fails, it also instantly reverts to its original form and can't assume a different form until it leaves the spell's light.\\n\\nOn each of your turns after you cast this spell, you can use an action to move the beam 60 feet in any direction.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1dl0 for each slot level above 2nd."},"it":{"name":"Bagliore lunare","description":"Un bagliore argentato di luce pallida forma un cilindro del raggio di 1,5 metri e dell'altezza di 12 metri centrato su un punto entro gittata. Fino al termine dell'incantesimo, il cilindro è pervaso da luce fioca.\\n\\nQuando una creatura entra nell'area dell'incantesimo per la prima volta in un turno o inizia il suo turno qui, è avvolta da fiamme spettrali che le causano dolori lancinanti e deve effettuare un tiro salvezza su Costituzione. In caso di fallimento, subisce 2d10 danni radiosi, o la metà dei danni in caso di successo.\\n\\nUn mutaforma subisce svantaggio a questo tiro salvezza e, se lo fallisce, riassume immediatamente la sua forma originale e non può assumerne una diversa finché non esce dalla luce dell'incantesimo.\\n\\nNei suoi turni successivi, dopo aver lanciato questo incantesimo, l'incantatore può usare un'azione per muovere il bagliore per 18 metri in ogni direzione.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, i danni aumentano di 1d10 per ogni slot di livello superiore al 2°.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 1 minuto","material":"alcuni semi a mezzaluna di un qualsiasi vitigno legnoso e un frammento di feldspato opalescente"}},"data":{"level":2,"school":"srd:rule:school-evocation","classes":["srd:class:druid"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"120 feet","components":["V","S","M"],"material":"Several seeds of any moonseed plant and a piece of opalescent feldspar.","ritual":false,"concentration":true,"duration":"Up to 1 minute","damage":[{"type":"srd:rule:damage-radiant","atSlotLevel":{"2":"2d10","3":"3d10","4":"4d10","5":"5d10","6":"6d10","7":"7d10","8":"8d10","9":"9d10"}}],"savingThrow":{"ability":"con","onSuccess":"half"},"area":{"type":"cylinder","size":5}}},{"id":"srd:spell:move-earth","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Move Earth","description":"Choose an area of terrain no larger than 40 feet on a side within range. You can reshape dirt, sand, or clay in the area in any manner you choose for the duration. You can raise or lower the area's elevation, create or fill in a trench, erect or flatten a wall, or form a pillar. The extent of any such changes can't exceed half the area's largest dimension. So, if you affect a 40-foot square, you can create a pillar up to 20 feet high, raise or lower the square's elevation by up to 20 feet, dig a trench up to 20 feet deep, and so on. It takes 10 minutes for these changes to complete.\\n\\nAt the end of every 10 minutes you spend concentrating on the spell, you can choose a new area of terrain to affect.\\n\\nBecause the terrain's transformation occurs slowly, creatures in the area can't usually be trapped or injured by the ground's movement.\\n\\nThis spell can't manipulate natural stone or stone construction. Rocks and structures shift to accommodate the new terrain. If the way you shape the terrain would make a structure unstable, it might collapse.\\n\\nSimilarly, this spell doesn't directly affect plant growth. The moved earth carries any plants along with it."},"it":{"name":"Muovere il terreno","description":"L'incantatore sceglie un'area di terreno entro gittata ampia al massimo 12 metri per lato. Per la durata dell'incantesimo, può rimodellare come desidera l'argilla, il terriccio o la sabbia presente nell'area. L'incantatore può aumentare o ridurre l'elevazione dell'area, creare o riempire una fossa, erigere o spianare una parete, oppure innalzare una colonna. Tuttavia, l'estensione di tali cambiamenti non può superare la metà della dimensione più grande dell'area. Quindi, se l'area dell'incantesimo è un quadrato con lato di 12 metri, l'incantatore può creare una colonna alta fino a 6 metri, aumentare o ridurre l'elevazione del terreno di 6 metri, scavare una fossa della profondità massima di 6 metri e così via. Le modifiche verranno completate in 10 minuti.\\n\\nAl termine di ogni 10 minuti trascorsi a concentrarsi sull'incantesimo, l'incantatore può scegliere una nuova area di terreno da influenzare.\\n\\nDal momento che la trasformazione del terreno avviene lentamente, le creature nell'area non restano intrappolate o ferite a causa dei movimenti del suolo.\\n\\nQuesto incantesimo non può manipolare la pietra naturale e le costruzioni realizzate in pietra: le rocce e le strutture si spostano per adattarsi al nuovo terreno. Se il modo in cui l'incantatore modella il terreno rende una struttura instabile, quella potrebbe crollare.\\n\\nAllo stesso modo, questo incantesimo non influenza in modo diretto la crescita vegetale: la terra in movimento trasporta con sé i vegetali presenti.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 2 ore","material":"una lama di ferro e un sacchetto contenente un misto di terre: argilla, terriccio e sabbia"}},"data":{"level":6,"school":"srd:rule:school-transmutation","classes":["srd:class:druid","srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","components":["V","S","M"],"material":"An iron blade and a small bag containing a mixture of soils--clay, loam, and sand.","ritual":false,"concentration":true,"duration":"Up to 2 hours","area":{"type":"cone","size":40}}},{"id":"srd:spell:nondetection","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Nondetection","description":"For the duration, you hide a target that you touch from divination magic. The target can be a willing creature or a place or an object no larger than 10 feet in any dimension. The target can't be targeted by any divination magic or perceived through magical scrying sensors."},"it":{"name":"Anti-individuazione","description":"Per la durata dell'incantesimo, l'incantatore nasconde alle magie di divinazione un bersaglio da lui toccato. Il bersaglio può essere una creatura consenziente, oppure un luogo o un oggetto non più grande di 3 metri in qualsiasi dimensione. Il bersaglio non può essere preso di mira da alcuna magia di divinazione né percepito da sensori di scrutamento magico.","castingTime":"1 azione","range":"Contatto","duration":"8 ore","material":"un pizzico di polvere di diamante del valore di 25 mo da spargere sul bersaglio, che l'incantesimo consuma"}},"data":{"level":3,"school":"srd:rule:school-abjuration","classes":["srd:class:bard","srd:class:ranger","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A pinch of diamond dust worth 25 gp sprinkled over the target, which the spell consumes.","ritual":false,"concentration":false,"duration":"8 hours"}},{"id":"srd:spell:pass-without-trace","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Pass Without Trace","description":"A veil of shadows and silence radiates from you, masking you and your companions from detection. For the duration, each creature you choose within 30 feet of you (including you) has a +10 bonus to Dexterity (Stealth) checks and can't be tracked except by magical means. A creature that receives this bonus leaves behind no tracks or other traces of its passage."},"it":{"name":"Passare senza tracce","description":"L'incantatore è avvolto da un velo d'ombra e di silenzio che impedisce a lui e ai suoi compagni di essere individuati. Per la durata dell'incantesimo, ogni creatura scelta dall'incantatore e situata entro 9 metri da lui (incluso se stesso) ha un bonus di +10 alle prove di Destrezza (Furtività) e le sue tracce sono impossibili da seguire se non tramite mezzi magici. Una creatura che riceve questo bonus non lascia impronte o altre tracce del proprio passaggio.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 1 ora","material":"cenere di una foglia di vischio bruciata e un rametto di abete"}},"data":{"level":2,"school":"srd:rule:school-abjuration","classes":["srd:class:druid","srd:class:ranger"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"Ashes from a burned leaf of mistletoe and a sprig of spruce.","ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:passwall","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Passwall","description":"A passage appears at a point of your choice that you can see on a wooden, plaster, or stone surface (such as a wall, a ceiling, or a floor) within range, and lasts for the duration. You choose the opening's dimensions: up to 5 feet wide, 8 feet tall, and 20 feet deep. The passage creates no instability in a structure surrounding it.\\n\\nWhen the opening disappears, any creatures or objects still in the passage created by the spell are safely ejected to an unoccupied space nearest to the surface on which you cast the spell."},"it":{"name":"Passapareti","description":"L'incantatore sceglie un punto entro gittata e che è in grado di vedere su una superficie di legno, pietra o intonaco (come una parete, un soffitto o un pavimento), dove si apre un passaggio che permane per la durata dell'incantesimo. L'incantatore sceglie inoltre le dimensioni dell'apertura, che non possono superare una larghezza di 1,5 metri, un'altezza di 2,4 metri e una profondità di 6 metri. Il passaggio non crea alcuna instabilità nella struttura che lo circonda.\\n\\nQuando l'apertura scompare, qualsiasi creatura o oggetto all'interno del passaggio creato dall'incantesimo viene espulso senza subire danni nello spazio libero più vicino alla superficie su cui l'incantesimo è stato lanciato.","castingTime":"1 azione","range":"9 metri","duration":"1 ora","material":"un pizzico di semi di sesamo"}},"data":{"level":5,"school":"srd:rule:school-transmutation","classes":["srd:class:wizard"],"subclasses":["srd:subclass:land"],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A pinch of sesame seeds.","ritual":false,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:phantasmal-killer","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Phantasmal Killer","description":"You tap into the nightmares of a creature you can see within range and create an illusory manifestation of its deepest fears, visible only to that creature. The target must make a wisdom saving throw. On a failed save, the target becomes frightened for the duration. At the start of each of the target's turns before the spell ends, the target must succeed on a wisdom saving throw or take 4d10 psychic damage. On a successful save, the spell ends.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d10 for each slot level above 4th."},"it":{"name":"Allucinazione mortale","description":"L'incantatore attinge agli incubi di una creatura entro gittata che è in grado di vedere e crea una manifestazione illusoria delle sue paure più profonde, visibile solo a lei. Il bersaglio deve effettuare un tiro salvezza su Saggezza. Se lo fallisce, diventa spaventato per tutta la durata dell'incantesimo. Al termine di ogni suo turno prima che l'incantesimo finisca, il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti subisce 4d10 danni psichici. In caso di successo, l'incantesimo termina.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 5° livello o superiore, i danni aumentano di 1d10 per ogni slot di livello superiore al 4°.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":4,"school":"srd:rule:school-illusion","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","damage":[{"type":"srd:rule:damage-psychic","atSlotLevel":{"4":"4d10"}}],"savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:phantom-steed","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Phantom Steed","description":"A Large quasi-real, horselike creature appears on the ground in an unoccupied space of your choice within range. You decide the creature's appearance, but it is equipped with a saddle, bit, and bridle. Any of the equipment created by the spell vanishes in a puff of smoke if it is carried more than 10 feet away from the steed.\\n\\nFor the duration, you or a creature you choose can ride the steed. The creature uses the statistics for a riding horse, except it has a speed of 100 feet and can travel 10 miles in an hour, or 13 miles at a fast pace. When the spell ends, the steed gradually fades, giving the rider 1 minute to dismount. The spell ends if you use an action to dismiss it or if the steed takes any damage."},"it":{"name":"Destriero fantomatico","description":"Una creatura di taglia Grande, simile a un cavallo quasi reale, compare sul terreno in uno spazio libero entro gittata a scelta dell'incantatore. L'incantatore può inoltre scegliere l'aspetto della creatura, che deve tuttavia essere dotata di sella, morso e briglie. Qualsiasi equipaggiamento creato dall'incantesimo svanisce in uno sbuffo di fumo se trasportato a più di 3 metri dal destriero.\\n\\nPer la durata dell'incantesimo, l'incantatore o una creatura a sua scelta può cavalcare il destriero, che usa le statistiche di un cavallo da galoppo, ma ha una velocità di 30 metri e può percorrere 15 km in un'ora o 20 km a passo veloce. Al termine dell'incantesimo, la cavalcatura svanisce gradualmente, dando al sua cavaliere 1 minuto per smontare. L'incantesimo termina se l'incantatore usa un'azione per interromperlo o se il destriero subisce danni.","castingTime":"1 minuto","range":"9 metri","duration":"1 ora"}},"data":{"level":3,"school":"srd:rule:school-illusion","classes":["srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 minute","range":"30 feet","components":["V","S"],"ritual":true,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:planar-ally","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Planar Ally","description":"You beseech an otherworldly entity for aid. The being must be known to you: a god, a primordial, a demon prince, or some other being of cosmic power. That entity sends a celestial, an elemental, or a fiend loyal to it to aid you, making the creature appear in an unoccupied space within range. If you know a specific creature's name, you can speak that name when you cast this spell to request that creature, though you might get a different creature anyway (GM's choice).\\n\\nWhen the creature appears, it is under no compulsion to behave in any particular way. You can ask the creature to perform a service in exchange for payment, but it isn't obliged to do so. The requested task could range from simple (fly us across the chasm, or help us fight a battle) to complex (spy on our enemies, or protect us during our foray into the dungeon). You must be able to communicate with the creature to bargain for its services.\\n\\nPayment can take a variety of forms. A celestial might require a sizable donation of gold or magic items to an allied temple, while a fiend might demand a living sacrifice or a gift of treasure. Some creatures might exchange their service for a quest undertaken by you.\\n\\nAs a rule of thumb, a task that can be measured in minutes requires a payment worth 100 gp per minute. A task measured in hours requires 1,000 gp per hour. And a task measured in days (up to 10 days) requires 10,000 gp per day. The GM can adjust these payments based on the circumstances under which you cast the spell. If the task is aligned with the creature's ethos, the payment might be halved or even waived. Nonhazardous tasks typically require only half the suggested payment, while especially dangerous tasks might require a greater gift. Creatures rarely accept tasks that seem suicidal.\\n\\nAfter the creature completes the task, or when the agreed-upon duration of service expires, the creature returns to its home plane after reporting back to you, if appropriate to the task and if possible. If you are unable to agree on a price for the creature's service, the creature immediately returns to its home plane.\\n\\nA creature enlisted to join your group counts as a member of it, receiving a full share of experience points awarded."},"it":{"name":"Alleato planare","description":"L'incantatore chiede aiuto a un'entità ultraterrena che deve essergli nota: un dio, un primordiale, un principe dei demoni o qualche altro essere dotato di poteri cosmici. Quell'entità invia in aiuto un celestiale, un elementale o un immondo a lei fedele, che appare in uno spazio libero entro gittata. Se l'incantatore conosce il nome di una creatura specifica, può pronunciarlo quando lancia l'incantesimo per richiedere il suo intervento, ma potrebbe apparire comunque una creatura diversa (a scelta del GM).\\n\\nQuando la creatura appare, non è obbligata a comportarsi in un modo particolare. L'incantatore può chiederle di svolgere per lui un servizio in cambio di pagamento, ma essa non è costretta ad accettare. Il compito richiesto potrebbe essere qualcosa di semplice (\\"portaci in volo oltre il baratro\\" o \\"aiutaci a combattere una battaglia\\") o di complesso (\\"spia i nostri nemici\\" o \\"proteggici durante la nostra incursione nel dungeon\\"). L'incantatore deve essere in grado di comunicare con la creatura per contrattare per i suoi servigi.\\n\\nIl pagamento può avere varie forme: un celestiale potrebbe richiedere un'ingente donazione in oro o oggetti magici a un tempio alleato, un immondo esigere una creatura vivente in sacrificio o un tesoro in dono. Alcune creature potrebbero scambiare i propri servigi con una missione che l'incantatore deve svolgere.\\n\\nCome regola generale, un compito che può essere misurato in minuti richiede un pagamento del valore di 100 mo al minuto, un compito misurato in ore richiede 1.000 mo all'ora e un compito misurato in giorni (per un massimo di 10 giorni) richiede 10.000 mo al giorno. Il GM può modificare questi pagamenti in base alle circostanze del lancio. Se il compito è in sintonia con l'etica della creatura, il pagamento potrebbe essere dimezzato o addirittura revocato. I compiti non pericolosi richiedono tipicamente solo la metà del pagamento suggerito, mentre quelli particolarmente rischiosi potrebbero richiedere una ricompensa superiore. È raro che una creatura accetti un compito potenzialmente suicida.\\n\\nDopo aver portato a termine il compito o quando la durata pattuita termina, la creatura fa ritorno al suo piano d'origine dopo aver fatto rapporto all'incantatore, se possibile e se l'incarico lo richiede. Se l'incantatore e la creatura non riescono ad accordarsi sul prezzo del suo servizio, quest'ultima ritorna immediatamente sul suo piano d'origine.\\n\\nUna creatura arruolata per unirsi al gruppo dell'incantatore conta come membro di quel gruppo e riceve la sua parte di punti esperienza concessi.","castingTime":"10 minuti","range":"18 metri","duration":"Istantanea"}},"data":{"level":6,"school":"srd:rule:school-conjuration","classes":["srd:class:cleric"],"subclasses":[],"castingTime":"10 minutes","range":"60 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:planar-binding","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Planar Binding","description":"With this spell, you attempt to bind a celestial, an elemental, a fey, or a fiend to your service. The creature must be within range for the entire casting of the spell. (Typically, the creature is first summoned into the center of an inverted magic circle in order to keep it trapped while this spell is cast.) At the completion of the casting, the target must make a charisma saving throw. On a failed save, it is bound to serve you for the duration. If the creature was summoned or created by another spell, that spell's duration is extended to match the duration of this spell.\\n\\nA bound creature must follow your instructions to the best of its ability. You might command the creature to accompany you on an adventure, to guard a location, or to deliver a message. The creature obeys the letter of your instructions, but if the creature is hostile to you, it strives to twist your words to achieve its own objectives. If the creature carries out your instructions completely before the spell ends, it travels to you to report this fact if you are on the same plane of existence. If you are on a different plane of existence, it returns to the place where you bound it and remains there until the spell ends.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of a higher level, the duration increases to 10 days with a 6th-level slot, to 30 days with a 7th-level slot, to 180 days with an 8th-level slot, and to a year and a day with a 9th-level spell slot."},"it":{"name":"Legame planare","description":"Con questo incantesimo, l'incantatore tenta di vincolare un celestiale, un elementale, un folletto o un immondo al suo servizio. La creatura deve trovarsi entro gittata per l'intera durata del lancio dell'incantesimo (solitamente essa viene prima evocata al centro di un cerchio magico invertito per tenerla intrappolata mentre l'incantesimo viene lanciato). Una volta completato il lancio, il bersaglio deve effettuare un tiro salvezza su Carisma. Se lo fallisce, è obbligato a servire l'incantatore per tutta la durata dell'incantesimo. Se la creatura è stata evocata o creata da un altro incantesimo, la durata di quell'incantesimo viene estesa per corrispondere alla durata di questo.\\n\\nUna creatura vincolata deve eseguire le istruzioni al meglio delle sue capacità. L'incantatore potrebbe ordinarle di accompagnarlo in un'avventura, di proteggere un luogo o consegnare un messaggio. La creatura obbedisce alla lettera alle sue istruzioni, ma se è ostile nei confronti dell'incantatore lotterà per interpretare a modo suo le parole di quest'ultimo perseguendo i suoi obiettivi personali. Se la creatura porta a termine le istruzioni dell'incantatore prima del termine dell'incantesimo, si reca da lui per riferirglielo, ma solo se si trovano sullo stesso piano di esistenza. Se l'incantatore si trova su un piano di esistenza diverso, la creatura ritorna nel luogo in cui è stata vincolata e vi rimane fino al termine dell'incantesimo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di un livello superiore, la durata aumenta a 10 giorni con uno slot di 6° livello, a 30 giorni con uno slot di 7° livello, a 180 giorni con uno slot di 8° livello e a un anno e un giorno con uno slot di 9° livello.","castingTime":"1 ora","range":"18 metri","duration":"24 ore","material":"una gemma del valore di almeno 1.000 mo, che l'incantesimo consuma"}},"data":{"level":5,"school":"srd:rule:school-abjuration","classes":["srd:class:bard","srd:class:cleric","srd:class:druid","srd:class:wizard"],"subclasses":[],"castingTime":"1 hour","range":"60 feet","components":["V","S","M"],"material":"A jewel worth at least 1,000 gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"24 hours","savingThrow":{"ability":"cha","onSuccess":"none"}}},{"id":"srd:spell:plane-shift","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Plane Shift","description":"You and up to eight willing creatures who link hands in a circle are transported to a different plane of existence. You can specify a target destination in general terms, such as the City of Brass on the Elemental Plane of Fire or the palace of Dispater on the second level of the Nine Hells, and you appear in or near that destination. If you are trying to reach the City of Brass, for example, you might arrive in its Street of Steel, before its Gate of Ashes, or looking at the city from across the Sea of Fire, at the GM's discretion.\\n\\nAlternatively, if you know the sigil sequence of a teleportation circle on another plane of existence, this spell can take you to that circle. If the teleportation circle is too small to hold all the creatures you transported, they appear in the closest unoccupied spaces next to the circle.\\n\\nYou can use this spell to banish an unwilling creature to another plane. Choose a creature within your reach and make a melee spell attack against it. On a hit, the creature must make a charisma saving throw. If the creature fails this save, it is transported to a random location on the plane of existence you specify. A creature so transported must find its own way back to your current plane of existence."},"it":{"name":"Spostamento planare","description":"L'incantatore e un massimo di otto creature consenzienti, che si tengono per mano formando un cerchio, vengono trasportati su un piano di esistenza diverso. L'incantatore può specificare la destinazione in termini generici, come la Città di Ottone sul Piano Elementale del Fuoco o il palazzo di Dispater sul secondo livello dei Nove Inferi, apparendo in quella destinazione o nelle sue immediate vicinanze. Per esempio, se cerca di raggiungere la Città di Ottone, potrebbe arrivare nella Via dell'Acciaio, davanti alla Porta delle Ceneri, oppure nei pressi della città ma dalla parte opposta del Mare di Fuoco, a discrezione del GM.\\n\\nIn alternativa, se l'incantatore conosce la sequenza di sigilli di un cerchio di teletrasporto su un altro piano di esistenza, questo incantesimo può portarlo fino a quel cerchio. Se il cerchio di teletrasporto è troppo piccolo per contenere tutte le creature trasportate dall'incantatore, esse appariranno negli spazi liberi più vicini.\\n\\nL'incantatore può usare questo incantesimo per esiliare una creatura non consenziente su un altro piano, scegliendo una creatura alla sua portata ed effettuando un attacco con incantesimo in mischia contro di essa. Se il colpo va a segno, la creatura deve effettuare un tiro salvezza su Carisma. Se lo fallisce, viene trasportata in un luogo casuale sul piano di esistenza specificato dall'incantatore e dovrà trovare da sola il modo di tornare sul piano di esistenza in cui si trovava in precedenza.","castingTime":"1 azione","range":"Contatto","duration":"Istantanea","material":"una verga di metallo biforcuta del valore di almeno 250 mo, in sintonia con un particolare piano di esistenza"}},"data":{"level":7,"school":"srd:rule:school-conjuration","classes":["srd:class:cleric","srd:class:druid","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A forked, metal rod worth at least 250 gp, attuned to a particular plane of existence.","ritual":false,"concentration":false,"duration":"Instantaneous","savingThrow":{"ability":"cha","onSuccess":"none"},"attackType":"melee"}},{"id":"srd:spell:plant-growth","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Plant Growth","description":"This spell channels vitality into plants within a specific area. There are two possible uses for the spell, granting either immediate or long-term benefits.\\n\\nIf you cast this spell using 1 action, choose a point within range. All normal plants in a 100-foot radius centered on that point become thick and overgrown. A creature moving through the area must spend 4 feet of movement for every 1 foot it moves.\\n\\nYou can exclude one or more areas of any size within the spell's area from being affected.\\n\\nIf you cast this spell over 8 hours, you enrich the land. All plants in a half-mile radius centered on a point within range become enriched for 1 year. The plants yield twice the normal amount of food when harvested."},"it":{"name":"Crescita vegetale","description":"Questo incantesimo incanala vitalità nei vegetali di un'area specifica. Esistono due possibili usi dell'incantesimo, mirati a fornire benefici immediati o a lungo termine.\\n\\nSe l'incantatore lancia questo incantesimo usando 1 azione, sceglie un punto situato entro gittata: tutti i vegetali normali entro un raggio di 30 metri centrato su quel punto crescono rigogliosamente fino a formare un groviglio. Una creatura che si muove attraverso quell'area deve spendere 1,2 metri di movimento per ogni 30 cm di cui si muove.\\n\\nL'incantatore può escludere dall'influenza dell'incantesimo una o più aree di qualsiasi dimensione all'interno dell'area scelta.\\n\\nSe l'incantatore lancia questo incantesimo nell'arco di 8 ore, rende la terra fertile: tutti i vegetali entro un raggio di 750 metri centrato in un punto entro gittata cresceranno rigogliosamente per 1 anno e al momento del raccolto produrranno il doppio del cibo normale.","castingTime":"1 azione o 8 ore","range":"45 metri","duration":"Istantanea"}},"data":{"level":3,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:druid","srd:class:ranger"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"150 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:poison-spray","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Poison Spray","description":"You extend your hand toward a creature you can see within range and project a puff of noxious gas from your palm. The creature must succeed on a constitution saving throw or take 1d12 poison damage.\\n\\nThis spell's damage increases by 1d12 when you reach 5th level (2d12), 11th level (3d12), and 17th level (4d12)."},"it":{"name":"Spruzzo velenoso","description":"L'incantatore allunga la mano verso una creatura entro gittata che è in grado di vedere e proietta uno sbuffo di gas velenoso dal suo palmo. La creatura deve superare un tiro salvezza su Costituzione, altrimenti subisce 1d12 danni da veleno.\\n\\nI danni dell'incantesimo aumentano di 1d12 quando l'incantatore raggiunge il 5° livello (2d12), l'11° livello (3d12) e il 17° livello (4d12).","castingTime":"1 azione","range":"3 metri","duration":"Istantanea"}},"data":{"level":0,"school":"srd:rule:school-conjuration","classes":["srd:class:sorcerer","srd:class:warlock","srd:class:wizard","srd:class:druid"],"subclasses":[],"castingTime":"1 action","range":"10 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-poison","atCharacterLevel":{"1":"1d12","5":"2d12","11":"3d12","17":"4d12"}}],"savingThrow":{"ability":"con","onSuccess":"none"}}},{"id":"srd:spell:polymorph","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Polymorph","description":"This spell transforms a creature that you can see within range into a new form. An unwilling creature must make a wisdom saving throw to avoid the effect. A shapechanger automatically succeeds on this saving throw.\\n\\nThe transformation lasts for the duration, or until the target drops to 0 hit points or dies. The new form can be any beast whose challenge rating is equal to or less than the target's (or the target's level, if it doesn't have a challenge rating). The target's game statistics, including mental ability scores, are replaced by the statistics of the chosen beast. It retains its alignment and personality.\\n\\nThe target assumes the hit points of its new form. When it reverts to its normal form, the creature returns to the number of hit points it had before it transformed. If it reverts as a result of dropping to 0 hit points, any excess damage carries over to its normal form. As long as the excess damage doesn't reduce the creature's normal form to 0 hit points, it isn't knocked unconscious.\\n\\nThe creature is limited in the actions it can perform by the nature of its new form, and it can't speak, cast spells, or take any other action that requires hands or speech.\\n\\nThe target's gear melds into the new form. The creature can't activate, use, wield, or otherwise benefit from any of its equipment."},"it":{"name":"Metamorfosi","description":"Questo incantesimo conferisce una nuova forma a una creatura entro gittata che l'incantatore è in grado di vedere. Per evitarne l'effetto, una creatura non consenziente deve effettuare un tiro salvezza su Saggezza. L'incantesimo non ha effetto su un mutaforma o una creatura con 0 punti ferita.\\n\\nLa trasformazione permane per la durata dell'incantesimo o finché il bersaglio non scende a 0 punti ferita o muore. La nuova forma può essere quella di qualsiasi bestia il cui grado di sfida sia pari o inferiore a quello del bersaglio (o al livello del bersaglio, se esso non possiede un grado di sfida). Le statistiche di gioco del bersaglio, inclusi i punteggi di caratteristica mentali, vengono sostituite dalle statistiche della bestia scelta, ma mantiene il suo allineamento e la sua personalità.\\n\\nIl bersaglio assume i punti ferita della nuova forma e, quando riassume la sua forma normale, ritorna al numero di punti ferita che aveva prima della trasformazione. Se torna alla sua forma normale per essere sceso a 0 punti ferita, gli eventuali danni in eccesso si trasmettono alla sua forma normale. Fintantoché i danni in eccesso non riducono la forma normale della creatura a 0 punti ferita, questa non cade priva di sensi.\\n\\nLa creatura è limitata alle azioni che può effettuare in base alla natura della sua nuova forma e non può parlare, lanciare incantesimi o effettuare qualsiasi altra azione che richieda l'uso delle mani o della parola.\\n\\nL'attrezzatura del bersaglio si fonde nella sua nuova forma e la creatura non può attivare, usare, impugnare o beneficiare del proprio equipaggiamento.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 ora","material":"il bozzolo di un bruco"}},"data":{"level":4,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:druid","srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"A caterpillar cocoon.","ritual":false,"concentration":true,"duration":"Up to 1 hour","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:power-word-kill","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Power Word Kill","description":"You utter a word of power that can compel one creature you can see within range to die instantly. If the creature you choose has 100 hit points or fewer, it dies. Otherwise, the spell has no effect."},"it":{"name":"Parola del potere uccidere","description":"L'incantatore pronuncia una parola del potere che può uccidere istantaneamente una creatura entro gittata che è in grado di vedere. Se la creatura scelta possiede 100 punti ferita o meno, muore. Altrimenti, l'incantesimo non sortisce alcun effetto.","castingTime":"1 azione","range":"18 metri","duration":"Istantanea"}},"data":{"level":9,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:power-word-stun","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Power Word Stun","description":"You speak a word of power that can overwhelm the mind of one creature you can see within range, leaving it dumbfounded. If the target has 150 hit points or fewer, it is stunned. Otherwise, the spell has no effect.\\n\\nThe stunned target must make a constitution saving throw at the end of each of its turns. On a successful save, this stunning effect ends."},"it":{"name":"Parola del potere stordire","description":"L'incantatore pronuncia una parola del potere che può sopraffare la mente di una creatura entro gittata che è in grado di vedere, lasciandola in uno stato confusionale. Se il bersaglio possiede 150 punti ferita o meno, è stordito. Altrimenti, l'incantesimo non sortisce alcun effetto.\\n\\nIl bersaglio stordito deve effettuare un tiro salvezza su Costituzione alla fine di ogni suo turno. In caso di successo, l'effetto di stordimento termina.","castingTime":"1 azione","range":"18 metri","duration":"Istantanea"}},"data":{"level":8,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:prayer-of-healing","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Prayer of Healing","description":"Up to six creatures of your choice that you can see within range each regain hit points equal to 2d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, the healing increases by 1d8 for each slot level above 2nd."},"it":{"name":"Preghiera di guarigione","description":"Fino a sei creature scelte dall'incantatore, entro gittata e che è in grado di vedere, recuperano un ammontare di punti ferita pari a 2d8 + il modificatore di caratteristica da incantatore. Questo incantesimo non ha effetto sui non morti o sui costrutti.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, la guarigione aumenta di 1d8 per ogni slot di livello superiore al 2°.","castingTime":"10 minuti","range":"9 metri","duration":"Istantanea"}},"data":{"level":2,"school":"srd:rule:school-evocation","classes":["srd:class:cleric"],"subclasses":["srd:subclass:lore"],"castingTime":"10 minutes","range":"30 feet","components":["V"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:prestidigitation","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Prestidigitation","description":"This spell is a minor magical trick that novice spellcasters use for practice. You create one of the following magical effects within 'range':\\n\\nYou create an instantaneous, harmless sensory effect, such as a shower of sparks, a puff of wind, faint musical notes, or an odd odor.\\n\\nYou instantaneously light or snuff out a candle, a torch, or a small campfire.\\n\\nYou instantaneously clean or soil an object no larger than 1 cubic foot.\\n\\nYou chill, warm, or flavor up to 1 cubic foot of nonliving material for 1 hour.\\n\\nYou make a color, a small mark, or a symbol appear on an object or a surface for 1 hour.\\n\\nYou create a nonmagical trinket or an illusory image that can fit in your hand and that lasts until the end of your next turn.\\n\\nIf you cast this spell multiple times, you can have up to three of its non-instantaneous effects active at a time, and you can dismiss such an effect as an action."},"it":{"name":"Prestidigitazione","description":"Questo incantesimo è un trucco magico che gli incantatori novizi usano per fare pratica. Crei uno degli effetti magici seguenti entro gittata:\\n\\n- Crea un effetto sensoriale innocuo e istantaneo, come una pioggia di scintille, una folata di vento, una tenue melodia musicale o uno strano odore.\\n\\n- Accendi o spegni istantaneamente una candela, una torcia o un piccolo fuoco da campo.\\n\\n- Pulisci o sporca istantaneamente un oggetto non più grande di un cubo con spigolo di 30 cm.\\n\\n- Riscalda, raffredda o condisci materiale non vivente del volume massimo di un cubo con spigolo di 30 cm per 1 ora.\\n\\n- Fai comparire un colore, un piccolo segno o un simbolo su un oggetto o una superficie per 1 ora.\\n\\n- Crea un ninnolo non magico o un'immagine illusoria che può stare nel palmo della tua mano e che permane fino alla fine del tuo turno successivo.\\n\\nSe l'incantatore lancia questo incantesimo più volte, può tenere attivi fino a tre dei suoi effetti non istantanei contemporaneamente e può eliminare ognuno di questi effetti con un'azione.","castingTime":"1 azione","range":"3 metri","duration":"Fino a 1 ora"}},"data":{"level":0,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"10 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:prismatic-spray","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Prismatic Spray","description":"Eight multicolored rays of light flash from your hand. Each ray is a different color and has a different power and purpose. Each creature in a 60-foot cone must make a dexterity saving throw. For each target, roll a d8 to determine which color ray affects it.\\n\\n***1. Red.*** The target takes 10d6 fire damage on a failed save, or half as much damage on a successful one.\\n\\n***2. Orange.*** The target takes 10d6 acid damage on a failed save, or half as much damage on a successful one.\\n\\n***3. Yellow.*** The target takes 10d6 lightning damage on a failed save, or half as much damage on a successful one.\\n\\n***4. Green.*** The target takes 10d6 poison damage on a failed save, or half as much damage on a successful one.\\n\\n***5. Blue.*** The target takes 10d6 cold damage on a failed save, or half as much damage on a successful one.\\n\\n***6. Indigo.*** On a failed save, the target is restrained. It must then make a constitution saving throw at the end of each of its turns. If it successfully saves three times, the spell ends. If it fails its save three times, it permanently turns to stone and is subjected to the petrified condition. The successes and failures don't need to be consecutive; keep track of both until the target collects three of a kind.\\n\\n***7. Violet.*** On a failed save, the target is blinded. It must then make a wisdom saving throw at the start of your next turn. A successful save ends the blindness. If it fails that save, the creature is transported to another plane of existence of the GM's choosing and is no longer blinded. (Typically, a creature that is on a plane that isn't its home plane is banished home, while other creatures are usually cast into the Astral or Ethereal planes.)\\n\\n***8. Special.*** The target is struck by two rays. Roll twice more, rerolling any 8."},"it":{"name":"Spruzzo prismatico","description":"Otto raggi di luce multicolore si sprigionano dalla mano dell'incantatore. Ognuno di essi è di un colore diverso e ha un potere e una funzione differente. Ogni creatura situata in un cono di 18 metri deve effettuare un tiro salvezza su Destrezza. Per ogni bersaglio, si tira un d8 per determinare da quale raggio colorato viene influenzato.\\n\\n***1. Rosso.*** Il bersaglio subisce 10d6 danni da fuoco in caso di fallimento, o la metà dei danni in caso di successo.\\n\\n***2. Arancione.*** Il bersaglio subisce 10d6 danni da acido in caso di fallimento, o la metà dei danni in caso di successo.\\n\\n***3. Giallo.*** Il bersaglio subisce 10d6 danni da fulmine in caso di fallimento, o la metà dei danni in caso di successo.\\n\\n***4. Verde.*** Il bersaglio subisce 10d6 danni da veleno in caso di fallimento, o la metà dei danni in caso di successo.\\n\\n***5. Blu.*** Il bersaglio subisce 10d6 danni da freddo in caso di fallimento, o la metà dei danni in caso di successo.\\n\\n***6. Indaco.*** Se fallisce il tiro salvezza, il bersaglio è trattenuto e deve effettuare un tiro salvezza su Costituzione alla fine di ogni suo turno. Se lo supera per tre volte, l'incantesimo termina, mentre se lo fallisce per tre volte, viene tramutato in pietra permanentemente ed è soggetto alla condizione pietrificato. Non è necessario che i tiri superati o falliti siano consecutivi: si tiene semplicemente il conto di entrambi finché il bersaglio non ne accumula tre di un certo tipo.\\n\\n***7. Viola.*** Se fallisce il tiro salvezza, il bersaglio è accecato e deve effettuare un tiro salvezza su Saggezza all'inizio del turno successivo dell'incantatore. Se lo supera, non è più accecato, mentre se lo fallisce, viene trasportato su un altro piano di esistenza a scelta del GM e non è più accecato. (Solitamente, una creatura che si trova su un piano diverso da quello di origine viene esiliata sul suo piano di origine, mentre le altre creature vengono inviate sul Piano Astrale o sul Piano Etereo.)\\n\\n***8. Speciale.*** Il bersaglio viene colpito da due raggi. Si tira altre due volte, ignorando i risultati di 8.","castingTime":"1 azione","range":"Incantatore (cono di 18 metri)","duration":"Istantanea"}},"data":{"level":7,"school":"srd:rule:school-evocation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"atSlotLevel":{"7":"10d6"}}],"savingThrow":{"ability":"dex","onSuccess":"other"},"area":{"type":"cone","size":60}}},{"id":"srd:spell:prismatic-wall","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Prismatic Wall","description":"A shimmering, multicolored plane of light forms a vertical opaque wall--up to 90 feet long, 30 feet high, and 1 inch thick--centered on a point you can see within range. Alternatively, you can shape the wall into a sphere up to 30 feet in diameter centered on a point you choose within range. The wall remains in place for the duration. If you position the wall so that it passes through a space occupied by a creature, the spell fails, and your action and the spell slot are wasted.\\n\\nThe wall sheds bright light out to a range of 100 feet and dim light for an additional 100 feet. You and creatures you designate at the time you cast the spell can pass through and remain near the wall without harm. If another creature that can see the wall moves to within 20 feet of it or starts its turn there, the creature must succeed on a constitution saving throw or become blinded for 1 minute.\\n\\nThe wall consists of seven layers, each with a different color. When a creature attempts to reach into or pass through the wall, it does so one layer at a time through all the wall's layers. As it passes or reaches through each layer, the creature must make a dexterity saving throw or be affected by that layer's properties as described below.\\n\\nThe wall can be destroyed, also one layer at a time, in order from red to violet, by means specific to each layer. Once a layer is destroyed, it remains so for the duration of the spell. A rod of cancellation destroys a prismatic wall, but an antimagic field has no effect on it.\\n\\n***1. Red.*** The creature takes 10d6 fire damage on a failed save, or half as much damage on a successful one. While this layer is in place, nonmagical ranged attacks can't pass through the wall. The layer can be destroyed by dealing at least 25 cold damage to it.\\n\\n***2. Orange.*** The creature takes 10d6 acid damage on a failed save, or half as much damage on a successful one. While this layer is in place, magical ranged attacks can't pass through the wall. The layer is destroyed by a strong wind.\\n\\n***3. Yellow.*** The creature takes 10d6 lightning damage on a failed save, or half as much damage on a successful one. This layer can be destroyed by dealing at least 60 force damage to it.\\n\\n***4. Green.*** The creature takes 10d6 poison damage on a failed save, or half as much damage on a successful one. A passwall spell, or another spell of equal or greater level that can open a portal on a solid surface, destroys this layer.\\n\\n***5. Blue.*** The creature takes 10d6 cold damage on a failed save, or half as much damage on a successful one. This layer can be destroyed by dealing at least 25 fire damage to it.\\n\\n***6. Indigo.*** On a failed save, the creature is restrained. It must then make a constitution saving throw at the end of each of its turns. If it successfully saves three times, the spell ends. If it fails its save three times, it permanently turns to stone and is subjected to the petrified condition. The successes and failures don't need to be consecutive; keep track of both until the creature collects three of a kind.\\n\\nWhile this layer is in place, spells can't be cast through the wall. The layer is destroyed by bright light shed by a daylight spell or a similar spell of equal or higher level.\\n\\n***7. Violet.*** On a failed save, the creature is blinded. It must then make a wisdom saving throw at the start of your next turn. A successful save ends the blindness. If it fails that save, the creature is transported to another plane of the GM's choosing and is no longer blinded. (Typically, a creature that is on a plane that isn't its home plane is banished home, while other creatures are usually cast into the Astral or Ethereal planes.) This layer is destroyed by a dispel magic spell or a similar spell of equal or higher level that can end spells and magical effects."},"it":{"name":"Muro prismatico","description":"Un piano scintillante di luce multicolore forma un muro opaco verticale (che può misurare fino a 27 metri di lunghezza, 9 metri di altezza e 2,5 cm di spessore), centrato su un punto entro gittata che l'incantatore è in grado di vedere. In alternativa, l'incantatore può modellare il muro in una sfera del diametro massimo di 9 metri centrata su un punto a sua scelta entro gittata. Il muro rimane in quella posizione per la durata dell'incantesimo. Se l'incantatore posiziona il muro in modo che passi attraverso uno spazio occupato da una creatura, l'incantesimo fallisce e sia l'azione dell'incantatore che lo slot incantesimo vengono sprecati.\\n\\nIl muro emana luce intensa in un raggio di 30 metri e luce fioca per ulteriori 30 metri. L'incantatore e le creature da lui scelte al momento del lancio dell'incantesimo possono passare attraverso il muro o rimanervi accanto senza subire danni. Se un'altra creatura in grado di vedere il muro giunge entro 6 metri da esso o comincia lì il proprio turno, deve superare un tiro salvezza su Costituzione, altrimenti è accecata per 1 minuto.\\n\\nIl muro è composto da sette strati, ognuno di un colore diverso. Quando una creatura cerca di protendersi oltre il muro o passarvi attraverso, lo fa attraversando uno strato alla volta. Quando questo accade, deve superare un tiro salvezza su Destrezza, altrimenti sarà influenzata dalle proprietà di quello strato, come descritto in seguito.\\n\\nIl muro può essere distrutto, anche in questo caso uno strato alla volta e in ordine dal rosso al viola, in un modo specifico per ogni strato. Quando uno strato viene distrutto, rimane in questo stato per la durata dell'incantesimo. Una verga della cancellazione distrugge un muro prismatico, ma un campo anti-magia non ha alcun effetto su di esso.\\n\\n***1. Rosso.*** La creatura subisce 10d6 danni da fuoco se fallisce il tiro salvezza, o la metà dei danni in caso di successo. Finché questo strato rimane al suo posto, gli attacchi non magici a distanza non possono attraversare il muro. Questo strato può essere distrutto se subisce almeno 25 danni da freddo.\\n\\n***2. Arancione.*** La creatura subisce 10d6 danni da acido se fallisce il tiro salvezza, o la metà dei danni in caso di successo. Finché questo strato rimane al suo posto, gli attacchi magici a distanza non possono attraversare il muro. Questo strato può essere distrutto da un vento forte.\\n\\n***3. Giallo.*** La creatura subisce 10d6 danni da fulmine se fallisce il tiro salvezza, o la metà dei danni in caso di successo. Questo strato può essere distrutto se subisce almeno 60 danni da forza.\\n\\n***4. Verde.*** La creatura subisce 10d6 danni da veleno se fallisce il tiro salvezza, o la metà dei danni in caso di successo. Un incantesimo passapareti o un altro incantesimo di livello pari o superiore è in grado di aprire un portale su una superficie solida, distruggendo questo strato.\\n\\n***5. Blu.*** La creatura subisce 10d6 danni da freddo se fallisce il tiro salvezza, o la metà dei danni in caso di successo. Questo strato può essere distrutto se subisce almeno 25 danni da fuoco.\\n\\n***6. Indaco.*** Se fallisce il tiro salvezza, la creatura è trattenuta e deve effettuare un tiro salvezza su Costituzione alla fine di ogni suo turno. Se lo supera per tre volte, l'incantesimo termina, mentre se lo fallisce per tre volte, viene tramutato in pietra permanentemente ed è soggetto alla condizione pietrificato. Non è necessario che i tiri superati o falliti siano consecutivi: si tiene semplicemente il conto di entrambi finché la creatura non ne accumula tre di un certo tipo.\\n\\nFinché questo strato rimane al suo posto, non è possibile lanciare incantesimi attraverso il muro. Questo strato può essere distrutto da una luce intensa emanata da un incantesimo luce diurna o da un incantesimo analogo di livello pari o superiore.\\n\\n***7. Viola.*** Se fallisce il tiro salvezza, la creatura è accecata e deve effettuare un tiro salvezza su Saggezza all'inizio del turno successivo dell'incantatore. Se lo supera, non è più accecata, mentre se lo fallisce, viene trasportata su un altro piano a scelta del GM e non è più accecata. (Solitamente, una creatura che si trova su un piano diverso da quello di origine viene esiliata sul suo piano di origine, mentre le altre creature vengono inviate sul Piano Astrale o sul Piano Etereo.) Questo strato viene distrutto da un incantesimo dissolvi magie o da un incantesimo analogo di livello pari o superiore che sia in grado di porre termine agli incantesimi e agli effetti magici.","castingTime":"1 azione","range":"18 metri","duration":"10 minuti"}},"data":{"level":9,"school":"srd:rule:school-abjuration","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"10 minutes","area":{"type":"line","size":90}}},{"id":"srd:spell:private-sanctum","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Private Sanctum","description":"You make an area within range magically secure. The area is a cube that can be as small as 5 feet to as large as 100 feet on each side. The spell lasts for the duration or until you use an action to dismiss it.\\n\\nWhen you cast the spell, you decide what sort of security the spell provides, choosing any or all of the following properties:\\n\\n- Sound can't pass through the barrier at the edge of the warded area.\\n\\n- The barrier of the warded area appears dark and foggy, preventing vision (including darkvision) through it.\\n\\n- Sensors created by divination spells can't appear inside the protected area or pass through the barrier at its perimeter.\\n\\n- Creatures in the area can't be targeted by divination spells.\\n\\n- Nothing can teleport into or out of the warded area.\\n\\n- Planar travel is blocked within the warded area.\\n\\nCasting this spell on the same spot every day for a year makes this effect permanent.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 5th level or higher, you can increase the size of the cube by 100 feet for each slot level beyond 4th. Thus you could protect a cube that can be up to 200 feet on one side by using a spell slot of 5th level."},"it":{"name":"Santuario privato","description":"L'incantatore rende magicamente sicura un'area entro gittata: un cubo le cui dimensioni possono variare da un minimo di 1,5 metri a un massimo di 30 metri. L'incantesimo permane per tutta la sua durata o finché l'incantatore non usa un'azione per interromperlo.\\n\\nQuando lancia l'incantesimo, l'incantatore decide che tipo di sicurezza esso fornisce, scegliendo una o più tra le proprietà seguenti:\\n\\n- I suoni non possono attraversare la barriera ai confini dell'area protetta.\\n\\n- La barriera nell'area protetta appare oscura e nebulosa, rendendo impossibile vedere oltre (anche utilizzando scurovisione).\\n\\n- I sensori creati dagli incantesimi di divinazione non possono apparire all'interno dell'area protetta né oltrepassarne il perimetro.\\n\\n- Le creature nell'area non possono essere bersaglio di incantesimi di divinazione.\\n\\n- Nulla può teletrasportarsi dentro o fuori dall'area protetta.\\n\\n- I viaggi planari sono bloccati all'interno dell'area protetta.\\n\\nLanciare questo incantesimo nello stesso punto per un anno rende l'effetto permanente.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 5° livello o superiore, può aumentare la dimensione del cubo di 30 metri per ogni slot di livello superiore al 4°. Quindi è possibile proteggere un cubo con lato lungo fino a 60 metri usando uno slot incantesimo di 5° livello.","castingTime":"10 minuti","range":"36 metri","duration":"24 ore","material":"una sottile lamina di piombo, un frammento di vetro opaco, un pezzo di cotone o stoffa e polvere di crisolito"}},"data":{"level":4,"school":"srd:rule:school-abjuration","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"10 minutes","range":"120 feet","components":["V","S","M"],"material":"A thin sheet of lead, a piece of opaque glass, a wad of cotton or cloth, and powdered chrysolite.","ritual":false,"concentration":false,"duration":"24 hours","area":{"type":"cube","size":100}}},{"id":"srd:spell:produce-flame","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Produce Flame","description":"A flickering flame appears in your hand. The flame remains there for the duration and harms neither you nor your equipment. The flame sheds bright light in a 10-foot radius and dim light for an additional 10 feet. The spell ends if you dismiss it as an action or if you cast it again.\\n\\nYou can also attack with the flame, although doing so ends the spell. When you cast this spell, or as an action on a later turn, you can hurl the flame at a creature within 30 feet of you. Make a ranged spell attack. On a hit, the target takes 1d8 fire damage.\\n\\nThis spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."},"it":{"name":"Produrre fiamma","description":"Nella mano dell'incantatore appare una fiamma tremolante che permane per la durata dell'incantesimo e non infligge danni né all'incantatore né al suo equipaggiamento. La fiamma emana luce intensa in un raggio di 3 metri e luce fioca per ulteriori 3 metri. L'incantesimo termina se l'incantatore lo interrompe con un'azione o se lo lancia di nuovo.\\n\\nL'incantatore può anche attaccare con la fiamma, ponendo tuttavia fine all'incantesimo. Quando lancia questo incantesimo o con un'azione in un turno successivo, l'incantatore può scagliare la fiamma contro una creatura situata entro 9 metri da lui, effettuando un attacco a distanza con incantesimo. Se il colpo va a segno, il bersaglio subisce 1d8 danni da fuoco.\\n\\nI danni di questo incantesimo aumentano di 1d8 quando l'incantatore raggiunge il 5° livello (2d8), l'11° livello (3d8) e il 17° livello (4d8).","castingTime":"1 azione","range":"Incantatore","duration":"10 minuti"}},"data":{"level":0,"school":"srd:rule:school-conjuration","classes":["srd:class:druid"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":false,"concentration":false,"duration":"10 minutes","damage":[{"type":"srd:rule:damage-fire","atCharacterLevel":{"1":"1d8","5":"2d8","11":"3d8","17":"4d8"}}],"attackType":"ranged"}},{"id":"srd:spell:programmed-illusion","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Programmed Illusion","description":"You create an illusion of an object, a creature, or some other visible phenomenon within range that activates when a specific condition occurs. The illusion is imperceptible until then. It must be no larger than a 30-foot cube, and you decide when you cast the spell how the illusion behaves and what sounds it makes. This scripted performance can last up to 5 minutes.\\n\\nWhen the condition you specify occurs, the illusion springs into existence and performs in the manner you described. Once the illusion finishes performing, it disappears and remains dormant for 10 minutes. After this time, the illusion can be activated again.\\n\\nThe triggering condition can be as general or as detailed as you like, though it must be based on visual or audible conditions that occur within 30 feet of the area. For example, you could create an illusion of yourself to appear and warn off others who attempt to open a trapped door, or you could set the illusion to trigger only when a creature says the correct word or phrase.\\n\\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and any noise it makes sounds hollow to the creature."},"it":{"name":"Illusione programmata","description":"L'incantatore crea un'illusione di un oggetto, una creatura o qualche altro fenomeno visibile entro gittata che si attiva al verificarsi di una condizione specifica. Fino ad allora, l'illusione è impercettibile. Inoltre, essa non può essere più grande di un cubo di 9 metri ed è l'incantatore al momento del lancio a decidere come si comporta e quali suoni emette. Questa esibizione programmata può durare un massimo di 5 minuti.\\n\\nQuando la condizione specificata si verifica, l'illusione si materializza e si comporta nella maniera descritta dall'incantatore. Al termine della sua esibizione, l'illusione scompare e rimane latente per 10 minuti. Dopo questo periodo, l'illusione può essere attivata di nuovo.\\n\\nLa condizione di innesco può essere sia generale che dettagliata, ma deve essere basata su condizioni visibili o udibili che si verificano entro 9 metri dall'area. Per esempio, l'incantatore potrebbe creare un'illusione di se stesso per avvertire coloro che tentano di aprire una porta protetta da una trappola o potrebbe programmare l'illusione per innescarsi solo quando una creatura recita la parola o la frase giusta.\\n\\nL'illusione può essere rivelata da un'interazione fisica, perché è possibile passarle attraverso. Una creatura che usa la sua azione per esaminare l'immagine può determinare che si tratta di un'illusione superando una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo. Se una creatura riconosce l'illusione per ciò che è, riesce a vedere attraverso l'immagine e gli eventuali suoni che emette si attenuano alle sue orecchie.","castingTime":"1 azione","range":"36 metri","duration":"Finché non viene dissolto","material":"un ciuffo di lana e polvere di giada del valore di almeno 25 mo"}},"data":{"level":6,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","components":["V","S","M"],"material":"A bit of fleece and jade dust worth at least 25 gp.","ritual":false,"concentration":false,"duration":"Until dispelled","area":{"type":"cube","size":30}}},{"id":"srd:spell:project-image","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Project Image","description":"You create an illusory copy of yourself that lasts for the duration. The copy can appear at any location within range that you have seen before, regardless of intervening obstacles. The illusion looks and sounds like you but is intangible. If the illusion takes any damage, it disappears, and the spell ends.\\n\\nYou can use your action to move this illusion up to twice your speed, and make it gesture, speak, and behave in whatever way you choose. It mimics your mannerisms perfectly.\\n\\nYou can see through its eyes and hear through its ears as if you were in its space. On your turn as a bonus action, you can switch from using its senses to using your own, or back again. While you are using its senses, you are blinded and deafened in regard to your own surroundings.\\n\\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and any noise it makes sounds hollow to the creature."},"it":{"name":"Immagine proiettata","description":"L'incantatore crea una copia illusoria di se stesso che permane per la durata dell'incantesimo. La copia può apparire in qualsiasi luogo entro gittata che l'incantatore abbia visto in precedenza, a prescindere dalla presenza di ostacoli. L'illusione assomiglia in tutto e per tutto all'incantatore, ma è intangibile. Inoltre, se subisce danni, scompare e l'incantesimo termina.\\n\\nL'incantatore può usare la sua azione per muovere questa illusione fino al doppio della sua velocità e farla gesticolare, parlare e comportare nel modo che ritiene più opportuno. L'illusione imita i modi di fare dell'incantatore alla perfezione.\\n\\nL'incantatore può vedere e sentire attraverso l'illusione, come se si trovasse nel suo spazio. Nel suo turno come azione bonus, l'incantatore può passare dall'uso dei propri sensi a quelli dell'illusione e viceversa. Mentre utilizza i sensi del sosia, non può vedere né sentire nulla di ciò che circonda il suo vero corpo.\\n\\nL'illusione può essere rivelata da un'interazione fisica, perché è possibile passarle attraverso. Una creatura che usa la sua azione per esaminare l'immagine può determinare che si tratta di un'illusione superando una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo. Se una creatura riconosce l'illusione per ciò che è, riesce a vedere attraverso l'immagine e gli eventuali suoni che emette si attenuano alle sue orecchie.","castingTime":"1 azione","range":"750 km","duration":"Concentrazione, fino a 1 giorno","material":"una piccola replica dell'incantatore realizzata con materiali del valore di almeno 5 mo"}},"data":{"level":7,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"500 miles","components":["V","S","M"],"material":"A small replica of you made from materials worth at least 5 gp.","ritual":false,"concentration":true,"duration":"Up to 24 hours"}},{"id":"srd:spell:protection-from-energy","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Protection From Energy","description":"For the duration, the willing creature you touch has resistance to one damage type of your choice: acid, cold, fire, lightning, or thunder."},"it":{"name":"Protezione dall'energia","description":"Per la durata dell'incantesimo, una creatura consenziente toccata dall'incantatore dispone di resistenza a un tipo di danni a scelta di quest'ultimo: acido, freddo, fulmine, fuoco o tuono.","castingTime":"1 azione","range":"Contatto","duration":"Concentrazione, fino a 1 ora"}},"data":{"level":3,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric","srd:class:druid","srd:class:ranger","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:protection-from-evil-and-good","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Protection from Evil and Good","description":"Until the spell ends, one willing creature you touch is protected against certain types of creatures: aberrations, celestials, elementals, fey, fiends, and undead.\\n\\nThe protection grants several benefits. Creatures of those types have disadvantage on attack rolls against the target. The target also can't be charmed, frightened, or possessed by them. If the target is already charmed, frightened, or possessed by such a creature, the target has advantage on any new saving throw against the relevant effect."},"it":{"name":"Protezione dal bene e dal male","description":"Fino al termine dell'incantesimo, una creatura consenziente toccata è protetta contro i seguenti tipi di creature: aberrazioni, celestiali, elementali, folletti, immondi e non morti.\\n\\nLa protezione garantisce diversi vantaggi. Le creature contro cui è attiva subiscono svantaggio ai tiri per colpire indirizzati contro il bersaglio; inoltre, il bersaglio non può essere affascinato, spaventato o posseduto da creature analoghe. Se il bersaglio è già affascinato, spaventato o posseduto da una tale creatura, possiede vantaggio a qualsiasi nuovo tiro salvezza contro il relativo effetto.","castingTime":"1 azione","range":"Contatto","duration":"Concentrazione, fino a 10 minuti","material":"acqua santa o polvere d'argento e ferro, che l'incantesimo consuma"}},"data":{"level":1,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric","srd:class:paladin","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:devotion"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"Holy water or powdered silver and iron, which the spell consumes.","ritual":false,"concentration":true,"duration":"Up to 10 minutes"}},{"id":"srd:spell:protection-from-poison","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Protection from Poison","description":"You touch a creature. If it is poisoned, you neutralize the poison. If more than one poison afflicts the target, you neutralize one poison that you know is present, or you neutralize one at random.\\n\\nFor the duration, the target has advantage on saving throws against being poisoned, and it has resistance to poison damage."},"it":{"name":"Protezione dai veleni","description":"L'incantatore tocca una creatura, neutralizzandone il veleno nel caso fosse avvelenata. Se il bersaglio è afflitto da più veleni, l'incantatore neutralizza un veleno di cui conosce la presenza o ne neutralizza uno casuale.\\n\\nPer la durata dell'incantesimo, il bersaglio dispone di vantaggio ai tiri salvezza per non essere avvelenato e di resistenza ai danni da veleno.","castingTime":"1 azione","range":"Contatto","duration":"1 ora"}},"data":{"level":2,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric","srd:class:druid","srd:class:paladin","srd:class:ranger"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":false,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:purify-food-and-drink","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Purify Food and Drink","description":"All nonmagical food and drink within a 5-foot radius sphere centered on a point of your choice within range is purified and rendered free of poison and disease."},"it":{"name":"Purificare cibo e bevande","description":"Tutti i cibi e le bevande non magiche all'interno di una sfera del raggio di 1,5 metri, centrata su un punto a scelta dell'incantatore ed entro gittata, vengono purificati e liberati dai veleni e dalle malattie.","castingTime":"1 azione","range":"3 metri","duration":"Istantanea"}},"data":{"level":1,"school":"srd:rule:school-transmutation","classes":["srd:class:cleric","srd:class:druid","srd:class:paladin"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"10 feet","components":["V","S"],"ritual":true,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:raise-dead","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Raise Dead","description":"You return a dead creature you touch to life, provided that it has been dead no longer than 10 days. If the creature's soul is both willing and at liberty to rejoin the body, the creature returns to life with 1 hit point.\\n\\nThis spell also neutralizes any poisons and cures nonmagical diseases that affected the creature at the time it died. This spell doesn't, however, remove magical diseases, curses, or similar effects; if these aren't first removed prior to casting the spell, they take effect when the creature returns to life. The spell can't return an undead creature to life.\\n\\nThis spell closes all mortal wounds, but it doesn't restore missing body parts. If the creature is lacking body parts or organs integral for its survival--its head, for instance--the spell automatically fails.\\n\\nComing back from the dead is an ordeal. The target takes a -4 penalty to all attack rolls, saving throws, and ability checks. Every time the target finishes a long rest, the penalty is reduced by 1 until it disappears."},"it":{"name":"Rianimare morti","description":"L'incantatore riporta in vita con il suo tocco una creatura morta da meno di 10 giorni. Se la sua anima è consenziente e libera di riunirsi al corpo, la creatura torna in vita con 1 punto ferita.\\n\\nQuesto incantesimo inoltre neutralizza qualsiasi veleno e cura le malattie non magiche che influenzavano la creatura al momento della morte. Tuttavia, non rimuove malattie magiche, maledizioni o effetti simili che, se non vengono rimossi prima del lancio, affliggeranno il bersaglio una volta tornato in vita. Questo incantesimo non può riportare in vita una creatura non morta.\\n\\nL'incantesimo richiude tutte le ferite mortali, ma non ripristina le parti del corpo mancanti. Se una creatura è priva di organi o parti del corpo essenziali per la sua sopravvivenza, come per esempio la testa, l'incantesimo fallisce automaticamente.\\n\\nIl ritorno dalla morte è un vero e proprio travaglio. Il bersaglio subisce una penalità di -4 a tutti i tiri per colpire, tiri salvezza e prove di caratteristica. Ogni volta che completa un riposo lungo, questa penalità viene ridotta di 1 finché non sparisce del tutto.","castingTime":"1 ora","range":"Contatto","duration":"Istantanea","material":"un diamante del valore di almeno 500 mo, che l'incantesimo consuma"}},"data":{"level":5,"school":"srd:rule:school-necromancy","classes":["srd:class:bard","srd:class:cleric","srd:class:paladin"],"subclasses":["srd:subclass:life"],"castingTime":"1 hour","range":"Touch","components":["V","S","M"],"material":"A diamond worth at least 500gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:ray-of-enfeeblement","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Ray of Enfeeblement","description":"A black beam of enervating energy springs from your finger toward a creature within range. Make a ranged spell attack against the target. On a hit, the target deals only half damage with weapon attacks that use Strength until the spell ends.\\n\\nAt the end of each of the target's turns, it can make a constitution saving throw against the spell. On a success, the spell ends."},"it":{"name":"Raggio di affaticamento","description":"Un raggio nero di energia logorante scaturisce dal dito dell'incantatore puntato contro una creatura entro gittata. Con questo incantesimo, l'incantatore effettua un attacco a distanza contro il bersaglio. Se il colpo va a segno, fino al termine dell'incantesimo il bersaglio infligge solo la metà dei danni con attacchi con armi che usano Forza.\\n\\nAlla fine di ogni suo turno, il bersaglio può effettuare un tiro salvezza su Costituzione contro l'incantesimo. In caso di successo, l'incantesimo termina.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":2,"school":"srd:rule:school-necromancy","classes":["srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"con","onSuccess":"none"},"attackType":"ranged"}},{"id":"srd:spell:ray-of-frost","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Ray of Frost","description":"A frigid beam of blue-white light streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes 1d8 cold damage, and its speed is reduced by 10 feet until the start of your next turn.\\n\\nThe spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."},"it":{"name":"Raggio di gelo","description":"Un raggio gelido di luce bianco-azzurra sfreccia verso una creatura entro gittata, contro cui l'incantatore effettua un attacco a distanza con incantesimo. Se il colpo va a segno, il bersaglio subisce 1d8 danni da freddo e la sua velocità è ridotta di 3 metri fino all'inizio del turno successivo dell'incantatore.\\n\\nI danni di questo incantesimo aumentano di 1d8 quando l'incantatore raggiunge il 5° livello (2d8), l'11° livello (3d8) e il 17° livello (4d8).","castingTime":"1 azione","range":"18 metri","duration":"Istantanea"}},"data":{"level":0,"school":"srd:rule:school-evocation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-cold","atCharacterLevel":{"1":"1d8","5":"2d8","11":"3d8","17":"4d8"}}],"attackType":"ranged"}},{"id":"srd:spell:regenerate","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Regenerate","description":"You touch a creature and stimulate its natural healing ability. The target regains 4d8 + 15 hit points. For the duration of the spell, the target regains 1 hit point at the start of each of its turns (10 hit points each minute).\\n\\nThe target's severed body members (fingers, legs, tails, and so on), if any, are restored after 2 minutes. If you have the severed part and hold it to the stump, the spell instantaneously causes the limb to knit to the stump."},"it":{"name":"Rigenerazione","description":"L'incantatore tocca una creatura e amplifica le sue capacità curative naturali, facendole recuperare 4d8 + 15 punti ferita. Per la durata dell'incantesimo, il bersaglio recupera 1 punto ferita all'inizio di ogni suo turno (10 punti ferita al minuto).\\n\\nSe al bersaglio sono state recise delle parti del corpo (dita, gambe, coda e così via), quelle parti ricrescono dopo 2 minuti e, se è in possesso della parte recisa, appoggiandola al moncone l'incantesimo rinsalda istantaneamente l'arto.","castingTime":"1 minuto","range":"Contatto","duration":"1 ora","material":"un ruota della preghiera e acqua santa"}},"data":{"level":7,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:cleric","srd:class:druid"],"subclasses":[],"castingTime":"1 minute","range":"Touch","components":["V","S","M"],"material":"A prayer wheel and holy water.","ritual":false,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:reincarnate","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Reincarnate","description":"You touch a dead humanoid or a piece of a dead humanoid. Provided that the creature has been dead no longer than 10 days, the spell forms a new adult body for it and then calls the soul to enter that body. If the target's soul isn't free or willing to do so, the spell fails.\\n\\nThe magic fashions a new body for the creature to inhabit, which likely causes the creature's race to change. The GM rolls a d 100 and consults the following table to determine what form the creature takes when restored to life, or the GM chooses a form.\\n\\n| d100 | Race |\\n\\n|---|---|\\n\\n| 01-04 | Dragonborn |\\n\\n| 05-13 | Dwarf, hill |\\n\\n| 14-21 | Dwarf, mountain |\\n\\n| 22-25 | Elf, dark |\\n\\n| 26-34 | Elf, high |\\n\\n| 35-42 | Elf, wood |\\n\\n| 43-46 | Gnome, forest |\\n\\n| 47-52 | Gnome, rock |\\n\\n| 53-56 | Half-elf |\\n\\n| 57-60 | Half-orc |\\n\\n| 61-68 | Halfling, lightfoot |\\n\\n| 69-76 | Halfling, stout |\\n\\n| 77-96 | Human |\\n\\n| 97-00 | Tiefling |\\n\\nThe reincarnated creature recalls its former life and experiences. It retains the capabilities it had in its original form, except it exchanges its original race for the new one and changes its racial traits accordingly."},"it":{"name":"Reincarnazione","description":"L'incantatore tocca un umanoide defunto o una parte di umanoide defunto. Se la creatura non è morta da più di 10 giorni, l'incantesimo le forma un nuovo corpo adulto e poi richiama la sua anima all'interno di quel corpo. Se l'anima del bersaglio non è consenziente o libera di tornare, l'incantesimo non funziona.\\n\\nLa magia crea un nuovo corpo in cui l'umanoide possa vivere, perciò è probabile che anche la razza della creatura cambi. Il GM tira un d100 e consulta la tabella seguente per determinare quale forma assume la creatura quando torna in vita o, in alternativa, la può scegliere lui stesso.\\n\\n| d100 | Razza |\\n\\n|---|---|\\n\\n| 01–04 | Dragonide |\\n\\n| 05–13 | Elfo alto |\\n\\n| 14–21 | Elfo dei boschi |\\n\\n| 22–25 | Elfo oscuro |\\n\\n| 26–29 | Gnomo delle foreste |\\n\\n| 30–35 | Gnomo delle rocce |\\n\\n| 36–43 | Halfling piedelesto |\\n\\n| 44–51 | Halfling tozzo |\\n\\n| 52–55 | Mezzelfo |\\n\\n| 56–59 | Mezzorco |\\n\\n| 60–68 | Nano delle colline |\\n\\n| 69–76 | Nano delle montagne |\\n\\n| 77–80 | Tiefling |\\n\\n| 81–100 | Umano |\\n\\nLa creatura reincarnata ricorda la sua vita e le sue esperienze passate. Conserva le capacità che possedeva nella sua forma originale, ma la sua razza precedente viene sostituita dalla nuova, così come i suoi tratti razziali.","castingTime":"1 ora","range":"Contatto","duration":"Istantanea","material":"oli e unguenti rari del valore di almeno 1.000 mo, che l'incantesimo consuma"}},"data":{"level":5,"school":"srd:rule:school-transmutation","classes":["srd:class:druid"],"subclasses":[],"castingTime":"1 hour","range":"Touch","components":["V","S","M"],"material":"Rare oils and unguents worth at least 1,000 gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:remove-curse","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Remove Curse","description":"At your touch, all curses affecting one creature or object end. If the object is a cursed magic item, its curse remains, but the spell breaks its owner's attunement to the object so it can be removed or discarded."},"it":{"name":"Rimuovi maledizione","description":"Al tocco dell'incantatore, tutte le maledizioni che affliggono una creatura o un oggetto terminano. Nel caso di un oggetto magico maledetto, la sua maledizione permane, ma l'incantesimo spezza la sintonia del suo proprietario, consentendogli di rimuoverlo o di liberarsene.","castingTime":"1 azione","range":"Contatto","duration":"Istantanea"}},"data":{"level":3,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric","srd:class:paladin","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:resilient-sphere","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Resilient Sphere","description":"A sphere of shimmering force encloses a creature or object of Large size or smaller within range. An unwilling creature must make a dexterity saving throw. On a failed save, the creature is enclosed for the duration.\\n\\nNothing--not physical objects, energy, or other spell effects--can pass through the barrier, in or out, though a creature in the sphere can breathe there. The sphere is immune to all damage, and a creature or object inside can't be damaged by attacks or effects originating from outside, nor can a creature inside the sphere damage anything outside it.\\n\\nThe sphere is weightless and just large enough to contain the creature or object inside. An enclosed creature can use its action to push against the sphere's walls and thus roll the sphere at up to half the creature's speed. Similarly, the globe can be picked up and moved by other creatures.\\n\\nA disintegrate spell targeting the globe destroys it without harming anything inside it."},"it":{"name":"Sfera elastica","description":"Una sfera di forza scintillante circonda una creatura o un oggetto di taglia Grande o inferiore entro gittata. Una creatura non consenziente deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, rimane intrappolata nella sfera per la durata dell'incantesimo.\\n\\nNulla può attraversare la barriera in entrata e in uscita (oggetti fisici, energia o altri effetti magici), ma una creatura all'interno può respirare liberamente. La sfera è immune a tutti i danni e una creatura o un oggetto all'interno non può essere danneggiato dagli attacchi o dagli effetti che provengono dall'esterno; analogamente, non può infliggere danni a qualsiasi cosa si trovi all'esterno.\\n\\nLa sfera non ha peso ed è grande quanto basta da contenere la creatura o l'oggetto al suo interno. Una creatura rinchiusa può usare la sua azione per spingere le pareti della sfera e farla rotolare a una velocità massima pari alla metà della propria. Analogamente, la sfera può essere sollevata e mossa da altre creature.\\n\\nUn incantesimo disintegrazione distrugge la sfera senza danneggiare ciò che contiene.","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 1 minuto","material":"una semisfera di cristallo trasparente e una semisfera corrispondente di resina"}},"data":{"level":4,"school":"srd:rule:school-evocation","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A hemispherical piece of clear crystal and a matching hemispherical piece of gum arabic.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"dex","onSuccess":"none"}}},{"id":"srd:spell:resistance","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Resistance","description":"You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one saving throw of its choice. It can roll the die before or after making the saving throw. The spell then ends."},"it":{"name":"Resistenza","description":"L'incantatore tocca una creatura consenziente. Prima che l'incantesimo termini, il bersaglio può tirare un d4 e aggiungere il risultato ottenuto a un tiro salvezza a sua scelta. Può tirare il dado prima o dopo avere effettuato il tiro salvezza, dopodiché l'incantesimo termina.","castingTime":"1 azione","range":"Contatto","duration":"Concentrazione, fino a 1 minuto","material":"un mantello in miniatura"}},"data":{"level":0,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric","srd:class:druid"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A miniature cloak.","ritual":false,"concentration":true,"duration":"Up to 1 minute"}},{"id":"srd:spell:resurrection","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Resurrection","description":"You touch a dead creature that has been dead for no more than a century, that didn't die of old age, and that isn't undead. If its soul is free and willing, the target returns to life with all its hit points.\\n\\nThis spell neutralizes any poisons and cures normal diseases afflicting the creature when it died. It doesn't, however, remove magical diseases, curses, and the like; if such effects aren't removed prior to casting the spell, they afflict the target on its return to life.\\n\\nThis spell closes all mortal wounds and restores any missing body parts.\\n\\nComing back from the dead is an ordeal. The target takes a -4 penalty to all attack rolls, saving throws, and ability checks. Every time the target finishes a long rest, the penalty is reduced by 1 until it disappears.\\n\\nCasting this spell to restore life to a creature that has been dead for one year or longer taxes you greatly. Until you finish a long rest, you can't cast spells again, and you have disadvantage on all attack rolls, ability checks, and saving throws."},"it":{"name":"Resurrezione","description":"L'incantatore tocca una creatura defunta da non più di un secolo, che non sia morta di vecchiaia e non sia un non morto. Se la sua anima è libera e consenziente, il bersaglio torna in vita con tutti i suoi punti ferita.\\n\\nQuesto incantesimo neutralizza qualsiasi veleno e cura le normali malattie che influenzavano la creatura al momento della morte. Non rimuove tuttavia malattie magiche, maledizioni e altre afflizioni analoghe; se tali effetti non vengono rimossi prima del lancio dell'incantesimo, affliggeranno il bersaglio una volta tornato in vita.\\n\\nQuesto incantesimo richiude tutte le ferite mortali e ripristina le eventuali parti del corpo mancanti.\\n\\nIl ritorno dalla morte è un vero e proprio travaglio. Il bersaglio subisce una penalità di -4 a tutti i tiri per colpire, tiri salvezza e prove di caratteristica. Ogni volta che completa un riposo lungo, questa penalità viene ridotta di 1 finché non sparisce del tutto.\\n\\nLanciare questo incantesimo per riportare in vita una creatura morta da un anno o più risulta estremamente spossante per l'incantatore. Finché non completa un riposo lungo, non può lanciare di nuovo incantesimi e subisce svantaggio a tutti i tiri per colpire, alle prove di caratteristica e ai tiri salvezza.","castingTime":"1 ora","range":"Contatto","duration":"Istantanea","material":"un diamante del valore di almeno 1.000 mo, che l'incantesimo consuma"}},"data":{"level":7,"school":"srd:rule:school-necromancy","classes":["srd:class:bard","srd:class:cleric"],"subclasses":[],"castingTime":"1 hour","range":"Touch","components":["V","S","M"],"material":"A diamond worth at least 1,000gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:reverse-gravity","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Reverse Gravity","description":"This spell reverses gravity in a 50-foot-radius, 100-foot high cylinder centered on a point within range. All creatures and objects that aren't somehow anchored to the ground in the area fall upward and reach the top of the area when you cast this spell. A creature can make a dexterity saving throw to grab onto a fixed object it can reach, thus avoiding the fall.\\n\\nIf some solid object (such as a ceiling) is encountered in this fall, falling objects and creatures strike it just as they would during a normal downward fall. If an object or creature reaches the top of the area without striking anything, it remains there, oscillating slightly, for the duration.\\n\\nAt the end of the duration, affected objects and creatures fall back down."},"it":{"name":"Inversione della gravità","description":"Questo incantesimo inverte la gravità all'interno di un cilindro del raggio di 15 metri e dell'altezza di 30 metri centrato su un punto entro gittata. Quando viene lanciato, tutte le creature e gli oggetti presenti nell'area che non sono in qualche modo ancorati al terreno vengono trascinati verso l'alto e raggiungono la parte superiore del cilindro. Una creatura può effettuare un tiro salvezza su Destrezza per afferrare un oggetto ancorato entro portata, evitando di essere trascinata verso l'alto.\\n\\nSe un oggetto solido di qualche tipo (come per esempio un soffitto) viene urtato durante l'ascesa, gli oggetti e le creature subiscono un impatto identico a quello di una normale caduta verso il basso. Se un oggetto o una creatura raggiunge la sommità dell'area senza colpire nulla, rimane sospeso lassù a oscillare leggermente per la durata dell'incantesimo.\\n\\nAl termine dell'incantesimo, gli oggetti e le creature influenzati ricadono a terra.","castingTime":"1 azione","range":"30 metri","duration":"Concentrazione, fino a 1 minuto","material":"una calamita e limatura di ferro"}},"data":{"level":7,"school":"srd:rule:school-transmutation","classes":["srd:class:druid","srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"100 feet","components":["V","S","M"],"material":"A lodestone and iron filings.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"dex","onSuccess":"other"},"area":{"type":"cylinder","size":50}}},{"id":"srd:spell:revivify","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Revivify","description":"You touch a creature that has died within the last minute. That creature returns to life with 1 hit point. This spell can't return to life a creature that has died of old age, nor can it restore any missing body parts."},"it":{"name":"Rinascita","description":"L'incantatore tocca una creatura morta nell'ultimo minuto e la creatura torna in vita con 1 punto ferita. Questo incantesimo non può riportare in vita una creatura morta di vecchiaia e non può ripristinare le eventuali parti del corpo mancanti.","castingTime":"1 azione","range":"Contatto","duration":"Istantanea","material":"diamanti del valore di 300 mo, che vengono consumati dall'incantesimo"}},"data":{"level":3,"school":"srd:rule:school-conjuration","classes":["srd:class:cleric","srd:class:paladin"],"subclasses":["srd:subclass:lore","srd:subclass:life"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"Diamonds worth 300gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:rope-trick","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Rope Trick","description":"You touch a length of rope that is up to 60 feet long. One end of the rope then rises into the air until the whole rope hangs perpendicular to the ground. At the upper end of the rope, an invisible entrance opens to an extradimensional space that lasts until the spell ends.\\n\\nThe extradimensional space can be reached by climbing to the top of the rope. The space can hold as many as eight Medium or smaller creatures. The rope can be pulled into the space, making the rope disappear from view outside the space.\\n\\nAttacks and spells can't cross through the entrance into or out of the extradimensional space, but those inside can see out of it as if through a 3-foot-by-5-foot window centered on the rope.\\n\\nAnything inside the extradimensional space drops out when the spell ends."},"it":{"name":"Trucco della corda","description":"L'incantatore tocca un pezzo di corda della lunghezza massima di 18 metri. Un'estremità della corda sale in aria finché non pende perpendicolarmente al terreno. All'estremità superiore della corda, si apre un'entrata invisibile verso uno spazio extradimensionale che permane fino al termine dell'incantesimo.\\n\\nLo spazio extradimensionale può essere raggiunto arrampicandosi in cima alla corda e può contenere un massimo di otto creature di taglia Media o inferiore. La corda può essere ritratta all'interno dello spazio, facendola sparire dalla vista di chi osserva dall'esterno.\\n\\nGli attacchi e gli incantesimi non possono attraversare lo spazio extradimensionale in entrata o uscita, ma coloro che si trovano all'interno possono vedere all'esterno come da una finestra di 90 cm per 1,5 metri centrata sulla corda.\\n\\nTutto ciò che si trova all'interno dello spazio extradimensionale cade all'esterno al termine dell'incantesimo.","castingTime":"1 azione","range":"Contatto","duration":"1 ora","material":"estratto di mais in polvere e un pezzo di pergamena intrecciato"}},"data":{"level":2,"school":"srd:rule:school-transmutation","classes":["srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"Powdered corn extract and a twisted loop of parchment.","ritual":false,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:sacred-flame","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Sacred Flame","description":"Flame-like radiance descends on a creature that you can see within range. The target must succeed on a dexterity saving throw or take 1d8 radiant damage. The target gains no benefit from cover for this saving throw.\\n\\nThe spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."},"it":{"name":"Fiamma sacra","description":"Un bagliore simile a una fiamma discende su una creatura entro gittata che l'incantatore è in grado di vedere. Il bersaglio deve superare un tiro salvezza su Destrezza, altrimenti subisce 1d8 danni radiosi. Inoltre, per questo tiro salvezza, non trae beneficio dalla copertura.\\n\\nI danni di questo incantesimo aumentano di 1d8 quando l'incantatore raggiunge il 5° livello (2d8), l'11° livello (3d8) e il 17° livello (4d8).","castingTime":"1 azione","range":"18 metri","duration":"Istantanea"}},"data":{"level":0,"school":"srd:rule:school-evocation","classes":["srd:class:cleric"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-radiant","atCharacterLevel":{"1":"1d8","5":"2d8","11":"3d8","17":"4d8"}}],"savingThrow":{"ability":"dex","onSuccess":"none"}}},{"id":"srd:spell:sanctuary","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Sanctuary","description":"You ward a creature within range against attack. Until the spell ends, any creature who targets the warded creature with an attack or a harmful spell must first make a wisdom saving throw. On a failed save, the creature must choose a new target or lose the attack or spell. This spell doesn't protect the warded creature from area effects, such as the explosion of a fireball.\\n\\nIf the warded creature makes an attack or casts a spell that affects an enemy creature, this spell ends."},"it":{"name":"Santuario","description":"L'incantatore protegge dagli attacchi una creatura situata entro gittata. Finché l'incantesimo non termina, ogni creatura che bersaglia la creatura protetta con un attacco o un incantesimo che infligge danni deve prima effettuare un tiro salvezza su Saggezza. Se lo fallisce, deve scegliere un nuovo bersaglio o perdere l'attacco o l'incantesimo. Questo incantesimo non protegge la creatura bersaglio dagli effetti ad area, come l'esplosione di una palla di fuoco.\\n\\nSe la creatura protetta effettua un attacco o lancia un incantesimo che influenza una creatura nemica, questo incantesimo termina.","castingTime":"1 azione bonus","range":"9 metri","duration":"1 minuto","material":"uno specchietto d'argento"}},"data":{"level":1,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric"],"subclasses":["srd:subclass:lore","srd:subclass:devotion"],"castingTime":"1 bonus action","range":"30 feet","components":["V","S","M"],"material":"A small silver mirror.","ritual":false,"concentration":false,"duration":"1 minute"}},{"id":"srd:spell:scorching-ray","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Scorching Ray","description":"You create three rays of fire and hurl them at targets within range. You can hurl them at one target or several.\\n\\nMake a ranged spell attack for each ray. On a hit, the target takes 2d6 fire damage.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, you create one additional ray for each slot level above 2nd."},"it":{"name":"Raggio rovente","description":"L'incantatore crea tre raggi di fuoco e li scaglia contro dei bersagli entro gittata, che possono essere uno o più.\\n\\nCon questo incantesimo, l'incantatore effettua un attacco a distanza per ogni raggio. Se il colpo va a segno, il bersaglio subisce 2d6 danni da fuoco.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, crea un raggio aggiuntivo per ogni slot superiore al 2°.","castingTime":"1 azione","range":"36 metri","duration":"Istantanea"}},"data":{"level":2,"school":"srd:rule:school-evocation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:fiend"],"castingTime":"1 action","range":"120 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-fire","atSlotLevel":{"2":"2d6"}}]}},{"id":"srd:spell:scrying","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Scrying","description":"You can see and hear a particular creature you choose that is on the same plane of existence as you. The target must make a wisdom saving throw, which is modified by how well you know the target and the sort of physical connection you have to it. If a target knows you're casting this spell, it can fail the saving throw voluntarily if it wants to be observed.\\n\\n| Knowledge | Save Modifier |\\n\\n|---|---|\\n\\n| Secondhand (you have heard of the target) | +5 |\\n\\n| Firsthand (you have met the target) | +0 |\\n\\n| Familiar (you know the target well) | -5 |\\n\\n\\n\\n| Connection | Save Modifier |\\n\\n|---|---|\\n\\n| Likeness or picture | -2 |\\n\\n| Possession or garment | -4 |\\n\\n| Body part, lock of hair, bit of nail, or the like | -10 |\\n\\nOn a successful save, the target isn't affected, and you can't use this spell against it again for 24 hours.\\n\\nOn a failed save, the spell creates an invisible sensor within 10 feet of the target. You can see and hear through the sensor as if you were there. The sensor moves with the target, remaining within 10 feet of it for the duration. A creature that can see invisible objects sees the sensor as a luminous orb about the size of your fist.\\n\\nInstead of targeting a creature, you can choose a location you have seen before as the target of this spell. When you do, the sensor appears at that location and doesn't move."},"it":{"name":"Scrutare","description":"L'incantatore può vedere e udire una particolare creatura a sua scelta situata sul suo stesso piano di esistenza. Il bersaglio deve effettuare un tiro salvezza su Saggezza, modificato dalla conoscenza e dal tipo di legame fisico che l'incantatore ha nei confronti della creatura. Se il bersaglio è consapevole che l'incantatore sta lanciando questo incantesimo, può fallire volontariamente il tiro salvezza se desidera essere osservato.\\n\\n| Conoscenza | Modificatore al tiro salvezza |\\n\\n|---|---|\\n\\n| Indiretta (l'incantatore ha solo sentito parlare del bersaglio) | +5 |\\n\\n| Diretta (l'incantatore ha incontrato il bersaglio) | +0 |\\n\\n| Familiarità (l'incantatore conosce bene il bersaglio) | -5 |\\n\\n\\n\\n| Connessione | Modificatore al tiro salvezza |\\n\\n|---|---|\\n\\n| Descrizione o immagine | -2 |\\n\\n| Oggetto personale o abito | -4 |\\n\\n| Parte del corpo, ciocca di capelli, pezzo di unghia, ecc... | -10 |\\n\\nIn caso di tiro salvezza superato, il bersaglio non viene influenzato dall'incantesimo, che l'incantatore non può usare contro di lui per 24 ore.\\n\\nSe lo fallisce, l'incantesimo crea un sensore invisibile entro 3 metri dal bersaglio, attraverso cui l'incantatore può vedere e sentire come se si trovasse sul posto. Il sensore si muove insieme al bersaglio, rimanendo entro 3 metri da esso per la durata dell'incantesimo. Una creatura che è in grado di vedere gli oggetti invisibili vede il sensore come una sfera luminosa grande quando il pugno dell'incantatore.\\n\\nAnziché una creatura, l'incantatore può scegliere come bersaglio dell'incantesimo un luogo che abbia già visto in precedenza. Quando lo fa, il sensore appare in quel luogo e non si muove.","castingTime":"10 minuti","range":"Incantatore","duration":"Concentrazione, fino a 10 minuti","material":"un focus del valore di almeno 1.000 mo, come una sfera di cristallo, uno specchio d'argento o un bacile pieno di acqua santa"}},"data":{"level":5,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:cleric","srd:class:druid","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:land"],"castingTime":"10 minutes","range":"Self","components":["V","S","M"],"material":"A focus worth at least 1,000 gp, such as a crystal ball, a silver mirror, or a font filled with holy water.","ritual":false,"concentration":true,"duration":"Up to 10 minutes","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:secret-chest","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Secret Chest","description":"You hide a chest, and all its contents, on the Ethereal Plane. You must touch the chest and the miniature replica that serves as a material component for the spell. The chest can contain up to 12 cubic feet of nonliving material (3 feet by 2 feet by 2 feet).\\n\\nWhile the chest remains on the Ethereal Plane, you can use an action and touch the replica to recall the chest. It appears in an unoccupied space on the ground within 5 feet of you. You can send the chest back to the Ethereal Plane by using an action and touching both the chest and the replica.\\n\\nAfter 60 days, there is a cumulative 5 percent chance per day that the spell's effect ends. This effect ends if you cast this spell again, if the smaller replica chest is destroyed, or if you choose to end the spell as an action. If the spell ends and the larger chest is on the Ethereal Plane, it is irretrievably lost."},"it":{"name":"Scrigno segreto","description":"L'incantatore nasconde uno scrigno e tutti i suoi contenuti sul Piano Etereo. Per farlo, deve toccare il forziere e la riproduzione in miniatura che funge da componente materiale dell'incantesimo. Il forziere può contenere fino a 12 cubi con spigolo di 30 cm di materiale non vivente (90 × 60 × 60 cm).\\n\\nFinché il forziere rimane sul Piano Etereo, l'incantatore può usare un'azione e toccare la riproduzione per richiamare a sé lo scrigno, che appare a terra in uno spazio libero entro 1,5 metri da lui. Con un'azione, l'incantatore può inviarlo nuovamente sul Piano Etereo toccando sia il forziere che la replica.\\n\\nDopo 60 giorni, esiste una probabilità cumulativa del 5% al giorno che l'effetto dell'incantesimo termini. Inoltre, esso termina se l'incantatore lancia nuovamente l'incantesimo, se la riproduzione più piccola del forziere viene distrutta o se l'incantatore sceglie di terminare l'incantesimo con un'azione. Se il forziere più grande si trova sul Piano Etereo quando l'incantesimo termina, è perduto irrimediabilmente.","castingTime":"1 azione","range":"Contatto","duration":"Istantanea","material":"un forziere di fattura pregiata che misura 90 × 60 × 60 cm, realizzato con materiali rari del valore di almeno 5.000 mo e una riproduzione minuscola fatta degli stessi materiali del valore di 50 mo"}},"data":{"level":4,"school":"srd:rule:school-conjuration","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"An exquisite chest, 3 feet by 2 feet by 2 feet, constructed from rare materials worth at least 5,000 gp, and a Tiny replica made from the same materials worth at least 50 gp.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:see-invisibility","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"See Invisibility","description":"For the duration of the spell, you see invisible creatures and objects as if they were visible, and you can see through Ethereal. The ethereal objects and creatures appear ghostly translucent."},"it":{"name":"Vedere invisibilità","description":"Per la durata dell'incantesimo, l'incantatore è in grado di vedere le creature e gli oggetti invisibili e proiettare la sua vista sul Piano Etereo. Le creature e gli oggetti eterei gli appaiono spettrali e trasparenti.","castingTime":"1 azione","range":"Incantatore","duration":"1 ora","material":"un pizzico di talco e una spolverata di polvere d'argento"}},"data":{"level":2,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A dash of talc and a small amount of silver powder.","ritual":false,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:seeming","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Seeming","description":"This spell allows you to change the appearance of any number of creatures that you can see within range. You give each target you choose a new, illusory appearance. An unwilling target can make a charisma saving throw, and if it succeeds, it is unaffected by this spell.\\n\\nThe spell disguises physical appearance as well as clothing, armor, weapons, and equipment. You can make each creature seem 1 foot shorter or taller and appear thin, fat, or in between. You can't change a target's body type, so you must choose a form that has the same basic arrangement of limbs. Otherwise, the extent of the illusion is up to you. The spell lasts for the duration, unless you use your action to dismiss it sooner.\\n\\nThe changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to a creature's outfit, objects pass through the hat, and anyone who touches it would feel nothing or would feel the creature's head and hair. If you use this spell to appear thinner than you are, the hand of someone who reaches out to touch you would bump into you while it was seemingly still in midair.\\n\\nA creature can use its action to inspect a target and make an Intelligence (Investigation) check against your spell save DC. If it succeeds, it becomes aware that the target is disguised."},"it":{"name":"Sembrare","description":"Questo incantesimo consente all'incantatore di alterare l'aspetto di un qualsiasi numero di creature entro gittata che è in grado di vedere, assegnando a ognuna un nuovo aspetto illusorio. Un bersaglio non consenziente può effettuare un tiro salvezza su Carisma e, se lo supera, non ne viene influenzato.\\n\\nL'incantesimo camuffa l'aspetto fisico oltre agli abiti, l'armatura, le armi e l'equipaggiamento. Ogni creatura può apparire 30 cm più alta o più bassa, apparire magra, grassa o di corporatura intermedia. Tuttavia, l'incantatore non può cambiare il tipo di corpo del bersaglio, quindi deve scegliere una forma che usi la stessa disposizione basilare degli arti. Entro questi limiti, la natura dell'illusione dipende da lui. L'incantesimo permane per tutta la sua durata, a meno che l'incantatore non usi un'azione per interromperlo prima.\\n\\nI cambiamenti apportati da questo incantesimo non passano il vaglio di un'ispezione fisica. Per esempio, se l'incantatore usa questo incantesimo per aggiungere un cappello all'abbigliamento della creatura, dato che gli oggetti sono in grado di attraversarlo, chiunque lo tocchi non sente nulla o tasta solamente la testa e i capelli della creatura. Se l'incantatore usa questo incantesimo per apparire più magro rispetto alla realtà, quando qualcuno tenta di toccarlo incontrerebbe il suo corpo mentre la mano è ancora apparentemente a mezz'aria.\\n\\nUna creatura può usare la sua azione per ispezionare il bersaglio ed effettuare una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo. Se la supera, capisce che il bersaglio è camuffato.","castingTime":"1 azione","range":"9 metri","duration":"8 ore"}},"data":{"level":5,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"8 hours"}},{"id":"srd:spell:sending","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Sending","description":"You send a short message of twenty-five words or less to a creature with which you are familiar. The creature hears the message in its mind, recognizes you as the sender if it knows you, and can answer in a like manner immediately. The spell enables creatures with Intelligence scores of at least 1 to understand the meaning of your message.\\n\\nYou can send the message across any distance and even to other planes of existence, but if the target is on a different plane than you, there is a 5 percent chance that the message doesn't arrive."},"it":{"name":"Inviare","description":"L'incantatore invia un breve messaggio di un massimo di venticinque parole a una creatura che gli sia familiare. La creatura sente il messaggio nella sua mente, riconosce l'incantatore come colui che l'ha inviato e può rispondere immediatamente allo stesso modo. L'incantesimo consente alle creature con un punteggio di Intelligenza pari o superiore a 1 di capire il significato del messaggio.\\n\\nL'incantatore può inviare il messaggio a qualsiasi distanza e perfino ad altri piani di esistenza, ma se il bersaglio si trova su un piano di esistenza diverso dal suo, c'è una probabilità del 5% che il messaggio non arrivi.","castingTime":"1 azione","range":"Illimitata","duration":"1 round","material":"un piccolo pezzo di filo di rame"}},"data":{"level":3,"school":"srd:rule:school-evocation","classes":["srd:class:bard","srd:class:cleric","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Unlimited","components":["V","S","M"],"material":"A short piece of fine copper wire.","ritual":false,"concentration":false,"duration":"1 round"}},{"id":"srd:spell:sequester","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Sequester","description":"By means of this spell, a willing creature or an object can be hidden away, safe from detection for the duration. When you cast the spell and touch the target, it becomes invisible and can't be targeted by divination spells or perceived through scrying sensors created by divination spells.\\n\\nIf the target is a creature, it falls into a state of suspended animation. Time ceases to flow for it, and it doesn't grow older.\\n\\nYou can set a condition for the spell to end early. The condition can be anything you choose, but it must occur or be visible within 1 mile of the target. Examples include \\"after 1,000 years\\" or \\"when the tarrasque awakens.\\" This spell also ends if the target takes any damage."},"it":{"name":"Celare","description":"Questo incantesimo consente all'incantatore di nascondere una creatura consenziente o un oggetto dai tentativi di individuazione per la durata dell'incantesimo. Quando l'incantatore lancia questo incantesimo e tocca il bersaglio, questo diventa invisibile e non può essere bersagliato da incantesimi di divinazione o percepito dai sensori di scrutamento creati da quegli incantesimi.\\n\\nSe il bersaglio è una creatura, cade in uno stato di animazione sospesa: per lei, il tempo cessa di scorrere e non invecchia.\\n\\nPer terminare prematuramente l'incantesimo, l'incantatore può stabilire una condizione, che può essere qualsiasi cosa a sua scelta che, tuttavia, debba verificarsi o essere visibile entro 1,5 km dal bersaglio. Per esempio, \\"dopo 1.000 anni\\" o \\"al risveglio del tarrasque\\". Questo incantesimo termina inoltre se il bersaglio subisce danni.","castingTime":"1 azione","range":"Contatto","duration":"Finché non viene dissolto","material":"un composto di polvere di diamante, smeraldo, rubino e zaffiro del valore di almeno 5.000 mo, che l'incantesimo consuma"}},"data":{"level":7,"school":"srd:rule:school-transmutation","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A powder composed of diamond, emerald, ruby, and sapphire dust worth at least 5,000 gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"Until dispelled"}},{"id":"srd:spell:shapechange","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Shapechange","description":"You assume the form of a different creature for the duration. The new form can be of any creature with a challenge rating equal to your level or lower. The creature can't be a construct or an undead, and you must have seen the sort of creature at least once. You transform into an average example of that creature, one without any class levels or the Spellcasting trait.\\n\\nYour game statistics are replaced by the statistics of the chosen creature, though you retain your alignment and Intelligence, Wisdom, and Charisma scores. You also retain all of your skill and saving throw proficiencies, in addition to gaining those of the creature. If the creature has the same proficiency as you and the bonus listed in its statistics is higher than yours, use the creature's bonus in place of yours. You can't use any legendary actions or lair actions of the new form.\\n\\nYou assume the hit points and Hit Dice of the new form. When you revert to your normal form, you return to the number of hit points you had before you transformed. If you revert as a result of dropping to 0 hit points, any excess damage carries over to your normal form. As long as the excess damage doesn't reduce your normal form to 0 hit points, you aren't knocked unconscious.\\n\\nYou retain the benefit of any features from your class, race, or other source and can use them, provided that your new form is physically capable of doing so. You can't use any special senses you have (for example, darkvision) unless your new form also has that sense. You can only speak if the creature can normally speak.\\n\\nWhen you transform, you choose whether your equipment falls to the ground, merges into the new form, or is worn by it. Worn equipment functions as normal. The GM determines whether it is practical for the new form to wear a piece of equipment, based on the creature's shape and size. Your equipment doesn't change shape or size to match the new form, and any equipment that the new form can't wear must either fall to the ground or merge into your new form. Equipment that merges has no effect in that state.\\n\\nDuring this spell's duration, you can use your action to assume a different form following the same restrictions and rules for the original form, with one exception: if your new form has more hit points than your current one, your hit points remain at their current value."},"it":{"name":"Trasformazione","description":"L'incantatore assume la forma di una creatura diversa per la durata dell'incantesimo. La nuova forma può essere quella di una qualsiasi creatura con un grado di sfida pari o inferiore al suo. La creatura non può essere un costrutto o un non morto e deve essere di un tipo che l'incantatore abbia già visto almeno una volta. L'incantatore si trasforma in un normale esemplare di quella creatura, privo di livelli di classe o di tratto Incantesimi.\\n\\nLe sue statistiche di gioco vengono sostituite dalle statistiche della creatura scelta, benché l'incantatore conservi il proprio allineamento e i punteggi di Intelligenza, Saggezza e Carisma. Conserva inoltre tutte le sue abilità e competenze nei tiri salvezza, oltre a ottenere quelle della creatura. Se la creatura possiede una competenza che anche l'incantatore possiede e il bonus nelle sue statistiche è superiore a quello dell'incantatore, quest'ultimo usa il bonus della creatura anziché il proprio. L'incantatore non può usare azioni leggendarie o azioni di tana nella sua nuova forma.\\n\\nL'incantatore assume i punti ferita e i dadi vita della nuova forma e, una volta tornato nella sua forma normale, riassume il numero di punti ferita che possedeva prima della trasformazione. Se torna nella sua forma normale per essere sceso a 0 punti ferita, gli eventuali danni in eccesso si trasmettono a essa. Fintantoché i danni in eccesso non portano la sua forma normale a 0 punti ferita, non cade privo di sensi.\\n\\nL'incantatore mantiene i benefici di tutti i privilegi forniti dalla sua classe, razza e da qualsiasi altra fonte e può usarli se, nella nuova forma, è fisicamente in grado di farlo. Tuttavia, non può usare nessuno dei suoi sensi speciali, come per esempio la scurovisione, a meno che non li possieda anche nella nuova forma, potendo parlare solo se la creatura è normalmente in grado di farlo.\\n\\nQuando si trasforma, l'incantatore può scegliere se lasciare cadere a terra l'equipaggiamento, se permettere che si fonda nella sua nuova forma o se indossarlo. L'equipaggiamento indossato funziona normalmente, ma spetta al GM decidere se è pratico o meno che la nuova forma indossi ogni determinato oggetto d'equipaggiamento, in base alla forma e alla taglia della creatura. L'equipaggiamento dell'incantatore non cambia per adattarsi alla nuova forma e ogni oggetto di equipaggiamento che non può indossare deve cadere a terra o fondersi con essa. L'equipaggiamento fuso nella nuova forma non ha alcun effetto in quello stato.\\n\\nPer la durata dell'incantesimo, l'incantatore può usare un'azione per assumere una forma diversa seguendo le stesse regole e restrizioni relative alla forma originale, con un'eccezione: se la nuova forma possiede più punti ferita rispetto a quelli attuali dell'incantatore, i punti ferita di quest'ultimo rimangono al valore attuale.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 1 ora","material":"un diadema di giada del valore di almeno 1.500 mo, che l'incantatore deve indossare prima di lanciare l'incantesimo"}},"data":{"level":9,"school":"srd:rule:school-transmutation","classes":["srd:class:druid","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A jade circlet worth at least 1,500 gp, which you must place on your head before you cast the spell.","ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:shatter","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Shatter","description":"A sudden loud ringing noise, painfully intense, erupts from a point of your choice within range. Each creature in a 10-foot-radius sphere centered on that point must make a Constitution saving throw. A creature takes 3d8 thunder damage on a failed save, or half as much damage on a successful one. A creature made of inorganic material such as stone, crystal, or metal has disadvantage on this saving throw.\\n\\nA non-magical item that is not worn or carried also suffers damage if it is in the area of the spell.\\n\\n**At Higher Levels.** When you cast this spell using a 3 or higher level spell slot, the damage of the spell increases by 1d8 for each level of higher spell slot 2."},"it":{"name":"Frantumare","description":"Un rumore improvviso e assordante, dolorosamente intenso, si diffonde da un punto a scelta dell'incantatore situato entro gittata. Ogni creatura entro una sfera del raggio di 3 metri centrata su quel punto deve effettuare un tiro salvezza su Costituzione. In caso di fallimento, la creatura subisce 3d8 danni da tuono, mentre se lo supera subisce soltanto la metà di quei danni. Una creatura fatta di materiale inorganico come pietra, cristallo o metallo subisce svantaggio a questo tiro salvezza.\\n\\nAnche un oggetto non magico che non sia indossato o trasportato subisce i danni se si trova entro l'area dell'incantesimo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 2°.","castingTime":"1 azione","range":"18 metri","duration":"Istantanea","material":"un frammento di mica"}},"data":{"level":2,"school":"srd:rule:school-evocation","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"A burst of mica.","ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-thunder","atSlotLevel":{"2":"3d8","3":"4d8","4":"5d8","5":"6d8","6":"7d8","7":"8d8","8":"9d8","9":"10d8"}}],"savingThrow":{"ability":"con","onSuccess":"half"},"area":{"type":"sphere","size":10}}},{"id":"srd:spell:shield","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Shield","description":"An invisible barrier of magical force appears and protects you. Until the start of your next turn, you have a +5 bonus to AC, including against the triggering attack, and you take no damage from magic missile."},"it":{"name":"Scudo","description":"Una barriera di forza magica invisibile si materializza e protegge l'incantatore. Fino all'inizio del proprio turno successivo, l'incantatore ottiene un bonus di +5 alla CA da applicare anche all'attacco innescante e non subisce danni da dardo incantato.","castingTime":"1 reazione, che l'incantatore effettua quando è colpito da un attacco o bersagliato dall'incantesimo dardo incantato","range":"Incantatore","duration":"1 round"}},"data":{"level":1,"school":"srd:rule:school-abjuration","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 reaction","range":"Self","components":["V","S"],"ritual":false,"concentration":false,"duration":"1 round"}},{"id":"srd:spell:shield-of-faith","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Shield of Faith","description":"A shimmering field appears and surrounds a creature of your choice within range, granting it a +2 bonus to AC for the duration."},"it":{"name":"Scudo della fede","description":"Un campo di energia scintillante si materializza attorno a una creatura scelta dall'incantatore entro gittata, conferendole un bonus di +2 alla CA per la durata dell'incantesimo.","castingTime":"1 azione bonus","range":"18 metri","duration":"Concentrazione, fino a 10 minuti","material":"una piccola pergamena recante un frammento di un testo sacro"}},"data":{"level":1,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric","srd:class:paladin"],"subclasses":["srd:subclass:lore"],"castingTime":"1 bonus action","range":"60 feet","components":["V","S","M"],"material":"A small parchment with a bit of holy text written on it.","ritual":false,"concentration":true,"duration":"Up to 10 minutes"}},{"id":"srd:spell:shillelagh","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Shillelagh","description":"The wood of a club or a quarterstaff you are holding is imbued with nature's power. For the duration, you can use your spellcasting ability instead of Strength for the attack and damage rolls of melee attacks using that weapon, and the weapon's damage die becomes a d8. The weapon also becomes magical, if it isn't already. The spell ends if you cast it again or if you let go of the weapon."},"it":{"name":"Randello incantato","description":"Il legno di un randello o di un bastone ferrato impugnato dall'incantatore è pervaso dal potere della natura. Per la durata dell'incantesimo, l'incantatore usa la propria caratteristica da incantatore anziché la Forza per i tiri per i danni e i tiri per colpire effettuati negli attacchi in mischia usando quell'arma: inoltre, i danni dell'arma sono calcolati con un d8. Se già non lo è, l'arma diventa magica. L'incantesimo termina se l'incantatore lo lancia di nuovo o lascia andare l'arma.","castingTime":"1 azione bonus","range":"Contatto","duration":"1 minuto","material":"vischio, una foglia di trifoglio e un randello o un bastone ferrato"}},"data":{"level":0,"school":"srd:rule:school-transmutation","classes":["srd:class:druid"],"subclasses":["srd:subclass:lore"],"castingTime":"1 bonus action","range":"Touch","components":["V","S","M"],"material":"Mistletoe, a shamrock leaf, and a club or quarterstaff.","ritual":false,"concentration":false,"duration":"1 minute"}},{"id":"srd:spell:shocking-grasp","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Shocking Grasp","description":"Lightning springs from your hand to deliver a shock to a creature you try to touch. Make a melee spell attack against the target. You have advantage on the attack roll if the target is wearing armor made of metal. On a hit, the target takes 1d8 lightning damage, and it can't take reactions until the start of its next turn.\\n\\nThe spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."},"it":{"name":"Stretta folgorante","description":"Un fulmine si sprigiona dalla mano dell'incantatore per trasmettere una scarica folgorante a una creatura che prova a toccare. Con questo incantesimo effettui un attacco in mischia contro il bersaglio. Se il bersaglio indossa un'armatura fatta di metallo, disponi di vantaggio al tiro per colpire. Se il colpo va a segno, il bersaglio subisce 1d8 danni da fulmine e non può effettuare reazioni fino all'inizio del proprio turno successivo.\\n\\nI danni di questo incantesimo aumentano di 1d8 quando l'incantatore raggiunge il 5° livello (2d8), l'11° livello (3d8) e il 17° livello (4d8).","castingTime":"1 azione","range":"Contatto","duration":"Istantanea"}},"data":{"level":0,"school":"srd:rule:school-evocation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-lightning","atCharacterLevel":{"1":"1d8","5":"2d8","11":"3d8","17":"4d8"}}],"attackType":"melee"}},{"id":"srd:spell:silence","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Silence","description":"For the duration, no sound can be created within or pass through a 20-foot-radius sphere centered on a point you choose within range. Any creature or object entirely inside the sphere is immune to thunder damage, and creatures are deafened while entirely inside it.\\n\\nCasting a spell that includes a verbal component is impossible there."},"it":{"name":"Silenzio","description":"L'incantatore genera una sfera del raggio di 6 metri centrata su un punto a sua scelta situato entro gittata e, per la durata dell'incantesimo, nessun suono può essere creato all'interno di quella sfera o attraversarla. Ogni creatura o oggetto interamente all'interno della sfera è immune ai danni da tuono e ogni creatura interamente all'interno della sfera è assordata. All'interno dell'area è impossibile lanciare un incantesimo che includa una componente verbale.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 10 minuti"}},"data":{"level":2,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:cleric","srd:class:ranger"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"120 feet","components":["V","S"],"ritual":true,"concentration":true,"duration":"Up to 10 minutes","area":{"type":"sphere","size":20}}},{"id":"srd:spell:silent-image","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Silent Image","description":"You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 15-foot cube. The image appears at a spot within range and lasts for the duration. The image is purely visual; it isn't accompanied by sound, smell, or other sensory effects.\\n\\nYou can use your action to cause the image to move to any spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking.\\n\\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image."},"it":{"name":"Immagine silenziosa","description":"L'incantatore crea l'immagine di un oggetto, una creatura o un altro fenomeno visibile che non sia più grande di un cubo di 4,5 metri. L'immagine compare in un punto situato entro gittata e permane per la durata dell'incantesimo. L'immagine è puramente visiva; non è accompagnata da suoni, odori o altri effetti sensoriali.\\n\\nL'incantatore può usare la sua azione per fare in modo che l'immagine si muova fino a un qualsiasi altro punto entro gittata. Mentre l'immagine è in movimento, l'incantatore può alterarne l'aspetto in modo che i movimenti risultino naturali. Ad esempio, se l'incantatore crea l'immagine di una creatura e decide di farla muovere, può alterarla in modo da simulare che stia camminando.\\n\\nL'illusione può essere rivelata da un'interazione fisica, perché è possibile passarle attraverso. Una creatura che usa la sua azione per esaminare l'immagine può determinare che si tratta di un'illusione superando una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo. Se una creatura riconosce l'illusione per ciò che è, riesce a vedere attraverso l'immagine.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 10 minuti","material":"un ciuffo di lana"}},"data":{"level":1,"school":"srd:rule:school-illusion","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"A bit of fleece.","ritual":false,"concentration":true,"duration":"Up to 10 minutes","area":{"type":"cube","size":15}}},{"id":"srd:spell:simulacrum","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Simulacrum","description":"You shape an illusory duplicate of one beast or humanoid that is within range for the entire casting time of the spell. The duplicate is a creature, partially real and formed from ice or snow, and it can take actions and otherwise be affected as a normal creature. It appears to be the same as the original, but it has half the creature's hit point maximum and is formed without any equipment. Otherwise, the illusion uses all the statistics of the creature it duplicates.\\n\\nThe simulacrum is friendly to you and creatures you designate. It obeys your spoken commands, moving and acting in accordance with your wishes and acting on your turn in combat. The simulacrum lacks the ability to learn or become more powerful, so it never increases its level or other abilities, nor can it regain expended spell slots.\\n\\nIf the simulacrum is damaged, you can repair it in an alchemical laboratory, using rare herbs and minerals worth 100 gp per hit point it regains. The simulacrum lasts until it drops to 0 hit points, at which point it reverts to snow and melts instantly.\\n\\nIf you cast this spell again, any currently active duplicates you created with this spell are instantly destroyed."},"it":{"name":"Simulacro","description":"L'incantatore realizza un duplicato illusorio di una bestia o un umanoide che deve rimanere entro gittata per l'intero tempo di lancio dell'incantesimo. Il duplicato è una creatura parzialmente reale fatta di ghiaccio o di neve, che può effettuare azioni ed essere influenzata come una creatura normale. Ha lo stesso aspetto dell'originale, ma possiede la metà dei suoi punti ferita massimi ed è creata senza equipaggiamento. Sotto ogni altro aspetto, l'illusione usa tutte le statistiche della creatura che duplica.\\n\\nIl simulacro è amichevole nei confronti dell'incantatore e delle creature da lui indicate. Obbedisce ai comandi vocali dell'incantatore, muovendosi e agendo in ottemperanza ai suoi desideri, nonché agendo in combattimento nel suo turno. Il simulacro non è in grado di apprendere o di diventare più potente, quindi non aumenta mai di livello, come non lo fanno le altre abilità, e non può recuperare gli slot incantesimo spesi.\\n\\nSe il simulacro subisce danni, l'incantatore può ripararlo in un laboratorio alchemico, usando erbe e minerali rari del valore di 100 mo per punto ferita recuperato. Il simulacro permane finché non scende a 0 punti ferita, nel qual caso si ritrasforma in neve e si scioglie istantaneamente.\\n\\nSe l'incantatore lancia di nuovo questo incantesimo, il duplicato attualmente attivo da lui creato viene istantaneamente distrutto.","castingTime":"12 ore","range":"Contatto","duration":"Finché non viene dissolto","material":"una quantità di neve o ghiaccio sufficiente per realizzare una copia a grandezza naturale della creatura da duplicare; una ciocca di capelli, un'unghia tagliata o un altro pezzo del corpo di quella creatura da collocare in mezzo alla neve o al ghiaccio; polvere di rubino del valore di 1.500 mo da cospargere sul duplicato, che l'incantesimo consuma"}},"data":{"level":7,"school":"srd:rule:school-illusion","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"12 hours","range":"Touch","components":["V","S","M"],"material":"Snow or ice in quantities sufficient to made a life-size copy of the duplicated creature; some hair, fingernail clippings, or other piece of that creature's body placed inside the snow or ice; and powdered ruby worth 1,500 gp, sprinkled over the duplicate and consumed by the spell.","ritual":false,"concentration":false,"duration":"Until dispelled"}},{"id":"srd:spell:sleep","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Sleep","description":"This spell sends creatures into a magical slumber. Roll 5d8; the total is how many hit points of creatures this spell can affect. Creatures within 20 feet of a point you choose within range are affected in ascending order of their current hit points (ignoring unconscious creatures).\\n\\nStarting with the creature that has the lowest current hit points, each creature affected by this spell falls unconscious until the spell ends, the sleeper takes damage, or someone uses an action to shake or slap the sleeper awake. Subtract each creature's hit points from the total before moving on to the creature with the next lowest hit points. A creature's hit points must be equal to or less than the remaining total for that creature to be affected.\\n\\nUndead and creatures immune to being charmed aren't affected by this spell.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, roll an additional 2d8 for each slot level above 1st."},"it":{"name":"Sonno","description":"Questo incantesimo fa in modo che le creature siano vittime di un sonno magico. Tiri 5d8 e il totale ottenuto è la quantità di Punti Ferita delle creature che questo incantesimo può influenzare. Le creature entro 6 metri da un punto a scelta dell'incantatore situato entro gittata sono influenzate in ordine crescente in base ai loro punti ferita attuali (le creature prive di sensi sono escluse).\\n\\nA partire da quella che al momento possiede meno punti ferita, ogni creatura influenzata da questo incantesimo cade priva di sensi e resta tale finché l'incantesimo non termina, finché subisce dei danni o qualcuno usa un'azione per svegliarla scuotendola o schiaffeggiandola. Si sottraggono i punti ferita di ogni creatura dal totale, per poi iniziare dalla creatura che possiede il numero di punti ferita più basso. Affinché quella creatura possa essere influenzata, il totale dei suoi punti ferita deve essere pari o inferiore al totale rimanente.\\n\\nLe creature non morte e quelle immuni all'essere affascinate non sono influenzate da questo incantesimo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, tira 2d8 aggiuntivi per ogni slot di livello superiore al 1°.","castingTime":"1 azione","range":"27 metri","duration":"1 minuto","material":"un pizzico di sabbia finissima, petali di rosa o un grillo"}},"data":{"level":1,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"90 feet","components":["V","S","M"],"material":"A pinch of fine sand, rose petals, or a cricket.","ritual":false,"concentration":false,"duration":"1 minute","damage":[{"atSlotLevel":{"1":"5d8"}}],"area":{"type":"sphere","size":20}}},{"id":"srd:spell:sleet-storm","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Sleet Storm","description":"Until the spell ends, freezing rain and sleet fall in a 20-foot-tall cylinder with a 40-foot radius centered on a point you choose within range. The area is heavily obscured, and exposed flames in the area are doused.\\n\\nThe ground in the area is covered with slick ice, making it difficult terrain. When a creature enters the spell's area for the first time on a turn or starts its turn there, it must make a dexterity saving throw. On a failed save, it falls prone.\\n\\nIf a creature is concentrating in the spell's area, the creature must make a successful constitution saving throw against your spell save DC or lose concentration."},"it":{"name":"Tempesta di nevischio","description":"Fino al termine dell'incantesimo, una pioggia gelida mista a nevischio cade in un cilindro, alto 6 metri e con raggio di 12 metri, centrato in un punto a scelta dell'incantatore entro gittata. L'area è pesantemente oscurata e le fiamme libere al suo interno vengono estinte.\\n\\nIl terreno nell'area è ricoperto di ghiaccio scivoloso che lo rende terreno difficile. Quando una creatura entra nell'area dell'incantesimo per la prima volta in un turno o inizia il suo turno qui, deve superare un tiro salvezza su Destrezza. Se lo fallisce, cade a terra prona.\\n\\nSe una creatura si sta concentrando nell'area dell'incantesimo, deve superare un tiro salvezza su Costituzione contro la CD del tiro salvezza sull'incantesimo o perde la concentrazione.","castingTime":"1 azione","range":"45 metri","duration":"Concentrazione, fino a 1 minuto","material":"un pizzico di polvere e qualche goccia d'acqua"}},"data":{"level":3,"school":"srd:rule:school-conjuration","classes":["srd:class:druid","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"150 feet","components":["V","S","M"],"material":"A pinch of dust and a few drops of water.","ritual":false,"concentration":true,"duration":"Up to 1 minute","area":{"type":"cylinder","size":40}}},{"id":"srd:spell:slow","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Slow","description":"You alter time around up to six creatures of your choice in a 40-foot cube within range. Each target must succeed on a wisdom saving throw or be affected by this spell for the duration.\\n\\nAn affected target's speed is halved, it takes a -2 penalty to AC and dexterity saving throws, and it can't use reactions. On its turn, it can use either an action or a bonus action, not both. Regardless of the creature's abilities or magic items, it can't make more than one melee or ranged attack during its turn.\\n\\nIf the creature attempts to cast a spell with a casting time of 1 action, roll a d20. On an 11 or higher, the spell doesn't take effect until the creature's next turn, and the creature must use its action on that turn to complete the spell. If it can't, the spell is wasted.\\n\\nA creature affected by this spell makes another wisdom saving throw at the end of its turn. On a successful save, the effect ends for it."},"it":{"name":"Lentezza","description":"L'incantatore altera il tempo intorno a un massimo di sei creature a sua scelta all'interno in un cubo di 12 metri entro gittata. Ogni bersaglio deve superare un tiro salvezza su Saggezza, altrimenti è influenzato da questo incantesimo per tutta la sua durata.\\n\\nUn bersaglio influenzato subisce una penalità di -2 alla CA e ai tiri salvezza su Destrezza, non può usare reazioni e la sua velocità è dimezzata. Nel proprio turno, può usare un'azione o un'azione bonus, ma non entrambe. A prescindere dalle sue capacità o oggetti magici, la creatura non può effettuare più di un attacco in mischia o a distanza durante il suo turno.\\n\\nSe la creatura tenta di lanciare un incantesimo con un tempo di lancio di 1 azione, deve tirare un d20. Con un risultato pari o superiore a 11, l'incantesimo non ha effetto fino al turno successivo della creatura, che deve usare una sua azione per completare l'incantesimo. Se non può farlo, l'incantesimo viene sprecato.\\n\\nUna creatura influenzata da questo incantesimo deve effettuare un altro tiro salvezza su Saggezza al termine del suo turno. In caso di successo, l'effetto svanisce.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 1 minuto","material":"una goccia di melassa"}},"data":{"level":3,"school":"srd:rule:school-transmutation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"120 feet","components":["V","S","M"],"material":"A drop of molasses.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"wis","onSuccess":"none"},"area":{"type":"cube","size":40}}},{"id":"srd:spell:spare-the-dying","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Spare the Dying","description":"You touch a living creature that has 0 hit points. The creature becomes stable. This spell has no effect on undead or constructs."},"it":{"name":"Salvare i morenti","description":"L'incantatore tocca una creatura vivente con 0 punti ferita che diventa stabile. Questo incantesimo non ha effetto sui non morti o sui costrutti.","castingTime":"1 azione","range":"Contatto","duration":"Istantanea"}},"data":{"level":0,"school":"srd:rule:school-necromancy","classes":["srd:class:cleric"],"subclasses":[],"castingTime":"1 action","range":"Touch","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:speak-with-animals","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Speak with Animals","description":"You gain the ability to comprehend and verbally communicate with beasts for the duration. The knowledge and awareness of many beasts is limited by their intelligence, but at a minimum, beasts can give you information about nearby locations and monsters, including whatever they can perceive or have perceived within the past day. You might be able to persuade a beast to perform a small favor for you, at the GM's discretion."},"it":{"name":"Parlare con gli animali","description":"L'incantatore ottiene la capacità di comprendere le bestie e comunicare verbalmente con loro per la durata dell'incantesimo. Le conoscenze e la consapevolezza di molte bestie sono limitate alla loro intelligenza, ma quantomeno l'incantatore può apprendere da loro informazioni sui luoghi e sui mostri nelle vicinanze, o su ciò che esse sono in grado di percepire o hanno percepito nell'ultimo giorno. L'incantatore potrebbe anche persuadere una bestia a fargli un piccolo favore, a discrezione del GM.","castingTime":"1 azione","range":"Incantatore","duration":"10 minuti"}},"data":{"level":1,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:druid","srd:class:ranger"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":true,"concentration":false,"duration":"10 minutes"}},{"id":"srd:spell:speak-with-dead","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Speak with Dead","description":"You grant the semblance of life and intelligence to a corpse of your choice within range, allowing it to answer the questions you pose. The corpse must still have a mouth and can't be undead. The spell fails if the corpse was the target of this spell within the last 10 days.\\n\\nUntil the spell ends, you can ask the corpse up to five questions. The corpse knows only what it knew in life, including the languages it knew. Answers are usually brief, cryptic, or repetitive, and the corpse is under no compulsion to offer a truthful answer if you are hostile to it or it recognizes you as an enemy. This spell doesn't return the creature's soul to its body, only its animating spirit. Thus, the corpse can't learn new information, doesn't comprehend anything that has happened since it died, and can't speculate about future events."},"it":{"name":"Parlare con i morti","description":"L'incantatore conferisce una parvenza di vita e di intelligenza a un cadavere a sua scelta situato entro gittata, permettendogli di rispondere alle domande che gli vengono poste. Il cadavere deve avere ancora una bocca e non può essere un non morto. L'incantesimo fallisce se il cadavere è già stato il bersaglio di questo incantesimo negli ultimi 10 giorni.\\n\\nFino al termine dell'incantesimo, l'incantatore può porre al cadavere un massimo di cinque domande. Il cadavere conosce solo quello che sapeva in vita, inclusi i linguaggi. Generalmente, le risposte sono brevi, criptiche o ripetitive e il cadavere non è obbligato a offrire una risposta sincera se l'incantatore gli è ostile o se il cadavere lo riconosce come nemico. Questo incantesimo non riporta l'anima della creatura nel suo corpo, solamente lo spirito animante. Perciò il cadavere non può apprendere nuove informazioni, non conosce nulla di ciò che è accaduto dopo la sua morte e non può speculare sugli eventi futuri.","castingTime":"1 azione","range":"3 metri","duration":"10 minuti","material":"incenso bruciato"}},"data":{"level":3,"school":"srd:rule:school-necromancy","classes":["srd:class:bard","srd:class:cleric"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"10 feet","components":["V","S","M"],"material":"Burning incense.","ritual":false,"concentration":false,"duration":"10 minutes"}},{"id":"srd:spell:speak-with-plants","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Speak with Plants","description":"You imbue plants within 30 feet of you with limited sentience and animation, giving them the ability to communicate with you and follow your simple commands. You can question plants about events in the spell's area within the past day, gaining information about creatures that have passed, weather, and other circumstances.\\n\\nYou can also turn difficult terrain caused by plant growth (such as thickets and undergrowth) into ordinary terrain that lasts for the duration. Or you can turn ordinary terrain where plants are present into difficult terrain that lasts for the duration, causing vines and branches to hinder pursuers, for example.\\n\\nPlants might be able to perform other tasks on your behalf, at the GM's discretion. The spell doesn't enable plants to uproot themselves and move about, but they can freely move branches, tendrils, and stalks.\\n\\nIf a plant creature is in the area, you can communicate with it as if you shared a common language, but you gain no magical ability to influence it.\\n\\nThis spell can cause the plants created by the entangle spell to release a restrained creature."},"it":{"name":"Parlare con i vegetali","description":"L'incantatore infonde nei vegetali entro 9 metri da sé una parvenza di animazione e di volontà, donando loro l'abilità di comunicare con lui e di seguire dei comandi semplici. Può interrogare i vegetali sugli eventi avvenuti nell'area dell'incantesimo nella giornata passata, ottenere informazioni riguardo alle creature transitate al suo interno, al clima e ad altre circostanze.\\n\\nPer la durata dell'incantesimo, l'incantatore può anche trasformare un terreno difficile a causa della crescita vegetale (come per esempio arbusti e sottobosco) in un terreno normale. In alternativa può trasformare un terreno normale dove siano presenti dei vegetali in un terreno difficile, ordinando per esempio a rampicanti e rami di ostacolare degli inseguitori.\\n\\nI vegetali potrebbero essere in grado di effettuare altri compiti per conto dell'incantatore, a discrezione del GM. L'incantesimo non consente alle piante di sradicarsi e di deambulare, ma consente loro di muovere liberamente rami, rampicanti e viticci.\\n\\nSe una creatura vegetale si trova nell'area, l'incantatore può comunicarci come se entrambi condividessero una lingua comune, ma non ottiene alcuna capacità magica di influenzarla.\\n\\nQuesto incantesimo può fare in modo che i vegetali creati con un incantesimo intralciare liberino una creatura trattenuta.","castingTime":"1 azione","range":"Incantatore (raggio di 9 metri)","duration":"10 minuti"}},"data":{"level":3,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:druid","srd:class:ranger"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":false,"concentration":false,"duration":"10 minutes","area":{"type":"sphere","size":30}}},{"id":"srd:spell:spider-climb","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Spider Climb","description":"Until the spell ends, one willing creature you touch gains the ability to move up, down, and across vertical surfaces and upside down along ceilings, while leaving its hands free. The target also gains a climbing speed equal to its walking speed."},"it":{"name":"Movimenti del ragno","description":"Fino al termine dell'incantesimo, una creatura consenziente toccata dall'incantatore ottiene la capacità di muoversi verticalmente e orizzontalmente sulle pareti e a testa in giù sui soffitti, mantenendo le mani libere. Il bersaglio ottiene inoltre una velocità di scalare pari alla sua velocità base sul terreno.","castingTime":"1 azione","range":"Contatto","duration":"Concentrazione, fino a 1 ora","material":"una goccia di bitume e un ragno"}},"data":{"level":2,"school":"srd:rule:school-transmutation","classes":["srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A drop of bitumen and a spider.","ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:spike-growth","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Spike Growth","description":"The ground in a 20-foot radius centered on a point within range twists and sprouts hard spikes and thorns. The area becomes difficult terrain for the duration. When a creature moves into or within the area, it takes 2d4 piercing damage for every 5 feet it travels.\\n\\nThe transformation of the ground is camouflaged to look natural. Any creature that can't see the area at the time the spell is cast can make a Wisdom (Perception) check against your spell save DC to recognize the terrain as hazardous before entering it."},"it":{"name":"Crescita di spine","description":"Spine e spuntoni nascono dal terreno entro un raggio di 6 metri centrato su un punto entro gittata. Per tutta la durata dell'azione, l'area diventa terreno difficile. Quando una creatura entra nell'area o si muove al suo interno, subisce 2d4 danni perforanti ogni 1,5 metri di movimento.\\n\\nLa trasformazione del terreno è mimetizzata in modo da sembrare naturale. Qualsiasi creatura che non stesse osservando l'area al momento del lancio dell'incantesimo deve effettuare una prova di Saggezza (Percezione) contro la CD del tiro salvezza sull'incantesimo per riconoscere la pericolosità del terreno prima di entrarvi.","castingTime":"1 azione","range":"45 metri","duration":"Concentrazione, fino a 10 minuti","material":"sette spine aguzze o sette rametti appuntiti"}},"data":{"level":2,"school":"srd:rule:school-transmutation","classes":["srd:class:druid","srd:class:ranger"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"150 feet","components":["V","S","M"],"material":"Seven sharp thorns or seven small twigs, each sharpened to a point.","ritual":false,"concentration":true,"duration":"Up to 10 minutes","area":{"type":"cylinder","size":20}}},{"id":"srd:spell:spirit-guardians","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Spirit Guardians","description":"You call forth spirits to protect you. They flit around you to a distance of 15 feet for the duration. If you are good or neutral, their spectral form appears angelic or fey (your choice). If you are evil, they appear fiendish.\\n\\nWhen you cast this spell, you can designate any number of creatures you can see to be unaffected by it. An affected creature's speed is halved in the area, and when the creature enters the area for the first time on a turn or starts its turn there, it must make a wisdom saving throw. On a failed save, the creature takes 3d8 radiant damage (if you are good or neutral) or 3d8 necrotic damage (if you are evil). On a successful save, the creature takes half as much damage.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d8 for each slot level above 3rd."},"it":{"name":"Guardiani spirituali","description":"L'incantatore chiama a sé degli spiriti che lo proteggano. Gli spiriti fluttuano attorno a lui a una distanza di 4,5 metri per la durata dell'incantesimo. Se l'incantatore è buono o neutrale, la loro forma spettrale appare angelica o fatata (a scelta dell'incantatore). Se è malvagio, appaiono come demoniaci.\\n\\nQuando l'incantatore lancia questo incantesimo, può indicare un qualsiasi numero di creature, che è in grado di vedere, che non ne saranno influenzate. La velocità di una creatura influenzata viene dimezzata all'interno dell'area e quando essa vi entra per la prima volta in un turno o vi inizia il proprio turno, deve effettuare un tiro salvezza su Saggezza. Se lo fallisce, subisce 3d8 danni radiosi (se l'incantatore è buono o neutrale) o 3d8 danni necrotici (se è malvagio), In caso di successo, subisce invece soltanto la metà di quei danni.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 3°.","castingTime":"1 azione","range":"Incantatore (raggio di 4,5 metri)","duration":"Concentrazione, fino a 10 minuti","material":"un simbolo sacro"}},"data":{"level":3,"school":"srd:rule:school-conjuration","classes":["srd:class:cleric"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A holy symbol.","ritual":false,"concentration":true,"duration":"Up to 10 minutes"}},{"id":"srd:spell:spiritual-weapon","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Spiritual Weapon","description":"You create a floating, spectral weapon within range that lasts for the duration or until you cast this spell again. When you cast the spell, you can make a melee spell attack against a creature within 5 feet of the weapon. On a hit, the target takes force damage equal to 1d8 + your spellcasting ability modifier.\\n\\nAs a bonus action on your turn, you can move the weapon up to 20 feet and repeat the attack against a creature within 5 feet of it.\\n\\nThe weapon can take whatever form you choose. Clerics of deities who are associated with a particular weapon (as St. Cuthbert is known for his mace and Thor for his hammer) make this spell's effect resemble that weapon.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for every two slot levels above the 2nd."},"it":{"name":"Arma spirituale","description":"L'incantatore crea entro gittata un'arma fluttuante spettrale che permane per la durata dell'incantesimo o finché l'incantatore non lo lancia di nuovo. Puoi effettuare un attacco in mischia con questo incantesimo contro una creatura entro 1,5 metri dall'arma. Se il colpo va a segno, il bersaglio subisce 1d8 danni da forza + il modificatore di caratteristica da incantatore.\\n\\nCome azione bonus nel suo turno, l'incantatore può muovere l'arma di un massimo di 6 metri e ripetere l'attacco contro una creatura situata entro 1,5 metri da essa.\\n\\nL'arma può assumere la forma che l'incantatore preferisce. I chierici di una divinità associata a un tipo particolare di arma (come per esempio St. Cuthbert, noto per la sua mazza, o Thor per il suo martello) con questo incantesimo creeranno delle armi somiglianti a quelle della loro divinità.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, i danni aumentano di 1d8 per ogni due slot di livello superiore al 2°.","castingTime":"1 azione bonus","range":"18 metri","duration":"1 minuto"}},"data":{"level":2,"school":"srd:rule:school-evocation","classes":["srd:class:cleric"],"subclasses":["srd:subclass:lore","srd:subclass:life"],"castingTime":"1 bonus action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"1 minute","damage":[{"type":"srd:rule:damage-force","atSlotLevel":{"2":"1d8 + MOD","3":"1d8 + MOD","4":"2d8 + MOD","5":"2d8 + MOD","6":"3d8 + MOD","7":"3d8 + MOD","8":"4d8 + MOD","9":"4d8 + MOD"}}],"attackType":"melee"}},{"id":"srd:spell:stinking-cloud","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Stinking Cloud","description":"You create a 20-foot-radius sphere of yellow, nauseating gas centered on a point within range. The cloud spreads around corners, and its area is heavily obscured. The cloud lingers in the air for the duration.\\n\\nEach creature that is completely within the cloud at the start of its turn must make a constitution saving throw against poison. On a failed save, the creature spends its action that turn retching and reeling. Creatures that don't need to breathe or are immune to poison automatically succeed on this saving throw.\\n\\nA moderate wind (at least 10 miles per hour) disperses the cloud after 4 rounds. A strong wind (at least 20 miles per hour) disperses it after 1 round."},"it":{"name":"Nube maleodorante","description":"L'incantatore genera una sfera di gas nauseante giallastro del raggio di 6 metri centrata su un punto entro gittata. La nuvola si estende intorno agli angoli, la sua area è pesantemente oscurata e permane nell'aria per tutta la durata dell'incantesimo.\\n\\nOgni creatura che si trova completamente all'interno della nuvola all'inizio del proprio turno deve effettuare un tiro salvezza su Costituzione contro il veleno. Se lo fallisce, è scossa dai conati e usa la sua azione di quel turno per vomitare. Le creature che non hanno bisogno di respirare o sono immuni al veleno superano automaticamente questo tiro salvezza.\\n\\nUn vento moderato (almeno 15 km orari) disperde la nuvola dopo 4 round. Un vento forte (almeno 30 km orari) disperde la nuvola dopo 1 round.","castingTime":"1 azione","range":"27 metri","duration":"Concentrazione, fino a 1 minuto","material":"un uovo marcio o alcune foglie di cavolo puzzola"}},"data":{"level":3,"school":"srd:rule:school-conjuration","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land","srd:subclass:fiend"],"castingTime":"1 action","range":"90 feet","components":["V","S","M"],"material":"A rotten egg or several skunk cabbage leaves.","ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"con","onSuccess":"none"},"area":{"type":"sphere","size":20}}},{"id":"srd:spell:stone-shape","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Stone Shape","description":"You touch a stone object of Medium size or smaller or a section of stone no more than 5 feet in any dimension and form it into any shape that suits your purpose. So, for example, you could shape a large rock into a weapon, idol, or coffer, or make a small passage through a wall, as long as the wall is less than 5 feet thick. You could also shape a stone door or its frame to seal the door shut. The object you create can have up to two hinges and a latch, but finer mechanical detail isn't possible."},"it":{"name":"Scolpire pietra","description":"L'incantatore tocca un oggetto di pietra di taglia Media o inferiore, oppure una sezione di pietra non più grande di 1,5 metri in ogni dimensione, modellandola nella forma che desidera. Potrebbe, per esempio, modellare una grossa roccia in un'arma, un idolo o uno scrigno, oppure aprire un piccolo passaggio in una parete, purché essa non sia spessa più di 1,5 metri. L'incantatore può anche modellare una porta di pietra o i suoi stipiti per sigillarla. L'oggetto creato può avere un massimo di due cardini e una chiusura, ma non può essere dotato di meccanismi più raffinati.","castingTime":"1 azione","range":"Contatto","duration":"Istantanea","material":"argilla morbida, che deve essere plasmata nella forma dell'oggetto desiderato"}},"data":{"level":4,"school":"srd:rule:school-transmutation","classes":["srd:class:cleric","srd:class:druid","srd:class:wizard"],"subclasses":["srd:subclass:land"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"Soft clay, to be crudely worked into the desired shape for the stone object.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:stoneskin","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Stoneskin","description":"This spell turns the flesh of a willing creature you touch as hard as stone. Until the spell ends, the target has resistance to nonmagical bludgeoning, piercing, and slashing damage."},"it":{"name":"Pelle di pietra","description":"Questo incantesimo rende la pelle di una creatura consenziente dura come la pietra. Fino al termine dell'incantesimo, il bersaglio è resistente ai danni contundenti, perforanti e taglienti non magici.","castingTime":"1 azione","range":"Contatto","duration":"Concentrazione, fino a 1 ora","material":"polvere di diamante del valore di 100 mo, che l'incantesimo consuma"}},"data":{"level":4,"school":"srd:rule:school-abjuration","classes":["srd:class:druid","srd:class:ranger","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:land"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"Diamond dust worth 100 gp, which the spell consumes.","ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:storm-of-vengeance","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Storm of Vengeance","description":"A churning storm cloud forms, centered on a point you can see and spreading to a radius of 360 feet. Lightning flashes in the area, thunder booms, and strong winds roar. Each creature under the cloud (no more than 5,000 feet beneath the cloud) when it appears must make a constitution saving throw. On a failed save, a creature takes 2d6 thunder damage and becomes deafened for 5 minutes.\\n\\nEach round you maintain concentration on this spell, the storm produces additional effects on your turn.\\n\\n***Round 2.*** Acidic rain falls from the cloud. Each creature and object under the cloud takes 1d6 acid damage.\\n\\n***Round 3.*** You call six bolts of lightning from the cloud to strike six creatures or objects of your choice beneath the cloud. A given creature or object can't be struck by more than one bolt. A struck creature must make a dexterity saving throw. The creature takes 10d6 lightning damage on a failed save, or half as much damage on a successful one.\\n\\n***Round 4.*** Hailstones rain down from the cloud. Each creature under the cloud takes 2d6 bludgeoning damage.\\n\\n***Round 5-10.*** Gusts and freezing rain assail the area under the cloud. The area becomes difficult terrain and is heavily obscured. Each creature there takes 1d6 cold damage. Ranged weapon attacks in the area are impossible. The wind and rain count as a severe distraction for the purposes of maintaining concentration on spells. Finally, gusts of strong wind (ranging from 20 to 50 miles per hour) automatically disperse fog, mists, and similar phenomena in the area, whether mundane or magical."},"it":{"name":"Tempesta di vendetta","description":"L'incantatore genera una minacciosa nube tempestosa che si espande fino a una raggio di 110 metri centrata su un punto che è in grado di vedere. Sull'area si abbattono tuoni, fulmini e venti forti. Ogni creatura sotto la nube (a non più di 1,5 km sotto di essa) nel momento in cui compare deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 2d6 danni da tuono e diventa assordata per 5 minuti.\\n\\nPer ogni round in cui l'incantatore mantiene la concentrazione su questo incantesimo, la tempesta produce effetti differenti nel suo turno.\\n\\n***Round 2.*** Dalla nube cade pioggia acida. Ogni creatura e ogni oggetto sotto di essa subisce 1d6 danni da acido.\\n\\n***Round 3.*** L'incantatore invoca sei fulmini che scendono dalla nube e colpiscono sei creature o oggetti a sua scelta situati sotto di essa. Una creatura o un oggetto particolare non può essere colpito da più di un fulmine. Una creatura colpita deve effettuare un tiro salvezza su Destrezza e subisce 10d6 danni da fulmine in caso di fallimento, o la metà dei danni in caso di successo.\\n\\n***Round 4.*** Dalla nube si rovescia una violenta grandinata e ogni creatura sotto di essa subisce 2d6 danni contundenti.\\n\\n***Round 5–10.*** L'area sotto la nube è attraversata da raffiche di vento e pioggia gelida, diventa terreno difficile ed è pesantemente oscurata. Ogni creatura sotto la nube subisce 1d6 danni da freddo. Gli attacchi con le armi a distanza all'interno dell'area sono impossibili e il vento e la pioggia contano come forte distrazione al fine di mantenere la concentrazione sugli incantesimi. Infine, le raffiche di vento (variabili da 30 a 75 km orari) disperdono automaticamente nebbia, foschia e fenomeni simili nell'area, sia comuni che magici.","castingTime":"1 azione","range":"Vista","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":9,"school":"srd:rule:school-conjuration","classes":["srd:class:druid"],"subclasses":[],"castingTime":"1 action","range":"Sight","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","damage":[{"type":"srd:rule:damage-thunder","atSlotLevel":{"9":"2d6"}}],"savingThrow":{"ability":"con","onSuccess":"none"},"area":{"type":"sphere","size":360}}},{"id":"srd:spell:suggestion","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Suggestion","description":"You suggest a course of activity (limited to a sentence or two) and magically influence a creature you can see within range that can hear and understand you. Creatures that can't be charmed are immune to this effect. The suggestion must be worded in such a manner as to make the course of action sound reasonable. Asking the creature to stab itself, throw itself onto a spear, immolate itself, or do some other obviously harmful act ends the spell.\\n\\nThe target must make a wisdom saving throw. On a failed save, it pursues the course of action you described to the best of its ability. The suggested course of action can continue for the entire duration. If the suggested activity can be completed in a shorter time, the spell ends when the subject finishes what it was asked to do.\\n\\nYou can also specify conditions that will trigger a special activity during the duration. For example, you might suggest that a knight give her warhorse to the first beggar she meets. If the condition isn't met before the spell expires, the activity isn't performed.\\n\\nIf you or any of your companions damage the target, the spell ends."},"it":{"name":"Suggestione","description":"L'incantatore suggerisce un corso d'azione da intraprendere (limitandosi a una o due frasi) influenzando magicamente una creatura entro gittata che è in grado di vedere. La creatura deve essere in grado di sentire l'incantatore e di comprendere le sue parole. Le creature che non possono essere affascinate sono immuni a questo effetto. La suggestione deve essere formulata in modo che il corso d'azione appaia ragionevole: chiedere a una creatura di pugnalarsi, gettarsi su una lancia, immolarsi o compiere altri atti palesemente autolesionistici pone termine all'incantesimo.\\n\\nIl bersaglio deve effettuare un tiro salvezza su Saggezza. Se lo fallisce, deve perseguire il corso d'azione descritto dall'incantatore al meglio delle sue capacità. Tale corso d'azione può proseguire per l'intera durata dell'incantesimo. Se l'attività suggerita può essere completata in un periodo di tempo più breve, l'incantesimo termina quando il soggetto conclude ciò che gli è stato chiesto di fare.\\n\\nMentre l'incantesimo è attivo, l'incantatore può anche specificare delle condizioni che inneschino un'attività speciale. Per esempio, potrebbe suggerire che una condottiera ceda il suo cavallo da guerra al primo mendicante che incontra. Se la condizione non viene soddisfatta prima che l'incantesimo termini, l'attività non viene eseguita.\\n\\nSe l'incantatore o uno dei suoi compagni infliggono danni al bersaglio, l'incantesimo termina.","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 8 ore","material":"una lingua di serpente e un elemento a scelta tra un frammento di alveare e una goccia di olio dolce"}},"data":{"level":2,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"30 feet","components":["V","M"],"material":"A snake's tongue and either a bit of honeycomb or a drop of sweet oil.","ritual":false,"concentration":true,"duration":"Up to 8 hours","savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:sunbeam","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Sunbeam","description":"A beam of brilliant light flashes out from your hand in a 5-foot-wide, 60-foot-long line. Each creature in the line must make a constitution saving throw. On a failed save, a creature takes 6d8 radiant damage and is blinded until your next turn. On a successful save, it takes half as much damage and isn't blinded by this spell. Undead and oozes have disadvantage on this saving throw.\\n\\nYou can create a new line of radiance as your action on any turn until the spell ends.\\n\\nFor the duration, a mote of brilliant radiance shines in your hand. It sheds bright light in a 30-foot radius and dim light for an additional 30 feet. This light is sunlight."},"it":{"name":"Bagliore solare","description":"Un raggio di luce brillante si sprigiona dalla mano dell'incantatore in una linea lunga 18 metri e larga 1,5 metri. Ogni creatura entro la linea deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 6d8 danni radiosi e rimane accecata fino al turno successivo dell'incantatore. In caso di successo, subisce invece solo la metà dei danni e non viene accecata dall'incantesimo. Non morti e melme subiscono svantaggio a questo tiro salvezza.\\n\\nCon un'azione, l'incantatore può creare una nuova linea di luce in qualsiasi turno fino al termine dell'incantesimo.\\n\\nPer la sua durata, una scintilla di luce radiosa risplende nella mano dell'incantatore ed emana luce intensa in un raggio di 9 metri e luce fioca per ulteriori 9 metri. Questa luce è considerata luce solare.","castingTime":"1 azione","range":"Incantatore (linea di 18 metri)","duration":"Concentrazione, fino a 1 minuto","material":"una lente d'ingrandimento"}},"data":{"level":6,"school":"srd:rule:school-evocation","classes":["srd:class:druid","srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","components":["V","S","M"],"material":"A magnifying glass.","ritual":false,"concentration":true,"duration":"Up to 1 minute","damage":[{"type":"srd:rule:damage-radiant","atSlotLevel":{"6":"6d8"}}],"savingThrow":{"ability":"con","onSuccess":"half"},"area":{"type":"line","size":60}}},{"id":"srd:spell:sunburst","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Sunburst","description":"Brilliant sunlight flashes in a 60-foot radius centered on a point you choose within range. Each creature in that light must make a constitution saving throw. On a failed save, a creature takes 12d6 radiant damage and is blinded for 1 minute. On a successful save, it takes half as much damage and isn't blinded by this spell. Undead and oozes have disadvantage on this saving throw.\\n\\nA creature blinded by this spell makes another constitution saving throw at the end of each of its turns. On a successful save, it is no longer blinded.\\n\\nThis spell dispels any darkness in its area that was created by a spell."},"it":{"name":"Esplosione solare","description":"Una radiosa luce solare splende in un raggio di 18 metri, centrato su un punto entro gittata a scelta dell'incantatore. Ogni creatura toccata dalla luce deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 12d6 danni radiosi e rimane accecata per 1 minuto. In caso di successo, subisce invece solo la metà dei danni e non viene accecata dall'incantesimo. Non morti e melme subiscono svantaggio a questo tiro salvezza.\\n\\nUna creatura accecata da questo incantesimo effettua un altro tiro salvezza su Costituzione al termine di ogni suo turno. In caso di successo, non è più accecata.\\n\\nQuesto incantesimo dissolve qualsiasi oscurità creata da un incantesimo presente nell'area.","castingTime":"1 azione","range":"45 metri","duration":"Istantanea","material":"fuoco e un frammento di pietra del sole"}},"data":{"level":8,"school":"srd:rule:school-evocation","classes":["srd:class:druid","srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"150 feet","components":["V","S","M"],"material":"Fire and a piece of sunstone.","ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-radiant","atSlotLevel":{"8":"12d6"}}],"savingThrow":{"ability":"con","onSuccess":"half"},"area":{"type":"cylinder","size":60}}},{"id":"srd:spell:symbol","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Symbol","description":"When you cast this spell, you inscribe a harmful glyph either on a surface (such as a section of floor, a wall, or a table) or within an object that can be closed to conceal the glyph (such as a book, a scroll, or a treasure chest). If you choose a surface, the glyph can cover an area of the surface no larger than 10 feet in diameter. If you choose an object, that object must remain in its place; if the object is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered.\\n\\nThe glyph is nearly invisible, requiring an Intelligence (Investigation) check against your spell save DC to find it.\\n\\nYou decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, the most typical triggers include touching or stepping on the glyph, removing another object covering it, approaching within a certain distance of it, or manipulating the object that holds it. For glyphs inscribed within an object, the most common triggers are opening the object, approaching within a certain distance of it, or seeing or reading the glyph.\\n\\nYou can further refine the trigger so the spell is activated only under certain circumstances or according to a creature's physical characteristics (such as height or weight), or physical kind (for example, the ward could be set to affect hags or shapechangers). You can also specify creatures that don't trigger the glyph, such as those who say a certain password.\\n\\nWhen you inscribe the glyph, choose one of the options below for its effect. Once triggered, the glyph glows, filling a 60-foot-radius sphere with dim light for 10 minutes, after which time the spell ends. Each creature in the sphere when the glyph activates is targeted by its effect, as is a creature that enters the sphere for the first time on a turn or ends its turn there.\\n\\n***Death.*** Each target must make a constitution saving throw, taking 10d 10 necrotic damage on a failed save, or half as much damage on a successful save.\\n\\n***Discord.*** Each target must make a constitution saving throw. On a failed save, a target bickers and argues with other creatures for 1 minute. During this time, it is incapable of meaningful communication and has disadvantage on attack rolls and ability checks.\\n\\n***Fear.*** Each target must make a wisdom saving throw and becomes frightened for 1 minute on a failed save. While frightened, the target drops whatever it is holding and must move at least 30 feet away from the glyph on each of its turns, if able.\\n\\n***Hopelessness.*** Each target must make a charisma saving throw. On a failed save, the target is overwhelmed with despair for 1 minute. During this time, it can't attack or target any creature with harmful abilities, spells, or other magical effects.\\n\\n***Insanity.*** Each target must make an intelligence saving throw. On a failed save, the target is driven insane for 1 minute. An insane creature can't take actions, can't understand what other creatures say, can't read, and speaks only in gibberish. The GM controls its movement, which is erratic.\\n\\n***Pain.*** Each target must make a constitution saving throw and becomes incapacitated with excruciating pain for 1 minute on a failed save.\\n\\n***Sleep.*** Each target must make a wisdom saving throw and falls unconscious for 10 minutes on a failed save. A creature awakens if it takes damage or if someone uses an action to shake or slap it awake.\\n\\n***Stunning.*** Each target must make a wisdom saving throw and becomes stunned for 1 minute on a failed save."},"it":{"name":"Simbolo","description":"Quando lancia questo incantesimo, l'incantatore traccia un glifo nocivo su una superficie (come una sezione di pavimento, una parete o un tavolo) o, al fine di nasconderlo, all'interno di un oggetto che può essere chiuso (come un libro, una pergamena o un forziere del tesoro). Se sceglie una superficie, il glifo può coprire un'area massima del diametro di 3 metri. Se l'incantatore sceglie un oggetto, questo non deve essere spostato; se ciò avviene, una volta che l'oggetto si allontana per più di 3 metri dal luogo in cui è stato lanciato l'incantesimo, il glifo si infrange e l'incantesimo termina senza essere innescato.\\n\\nIl glifo è pressoché invisibile e per scorgerlo è necessario superare una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo.\\n\\nQuando questo incantesimo viene lanciato, l'incantatore decide cosa innesca il glifo. Nel caso di glifi tracciati su una superficie, gli inneschi più comuni includono: toccare o camminare su di essi, rimuovere un altro oggetto che li copre, avvicinarsi a una certa distanza da loro o manipolare gli oggetti su cui sono tracciati. Nel caso di glifi tracciati all'interno di un oggetto, gli inneschi più comuni sono: aprire l'oggetto, avvicinarsi a una certa distanza da esso, oppure vedere o leggere il glifo.\\n\\nL'incantatore può definire l'innesco in modo che l'incantesimo si attivi solamente in certe circostanze o in base a certe caratteristiche fisiche di una creatura (come peso o altezza) o al suo tipo (per esempio, la protezione potrebbe attivarsi solo contro megere o mutaforma). L'incantatore può inoltre specificare condizioni per evitare di innescare il glifo, come pronunciare una specifica parola d'ordine.\\n\\nQuando traccia il glifo, l'incantatore sceglie una delle seguenti opzioni per determinarne l'effetto. Una volta attivato, il glifo brilla, proiettando luce fioca in una sfera di 18 metri di raggio per 10 minuti, dopodiché l'incantesimo termina. Ogni creatura all'interno della sfera quando il glifo si attiva, oppure che entra nella sfera per la prima volta in un turno o termina qui il suo turno, ne subisce l'effetto.\\n\\n***Discordia.*** Ogni bersaglio deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, inizia a discutere e litigare con le altre creature per 1 minuto, durante il quale non è in grado di comunicare in modo significativo e subisce svantaggio ai tiri per colpire e alle prove di caratteristica.\\n\\n***Disperazione.*** Ogni bersaglio deve effettuare un tiro salvezza su Carisma. Se lo fallisce, è sopraffatto dalla disperazione per 1 minuto, durante il quale non può attaccare o bersagliare qualsiasi creatura con abilità, incantesimi o altri effetti magici nocivi.\\n\\n***Dolore.*** Ogni bersaglio deve superare un tiro salvezza su Costituzione, altrimenti diventa incapacitato a causa di dolori lancinanti per 1 minuto.\\n\\n***Morte.*** Ogni bersaglio deve effettuare un tiro salvezza su Costituzione, subendo 10d10 danni necrotici in caso di fallimento, o la metà dei danni in caso di successo.\\n\\n***Paura.*** Ogni bersaglio deve superare un tiro salvezza su Saggezza, altrimenti diventa spaventato per 1 minuto. Mentre è in questo stato, il bersaglio lascia cadere ciò che stava impugnando e, se ne è in grado, deve allontanarsi di almeno 9 metri dal glifo in ogni suo turno.\\n\\n***Pazzia.*** Ogni bersaglio deve effettuare un tiro salvezza su Intelligenza. Se lo fallisce, impazzisce per 1 minuto. Una creatura in questa condizione non può effettuare azioni, capire i discorsi altrui o leggere e si limita a farfugliare parole senza senso. Il GM ne controlla i movimenti, che sono imprevedibili.\\n\\n***Sonno.*** Ogni bersaglio deve superare un tiro salvezza su Saggezza, altrimenti cade privo di sensi per 10 minuti. Una creatura si risveglia se subisce danni o se qualcuno usa un'azione per scuoterla o schiaffeggiarla.\\n\\n***Stordimento.*** Ogni bersaglio deve superare un tiro salvezza su Saggezza, altrimenti diventa stordito per 1 minuto.","castingTime":"1 minuto","range":"Contatto","duration":"Finché non viene dissolto o innescato","material":"mercurio, fosforo e polvere di diamante e opale del valore totale di almeno 1.000 mo, che l'incantesimo consuma"}},"data":{"level":7,"school":"srd:rule:school-abjuration","classes":["srd:class:bard","srd:class:cleric","srd:class:wizard"],"subclasses":[],"castingTime":"1 minute","range":"Touch","components":["V","S","M"],"material":"Mercury, phosphorus, and powdered diamond and opal with a total value of at least 1,000 gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"Until dispelled","area":{"type":"cube","size":10}}},{"id":"srd:spell:telekinesis","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Telekinesis","description":"You gain the ability to move or manipulate creatures or objects by thought. When you cast the spell, and as your action each round for the duration, you can exert your will on one creature or object that you can see within range, causing the appropriate effect below. You can affect the same target round after round, or choose a new one at any time. If you switch targets, the prior target is no longer affected by the spell.\\n\\n***Creature.*** You can try to move a Huge or smaller creature. Make an ability check with your spellcasting ability contested by the creature's Strength check. If you win the contest, you move the creature up to 30 feet in any direction, including upward but not beyond the range of this spell. Until the end of your next turn, the creature is restrained in your telekinetic grip. A creature lifted upward is suspended in mid-air.\\n\\nOn subsequent rounds, you can use your action to attempt to maintain your telekinetic grip on the creature by repeating the contest.\\n\\n***Object.*** You can try to move an object that weighs up to 1,000 pounds. If the object isn't being worn or carried, you automatically move it up to 30 feet in any direction, but not beyond the range of this spell.\\n\\nIf the object is worn or carried by a creature, you must make an ability check with your spellcasting ability contested by that creature's Strength check. If you succeed, you pull the object away from that creature and can move it up to 30 feet in any direction but not beyond the range of this spell.\\n\\nYou can exert fine control on objects with your telekinetic grip, such as manipulating a simple tool, opening a door or a container, stowing or retrieving an item from an open container, or pouring the contents from a vial."},"it":{"name":"Telecinesi","description":"L'incantatore ottiene la capacità di spostare o manipolare creature e oggetti con la forza del pensiero. Al lancio e come sua azione ogni round per la durata dell'incantesimo, l'incantatore può esercitare la propria volontà su una creatura o un oggetto che è in grado di vedere entro gittata, provocando l'effetto appropriato di seguito. L'incantatore può influenzare lo stesso bersaglio in ogni round o sceglierne uno nuovo in ogni momento. Se cambia bersaglio, quello precedente non risentirà più degli effetti dell'incantesimo.\\n\\n***Creatura.*** L'incantatore può provare a spostare una creatura di taglia Enorme o inferiore, effettuando una prova di caratteristica con la propria caratteristica da incantatore contrapposta alla prova di Forza della creatura. Se vince la prova, l'incantatore sposta la creatura fino a 9 metri in ogni direzione, anche verticalmente, ma non oltre la gittata dell'incantesimo. Fino al termine del suo turno successivo, la creatura è trattenuta dalla morsa telecinetica e una creatura sollevata verticalmente rimane sospesa a mezz'aria.\\n\\nNei round successivi, l'incantatore può usare la sua azione per provare a mantenere la sua morsa telecinetica sulla creatura ripetendo la contesa.\\n\\n***Oggetto.*** L'incantatore può provare a muovere un oggetto che pesa al massimo 500 kg. Se esso non è indossato o trasportato, lo sposta automaticamente fino a 9 metri in qualsiasi direzione, ma non oltre la gittata dell'incantesimo.\\n\\nSe l'oggetto è indossato o trasportato da una creatura, l'incantatore deve effettuare una prova di caratteristica con la propria caratteristica da incantatore contrapposta alla prova di Forza della creatura. In caso di successo, l'incantatore allontana l'oggetto dalla creatura e può spostarlo fino a 9 metri in qualsiasi direzione, ma non oltre la gittata dell'incantesimo.\\n\\nCon la sua presa telecinetica, l'incantatore può esercitare un controllo più preciso sugli oggetti, come manipolare uno strumento semplice, aprire una porta o un contenitore, riporre o prelevare un oggetto da un contenitore aperto, oppure versare il contenuto di una fiala.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 10 minuti"}},"data":{"level":5,"school":"srd:rule:school-transmutation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 10 minutes","area":{"type":"sphere","size":30}}},{"id":"srd:spell:telepathic-bond","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Telepathic Bond","description":"You forge a telepathic link among up to eight willing creatures of your choice within range, psychically linking each creature to all the others for the duration. Creatures with Intelligence scores of 2 or less aren't affected by this spell.\\n\\nUntil the spell ends, the targets can communicate telepathically through the bond whether or not they have a common language. The communication is possible over any distance, though it can't extend to other planes of existence."},"it":{"name":"Legame telepatico","description":"L'incantatore stringe un legame telepatico con un massimo di otto creature consenzienti a sua scelta entro gittata, collegando mentalmente ogni creatura a tutte le altre per la durata dell'incantesimo. Le creature con un punteggio di Intelligenza pari o inferiore a 2 non sono influenzate da questo incantesimo.\\n\\nFino al termine dell'incantesimo, i bersagli possono comunicare telepaticamente attraverso il legame, a prescindere che abbiano un linguaggio comune. La comunicazione è possibile attraverso qualsiasi distanza, ma non può estendersi ad altri piani di esistenza.","castingTime":"1 azione","range":"9 metri","duration":"1 ora","material":"pezzi di gusci d'uovo di due tipi di creature diverse"}},"data":{"level":5,"school":"srd:rule:school-divination","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"Pieces of eggshell from two different kinds of creatures","ritual":true,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:teleport","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Teleport","description":"This spell instantly transports you and up to eight willing creatures of your choice that you can see within range, or a single object that you can see within range, to a destination you select. If you target an object, it must be able to fit entirely inside a 10-foot cube, and it can't be held or carried by an unwilling creature.\\n\\nThe destination you choose must be known to you, and it must be on the same plane of existence as you. Your familiarity with the destination determines whether you arrive there successfully. The GM rolls d100 and consults the table.\\n\\n| Familiarity | Mishap | Similar Area | Off Target | On Target |\\n\\n|---|---|---|---|---|\\n\\n| Permanent circle | -- | -- | -- | 01-100 |\\n\\n| Associated object | -- | -- | -- | 01-100 |\\n\\n| Very familiar | 01-05 | 06-13 | 14-24 | 25-100 |\\n\\n| Seen casually | 01-33 | 34-43 | 44-53 | 54-100 |\\n\\n| Viewed once | 01-43 | 44-53 | 54-73 | 74-100 |\\n\\n| Description | 01-43 | 44-53 | 54-73 | 74-100 |\\n\\n| False destination | 01-50 | 51-100 | -- | -- |\\n\\n***Familiarity.*** \\"Permanent circle\\" means a permanent teleportation circle whose sigil sequence you know.\\n\\n\\"Associated object\\" means that you possess an object taken from the desired destination within the last six months, such as a book from a wizard's library, bed linen from a royal suite, or a chunk of marble from a lich's secret tomb.\\n\\n\\"Very familiar\\" is a place you have been very often, a place you have carefully studied, or a place you can see when you cast the spell.\\n\\n\\"Seen casually\\" is someplace you have seen more than once but with which you aren't very familiar.\\n\\n\\"Viewed once\\" is a place you have seen once, possibly using magic.\\n\\n\\"Description\\" is a place whose location and appearance you know through someone else's description, perhaps from a map.\\n\\n\\"False destination\\" is a place that doesn't exist. Perhaps you tried to scry an enemy's sanctum but instead viewed an illusion, or you are attempting to teleport to a familiar location that no longer exists.\\n\\n***On Target.*** You and your group (or the target object) appear where you want to.\\n\\n***Off Target.*** You and your group (or the target object) appear a random distance away from the destination in a random direction. Distance off target is 1d10 x 1d10 percent of the distance that was to be traveled. For example, if you tried to travel 120 miles, landed off target, and rolled a 5 and 3 on the two d10s, then you would be off target by 15 percent, or 18 miles. The GM determines the direction off target randomly by rolling a d8 and designating 1 as north, 2 as northeast, 3 as east, and so on around the points of the compass.  If you were teleporting to a coastal city and wound up 18 miles out at sea, you could be in trouble.\\n\\n***Similar Area.*** You and your group (or the target object) wind up in a different area that's visually or thematically similar to the target area. If you are heading for your home laboratory, for example, you might wind up in another wizard's laboratory or in an alchemical supply shop that has many of the same tools and implements as your laboratory. Generally, you appear in the closest similar place, but since the spell has no range limit, you could conceivably wind up anywhere on the plane.\\n\\n***Mishap.*** The spell's unpredictable magic results in a difficult journey. Each teleporting creature (or the target object) takes 3d10 force damage, and the GM rerolls on the table to see where you wind up (multiple mishaps can occur, dealing damage each time)."},"it":{"name":"Teletrasporto","description":"Questo incantesimo teletrasporta immediatamente l'incantatore e un solo oggetto o un massimo di otto creature consenzienti da lui scelte, che si trovano entro gittata e che egli è in grado di vedere, fino a una destinazione a sua scelta. Se il bersaglio è un oggetto, questo deve poter essere contenuto in un cubo di 3 metri e non può essere impugnato o trasportato da una creatura non consenziente.\\n\\nLa destinazione scelta deve essere nota all'incantatore e deve trovarsi sul suo stesso piano di esistenza. La sua familiarità con la destinazione determina il successo del teletrasporto. Il GM tira un d100 e consulta la tabella.\\n\\n| Familiarità | Errore | Area simile | Fuori bersaglio | Sul bersaglio |\\n\\n|---|---|---|---|---|\\n\\n| Cerchio permanente | — | — | — | 01–100 |\\n\\n| Oggetto associato | — | — | — | 01–100 |\\n\\n| Molto familiare | 01–05 | 06–13 | 14–24 | 25–100 |\\n\\n| Visto occasionalmente | 01–33 | 34–43 | 44–53 | 54–100 |\\n\\n| Visto una volta | 01–43 | 44–53 | 54–73 | 74–100 |\\n\\n| Descrizione | 01–43 | 44–53 | 54–73 | 74–100 |\\n\\n| Falsa destinazione | 01–50 | 51–100 | — | — |\\n\\n***Familiarità.*** \\"Cerchio permanente\\" indica un cerchio di teletrasporto permanente di cui l'incantatore conosce la sequenza di sigilli. \\"Oggetto associato\\" indica che l'incantatore è in possesso di un oggetto prelevato alla destinazione desiderata da non più di sei mesi, come un libro della biblioteca di un mago, lenzuola di un alloggio reale o un frammento di marmo della tomba segreta di un lich.\\n\\n\\"Molto familiare\\" è un luogo che l'incantatore ha visitato molto spesso, un luogo che ha studiato con attenzione o un luogo che è in grado di vedere quando lancia l'incantesimo. \\"Visto occasionalmente\\" è un luogo che l'incantatore ha visto più di una volta ma che non gli è troppo familiare. \\"Visto una volta\\" è un luogo che ha visto una volta sola, probabilmente usando la magia. \\"Descrizione\\" è un luogo la cui ubicazione e apparenza sono noti all'incantatore solo attraverso la descrizione di qualcun altro o grazie a una mappa.\\n\\n\\"Falsa destinazione\\" è un luogo inesistente. Forse l'incantatore ha cercato di scrutare il rifugio segreto di un nemico ma ha visto invece un'illusione, oppure tenta di teletrasportarsi in un luogo familiare che non esiste più.\\n\\n***Sul bersaglio.*** L'incantatore e il suo gruppo (o l'oggetto bersaglio) compaiono dove desidera.\\n\\n***Fuori bersaglio.*** L'incantatore e il suo gruppo (o l'oggetto bersaglio) compaiono a una distanza casuale dalla destinazione in una direzione casuale. La distanza fuori bersaglio è 1d10 × 1d10 per cento della distanza da percorrere. Per esempio, se l'incantatore prova a viaggiare per 180 km, arriva fuori bersaglio e ottiene un 5 e un 3 su due d10, arriva fuori bersaglio del 15%, cioè di 27 km. Il GM determina la direzione fuori bersaglio tirando un d8, dove l'1 corrisponde al nord, il 2 al nord-est, il 3 all'est e così via a indicare tutti i punti cardinali. Se l'incantatore voleva teletrasportarsi in una città costiera e si ritrova invece 27 km al largo della costa, potrebbe essere nei guai.\\n\\n***Area simile.*** L'incantatore e il suo gruppo (o l'oggetto bersaglio) arrivano in un'area diversa che è visivamente o tematicamente simile all'area bersaglio. Per esempio, se è diretto nel suo laboratorio personale, potrebbe finire nel laboratorio di un altro mago o in un negozio di sostanze alchemiche che contiene molti strumenti e materiali simili a quelli nel suo laboratorio. In genere, l'incantatore appare nel luogo simile più vicino, ma dal momento che l'incantesimo non ha limiti di gittata, potrebbe comparire in un qualsiasi punto del piano.\\n\\n***Errore.*** La magia imprevedibile dell'incantesimo rende difficile il viaggio. Ogni creatura che si teletrasporta (o l'oggetto bersaglio) subisce 3d10 danni da forza e il GM lancia di nuovo sulla tabella per determinare dove arriverà (potrebbero verificarsi vari errori, nel qual caso i danni verranno inflitti ogni volta).","castingTime":"1 azione","range":"3 metri","duration":"Istantanea"}},"data":{"level":7,"school":"srd:rule:school-conjuration","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"10 feet","components":["V"],"ritual":false,"concentration":false,"duration":"Instantaneous","area":{"type":"cube","size":10}}},{"id":"srd:spell:teleportation-circle","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Teleportation Circle","description":"As you cast the spell, you draw a 10-foot-diameter circle on the ground inscribed with sigils that link your location to a permanent teleportation circle of your choice whose sigil sequence you know and that is on the same plane of existence as you. A shimmering portal opens within the circle you drew and remains open until the end of your next turn. Any creature that enters the portal instantly appears within 5 feet of the destination circle or in the nearest unoccupied space if that space is occupied.\\n\\nMany major temples, guilds, and other important places have permanent teleportation circles inscribed somewhere within their confines. Each such circle includes a unique sigil sequence--a string of magical runes arranged in a particular pattern. When you first gain the ability to cast this spell, you learn the sigil sequences for two destinations on the Material Plane, determined by the GM. You can learn additional sigil sequences during your adventures. You can commit a new sigil sequence to memory after studying it for 1 minute.\\n\\nYou can create a permanent teleportation circle by casting this spell in the same location every day for one year. You need not use the circle to teleport when you cast the spell in this way."},"it":{"name":"Cerchio di teletrasporto","description":"Quando lancia l'incantesimo, l'incantatore traccia un cerchio del diametro di 3 metri sul terreno dotato di sigilli che collegano il luogo in cui si trova a un cerchio di teletrasporto permanente a sua scelta, di cui conosce la sequenza di sigilli e che si trova sul suo stesso piano di esistenza. All'interno del cerchio tracciato si apre un portale scintillante che rimane aperto fino al termine del suo turno successivo. Qualsiasi creatura che entra nel portale appare immediatamente entro 1,5 metri dal cerchio di destinazione o nello spazio libero più vicino se tale spazio è occupato.\\n\\nMolti dei più grandi templi, gilde e altri luoghi importanti hanno cerchi di teletrasporto permanenti tracciati entro i loro confini. Ognuno di questi cerchi include una sequenza di sigilli unica: una serie di rune magiche disposte secondo uno schema particolare. Quando l'incantatore ottiene per la prima volta la capacità di lanciare questo incantesimo, apprende la sequenza di sigilli abbinata a due destinazioni situate sul Piano Materiale, determinate dal GM. Nel corso delle sue avventure può apprendere ulteriori sequenze di sigilli, imparando a memoria ciascuna di esse dopo 1 minuto di studio.\\n\\nL'incantatore può creare un cerchio di teletrasporto permanente lanciando questo incantesimo nello stesso luogo ogni giorno per un anno e, in quel momento, non è obbligato a usare il cerchio per teletrasportarsi.","castingTime":"1 minuto","range":"3 metri","duration":"1 round","material":"gessetti e inchiostri rari infusi di gemme preziose del valore di 50 mo, che l'incantesimo consuma"}},"data":{"level":5,"school":"srd:rule:school-conjuration","classes":["srd:class:bard","srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 minute","range":"10 feet","components":["V","M"],"material":"Rare chalks and inks infused with precious gems with 50 gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"1 round","area":{"type":"sphere","size":10}}},{"id":"srd:spell:thaumaturgy","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Thaumaturgy","description":"You manifest a minor wonder, a sign of supernatural power, within range. You create one of the following magical effects within range.\\n\\n- Your voice booms up to three times as loud as normal for 1 minute.\\n\\n- You cause flames to flicker, brighten, dim, or change color for 1 minute.\\n\\n- You cause harmless tremors in the ground for 1 minute.\\n\\n- You create an instantaneous sound that originates from a point of your choice within range, such as a rumble of thunder, the cry of a raven, or ominous whispers.\\n\\n- You instantaneously cause an unlocked door or window to fly open or slam shut.\\n\\n- You alter the appearance of your eyes for 1 minute.\\n\\nIf you cast this spell multiple times, you can have up to three of its 1-minute effects active at a time, and you can dismiss such an effect as an action."},"it":{"name":"Taumaturgia","description":"L'incantatore genera una meraviglia minore, una manifestazione di potere soprannaturale entro gittata. Crei uno degli effetti magici seguenti entro gittata:\\n\\n- La tua voce rimbomba con potenza tre volte superiore rispetto al normale per 1 minuto.\\n\\n- Fai in modo che una fiamma tremi, si intensifichi, si affievolisca o cambi colore per 1 minuto.\\n\\n- Generi un tremito innocuo sul terreno per 1 minuto.\\n\\n- Crei un suono improvviso che abbia origine da un punto entro gittata a tua scelta, come un rombo di tuono, il verso di un corvo o un mormorio sinistro.\\n\\n- Fai in modo che una porta o una finestra non chiusa a chiave si spalanchi o si chiuda di colpo da sola.\\n\\n- Alteri l'aspetto dei tuoi occhi per 1 minuto.\\n\\nSe lanci questo incantesimo più volte, puoi mantenere attivi simultaneamente fino a tre dei suoi effetti da 1 minuto e puoi congedare uno di quegli effetti con un'azione.","castingTime":"1 azione","range":"9 metri","duration":"Fino a 1 minuto"}},"data":{"level":0,"school":"srd:rule:school-transmutation","classes":["srd:class:cleric"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"30 feet","components":["V"],"ritual":false,"concentration":false,"duration":"1 minute"}},{"id":"srd:spell:thunderwave","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Thunderwave","description":"A wave of thunderous force sweeps out from you. Each creature in a 15-foot cube originating from you must make a constitution saving throw. On a failed save, a creature takes 2d8 thunder damage and is pushed 10 feet away from you. On a successful save, the creature takes half as much damage and isn't pushed.\\n\\nIn addition, unsecured objects that are completely within the area of effect are automatically pushed 10 feet away from you by the spell's effect, and the spell emits a thunderous boom audible out to 300 feet.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st."},"it":{"name":"Onda tonante","description":"Un'ondata di energia tonante si propaga dall'incantatore. Ogni creatura entro un cubo con spigolo di 4,5 metri originato da te deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 2d8 danni da tuono e viene spinta a una distanza di 3 metri dall'incantatore, mentre se lo supera subisce soltanto la metà di quei danni e non viene spinta.\\n\\nInoltre, gli oggetti non fissati e completamente situati all'interno dell'area di effetto dell'incantesimo vengono automaticamente spinti a una distanza di 3 metri dall'incantatore. L'incantesimo emette il rumore di una fragorosa esplosione udibile fino a 90 metri di distanza.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 1°.","castingTime":"1 azione","range":"Incantatore (cubo con spigolo di 4,5 metri)","duration":"Istantanea"}},"data":{"level":1,"school":"srd:rule:school-evocation","classes":["srd:class:bard","srd:class:druid","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-thunder","atSlotLevel":{"1":"2d8","2":"3d8","3":"4d8","4":"5d8","5":"6d8","6":"7d8","7":"8d8","8":"9d8","9":"10d8"}}],"savingThrow":{"ability":"con","onSuccess":"half"},"area":{"type":"cube","size":15}}},{"id":"srd:spell:time-stop","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Time Stop","description":"You briefly stop the flow of time for everyone but yourself. No time passes for other creatures, while you take 1d4 + 1 turns in a row, during which you can use actions and move as normal.\\n\\nThis spell ends if one of the actions you use during this period, or any effects that you create during this period, affects a creature other than you or an object being worn or carried by someone other than you. In addition, the spell ends if you move to a place more than 1,000 feet from the location where you cast it."},"it":{"name":"Fermare il tempo","description":"L'incantatore interrompe brevemente lo scorrere nel tempo per tutti tranne che per se stesso. Per le altre creature il tempo non passa, mentre l'incantatore effettua 1d4 + 1 turni consecutivamente, nel corso dei quali può usare azioni e muoversi normalmente.\\n\\nQuesto incantesimo termina se una delle azioni usate o qualsiasi effetto creato dall'incantatore durante questo periodo influenza una creatura diversa da lui o un oggetto indossato o trasportato da qualcuno diverso da lui. Termina inoltre se l'incantatore si muove in un luogo a più di 300 metri dal punto in cui ha lanciato l'incantesimo.","castingTime":"1 azione","range":"Incantatore","duration":"Istantanea"}},"data":{"level":9,"school":"srd:rule:school-transmutation","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","components":["V"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:tiny-hut","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Tiny Hut","description":"A 10-foot-radius immobile dome of force springs into existence around and above you and remains stationary for the duration. The spell ends if you leave its area.\\n\\nNine creatures of Medium size or smaller can fit inside the dome with you. The spell fails if its area includes a larger creature or more than nine creatures. Creatures and objects within the dome when you cast this spell can move through it freely. All other creatures and objects are barred from passing through it. Spells and other magical effects can't extend through the dome or be cast through it. The atmosphere inside the space is comfortable and dry, regardless of the weather outside.\\n\\nUntil the spell ends, you can command the interior to become dimly lit or dark. The dome is opaque from the outside, of any color you choose, but it is transparent from the inside."},"it":{"name":"Capanna","description":"Una cupola di forza immobile del raggio di 3 metri si materializza intorno e al di sopra dell'incantatore, rimanendo fissa per la durata dell'incantesimo, che termina nel momento in cui l'incantatore esce dalla sua area.\\n\\nLa cupola può contenere, oltre all'incantatore, nove creature di taglia Media o inferiore. L'incantesimo non funziona se nella sua area è presente una creatura di taglia maggiore o più di nove creature. Le creature e gli oggetti all'interno della cupola al momento del lancio dell'incantesimo possono attraversare liberamente la barriera, mentre a tutte le altre creature e oggetti è proibito. Gli incantesimi e gli altri effetti magici non possono estendersi oltre la cupola o essere lanciati attraverso di essa. L'atmosfera all'interno dell'area è gradevole e asciutta, a prescindere dal tempo atmosferico all'esterno.\\n\\nFino al termine dell'incantesimo, l'incantatore può fare in modo che l'interno sia buio o illuminato da luce fioca. Dall'esterno la cupola appare opaca, di un qualsiasi colore a scelta dell'incantatore, ma dall'interno risulta trasparente.","castingTime":"1 minuto","range":"Incantatore (semisfera del raggio di 3 metri)","duration":"8 ore","material":"un piccola perla di cristallo"}},"data":{"level":3,"school":"srd:rule:school-evocation","classes":["srd:class:bard","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 minute","range":"Self","components":["V","S","M"],"material":"A small crystal bead.","ritual":true,"concentration":false,"duration":"8 hours","area":{"type":"sphere","size":10}}},{"id":"srd:spell:tongues","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Tongues","description":"This spell grants the creature you touch the ability to understand any spoken language it hears. Moreover, when the target speaks, any creature that knows at least one language and can hear the target understands what it says."},"it":{"name":"Linguaggi","description":"Questo incantesimo concede alla creatura toccata dall'incantatore l'abilità di comprendere qualsiasi linguaggio che sente parlare. Inoltre, quando il bersaglio parla, qualsiasi creatura che conosca almeno un linguaggio e sia in grado di udirlo capisce ciò che esso sta dicendo.","castingTime":"1 azione","range":"Contatto","duration":"1 ora","material":"una piccola riproduzione in argilla di una ziggurat"}},"data":{"level":3,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:cleric","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","M"],"material":"A small clay model of a ziggurat.","ritual":false,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:transport-via-plants","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Transport via Plants","description":"This spell creates a magical link between a Large or larger inanimate plant within range and another plant, at any distance, on the same plane of existence. You must have seen or touched the destination plant at least once before. For the duration, any creature can step into the target plant and exit from the destination plant by using 5 feet of movement."},"it":{"name":"Trasporto vegetale","description":"Questo incantesimo crea un legame magico tra un vegetale inanimato di taglia Grande o superiore situato entro gittata e un altro vegetale, situato a qualsiasi distanza sullo stesso piano di esistenza. L'incantatore deve aver visto o toccato il vegetale di destinazione almeno una volta in precedenza. Per la durata dell'incantesimo, qualsiasi creatura può entrare nel vegetale bersaglio e uscire da quello di destinazione usando 1,5 metri di movimento.","castingTime":"1 azione","range":"3 metri","duration":"1 round"}},"data":{"level":6,"school":"srd:rule:school-conjuration","classes":["srd:class:druid"],"subclasses":[],"castingTime":"1 action","range":"10 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"1 round"}},{"id":"srd:spell:tree-stride","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Tree Stride","description":"You gain the ability to enter a tree and move from inside it to inside another tree of the same kind within 500 feet. Both trees must be living and at least the same size as you. You must use 5 feet of movement to enter a tree. You instantly know the location of all other trees of the same kind within 500 feet and, as part of the move used to enter the tree, can either pass into one of those trees or step out of the tree you're in. You appear in a spot of your choice within 5 feet of the destination tree, using another 5 feet of movement. If you have no movement left, you appear within 5 feet of the tree you entered.\\n\\nYou can use this transportation ability once per round for the duration. You must end each turn outside a tree."},"it":{"name":"Traslazione arborea","description":"L'incantatore ottiene la capacità di entrare in un albero e muoversi al suo interno fino ad arrivare a un altro albero dello stesso tipo posto entro 150 metri. Entrambi gli alberi devono essere vivi e di taglia pari o superiore a quella dell'incantatore, che deve usare 1,5 metri di movimento per entrare in uno di essi. L'incantatore apprende immediatamente l'ubicazione di tutti gli altri alberi dello stesso tipo entro 150 metri e, come parte del movimento usato per entrare nell'albero, può scegliere se passare in uno di quegli alberi o riemergere da quello in cui si trova. L'incantatore ricompare in un punto a sua scelta entro 1,5 metri dall'albero di destinazione, usando ulteriori 1,5 metri di movimento. Se non gli rimane più alcun movimento, ricompare entro 1,5 metri dall'albero in cui è entrato.\\n\\nPer la durata dell'incantesimo, l'incantatore può usare questa abilità di trasporto una volta per round e deve concludere ogni suo turno fuori dall'albero.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":5,"school":"srd:rule:school-conjuration","classes":["srd:class:druid","srd:class:ranger"],"subclasses":["srd:subclass:land"],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute"}},{"id":"srd:spell:true-polymorph","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"True Polymorph","description":"Choose one creature or nonmagical object that you can see within range. You transform the creature into a different creature, the creature into an object, or the object into a creature (the object must be neither worn nor carried by another creature). The transformation lasts for the duration, or until the target drops to 0 hit points or dies. If you concentrate on this spell for the full duration, the transformation becomes permanent.\\n\\nShapechangers aren't affected by this spell. An unwilling creature can make a wisdom saving throw, and if it succeeds, it isn't affected by this spell.\\n\\n***Creature into Creature.*** If you turn a creature into another kind of creature, the new form can be any kind you choose whose challenge rating is equal to or less than the target's (or its level, if the target doesn't have a challenge rating). The target's game statistics, including mental ability scores, are replaced by the statistics of the new form. It retains its alignment and personality.\\n\\nThe target assumes the hit points of its new form, and when it reverts to its normal form, the creature returns to the number of hit points it had before it transformed. If it reverts as a result of dropping to 0 hit points, any excess damage carries over to its normal form. As long as the excess damage doesn't reduce the creature's normal form to 0 hit points, it isn't knocked unconscious.\\n\\nThe creature is limited in the actions it can perform by the nature of its new form, and it can't speak, cast spells, or take any other action that requires hands or speech unless its new form is capable of such actions.\\n\\nThe target's gear melds into the new form. The creature can't activate, use, wield, or otherwise benefit from any of its equipment.\\n\\n***Object into Creature.*** You can turn an object into any kind of creature, as long as the creature's size is no larger than the object's size and the creature's challenge rating is 9 or lower. The creature is friendly to you and your companions. It acts on each of your turns. You decide what action it takes and how it moves. The GM has the creature's statistics and resolves all of its actions and movement.\\n\\nIf the spell becomes permanent, you no longer control the creature. It might remain friendly to you, depending on how you have treated it.\\n\\n***Creature into Object.*** If you turn a creature into an object, it transforms along with whatever it is wearing and carrying into that form. The creature's statistics become those of the object, and the creature has no memory of time spent in this form, after the spell ends and it returns to its normal form."},"it":{"name":"Metamorfosi pura","description":"L'incantatore sceglie una creatura o un oggetto non magico entro gittata che è in grado di vedere e trasforma la creatura in una creatura diversa o in un oggetto, oppure l'oggetto in una creatura (esso non deve essere indossato o trasportato da un'altra creatura). La trasformazione permane per la durata dell'incantesimo o finché il bersaglio non scende a 0 punti ferita o muore. Se l'incantatore si concentra su questo incantesimo per tutta la sua durata, la trasformazione permane finché non viene dissolta.\\n\\nQuesto incantesimo non ha effetto su un mutaforma, una creatura con 0 punti ferita o una creatura non consenziente che supera un tiro salvezza su Saggezza.\\n\\n***Creatura in creatura.*** Se l'incantatore trasforma una creatura in un altro tipo di creatura, la nuova forma può essere di un qualsiasi tipo, purché il suo grado di sfida sia pari o inferiore a quello del bersaglio (o al livello del bersaglio, se esso non possiede un grado di sfida). Le statistiche di gioco del bersaglio, inclusi i punteggi di caratteristica mentali, vengono sostituite dalle statistiche della nuova forma, ma mantiene il suo allineamento e la sua personalità.\\n\\nIl bersaglio assume i punti ferita della nuova forma e, quando riassume la sua forma normale, la creatura ritorna al numero di punti ferita che aveva prima della trasformazione. Se torna alla sua forma normale per essere sceso a 0 punti ferita, gli eventuali danni in eccesso si trasmettono alla sua forma normale. Fintantoché i danni in eccesso non riducono la forma normale della creatura a 0 punti ferita, questa non cade priva di sensi.\\n\\nLa creatura è limitata alle azioni che può effettuare in base alla natura della sua nuova forma e non può parlare, lanciare incantesimi o effettuare qualsiasi altra azione che richieda l'uso delle mani o della parola, a meno che la sua nuova forma non sia in grado di compiere tali azioni.\\n\\nL'attrezzatura del bersaglio si fonde nella sua nuova forma e la creatura non può attivare, usare, impugnare o beneficiare del proprio equipaggiamento.\\n\\n***Oggetto in creatura.*** L'incantatore può trasformare un oggetto in un qualsiasi tipo di creatura, purché la sua taglia non sia maggiore di quella dell'oggetto e il suo grado di sfida sia pari o inferiore a 9. La creatura è amichevole nei confronti dell'incantatore e dei suoi compagni e agisce in ogni turno dell'incantatore, che decide quale azione effettua e come si muove. Il GM possiede le statistiche di questa creatura e risolve le sue azioni e i suoi movimenti.\\n\\nSe l'incantesimo diventa permanente, l'incantatore non controlla più la creatura, che potrebbe rimanere amichevole o meno nei suoi confronti, in base a come è stata trattata.\\n\\n***Creatura in oggetto.*** Se l'incantatore trasforma una creatura in un oggetto, tutto ciò che essa indossa o trasporta si fonde nella nuova forma. Le statistiche della creatura diventano quelle dell'oggetto e, una volta terminato l'incantesimo e tornata nella sua forma normale, essa non ricorderà nulla del tempo trascorso in quella forma.","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 1 ora","material":"una goccia di mercurio, una piccola quantità di resina e uno sbuffo di fumo"}},"data":{"level":9,"school":"srd:rule:school-transmutation","classes":["srd:class:bard","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A drop of mercury, a dollop of gum arabic, and a wisp of smoke.","ritual":false,"concentration":true,"duration":"Up to 1 hour"}},{"id":"srd:spell:true-resurrection","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"True Resurrection","description":"You touch a creature that has been dead for no longer than 200 years and that died for any reason except old age. If the creature's soul is free and willing, the creature is restored to life with all its hit points.\\n\\nThis spell closes all wounds, neutralizes any poison, cures all diseases, and lifts any curses affecting the creature when it died. The spell replaces damaged or missing organs and limbs.\\n\\nThe spell can even provide a new body if the original no longer exists, in which case you must speak the creature's name. The creature then appears in an unoccupied space you choose within 10 feet of you."},"it":{"name":"Resurrezione pura","description":"L'incantatore tocca una creatura morta da non più di 200 anni a causa di un qualsiasi motivo fuorché la vecchiaia. Se la sua anima è libera e consenziente, essa torna in vita con tutti i suoi punti ferita.\\n\\nQuesto incantesimo chiude tutte le ferite, neutralizza ogni veleno, cura tutte le malattie e annulla ogni maledizione che affiggeva la creatura al momento della morte. Inoltre, ripristina gli eventuali organi e arti danneggiati o mancanti.\\n\\nL'incantesimo può perfino fornire al bersaglio un nuovo corpo se l'originale non esiste più, nel qual caso l'incantatore deve pronunciare il nome della creatura, che appare in uno spazio libero a scelta dell'incantatore entro 3 metri da lui.","castingTime":"1 ora","range":"Contatto","duration":"Istantanea","material":"uno spruzzo di acqua santa e diamanti del valore di almeno 25.000 mo, che l'incantesimo consuma"}},"data":{"level":9,"school":"srd:rule:school-necromancy","classes":["srd:class:cleric","srd:class:druid"],"subclasses":[],"castingTime":"1 hour","range":"Touch","components":["V","S","M"],"material":"A sprinkle of holy water and diamonds worth at least 25,000gp, which the spell consumes.","ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:true-seeing","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"True Seeing","description":"This spell gives the willing creature you touch the ability to see things as they actually are. For the duration, the creature has truesight, notices secret doors hidden by magic, and can see into the Ethereal Plane, all out to a range of 120 feet."},"it":{"name":"Visione del vero","description":"Questo incantesimo conferisce alla creatura consenziente toccata dall'incantatore la capacità di vedere le cose per ciò che sono. Per la durata dell'incantesimo, la creatura è dotata di vista pura, nota le porte segrete nascoste dalla magia ed è in grado di vedere sul Piano Etereo, entro un raggio di 36 metri.","castingTime":"1 azione","range":"Contatto","duration":"1 ora","material":"un unguento per gli occhi del costo di 25 mo, realizzato con polvere di funghi, zafferano e grasso, che l'incantesimo consuma"}},"data":{"level":6,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:cleric","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"An ointment for the eyes that costs 25gp; is made from mushroom powder, saffron, and fat; and is consumed by the spell.","ritual":false,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:true-strike","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"True Strike","description":"You extend your hand and point a finger at a target in range. Your magic grants you a brief insight into the target's defenses. On your next turn, you gain advantage on your first attack roll against the target, provided that this spell hasn't ended."},"it":{"name":"Colpo accurato","description":"L'incantatore punta il dito contro un bersaglio entro gittata e la magia gli concede una breve percezione delle sue difese. Nel suo turno successivo, l'incantatore dispone di vantaggio al primo tiro per colpire contro il bersaglio, purché l'incantesimo non sia terminato.","castingTime":"1 azione","range":"9 metri","duration":"Concentrazione, fino a 1 round"}},"data":{"level":0,"school":"srd:rule:school-divination","classes":["srd:class:bard","srd:class:sorcerer","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"30 feet","components":["S"],"ritual":false,"concentration":true,"duration":"Up to 1 round"}},{"id":"srd:spell:unseen-servant","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Unseen Servant","description":"This spell creates an invisible, mindless, shapeless force that performs simple tasks at your command until the spell ends. The servant springs into existence in an unoccupied space on the ground within range. It has AC 10, 1 hit point, and a Strength of 2, and it can't attack. If it drops to 0 hit points, the spell ends.\\n\\nOnce on each of your turns as a bonus action, you can mentally command the servant to move up to 15 feet and interact with an object. The servant can perform simple tasks that a human servant could do, such as fetching things, cleaning, mending, folding clothes, lighting fires, serving food, and pouring wine. Once you give the command, the servant performs the task to the best of its ability until it completes the task, then waits for your next command.\\n\\nIf you command the servant to perform a task that would move it more than 60 feet away from you, the spell ends."},"it":{"name":"Servitore inosservato","description":"Fino al termine di questo incantesimo, una forza invisibile, amorfa e priva di volontà propria svolge dei compiti semplici su ordine dell'incantatore. Il servitore appare sul terreno in uno spazio libero entro gittata, possiede CA 10, 1 punto ferita e Forza pari a 2 e non può attaccare. Quando i suoi punti ferita scendono a 0, l'incantesimo termina.\\n\\nUna volta in ogni suo turno, come azione bonus, l'incantatore può ordinare mentalmente al servitore di spostarsi di un massimo di 4,5 metri e interagire con un oggetto. Esso può eseguire compiti semplici alla stregua di un servitore umano, come portare oggetti, pulire, riparare, ripiegare abiti, accendere fuochi, servire pietanze e versare vino. Una volta impartito il comando, il servitore svolge il compito al meglio delle sue capacità finché non lo porta a termine, poi attende l'ordine successivo dell'incantatore.\\n\\nSe l'incantatore ordina al servitore di eseguire un compito che lo porta a più di 18 metri da lui, l'incantesimo termina.","castingTime":"1 azione","range":"18 metri","duration":"1 ora","material":"un pezzo di spago e un pezzo di legno"}},"data":{"level":1,"school":"srd:rule:school-conjuration","classes":["srd:class:bard","srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"A piece of string and a bit of wood.","ritual":true,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:vampiric-touch","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Vampiric Touch","description":"The touch of your shadow-wreathed hand can siphon life force from others to heal your wounds. Make a melee spell attack against a creature within your reach. On a hit, the target takes 3d6 necrotic damage, and you regain hit points equal to half the amount of necrotic damage dealt. Until the spell ends, you can make the attack again on each of your turns as an action.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd."},"it":{"name":"Tocco del vampiro","description":"Il tocco della mano dell'incantatore, avviluppata in una cortina d'ombra, può risucchiare l'energia vitale delle altre creature per curare le proprie ferite. L'incantatore effettua un attacco in mischia con incantesimo contro una creatura entro gittata. Se il colpo va a segno, il bersaglio subisce 3d6 danni necrotici e l'incantatore recupera una quantità di punti ferita pari alla metà dei danni necrotici inflitti. Fino al termine dell'incantesimo, l'incantatore con un'azione può effettuare di nuovo l'attacco a ogni suo turno.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d6 per ogni slot di livello superiore al 3°.","castingTime":"1 azione","range":"Incantatore","duration":"Concentrazione, fino a 1 minuto"}},"data":{"level":3,"school":"srd:rule:school-necromancy","classes":["srd:class:warlock","srd:class:wizard"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Self","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","damage":[{"type":"srd:rule:damage-necrotic","atSlotLevel":{"3":"3d6","4":"4d6","5":"5d6","6":"6d6","7":"7d6","8":"8d6","9":"9d6"}}],"attackType":"melee"}},{"id":"srd:spell:vicious-mockery","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Vicious Mockery","description":"You unleash a string of insults laced with subtle enchantments at a creature you can see within range. If the target can hear you (though it need not understand you), it must succeed on a wisdom saving throw or take 1d4 psychic damage and have disadvantage on the next attack roll it makes before the end of its next turn.\\n\\nThis spell's damage increases by 1d4 when you reach 5th level (2d4), 11th level (3d4), and 17th level (4d4)."},"it":{"name":"Beffa crudele","description":"L'incantatore pronuncia una sequenza di insulti mescolati a impercettibili ammaliamenti contro una creatura entro gittata che è in grado di vedere. Se il bersaglio è in grado di sentirlo (non è necessario che lo capisca), deve superare un tiro salvezza su Saggezza, altrimenti subisce 1d4 danni psichici e svantaggio al tiro per colpire successivo che effettua prima della fine del suo turno successivo.\\n\\nI danni di questo incantesimo aumentano di 1d4 quando l'incantatore raggiunge il 5° livello (2d4), l'11° livello (3d4) e il 17° livello (4d4).","castingTime":"1 azione","range":"18 metri","duration":"Istantanea"}},"data":{"level":0,"school":"srd:rule:school-enchantment","classes":["srd:class:bard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","components":["V"],"ritual":false,"concentration":false,"duration":"Instantaneous","damage":[{"type":"srd:rule:damage-psychic","atCharacterLevel":{"1":"1d4","5":"2d4","11":"3d4","17":"4d4"}}],"savingThrow":{"ability":"wis","onSuccess":"none"}}},{"id":"srd:spell:wall-of-fire","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Wall of Fire","description":"You create a wall of fire on a solid surface within range. You can make the wall up to 60 feet long, 20 feet high, and 1 foot thick, or a ringed wall up to 20 feet in diameter, 20 feet high, and 1 foot thick. The wall is opaque and lasts for the duration.\\n\\nWhen the wall appears, each creature within its area must make a Dexterity saving throw. On a failed save, a creature takes 5d8 fire damage, or half as much damage on a successful save.\\n\\nOne side of the wall, selected by you when you cast this spell, deals 5d8 fire damage to each creature that ends its turn within 10 feet o f that side or inside the wall. A creature takes the same damage when it enters the wall for the first time on a turn or ends its turn there. The other side of the wall deals no damage.\\n\\nThe other side of the wall deals no damage.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d8 for each slot level above 4th."},"it":{"name":"Muro di fuoco","description":"L'incantatore crea un muro di fuoco su una superficie solida entro gittata. Il muro può essere lungo fino a 18 metri, alto 6 metri e spesso 30 cm, oppure essere un muro circolare del diametro massimo di 6 metri, alto 6 metri e spesso 30 cm. Il muro è opaco e permane per tutta la durata dell'incantesimo.\\n\\nQuando il muro appare, ogni creatura nella sua area deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 5d8 danni da fuoco, o la metà dei danni in caso di successo.\\n\\nUn lato del muro, scelto dall'incantatore al momento del lancio dell'incantesimo, infligge 5d8 danni da fuoco a ogni creatura che termina il proprio turno entro 3 metri da quel lato o all'interno del muro. Una creatura subisce gli stessi danni quando attraversa il muro per la prima volta in un turno o vi termina il suo turno. L'altro lato del muro non infligge danni.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 5° livello o superiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 4°.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 1 minuto","material":"un frammento di fosforo"}},"data":{"level":4,"school":"srd:rule:school-evocation","classes":["srd:class:druid","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:fiend"],"castingTime":"1 action","range":"120 feet","components":["V","S","M"],"material":"A small piece of phosphorus.","ritual":false,"concentration":true,"duration":"Up to 1 minute","damage":[{"type":"srd:rule:damage-fire","atSlotLevel":{"4":"5d8"}}],"savingThrow":{"ability":"dex","onSuccess":"half"},"area":{"type":"line","size":60}}},{"id":"srd:spell:wall-of-force","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Wall of Force","description":"An invisible wall of force springs into existence at a point you choose within range. The wall appears in any orientation you choose, as a horizontal or vertical barrier or at an angle. It can be free floating or resting on a solid surface. You can form it into a hemispherical dome or a sphere with a radius of up to 10 feet, or you can shape a flat surface made up of ten 10-foot-by-10-foot panels. Each panel must be contiguous with another panel. In any form, the wall is 1/4 inch thick. It lasts for the duration. If the wall cuts through a creature's space when it appears, the creature is pushed to one side of the wall (your choice which side).\\n\\nNothing can physically pass through the wall. It is immune to all damage and can't be dispelled by dispel magic. A disintegrate spell destroys the wall instantly, however. The wall also extends into the Ethereal Plane, blocking ethereal travel through the wall."},"it":{"name":"Muro di forza","description":"Un muro di forza invisibile si materializza in un punto a scelta dell'incantatore situato entro gittata. Esso appare nell'orientamento che l'incantatore desidera, come barriera orizzontale, verticale o inclinata. Può fluttuare nell'aria o poggiare su una superficie solida. L'incantatore può modellare la barriera in una cupola semisferica o in una sfera con raggio massimo di 3 metri, oppure come una superficie piatta composta da dieci pannelli con lato di 3 metri. Ogni pannello dev'essere contiguo a un altro pannello. In qualsiasi forma, il muro ha uno spessore di 0,6 cm e permane per tutta la durata dell'incantesimo. Inoltre, se quando appare passa attraverso lo spazio di una creatura, questa viene spinta da un lato del muro a scelta dell'incantatore.\\n\\nNulla può fisicamente attraversare il muro, che è immune a tutti i danni e non può essere dissolto con dissolvi magie. Tuttavia, un incantesimo disintegrazione distrugge il muro all'istante. Il muro si estende anche sul Piano Etereo, bloccando i viaggi eterei che lo attraversano.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 10 minuti","material":"un pizzico di polvere ricavata dalla distruzione di una gemma trasparente"}},"data":{"level":5,"school":"srd:rule:school-evocation","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","components":["V","S","M"],"material":"A pinch of powder made by crushing a clear gemstone.","ritual":false,"concentration":true,"duration":"Up to 10 minutes"}},{"id":"srd:spell:wall-of-ice","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Wall of Ice","description":"You create a wall of ice on a solid surface within range. You can form it into a hemispherical dome or a sphere with a radius of up to 10 feet, or you can shape a flat surface made up of ten 10-foot-square panels. Each panel must be contiguous with another panel. In any form, the wall is 1 foot thick and lasts for the duration.\\n\\nIf the wall cuts through a creature's space when it appears, the creature within its area is pushed to one side of the wall and must make a dexterity saving throw. On a failed save, the creature takes 10d6 cold damage, or half as much damage on a successful save.\\n\\nThe wall is an object that can be damaged and thus breached. It has AC 12 and 30 hit points per 10-foot section, and it is vulnerable to fire damage. Reducing a 10-foot section of wall to 0 hit points destroys it and leaves behind a sheet of frigid air in the space the wall occupied. A creature moving through the sheet of frigid air for the first time on a turn must make a constitution saving throw. That creature takes 5d6 cold damage on a failed save, or half as much damage on a successful one.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 7th level or higher, the damage the wall deals when it appears increases by 2d6, and the damage from passing through the sheet of frigid air increases by 1d6, for each slot level above 6th."},"it":{"name":"Muro di ghiaccio","description":"L'incantatore crea un muro di ghiaccio su una superficie solida entro gittata, modellandolo in una cupola semisferica o in una sfera con raggio massimo di 3 metri, oppure in una superficie piatta composta da dieci pannelli con lato di 3 metri. Ogni pannello dev'essere contiguo a un altro pannello. In qualsiasi forma, il muro ha uno spessore di 30 cm e permane per la durata dell'incantesimo.\\n\\nSe il muro passa attraverso lo spazio di una creatura quando appare, questa viene spinta da un lato del muro e deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 10d6 danni da freddo, o la metà dei danni in caso di successo.\\n\\nIl muro è un oggetto che può essere danneggiato e quindi sfondato, possiede CA 12 e 30 punti ferita per ogni sezione di 3 metri ed è vulnerabile ai danni da fuoco. Una sezione di 3 metri viene distrutta se scende a 0 punti ferita e, nello spazio che occupava in precedenza, rimane una cortina d'aria gelida. Una creatura che attraversa questa cortina per la prima volta in un turno deve effettuare un tiro salvezza su Costituzione e subisce 5d6 danni da freddo in caso di fallimento, o la metà dei danni in caso di successo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° livello o superiore, i danni inflitti dal muro quando compare aumentano di 2d6 e quelli subiti da chi passa attraverso la cortina d'aria gelida aumentano di 1d6 per ogni slot di livello superiore al 6°.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 10 minuti","material":"un frammento di quarzo"}},"data":{"level":6,"school":"srd:rule:school-evocation","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","components":["V","S","M"],"material":"A small piece of quartz.","ritual":false,"concentration":true,"duration":"Up to 10 minutes","damage":[{"type":"srd:rule:damage-cold","atSlotLevel":{"6":"10d6","7":"12d6","8":"14d6","9":"16d6"}}],"savingThrow":{"ability":"dex","onSuccess":"half"},"area":{"type":"sphere","size":10}}},{"id":"srd:spell:wall-of-stone","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Wall of Stone","description":"A nonmagical wall of solid stone springs into existence at a point you choose within range. The wall is 6 inches thick and is composed of ten 10-foot-by-10-foot panels. Each panel must be contiguous with at least one other panel. Alternatively, you can create 10-foot-by-20-foot panels that are only 3 inches thick.\\n\\nIf the wall cuts through a creature's space when it appears, the creature is pushed to one side of the wall (your choice). If a creature would be surrounded on all sides by the wall (or the wall and another solid surface), that creature can make a dexterity saving throw. On a success, it can use its reaction to move up to its speed so that it is no longer enclosed by the wall.\\n\\nThe wall can have any shape you desire, though it can't occupy the same space as a creature or object. The wall doesn't need to be vertical or rest on any firm foundation. It must, however, merge with and be solidly supported by existing stone. Thus, you can use this spell to bridge a chasm or create a ramp.\\n\\nIf you create a span greater than 20 feet in length, you must halve the size of each panel to create supports. You can crudely shape the wall to create crenellations, battlements, and so on.\\n\\nThe wall is an object made of stone that can be damaged and thus breached. Each panel has AC 15 and 30 hit points per inch of thickness. Reducing a panel to 0 hit points destroys it and might cause connected panels to collapse at the GM's discretion.\\n\\nIf you maintain your concentration on this spell for its whole duration, the wall becomes permanent and can't be dispelled. Otherwise, the wall disappears when the spell ends."},"it":{"name":"Muro di pietra","description":"Un muro non magico di solida pietra si materializza in un punto a scelta dell'incantatore situato entro gittata. Il muro è spesso 15 cm ed è composto da pannelli con lato di 3 metri, ognuno dei quali dev'essere contiguo ad almeno un altro pannello. In alternativa, l'incantatore può creare pannelli di 3 metri per 6 metri spessi solo 8 cm.\\n\\nSe, nel momento in cui appare, il muro passa attraverso lo spazio di una creatura, questa viene spinta da un lato del muro a scelta dell'incantatore. Se una creatura rischia di trovarsi circondata su tutti i lati dal muro (o dal muro e un'altra superficie solida) può effettuare un tiro salvezza su Destrezza. In caso di successo, può usare la sua reazione per muoversi fino alla sua velocità massima nel tentativo di non rimanere intrappolata dal muro.\\n\\nIl muro può avere la forma desiderata dall'incantatore, ma non può occupare lo stesso spazio di una creatura o un oggetto. Non è necessario che sia verticale o poggi su fondamenta solide, deve tuttavia fondersi ed essere saldamente appoggiato a un blocco di pietra già esistente. È quindi possibile usare questo incantesimo per creare una rampa o realizzare un ponte che attraversi un baratro.\\n\\nSe l'incantatore crea una campata di lunghezza superiore a 6 metri, deve dimezzare le dimensioni di ogni pannello per creare dei sostegni. Può inoltre modellare rozzamente il muro per creare feritoie, parapetti e così via.\\n\\nIl muro è un oggetto in pietra che può essere danneggiato e quindi sfondato. Ogni pannello possiede CA 15 e 30 punti ferita per ogni 2,5 cm di spessore. Quando un pannello scende a 0 punti ferita, viene distrutto e potrebbe causare il crollo dei pannelli collegati, a discrezione del GM.\\n\\nSe l'incantatore mantiene la concentrazione su questo incantesimo per l'intera durata, il muro diventa permanente e non può essere rimosso. In caso contrario, il muro scompare al termine dell'incantesimo.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 10 minuti","material":"un piccolo blocco di granito"}},"data":{"level":5,"school":"srd:rule:school-evocation","classes":["srd:class:druid","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:land"],"castingTime":"1 action","range":"120 feet","components":["V","S","M"],"material":"A small block of granite.","ritual":false,"concentration":true,"duration":"Up to 10 minutes"}},{"id":"srd:spell:wall-of-thorns","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Wall of Thorns","description":"You create a wall of tough, pliable, tangled brush bristling with needle-sharp thorns. The wall appears within range on a solid surface and lasts for the duration. You choose to make the wall up to 60 feet long, 10 feet high, and 5 feet thick or a circle that has a 20-foot diameter and is up to 20 feet high and 5 feet thick. The wall blocks line of sight.\\n\\nWhen the wall appears, each creature within its area must make a dexterity saving throw. On a failed save, a creature takes 7d8 piercing damage, or half as much damage on a successful save.\\n\\nA creature can move through the wall, albeit slowly and painfully. For every 1 foot a creature moves through the wall, it must spend 4 feet of movement. Furthermore, the first time a creature enters the wall on a turn or ends its turn there, the creature must make a dexterity saving throw. It takes 7d8 slashing damage on a failed save, or half as much damage on a successful one.\\n\\n**At Higher Levels.** When you cast this spell using a spell slot of 7th level or higher, both types of damage increase by 1d8 for each slot level above 6th."},"it":{"name":"Muro di spine","description":"L'incantatore crea un fitto muro di rovi, resistente, flessibile ed erto di spine affilate. Il muro appare entro gittata su una superficie solida e permane per tutta la durata dell'incantesimo. L'incantatore può scegliere se creare un muro lungo fino a 18 metri, alto 3 metri e spesso 1,5 metri, oppure un muro circolare del diametro massimo di 6 metri, alto fino a 6 metri e spesso 1,5 metri. Il muro blocca la visuale.\\n\\nQuando il muro appare, ogni creatura nella sua area deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 7d8 danni perforanti, o la metà dei danni in caso di successo.\\n\\nUna creatura può muoversi attraverso il muro, seppur con fatica e dolore: per ogni 30 cm di muro che attraversa, deve spendere 1,2 metri di movimento. Inoltre, la prima volta che una creatura entra nel muro in un turno o vi termina il suo turno, deve superare un tiro salvezza su Destrezza, subendo 7d8 danni taglienti in caso di fallimento, o la metà dei danni in caso di successo.\\n\\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° livello o superiore, entrambi i tipi di danno aumentano di 1d8 per ogni slot di livello superiore al 6°.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 10 minuti","material":"una manciata di spine"}},"data":{"level":6,"school":"srd:rule:school-conjuration","classes":["srd:class:druid"],"subclasses":[],"castingTime":"1 action","range":"120 feet","components":["V","S","M"],"material":"A handful of thorns.","ritual":false,"concentration":true,"duration":"Up to 10 minutes","damage":[{"type":"srd:rule:damage-piercing","atSlotLevel":{"6":"7d8","7":"8d8","8":"9d8","9":"10d8"}}],"savingThrow":{"ability":"dex","onSuccess":"half"},"area":{"type":"line","size":60}}},{"id":"srd:spell:warding-bond","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Warding Bond","description":"This spell wards a willing creature you touch and creates a mystic connection between you and the target until the spell ends. While the target is within 60 feet of you, it gains a +1 bonus to AC and saving throws, and it has resistance to all damage. Also, each time it takes damage, you take the same amount of damage.\\n\\nThe spell ends if you drop to 0 hit points or if you and the target become separated by more than 60 feet.\\n\\nIt also ends if the spell is cast again on either of the connected creatures. You can also dismiss the spell as an action."},"it":{"name":"Vincolo di interdizione","description":"Questo incantesimo protegge una creatura consenziente toccata dall'incantatore e crea tra i due un legame mistico che permane finché l'incantesimo non termina. Finché il bersaglio si trova entro 18 metri dall'incantatore, ottiene un bonus di +1 alla CA e ai tiri salvezza e resistenza a tutti i danni. Inoltre, ogni volta che subisce danni, l'incantatore ne subisce la stessa quantità.\\n\\nL'incantesimo termina se l'incantatore scende a 0 punti ferita, se lui e il bersaglio si allontanano per più di 18 metri o se l'incantesimo viene lanciato di nuovo su una delle due creature collegate. Inoltre, l'incantatore può interrompere l'incantesimo con un'azione.","castingTime":"1 azione","range":"Contatto","duration":"1 ora","material":"un paio di anelli di platino del valore di almeno 50 mo, che l'incantatore e il bersaglio devono indossare per la durata dell'incantesimo"}},"data":{"level":2,"school":"srd:rule:school-abjuration","classes":["srd:class:cleric"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"Touch","components":["V","S","M"],"material":"A pair of platinum rings worth at least 50gp each, which you and the target must wear for the duration.","ritual":false,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:water-breathing","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Water Breathing","description":"This spell gives a maximum of ten willing creatures within range and you can see, the ability to breathe underwater until the end of its term. Affected creatures also retain their normal breathing pattern."},"it":{"name":"Respirare sott'acqua","description":"Questo incantesimo concede a un massimo di dieci creature consenzienti, che si trovano entro gittata e che l'incantatore è in grado di vedere, la capacità di respirare sott'acqua per tutta la sua durata. Le creature influenzate conservano inoltre la loro normale modalità di respirazione.","castingTime":"1 azione","range":"9 metri","duration":"24 ore","material":"un piccolo giunco o una pagliuzza"}},"data":{"level":3,"school":"srd:rule:school-transmutation","classes":["srd:class:druid","srd:class:ranger","srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A short piece of reed or straw.","ritual":true,"concentration":false,"duration":"24 hours"}},{"id":"srd:spell:water-walk","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Water Walk","description":"This spell grants the ability to move across any liquid surface--such as water, acid, mud, snow, quicksand, or lava--as if it were harmless solid ground (creatures crossing molten lava can still take damage from the heat). Up to ten willing creatures you can see within range gain this ability for the duration.\\n\\nIf you target a creature submerged in a liquid, the spell carries the target to the surface of the liquid at a rate of 60 feet per round."},"it":{"name":"Camminare sull'acqua","description":"Questo incantesimo conferisce la capacità di muoversi su una qualsiasi superficie liquida, come l'acqua, l'acido, il fango, la neve, le sabbie mobili o la lava, come se si trattasse di un innocuo terreno solido (ma le creature che attraversano un tratto di lava fusa possono comunque subire danni dal calore). Fino a dieci creature consenzienti entro gittata che l'incantatore è in grado di vedere ottengono questa capacità per tutta la durata dell'incantesimo.\\n\\nSe il bersaglio è una creatura immersa in un liquido, l'incantesimo la sposta in superficie a una velocità di 18 metri per round.","castingTime":"1 azione","range":"9 metri","duration":"1 ora","material":"un pezzo di sughero"}},"data":{"level":3,"school":"srd:rule:school-transmutation","classes":["srd:class:cleric","srd:class:druid","srd:class:ranger","srd:class:sorcerer"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"30 feet","components":["V","S","M"],"material":"A piece of cork.","ritual":true,"concentration":false,"duration":"1 hour"}},{"id":"srd:spell:web","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Web","description":"You conjure a mass of thick, sticky webbing at a point of your choice within range. The webs fill a 20-foot cube from that point for the duration. The webs are difficult terrain and lightly obscure their area.\\n\\nIf the webs aren't anchored between two solid masses (such as walls or trees) or layered across a floor, wall, or ceiling, the conjured web collapses on itself, and the spell ends at the start of your next turn. Webs layered over a flat surface have a depth of 5 feet.\\n\\nEach creature that starts its turn in the webs or that enters them during its turn must make a dexterity saving throw. On a failed save, the creature is restrained as long as it remains in the webs or until it breaks free.\\n\\nA creature restrained by the webs can use its action to make a Strength check against your spell save DC. If it succeeds, it is no longer restrained.\\n\\nThe webs are flammable. Any 5-foot cube of webs exposed to fire burns away in 1 round, dealing 2d4 fire damage to any creature that starts its turn in the fire."},"it":{"name":"Ragnatela","description":"L'incantatore evoca una massa di spessi e viscosi filamenti di ragnatela in un punto a sua scelta situato entro gittata. A partire da quel punto, le ragnatele riempiono un cubo con spigolo di 6 metri per la durata dell'incantesimo. Le ragnatele sono terreno difficile e la loro area è considerata leggermente oscurata.\\n\\nSe le ragnatele non sono ancorate tra due masse solide (per esempio pareti o alberi) o stese su un pavimento, un muro o un soffitto, collassano su se stesse e l'incantesimo termina all'inizio del turno successivo dell'incantatore. Le ragnatele stese su una superficie piatta hanno una profondità di 1,5 metri.\\n\\nOgni creatura che inizia il suo turno nelle ragnatele o che vi entra durante il proprio turno deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, la creatura è trattenuta fintanto che rimane tra le ragnatele o finché non si libera.\\n\\nUna creatura trattenuta dalle ragnatele può usare la sua azione per effettuare una prova di Forza contro la CD del tiro salvezza sull'incantesimo. Se ha successo, non è più trattenuta.\\n\\nLe ragnatele sono infiammabili. Un cubo di ragnatele di 1,5 metri brucia in 1 round, infliggendo 2d4 danni da fuoco a ogni creatura che inizi il suo turno tra le fiamme.","castingTime":"1 azione","range":"18 metri","duration":"Concentrazione, fino a 1 ora","material":"un frammento di ragnatela comune"}},"data":{"level":2,"school":"srd:rule:school-conjuration","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":["srd:subclass:lore","srd:subclass:land"],"castingTime":"1 action","range":"60 feet","components":["V","S","M"],"material":"A bit of spiderweb.","ritual":false,"concentration":true,"duration":"Up to 1 hour","area":{"type":"cube","size":20}}},{"id":"srd:spell:weird","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Weird","description":"Drawing on the deepest fears of a group of creatures, you create illusory creatures in their minds, visible only to them. Each creature in a 30-foot-radius sphere centered on a point of your choice within range must make a wisdom saving throw. On a failed save, a creature becomes frightened for the duration. The illusion calls on the creature's deepest fears, manifesting its worst nightmares as an implacable threat. At the start of each of the frightened creature's turns, it must succeed on a wisdom saving throw or take 4d10 psychic damage. On a successful save, the spell ends for that creature."},"it":{"name":"Fatale","description":"Attingendo alle paure più profonde di un gruppo di creature, l'incantatore crea nelle loro menti delle creature illusorie, visibili soltanto a loro. Ogni creatura all'interno di una sfera con raggio di 9 metri, centrata su un punto entro gittata a scelta dell'incantatore, deve effettuare un tiro salvezza su Saggezza. Se lo fallisce, rimane spaventata per tutta la durata dell'incantesimo. L'illusione fa leva sulle paure più profonde di una creatura, manifestando i suoi incubi peggiori come una minaccia implacabile. Al termine di ogni suoi turno, la creatura spaventata deve superare un tiro salvezza su Saggezza, altrimenti subisce 4d10 danni psichici. In caso di successo, l'incantesimo non ha più effetto su di lei.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a un minuto"}},"data":{"level":9,"school":"srd:rule:school-illusion","classes":["srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","components":["V","S"],"ritual":false,"concentration":true,"duration":"Up to 1 minute","savingThrow":{"ability":"wis","onSuccess":"none"},"area":{"type":"sphere","size":30}}},{"id":"srd:spell:wind-walk","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Wind Walk","description":"You and up to ten willing creatures you can see within range assume a gaseous form for the duration, appearing as wisps of cloud. While in this cloud form, a creature has a flying speed of 300 feet and has resistance to damage from nonmagical weapons. The only actions a creature can take in this form are the Dash action or to revert to its normal form. Reverting takes 1 minute, during which time a creature is incapacitated and can't move. Until the spell ends, a creature can revert to cloud form, which also requires the 1-minute transformation.\\n\\nIf a creature is in cloud form and flying when the effect ends, the creature descends 60 feet per round for 1 minute until it lands, which it does safely. If it can't land after 1 minute, the creature falls the remaining distance."},"it":{"name":"Camminare nel vento","description":"L'incantatore e un massimo di dieci creature consenzienti che è in grado di vedere entro gittata assumono forma gassosa per la durata dell'incantesimo, apparendo come sbuffi di nuvole. Finché rimane in questa forma gassosa, una creatura possiede una velocità di volare di 90 metri e resistenza ai danni inferti dalle armi non magiche. Le uniche azioni che una creatura può effettuare in questa forma sono l'azione Scatto o riassumere la propria forma normale. Riassumere la propria forma richiede 1 minuto, durante il quale una creatura è incapacitata e non è in grado di muoversi. Fino al termine dell'incantesimo, una creatura può tornare in forma gassosa, il che richiede 1 minuto di trasformazione.\\n\\nSe una creatura è in forma gassosa e sta volando quando l'effetto termina, scende di 18 metri per round per 1 minuto finché non atterra, senza subire danni. Se tuttavia non riesce ad atterrare in 1 minuto, la creatura cade per la distanza rimanente.","castingTime":"1 minuto","range":"9 metri","duration":"8 ore","material":"fuoco e acqua santa"}},"data":{"level":6,"school":"srd:rule:school-transmutation","classes":["srd:class:druid"],"subclasses":[],"castingTime":"1 minute","range":"30 feet","components":["V","S","M"],"material":"Fire and holy water.","ritual":false,"concentration":false,"duration":"8 hours"}},{"id":"srd:spell:wind-wall","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Wind Wall","description":"A wall of strong wind rises from the ground at a point you choose within range. You can make the wall up to 50 feet long, 15 feet high, and 1 foot thick. You can shape the wall in any way you choose so long as it makes one continuous path along the ground. The wall lasts for the duration.\\n\\nWhen the wall appears, each creature within its area must make a strength saving throw. A creature takes 3d8 bludgeoning damage on a failed save, or half as much damage on a successful one.\\n\\nThe strong wind keeps fog, smoke, and other gases at bay. Small or smaller flying creatures or objects can't pass through the wall. Loose, lightweight materials brought into the wall fly upward. Arrows, bolts, and other ordinary projectiles launched at targets behind the wall are deflected upward and automatically miss. (Boulders hurled by giants or siege engines, and similar projectiles, are unaffected.) Creatures in gaseous form can't pass through it."},"it":{"name":"Muro di vento","description":"Un muro di vento forte si solleva dal terreno in un punto a scelta dell'incantatore situato entro gittata. Il muro può essere lungo fino a 15 metri, alto 4,5 metri e spesso 30 cm. L'incantatore può modellarlo nel modo che preferisce, purché formi un percorso continuo lungo il terreno. Il muro permane per tutta la durata dell'incantesimo.\\n\\nQuando il muro appare, ogni creatura nella sua area deve effettuare un tiro salvezza su Forza, subendo 3d8 danni contundenti in caso di fallimento, o la metà dei danni in caso di successo.\\n\\nIl vento forte tiene lontani fumo, nebbia e altri gas. Le creature o gli oggetti volanti di taglia Piccola o inferiore non possono passare attraverso il muro e i materiali leggeri, non fissati in qualche modo, volano verso l'alto una volta portati al suo interno. Frecce, quadrelli e altri proiettili ordinari lanciati contro bersagli dietro il muro vengono deviati verso l'alto e mancano automaticamente il bersaglio. (I macigni scagliati dai giganti o dalle macchine d'assedio e altri proiettili simili non sono influenzati dal muro.) Le creature in forma gassosa inoltre non possono attraversare questa barriera di vento.","castingTime":"1 azione","range":"36 metri","duration":"Concentrazione, fino a 1 minuto","material":"un ventaglio minuscolo e una piuma di origini esotiche"}},"data":{"level":3,"school":"srd:rule:school-evocation","classes":["srd:class:druid","srd:class:ranger"],"subclasses":["srd:subclass:lore"],"castingTime":"1 action","range":"120 feet","components":["V","S","M"],"material":"A tiny fan and a feather of exotic origin.","ritual":false,"concentration":true,"duration":"Up to 1 minute","damage":[{"type":"srd:rule:damage-bludgeoning","atSlotLevel":{"3":"3d8"}}],"savingThrow":{"ability":"str","onSuccess":"half"},"area":{"type":"line","size":50}}},{"id":"srd:spell:wish","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Wish","description":"Wish is the mightiest spell a mortal creature can cast. By simply speaking aloud, you can alter the very foundations of reality in accord with your desires.\\n\\nThe basic use of this spell is to duplicate any other spell of 8th level or lower. You don't need to meet any requirements in that spell, including costly components. The spell simply takes effect.\\n\\nAlternatively, you can create one of the following effects of your choice:\\n\\n- You create one object of up to 25,000 gp in value that isn't a magic item. The object can be no more than 300 feet in any dimension, and it appears in an unoccupied space you can see on the ground.\\n\\n- You allow up to twenty creatures that you can see to regain all hit points, and you end all effects on them described in the greater restoration spell.\\n\\n- You grant up to ten creatures that you can see resistance to a damage type you choose.\\n\\n- You grant up to ten creatures you can see immunity to a single spell or other magical effect for 8 hours. For instance, you could make yourself and all your companions immune to a lich's life drain attack.\\n\\n- You undo a single recent event by forcing a reroll of any roll made within the last round (including your last turn). Reality reshapes itself to accommodate the new result. For example, a wish spell could undo an opponent's successful save, a foe's critical hit, or a friend's failed save. You can force the reroll to be made with advantage or disadvantage, and you can choose whether to use the reroll or the original roll.\\n\\nYou might be able to achieve something beyond the scope of the above examples. State your wish to the GM as precisely as possible. The GM has great latitude in ruling what occurs in such an instance; the greater the wish, the greater the likelihood that something goes wrong. This spell might simply fail, the effect you desire might only be partly achieved, or you might suffer some unforeseen consequence as a result of how you worded the wish. For example, wishing that a villain were dead might propel you forward in time to a period when that villain is no longer alive, effectively removing you from the game. Similarly, wishing for a legendary magic item or artifact might instantly transport you to the presence of the item's current owner.\\n\\nThe stress of casting this spell to produce any effect other than duplicating another spell weakens you. After enduring that stress, each time you cast a spell until you finish a long rest, you take 1d10 necrotic damage per level of that spell. This damage can't be reduced or prevented in any way. In addition, your Strength drops to 3, if it isn't 3 or lower already, for 2d4 days. For each of those days that you spend resting and doing nothing more than light activity, your remaining recovery time decreases by 2 days. Finally, there is a 33 percent chance that you are unable to cast wish ever again if you suffer this stress."},"it":{"name":"Desiderio","description":"Desiderio è l'incantesimo più potente che una creatura mortale sia in grado di lanciare. Pronunciando semplicemente il proprio desiderio ad alta voce, l'incantatore altera le fondamenta stesse della realtà in base a ciò che desidera.\\n\\nL'uso base di questo incantesimo è riprodurre un qualsiasi altro incantesimo di livello pari o inferiore all'8°. L'incantatore non deve rispettarne i requisiti, inclusi eventuali componenti costosi: l'incantesimo ha semplicemente effetto.\\n\\nIn alternativa, l'incantatore può creare uno dei seguenti effetti a sua scelta:\\n\\n- L'incantatore crea un oggetto del valore massimo di 25.000 mo che non sia un oggetto magico e che non misuri più di 90 metri in ogni dimensione. L'oggetto si materializza a terra in uno spazio libero che l'incantatore è in grado di vedere.\\n\\n- L'incantatore consente a un massimo di venti creature che è in grado di vedere di recuperare tutti i punti ferita e pone fine a tutti gli effetti su di loro come descritto nell'incantesimo ristorare superiore.\\n\\n- L'incantatore conferisce a un massimo di dieci creature che è in grado di vedere resistenza a un tipo di danno a sua scelta.\\n\\n- L'incantatore conferisce a un massimo di dieci creature che è in grado di vedere immunità a un singolo incantesimo o un altro effetto magico per 8 ore. Per esempio, potrebbe rendere se stesso e tutti i suoi compagni immuni all'attacco Risucchio di vita di un lich.\\n\\n- L'incantatore annulla un singolo evento recente imponendo la ripetizione di un qualsiasi tiro effettuato entro l'ultimo round (incluso il suo ultimo turno). La realtà viene rimodellata e si adatta al nuovo risultato. Per esempio, un incantesimo desiderio potrebbe annullare il tiro salvezza superato di un avversario, il colpo critico di un nemico o un tiro salvezza fallito di un amico. L'incantatore può imporre che il tiro ripetuto sia effettuato con vantaggio o svantaggio e poi può scegliere se usare il tiro ripetuto o il tiro originale.\\n\\nL'incantatore potrebbe essere in grado di realizzare qualcosa che vada oltre gli esempi elencati sopra, dichiarando il suo desiderio al GM nel modo più preciso possibile. Il GM ha la massima libertà di decidere cosa accade in questi casi: più potente è il desiderio, maggiori sono le probabilità che qualcosa vada storto. L'incantesimo potrebbe semplicemente fallire, l'effetto desiderato potrebbe avverarsi solo in parte o l'incantatore potrebbe subire conseguenze inaspettate come risultato della formulazione del desiderio. Per esempio, se desidera che un suo nemico sia morto, potrebbe essere trascinato nel futuro fino al momento in cui quel nemico non è più in vita, venendo a tutti gli effetti rimosso dal gioco. Analogamente, se desidera un manufatto o un oggetto magico leggendario, potrebbe essere trasportato istantaneamente in presenza del suo attuale proprietario.\\n\\nLa tensione provocata dal lancio di questo incantesimo per produrre un qualsiasi effetto diverso dalla duplicazione di un altro incantesimo debilita l'incantatore. Dopo aver sopportato quella tensione, ogni volta che l'incantatore lancia un incantesimo prima di avere completato un riposo lungo, subisce 1d10 danni necrotici per livello di quell'incantesimo. Questi danni non possono essere ridotti o prevenuti in alcun modo. Inoltre, la Forza dell'incantatore scende a 3, se non è già pari o inferiore 3, per 2d4 giorni. Per ognuno di quei giorni trascorso a riposare e a non fare nulla fuorché attività poco impegnative, il tempo di recupero rimanente diminuisce di 2 giorni. Esiste infine una probabilità del 33% che l'incantatore non sia più in grado di lanciare desiderio, se non riesce a reggere la tensione.","castingTime":"1 azione","range":"Incantatore","duration":"Istantanea"}},"data":{"level":9,"school":"srd:rule:school-conjuration","classes":["srd:class:sorcerer","srd:class:wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","components":["V"],"ritual":false,"concentration":false,"duration":"Instantaneous"}},{"id":"srd:spell:word-of-recall","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Word of Recall","description":"You and up to five willing creatures within 5 feet of you instantly teleport to a previously designated sanctuary. You and any creatures that teleport with you appear in the nearest unoccupied space to the spot you designated when you prepared your sanctuary (see below). If you cast this spell without first preparing a sanctuary, the spell has no effect.\\n\\nYou must designate a sanctuary by casting this spell within a location, such as a temple, dedicated to or strongly linked to your deity. If you attempt to cast the spell in this manner in an area that isn't dedicated to your deity, the spell has no effect."},"it":{"name":"Parola del ritiro","description":"L'incantatore e un massimo di cinque creature consenzienti entro 1,5 metri da lui si teletrasportano immediatamente in un santuario indicato in precedenza. L'incantatore e le creature che si teletrasportano con lui appaiono nello spazio libero più vicino al punto indicato dall'incantatore quando ha preparato il suo santuario (vedi di seguito). Se lancia questo incantesimo senza prima preparare un santuario, l'incantesimo non ha effetto.\\n\\nL'incantatore deve prima indicare un santuario lanciando l'incantesimo all'interno di un luogo dedicato o fortemente legato alla sua divinità, come per esempio un tempio. Se l'incantatore cerca di lanciare l'incantesimo in questo modo in un'area che non è dedicata alla sua divinità, non ha effetto.","castingTime":"1 azione","range":"1,5 metri","duration":"Istantanea"}},"data":{"level":6,"school":"srd:rule:school-conjuration","classes":["srd:class:cleric"],"subclasses":[],"castingTime":"1 action","range":"5 feet","components":["V"],"ritual":false,"concentration":false,"duration":"Instantaneous","area":{"type":"sphere","size":5}}},{"id":"srd:spell:zone-of-truth","kind":"spell","schemaVersion":1,"version":"1.0.0","lang":"en","text":{"en":{"name":"Zone of Truth","description":"You create a magical zone that guards against deception in a 15-foot-radius sphere centered on a point of your choice within range. Until the spell ends, a creature that enters the spell's area for the first time on a turn or starts its turn there must make a Charisma saving throw. On a failed save, a creature can't speak a deliberate lie while in the radius. You know whether each creature succeeds or fails on its saving throw.\\n\\nAn affected creature is aware of the spell and can thus avoid answering questions to which it would normally respond with a lie. Such a creature can remain evasive in its answers as long as it remains within the boundaries of the truth."},"it":{"name":"Zona di verità","description":"L'incantatore crea una zona magica che protegge dagli inganni all'interno di una sfera con raggio di 4,5 metri, centrata su un punto entro gittata a sua scelta. Fino al termine dell'incantesimo, una creatura che entra nell'area dell'incantesimo per la prima volta in un turno o vi inizia il suo turno deve superare un tiro salvezza su Carisma. Se lo fallisce, non può mentire deliberatamente mentre si trova nell'area. Inoltre, l'incantatore è a conoscenza di quali creature hanno superato o fallito il proprio tiro salvezza.\\n\\nUna creatura influenzata è consapevole dell'incantesimo e può quindi evitare di rispondere alle domande a cui normalmente risponderebbe mentendo. Una tale creatura può fornire riposte sfuggenti, purché rimanga entro i confini della verità.","castingTime":"1 azione","range":"18 metri","duration":"10 minuti"}},"data":{"level":2,"school":"srd:rule:school-enchantment","classes":["srd:class:bard","srd:class:cleric","srd:class:paladin"],"subclasses":["srd:subclass:lore","srd:subclass:devotion"],"castingTime":"1 action","range":"60 feet","components":["V","S"],"ritual":false,"concentration":false,"duration":"10 minutes","area":{"type":"sphere","size":15}}}]`);export{e as default};